package nl.dexanddice.solsurvivor;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import nl.dexanddice.solsurvivor.core.BoardEntry;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The leaderboard's requests (core.BoardEntry), sent by the plugin's injected RuneLite HTTP client, and the site's
 * answers read with RuneLite's Gson: a wave put on the boards once the site has its log, and all of the player's times
 * taken off by Remove my times. An answer is read up to MAX_ANSWER bytes, as the site's are a line of JSON.
 */
final class BoardUpload
{
	/** The most of an answer read: the site's are under 300 bytes. */
	private static final int MAX_ANSWER = 4096;

	private BoardUpload()
	{
	}

	/** The request that puts a wave on the boards, with its body (BoardEntry.body). */
	static Request enter(String site, String body)
	{
		return new Request.Builder().url(BoardEntry.endpoint(site))
			.post(new LazyBody(BoardEntry.TYPE, () -> body.getBytes(StandardCharsets.UTF_8))).build();
	}

	/** The request that takes all of the times of the player whose key is `key` off the boards. */
	static Request remove(String site, String key)
	{
		return new Request.Builder().url(BoardEntry.removeEndpoint(site))
			.post(new LazyBody(BoardEntry.TYPE, () -> BoardEntry.removeBody(key).getBytes(StandardCharsets.UTF_8))).build();
	}

	/** An answer's JSON, or an IOException for one that is too long or none. */
	private static String text(Response response) throws IOException
	{
		ResponseBody body = response.body();
		if (body == null || body.source().request(MAX_ANSWER + 1) || body.source().getBuffer().size() > MAX_ANSWER)
		{
			throw new IOException("The site's answer was not one it gives.");
		}
		return body.source().readUtf8();
	}

	/**
	 * What the site's answer to a wave means for the player, in words for the panel (BoardEntry.said), `asked` being the
	 * name sent; null for an answer that says nothing to tell, such as a refusal, which is dropped without a word as a
	 * shared log's is.
	 */
	static String entered(Gson gson, Response response, String asked)
	{
		if (!response.isSuccessful())
		{
			return null;
		}
		try
		{
			return BoardEntry.said(gson.fromJson(text(response), BoardEntry.Answer.class), asked);
		}
		catch (IOException | RuntimeException ex)
		{
			return null;
		}
	}

	/**
	 * How many waves Remove my times took off, from the site's answer; an IOException in words for the player when it
	 * did not.
	 */
	static int removed(Gson gson, Response response) throws IOException
	{
		if (!response.isSuccessful())
		{
			throw new IOException(response.code() == 429 ? "Too many requests. Try again in a minute."
				: "The site could not remove your times. Try again later.");
		}
		try
		{
			return gson.fromJson(text(response), JsonObject.class).get("removed").getAsInt();
		}
		catch (RuntimeException ex)
		{
			throw new IOException("The site's answer was not one it gives. Try again later.", ex);
		}
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.components.LineComponent;
import nl.dexanddice.solsurvivor.core.WaveClock;

/** Both clock readings in one movable box, stacked or in the same labelled rows as RuneLite's wave boxes. */
class CombinedWaveTimerOverlay extends WaveClockOverlay
{
	@Inject
	CombinedWaveTimerOverlay(SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		super(plugin, config);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		WaveClock.View view = plugin.waveClock();
		boolean counter = view.counterVisible(config.quietOnSol());
		boolean timer = view.timerVisible(config.quietOnSol());
		if (!combined() || !plugin.inArena() || !(counter || timer))
		{
			return null;
		}
		background(view);
		Color tick = numberColour(view);
		// The counter runs from entering the arena, before any pick has started the timer: until then the box shows the
		// counter alone, rather than a blank time.
		if (timer)
		{
			title(view);
		}
		if (config.combinedTimerLayout() == SolSurvivorConfig.CombinedTimerLayout.ROWS)
		{
			if (counter)
			{
				panelComponent.getChildren().add(LineComponent.builder().left("Ticks").leftColor(Color.WHITE)
					.right(ticks(view)).rightColor(tick).build());
			}
			if (timer)
			{
				panelComponent.getChildren().add(LineComponent.builder().left("Time").leftColor(Color.WHITE)
					.right(time(view)).rightColor(Color.WHITE).build());
			}
		}
		else if (!timer)
		{
			number(ticks(view), 30f, tick);
		}
		else if (!counter)
		{
			number(time(view), 30f);
		}
		else if (config.largeTimerNumber() == SolSurvivorConfig.LargeTimerNumber.TIME)
		{
			number(time(view), 30f);
			number("Tick " + ticks(view), 13f, tick);
		}
		else
		{
			number(ticks(view), 30f, tick);
			number(time(view), 13f);
		}
		return draw(graphics, 132);
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.swing.Icon;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Doom's stacks in a box of their own that the player places, as the tick counter is (Stefan's request of
 * 2026-10-30): the same icon and "4/10" as by the hitpoints orb (DoomOverlay), red on the last stack, starting at the
 * top left with RuneLite's other boxes and moved with Alt and drag. It shows only with Doom's place set to a movable box.
 */
class DoomBoxOverlay extends Overlay
{
	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;
	private final Icon icon = Icons.of("modifier-doom", DoomOverlay.ICON);

	@Inject
	DoomBoxOverlay(SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WaveView view = plugin.waveView();
		if (!DoomOverlay.shows(config, plugin, view, SolSurvivorConfig.DoomPlace.MOVABLE))
		{
			return null;
		}
		graphics.setFont(FontManager.getRunescapeSmallFont());
		DoomOverlay.paint(graphics, icon, view, 0, 0);
		return new Dimension(DoomOverlay.width(graphics, view), DoomOverlay.HEIGHT);
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.swing.Icon;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Doom's stacks by the hitpoints orb, a setting that is on by default: Doom's icon and "4/10", the game's own count
 * against the tier's limit, red on the last stack, beside the orb where the player already reads their hitpoints (the
 * third of the five designs of 2026-10-26, the user's choice). It sits just left of the orb, on its row, as the prayer
 * orb sits under it. Facts only, as the buffs bar's own Doom count: nothing of how to play. With Doom's place set to
 * a movable box, DoomBoxOverlay draws the same box where the player puts it instead.
 */
class DoomOverlay extends Overlay
{
	/** The hitpoints orb, in each of the game's layouts of the orbs: by the minimap, without it, and their other two. */
	private static final int[] ORBS = {InterfaceID.Orbs.ORB_HEALTH, InterfaceID.OrbsNomap.ORB_HEALTH, InterfaceID.OrbsOsm.ORB_HEALTH,
		InterfaceID.OrbsOsmNomap.ORB_HEALTH};
	static final int ICON = 16;
	static final int HEIGHT = 20;
	private static final Color GROUND = new Color(0x1a, 0x16, 0x12, 225);
	private static final Color TEXT = Color.WHITE;
	private static final Color LAST = new Color(0xff3c3c);

	private final Client client;
	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;
	private final Icon icon = Icons.of("modifier-doom", ICON);

	@Inject
	DoomOverlay(Client client, SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WaveView view = plugin.waveView();
		if (!shows(config, plugin, view, SolSurvivorConfig.DoomPlace.BY_ORB))
		{
			return null;
		}
		Widget orb = healthOrb();
		if (orb == null)
		{
			return null;
		}
		Rectangle bounds = orb.getBounds();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		int width = width(graphics, view);
		paint(graphics, icon, view, bounds.x - 4 - width, bounds.y + bounds.height / 2 - HEIGHT / 2);
		return null;
	}

	/** Whether Doom's stacks show now in the given place: switched on there, in the arena, mid-wave and Doom held. */
	static boolean shows(SolSurvivorConfig config, SolSurvivorPlugin plugin, WaveView view, SolSurvivorConfig.DoomPlace place)
	{
		return config.doomByOrb() && config.doomPlace() == place && plugin.inArena() && view.underWay && view.doomLimit > 0;
	}

	/** The width of the stacks' box in the graphics' font: its icon, the count and their margins. */
	static int width(Graphics2D graphics, WaveView view)
	{
		return 3 + ICON + 3 + graphics.getFontMetrics().stringWidth(text(view)) + 4;
	}

	/**
	 * Draws the stacks' box with its top left corner at the given point, in the graphics' font: the same box by the orb
	 * and in the movable overlay (DoomBoxOverlay).
	 */
	static void paint(Graphics2D graphics, Icon icon, WaveView view, int left, int top)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		graphics.setColor(GROUND);
		graphics.fillRoundRect(left, top, width(graphics, view), HEIGHT, 6, 6);
		icon.paintIcon(null, graphics, left + 3, top + (HEIGHT - ICON) / 2);
		TextComponent words = new TextComponent();
		words.setText(text(view));
		words.setColor(view.doomLast() ? LAST : TEXT);
		words.setFont(graphics.getFont());
		words.setPosition(new Point(left + 3 + ICON + 3, top + HEIGHT / 2 + metrics.getAscent() / 2));
		words.render(graphics);
	}

	private static String text(WaveView view)
	{
		return view.doomStacks + "/" + view.doomLimit;
	}

	/** The hitpoints orb the game shows now, or null with none on the screen. */
	private Widget healthOrb()
	{
		for (int id : ORBS)
		{
			Widget orb = client.getWidget(id);
			if (orb != null && !orb.isHidden())
			{
				return orb;
			}
		}
		return null;
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;

/**
 * The small drawn icons beside the Screen tab's switches and on New in this update's card (Stefan's pick of 2026-11-08,
 * design B2 of thread "Help first-time plugin installers get set up"): one for each of In the game's features and one for
 * each look of NPCs in range, each a sketch of what the feature draws on the game's screen in its own colours, so that a
 * player can tell the switches apart before seeing them in a wave. They are drawn on a 16 pixel grid with no smoothing,
 * as the game's own icons are, rather than cut from screenshots, which blur at this size.
 */
final class FeatureIcons
{
	static final int SIZE = 16;

	private static final Color INK = new Color(0x0e0c09);
	private static final Color STONE = new Color(0x5b4e3c);
	private static final Color BOX = new Color(0x1e1912);
	private static final Color SAND = new Color(0xb08a55);
	private static final Color CYAN = new Color(0x3fe0ff);
	private static final Color FLESH = new Color(0x8a5a33);
	private static final Color PLAYER = new Color(0x3a6bd0);

	private FeatureIcons()
	{
	}

	/** Draws one 16 pixel icon, crisp: lines and fills fall on whole pixels. */
	private interface Painter
	{
		void paint(Graphics2D g);
	}

	private static ImageIcon draw(Painter p)
	{
		BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		p.paint(g);
		g.dispose();
		return new ImageIcon(image);
	}

	/** A rectangle's outline one pixel wide, `w` by `h` from its top left. */
	private static void frame(Graphics2D g, Color c, int x, int y, int w, int h)
	{
		g.setColor(c);
		g.drawRect(x, y, w - 1, h - 1);
	}

	/** A filled rectangle. */
	private static void fill(Graphics2D g, Color c, int x, int y, int w, int h)
	{
		g.setColor(c);
		g.fillRect(x, y, w, h);
	}

	/**
	 * The icon for In the game's feature `key` (SolSurvivorPanel.IN_GAME), or null for a key with none: the panel then
	 * shows the name alone.
	 */
	static ImageIcon of(String key)
	{
		switch (key)
		{
			case "waveBox":
				// The wave box: a stone box with an orange title and two lines, each with its yellow count.
				return draw(g ->
				{
					fill(g, STONE, 1, 1, 14, 14);
					frame(g, INK, 1, 1, 14, 14);
					fill(g, Stone.ORANGE, 3, 3, 10, 2);
					fill(g, Stone.TEXT, 3, 7, 6, 1);
					fill(g, Stone.YELLOW, 11, 7, 2, 1);
					fill(g, Stone.TEXT, 3, 10, 6, 1);
					fill(g, Stone.YELLOW, 11, 10, 2, 1);
				});
			case "modifiersBar":
				// The modifiers above the chatbox: two slots side by side, each with its picture.
				return draw(g ->
				{
					fill(g, new Color(0x3b3227), 0, 4, 7, 8);
					frame(g, INK, 0, 4, 7, 8);
					fill(g, Stone.BAD, 2, 6, 3, 4);
					fill(g, new Color(0x3b3227), 9, 4, 7, 8);
					frame(g, INK, 9, 4, 7, 8);
					fill(g, new Color(0x9fd8ff), 11, 6, 3, 4);
					fill(g, Stone.YELLOW, 14, 10, 1, 1);
				});
			case "doomByOrb":
				// Doom's stacks: a dark purple orb with a bar of stacks under it, the last one red.
				return draw(g ->
				{
					g.setColor(new Color(0x5b2a7a));
					g.fillOval(4, 1, 8, 8);
					g.setColor(INK);
					g.drawOval(4, 1, 8, 8);
					fill(g, INK, 1, 11, 14, 4);
					fill(g, new Color(0xb070e0), 2, 12, 9, 2);
					fill(g, Stone.BAD, 11, 12, 3, 2);
				});
			case "volatilityReminder":
				// Volatility's blast: an orange burst with a yellow heart.
				return draw(g ->
				{
					g.setColor(new Color(0xff5a1f));
					g.fillPolygon(new int[]{8, 10, 15, 11, 13, 8, 3, 5, 1, 6}, new int[]{0, 5, 4, 8, 15, 11, 15, 8, 4, 5}, 10);
					fill(g, Stone.YELLOW, 6, 6, 4, 4);
				});
			case "offerNames":
				// Minimus's three offers, each with its tier's colour on top: white, blue and purple.
				return draw(g ->
				{
					Color[] tiers = {Color.WHITE, new Color(0x4aa8ff), new Color(0xc070ff)};
					for (int i = 0; i < 3; i++)
					{
						int x = i * 5 + 1;
						fill(g, STONE, x, 3, 4, 11);
						frame(g, INK, x, 3, 4, 11);
						fill(g, tiers[i], x + 1, 4, 2, 2);
					}
				});
			case "npcHitpoints":
				// A hitpoints tag: two numbers on a dark plate over a green bar, the hit on its way in orange.
				return draw(g ->
				{
					fill(g, INK, 0, 3, 16, 10);
					fill(g, Stone.YELLOW, 2, 5, 5, 3);
					fill(g, Stone.TEXT, 9, 5, 5, 3);
					fill(g, Stone.GOOD, 2, 10, 6, 2);
					fill(g, Stone.ORANGE, 8, 10, 3, 2);
					fill(g, new Color(0xa3120c), 11, 10, 3, 2);
				});
			case "highlightInRange":
				// An NPC standing in a cyan tile.
				return draw(g ->
				{
					fill(g, new Color(0x3fe0ff).darker().darker(), 1, 1, 14, 14);
					frame(g, CYAN, 1, 1, 14, 14);
					frame(g, CYAN, 2, 2, 12, 12);
					fill(g, FLESH, 6, 4, 4, 8);
				});
			case "myRange":
				// The player in the middle, the range's outline dashed round them.
				return draw(g ->
				{
					g.setColor(CYAN);
					g.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10, new float[]{2, 2}, 0));
					g.drawRect(1, 1, 13, 13);
					fill(g, PLAYER, 6, 5, 4, 6);
					fill(g, new Color(0xf0c8a0), 7, 3, 2, 2);
				});
			case "npcColours":
				// The warband's three outlines, each in its style's colour: ranged green, magic blue, melee red.
				return draw(g ->
				{
					frame(g, Stone.GOOD, 0, 3, 5, 11);
					frame(g, new Color(0x33a0ff), 5, 3, 5, 11);
					frame(g, Stone.BAD, 11, 3, 5, 11);
				});
			case "tickCounter":
				// A box with a count in it.
				return draw(g ->
				{
					fill(g, BOX, 0, 3, 16, 10);
					frame(g, INK, 0, 3, 16, 10);
					// A "1" and a "7" in white pixels.
					fill(g, Color.WHITE, 4, 5, 1, 6);
					fill(g, Color.WHITE, 3, 6, 1, 1);
					fill(g, Color.WHITE, 8, 5, 4, 1);
					fill(g, Color.WHITE, 11, 6, 1, 2);
					fill(g, Color.WHITE, 10, 8, 1, 3);
				});
			case "waveTimer":
				// A clock's face with its two hands.
				return draw(g ->
				{
					g.setColor(BOX);
					g.fillOval(1, 1, 14, 14);
					g.setColor(Stone.TEXT);
					g.drawOval(1, 1, 13, 13);
					fill(g, Color.WHITE, 7, 4, 2, 5);
					fill(g, Color.WHITE, 9, 7, 3, 2);
				});
			case "hidePillars":
				// A pillar's square on the sand, the pillar itself gone.
				return draw(g ->
				{
					fill(g, SAND, 0, 0, 16, 16);
					frame(g, new Color(0x3a2a18), 3, 3, 10, 10);
					frame(g, new Color(0x3a2a18), 4, 4, 8, 8);
				});
			case "lootTotals":
				// A stack of gold coins.
				return draw(g ->
				{
					for (int i = 0; i < 4; i++)
					{
						fill(g, new Color(0x8a6a00), 3, 12 - i * 3, 10, 3);
						fill(g, Stone.GOLD, 3, 12 - i * 3, 10, 2);
					}
					fill(g, new Color(0xfff2a0), 5, 3, 3, 1);
				});
			case "leftClickBankAll":
				// The reward chest: a wooden box with a gold band and lock.
				return draw(g ->
				{
					fill(g, new Color(0x6b3e1c), 1, 4, 14, 10);
					frame(g, INK, 1, 4, 14, 10);
					fill(g, Stone.GOLD, 2, 8, 12, 1);
					fill(g, Stone.GOLD, 7, 7, 2, 3);
				});
			default:
				return null;
		}
	}

	/** The icon for a look of NPCs in range, a sketch of how it marks an NPC. */
	static ImageIcon look(SolSurvivorConfig.InRangeStyle look)
	{
		switch (look)
		{
			case OUTLINE:
				// The NPC's own outline.
				return draw(g ->
				{
					g.setColor(CYAN);
					g.drawPolyline(new int[]{5, 10, 10, 13, 13, 2, 2, 5, 5}, new int[]{2, 2, 6, 6, 14, 14, 6, 6, 2}, 9);
					fill(g, FLESH, 4, 7, 8, 6);
					fill(g, FLESH, 6, 3, 4, 4);
				});
			case ARROW:
				// An arrow over the NPC's head.
				return draw(g ->
				{
					g.setColor(CYAN);
					g.fillPolygon(new int[]{3, 13, 8}, new int[]{1, 1, 7}, 3);
					g.setColor(INK);
					g.drawPolygon(new int[]{3, 13, 8}, new int[]{1, 1, 7}, 3);
					fill(g, FLESH, 6, 9, 4, 6);
				});
			case BRACKETS:
				// Four corners round the NPC.
				return draw(g ->
				{
					g.setColor(Stone.TEXT);
					int[][] corners = {{1, 1, 1, 1}, {14, 1, -1, 1}, {1, 14, 1, -1}, {14, 14, -1, -1}};
					for (int[] c : corners)
					{
						g.drawLine(c[0], c[1], c[0] + 3 * c[2], c[1]);
						g.drawLine(c[0], c[1], c[0], c[1] + 3 * c[3]);
					}
					fill(g, FLESH, 6, 5, 4, 7);
				});
			case BOLD_TILE:
			default:
				// A bold tile under the NPC, seen at an angle as the game's camera shows it.
				return draw(g ->
				{
					g.setColor(new Color(0x3fe0ff).darker().darker());
					g.fillPolygon(new int[]{1, 8, 15, 8}, new int[]{11, 7, 11, 15}, 4);
					g.setColor(CYAN);
					g.drawPolygon(new int[]{1, 8, 15, 8}, new int[]{11, 7, 11, 15}, 4);
					fill(g, FLESH, 6, 2, 4, 9);
				});
		}
	}
}

package nl.dexanddice.solsurvivor;

import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The boxes' first places in the fixed 765 x 503 client (idea 363, Stefan's pick of 2026-11-08). Its game view is 512 x
 * 334, and RuneLite stacks every box at one corner on top of each other: the wave box, both clocks and Doom's box at
 * the top left come to most of the view's height there, beside the infoboxes RuneLite's own plugins keep in that corner.
 * So in the fixed client the small boxes start at the top centre instead, and the wave box keeps the top left to itself;
 * the modifiers bar keeps the bottom left, which in the fixed client is the view's own corner, clear of the chatbox.
 * <p>
 * Only on a fresh install, once, on its first login, and only for a box the player has not placed: RuneLite keeps a
 * box's place under its name in its own `runelite` group, so a box with either key set is left where it is.
 */
final class FixedLayout
{
	/** RuneLite's config group for the boxes' places (checked in 1.13.6's OverlayManager). */
	static final String GROUP = "runelite";

	/** Where the small boxes start in the fixed client. */
	static final OverlayPosition SMALL_BOXES = OverlayPosition.TOP_CENTER;

	private FixedLayout()
	{
	}

	/** Whether the player placed the box named `name`: snapped it to a corner or dragged it somewhere. */
	static boolean placedByPlayer(String name, Overlaps.Settings settings)
	{
		return settings.get(GROUP, name + "_preferredPosition") != null || settings.get(GROUP, name + "_preferredLocation") != null;
	}
}

package nl.dexanddice.solsurvivor;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import nl.dexanddice.solsurvivor.core.ArenaGeometry;
import nl.dexanddice.solsurvivor.core.TileMarker;

/**
 * The player's own tile markers in the arena, read from what RuneLite's Ground Markers saves, for Arena now's link with
 * "Send my tile markers" on (StatePayload.withMarkers). Ground Markers keeps a region's points in its config group
 * `groundMarker` under `region_<id>`, as a JSON list of {regionId, regionX, regionY, z, color, label}, the colour written
 * "#AARRGGBB" by the client's Gson (checked in RuneLite 1.13.4). The arena's points are under its template's region,
 * where the instance's tiles are marked.
 */
final class GroundMarkers
{
	/** Ground Markers' config group. */
	static final String GROUP = "groundMarker";

	/** The key of the arena's points. */
	static final String KEY = "region_" + ArenaGeometry.REGION_ID;

	/** A point as Ground Markers saves it: the fields its GroundMarkerPoint has. */
	private static final class Point
	{
		int regionId;
		int regionX;
		int regionY;
		int z;
		Color color;
		String label;
	}

	private GroundMarkers()
	{
	}

	/**
	 * The markers of Ground Markers' saved `json` for the arena, on the player's `plane`, in the order it saved them: none
	 * for no text, or text that is not its list. `gson` is the client's, which reads its colours.
	 */
	static List<TileMarker> read(Gson gson, String json, int plane)
	{
		return read(gson, json, plane, null, true);
	}

	/**
	 * The same, for points drawn by another plugin in the same format, Tile Packs: each in `override` rather than its own
	 * colour when that is not null, and without its label unless `labels`.
	 */
	static List<TileMarker> read(Gson gson, String json, int plane, Color override, boolean labels)
	{
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}
		List<Point> points;
		try
		{
			points = gson.fromJson(json, new TypeToken<List<Point>>()
			{
			}.getType());
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return Collections.emptyList();
		}
		List<TileMarker> markers = new ArrayList<>();
		for (Point p : points == null ? Collections.<Point>emptyList() : points)
		{
			Color colour = override != null ? override : p == null ? null : p.color;
			TileMarker m = p == null ? null : TileMarker.of(p.regionId, p.regionX, p.regionY, p.z, plane, colour == null ? null : colour.getRGB(), labels ? p.label : null);
			if (m != null && markers.size() < TileMarker.MAX_MARKERS)
			{
				markers.add(m);
			}
		}
		return markers;
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.AlphaComposite;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.Icon;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The panel's pictures, as the plugin feature designs of 2026-10-26 show them: the NPCs' faces, the modifiers and the
 * marks for a death and an idle stretch, the Sol Survivor site's own, which tools/plugin-icons.mjs takes from its
 * src/ui/icons as 48-pixel PNGs; and the protection prayers, the game's own sprites, which the plugin reads from the game
 * as it starts (put) rather than carry a copy of Jagex's art. Each is drawn at the size a row needs and smoothed down,
 * so that a display scaled to 150% or 200% draws it from more pixels than it shows.
 */
final class Icons
{
	private static final Logger log = LoggerFactory.getLogger(Icons.class);
	private static final Map<String, BufferedImage> IMAGES = new HashMap<>();

	private Icons()
	{
	}

	/** The picture by its name, "npc-javelin", "modifier-doom", "prayer-magic"; null when the plugin has none by it. */
	static synchronized BufferedImage image(String name)
	{
		if (IMAGES.containsKey(name))
		{
			return IMAGES.get(name);
		}
		BufferedImage image = null;
		try (InputStream in = Icons.class.getResourceAsStream("icons/" + name + ".png"))
		{
			if (in != null)
			{
				image = halved(ImageIO.read(in));
			}
		}
		catch (IOException ex)
		{
			log.warn("Could not read the icon {}", name, ex);
		}
		IMAGES.put(name, image);
		return image;
	}

	/** A picture the game gives the plugin, such as a prayer's sprite, under its name. */
	static synchronized void put(String name, BufferedImage image)
	{
		IMAGES.put(name, halved(image));
	}

	/**
	 * The picture as an icon `size` pixels a side, or an empty square of that size while the plugin has none by its name:
	 * it is looked up as it is drawn, so that a sprite the game gives later shows on the panel's next paint.
	 */
	static Icon of(String name, int size)
	{
		return new Scaled(name, size, 1f);
	}

	/** The same, at `alpha`: the dead and the reinforcements still to come are drawn faded. */
	static Icon of(String name, int size, float alpha)
	{
		return new Scaled(name, size, alpha);
	}

	/** An NPC's face by the roster's icon name: "javelin", "archer"; "warband" is the three frems' faces together. */
	static Icon npc(String icon, int size, float alpha)
	{
		if ("warband".equals(icon))
		{
			return new Warband(size, alpha);
		}
		return of("npc-" + icon, size, alpha);
	}

	/**
	 * The Fremennik warband's three faces in one square as big as another NPC's face, so that its name lines up with the
	 * rest: the seer's at the top, the archer's and the berserker's under it, each a little over half the square.
	 */
	private static final class Warband implements Icon
	{
		private final int size;
		private final Icon[] faces;

		Warband(int size, float alpha)
		{
			this.size = size;
			int face = (size * 5 + 4) / 8;
			faces = new Icon[] {of("npc-seer", face, alpha), of("npc-archer", face, alpha), of("npc-berserker", face, alpha)};
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			int face = faces[0].getIconWidth();
			faces[0].paintIcon(c, g, x + (size - face) / 2, y);
			faces[1].paintIcon(c, g, x, y + size - face);
			faces[2].paintIcon(c, g, x + size - face, y + size - face);
		}

		@Override
		public int getIconWidth()
		{
			return size;
		}

		@Override
		public int getIconHeight()
		{
			return size;
		}
	}

	/** A modifier's picture, by its key in the state link ("dynamicDuo"), as the site names its files ("dynamic-duo"). */
	static String modifier(String key)
	{
		return "modifier-" + key.replaceAll("([A-Z])", "-$1").toLowerCase(java.util.Locale.ROOT);
	}

	/**
	 * The picture halved while it is 64 pixels or more: the 48-pixel icons are kept as they are, so that the one smoothing
	 * step down to a row's size reads about two source pixels for each it draws, which bilinear filtering does well and one
	 * long step from many more pixels does not.
	 */
	private static BufferedImage halved(BufferedImage image)
	{
		if (image == null)
		{
			return null;
		}
		BufferedImage out = image;
		while (out.getWidth() >= 64)
		{
			int w = out.getWidth() / 2;
			int h = out.getHeight() / 2;
			BufferedImage half = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = half.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(out, 0, 0, w, h, null);
			g.dispose();
			out = half;
		}
		return out;
	}

	/** A picture by its name, drawn `size` pixels a side, smoothed, at an alpha. */
	static final class Scaled implements Icon
	{
		private final String name;
		private final int size;
		private final float alpha;

		Scaled(String name, int size, float alpha)
		{
			this.name = name;
			this.size = size;
			this.alpha = alpha;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			BufferedImage image = image(name);
			if (image == null)
			{
				return;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
			if (alpha < 1f)
			{
				g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			}
			g2.drawImage(image, x, y, size, size, null);
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return size;
		}

		@Override
		public int getIconHeight()
		{
			return size;
		}
	}
}

package nl.dexanddice.solsurvivor;

import java.io.IOException;
import okhttp3.MediaType;
import okhttp3.RequestBody;
import okio.BufferedSink;

/**
 * A request's body made when OkHttp sends it, on OkHttp's own thread, and kept for a retry: the plugin hands a shared
 * wave log or a run to OkHttp from the client thread, and the JSON or the gzip that takes a few milliseconds is made
 * here rather than on the tick, as RuneLite asks of a plugin. What the body is made of must not change after it is
 * handed over: a WaveLog's snapshot, or the past waves' logs. A body that cannot be made fails the call with its
 * IOException, which the call's onFailure gets.
 */
final class LazyBody extends RequestBody
{
	/** How the body's bytes are made. */
	interface Maker
	{
		byte[] make() throws IOException;
	}

	private final MediaType type;
	private Maker maker;
	private byte[] bytes;

	LazyBody(String type, Maker maker)
	{
		this.type = MediaType.parse(type);
		this.maker = maker;
	}

	/** The bytes, made the first time they are asked for: OkHttp asks for the length before it writes them. */
	private synchronized byte[] bytes() throws IOException
	{
		if (bytes == null)
		{
			bytes = maker.make();
			maker = null;
		}
		return bytes;
	}

	@Override
	public MediaType contentType()
	{
		return type;
	}

	@Override
	public long contentLength() throws IOException
	{
		return bytes().length;
	}

	@Override
	public void writeTo(BufferedSink sink) throws IOException
	{
		sink.write(bytes());
	}
}

package nl.dexanddice.solsurvivor;

import java.util.Locale;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.util.Text;

/**
 * "Loot totals", a setting that is on by default: two lines on Minimus's screen between waves (the user's ask of
 * 2026-10-26, so that Fortis Colosseum's own totals can be switched off for these). The game values the last wave's loot
 * on the left and the next wave's on the right, and totals all the loot so far only at the foot of its list in the
 * screen's second tab. The plugin writes that total under the left's value, what the player would leave with now, and
 * the total with the next wave's added under the right's, what they would leave with after it, both read from the
 * game's own values, never priced by the plugin. The game drops the lines with the screen.
 */
final class LootTotals
{
	static final String NOW = "Total so far";
	static final String AFTER_NEXT = "With the next wave";
	private static final String GP = " GP";

	private LootTotals()
	{
	}

	/** Writes the two lines once the screen is drawn, or sets them again where they are already. On the client thread. */
	static void write(Client client)
	{
		Widget all = client.getWidget(InterfaceID.ColosseumIntermission2.TAB_CONTENT_2_CONTENT);
		Widget left = client.getWidget(InterfaceID.ColosseumIntermission2.LEFT);
		Widget leftValue = client.getWidget(InterfaceID.ColosseumIntermission2.LEFT_LOOT_VALUE);
		Widget right = client.getWidget(InterfaceID.ColosseumIntermission2.RIGHT);
		Widget rightValue = client.getWidget(InterfaceID.ColosseumIntermission2.RIGHT_LOOT_VALUE);
		if (all == null || left == null || leftValue == null)
		{
			return;
		}
		Long total = lastValue(all);
		if (total == null)
		{
			return;
		}
		put(left, leftValue, label(NOW, total));
		Long next = rightValue == null ? null : value(rightValue.getText());
		if (right != null && next != null)
		{
			put(right, rightValue, label(AFTER_NEXT, total + next));
		}
	}

	/** "Total so far:" over the sum in the game's yellow, as two lines. */
	static String label(String what, long gp)
	{
		return what + ":<br><col=ffff00>" + String.format(Locale.UK, "%,d", gp) + GP + "</col>";
	}

	/** A value as the game writes one, "1,234,567 GP"; null for any other text. */
	static Long value(String text)
	{
		if (text == null)
		{
			return null;
		}
		String plain = Text.removeTags(text).trim();
		if (!plain.endsWith(GP))
		{
			return null;
		}
		String digits = plain.substring(0, plain.length() - GP.length()).replace(",", "").trim();
		if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit))
		{
			return null;
		}
		try
		{
			return Long.parseLong(digits);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** The last value in GP among a widget's children: the game's total, at the foot of its list of the loot. */
	private static Long lastValue(Widget list)
	{
		for (Widget[] children : new Widget[][] {list.getDynamicChildren(), list.getStaticChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (int i = children.length - 1; i >= 0; i--)
			{
				Long gp = children[i] == null ? null : value(children[i].getText());
				if (gp != null)
				{
					return gp;
				}
			}
		}
		return null;
	}

	/** The line under the value: the one already written there is set again, so that a redraw adds none. */
	private static void put(Widget side, Widget under, String text)
	{
		String prefix = text.substring(0, text.indexOf(':') + 1);
		Widget[] children = side.getDynamicChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child != null && child.getText() != null && child.getText().startsWith(prefix))
				{
					child.setText(text);
					return;
				}
			}
		}
		side.createChild(WidgetType.TEXT)
			.setText(text)
			.setTextColor(0xffffff)
			.setTextShadowed(true)
			.setFontId(FontID.PLAIN_11)
			.setLineHeight(14)
			.setSize(0, 26, WidgetSizeMode.MINUS, WidgetSizeMode.ABSOLUTE)
			.setPos(0, under.getOriginalY() + 26, WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP)
			.setXTextAlignment(WidgetTextAlignment.CENTER)
			.setYTextAlignment(WidgetTextAlignment.CENTER)
			.revalidate();
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import nl.dexanddice.solsurvivor.core.Modifier;

/**
 * "Modifiers above the chatbox", a setting that is on by default: the modifiers held in a row at the game screen's
 * bottom left, each its picture in a slot with its tier in the corner, as the panel's Modifiers held draws them (the
 * user's ask of 2026-10-26, so that Fortis Colosseum's own row can be switched off for this). RuneLite stacks a box at
 * the bottom left above the chatbox, and the player can move it with Alt. Its Size setting draws the slots, pictures
 * and gaps from 100% to 300% (the user's ask of 2026-10-30), the tiers in the game's larger font from 150%. Its Tiers
 * setting (the design review's 7, 2026-10-31) writes each tier on a dark plate in the slot's corner, where on the bare
 * picture a red tier was lost on a red picture such as Frailty's, or the modifier's name and tier under its slot, each
 * slot then as wide as its name. Each tier is written in the colour the offers on Minimus's screen give it, white for
 * I, blue for II and purple for III (OfferNames, the user's ask of 2026-11-08), and the name beside it in the game's
 * yellow. Facts only: what the game's own list holds.
 */
class ModifiersBarOverlay extends Overlay
{
	private static final int SLOT = 32;
	private static final int ICON = 26;
	private static final int GAP = 2;
	/** The gap between slots with their names under them, so that two names never run into one. */
	private static final int NAME_GAP = 8;
	private static final String[] TIERS = {"I", "II", "III"};
	/** The size from which the tiers are written in the game's larger font, which the small one looks lost beside. */
	private static final int LARGE_FONT_FROM = 150;

	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;
	private final Client client;
	private final TooltipManager tooltipManager;
	/** Each slot's width as last drawn, gaps aside: the slot's, or with names under the slots its name's where wider. */
	private int[] widths = new int[0];
	/** The gap between the slots as last drawn. */
	private int drawnGap;

	@Inject
	ModifiersBarOverlay(SolSurvivorPlugin plugin, SolSurvivorConfig config, Client client, TooltipManager tooltipManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.BOTTOM_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<Modifier, Integer> held = plugin.waveView().held;
		if (!config.modifiersBar() || !plugin.inArena() || held.isEmpty())
		{
			return null;
		}
		int slot = scaled(SLOT);
		int icon = scaled(ICON);
		graphics.setFont(size() >= LARGE_FONT_FROM ? FontManager.getRunescapeFont() : FontManager.getRunescapeSmallFont());
		FontMetrics metrics = graphics.getFontMetrics();
		boolean under = config.modifiersBarTiers() == SolSurvivorConfig.ModifierTiers.NAME_UNDER;
		int gap = scaled(under ? NAME_GAP : GAP);
		int inset = scaled(2);
		int[] drawn = new int[held.size()];
		int at = 0;
		int x = 0;
		for (Map.Entry<Modifier, Integer> e : held.entrySet())
		{
			Modifier modifier = e.getKey();
			String name = modifier.getName(e.getValue());
			int width = under ? Math.max(slot, metrics.stringWidth(name)) : slot;
			drawn[at++] = width;
			graphics.translate(x + (width - slot) / 2, 0);
			Stone.paintWell(graphics, slot, slot);
			Icons.of(Icons.modifier(modifier.getKey()), icon).paintIcon(null, graphics, (slot - icon) / 2, (slot - icon) / 2);
			String tier = tierOf(modifier, e.getValue());
			if (!under && !tier.isEmpty())
			{
				// The tier on a dark plate in the corner, the slot's own outline round it, so that it reads on any picture.
				int pad = scaled(1);
				int plateWidth = metrics.stringWidth(tier) + 2 * pad + 2;
				int plateHeight = metrics.getAscent() + pad + 1;
				graphics.setColor(Stone.OUTLINE);
				graphics.fillRect(slot - plateWidth, slot - plateHeight, plateWidth, plateHeight);
				graphics.setColor(Stone.BEVEL_LIGHT);
				graphics.drawLine(slot - plateWidth, slot - plateHeight, slot - 1, slot - plateHeight);
				graphics.drawLine(slot - plateWidth, slot - plateHeight, slot - plateWidth, slot - 1);
				TextComponent words = new TextComponent();
				words.setText(tier);
				words.setColor(OfferNames.tierColour(e.getValue()));
				words.setFont(graphics.getFont());
				words.setPosition(new Point(slot - pad - 1 - metrics.stringWidth(tier), slot - inset));
				words.render(graphics);
			}
			graphics.translate(-(x + (width - slot) / 2), 0);
			if (under)
			{
				// The name measured bare and drawn with its tier's colour tag, which the text component reads.
				TextComponent words = new TextComponent();
				words.setText(tier.isEmpty() ? name : modifier.getName() + " <col=" + OfferNames.tierColourTag(e.getValue()) + ">" + tier);
				words.setColor(Stone.YELLOW);
				words.setFont(graphics.getFont());
				words.setPosition(new Point(x + (width - metrics.stringWidth(name)) / 2, slot + inset + metrics.getAscent()));
				words.render(graphics);
			}
			x += width + gap;
		}
		widths = drawn;
		drawnGap = gap;
		int height = under ? slot + inset + metrics.getAscent() + metrics.getDescent() : slot;
		return new Dimension(x - gap, height);
	}

	/** The Size setting, kept to its range: a value typed past either end draws at that end. */
	private int size()
	{
		return Math.max(100, Math.min(300, config.modifiersBarSize()));
	}

	/** A length of the bar at 100%, at the size chosen. */
	private int scaled(int length)
	{
		return Math.round(length * size() / 100f);
	}

	/** RuneLite calls this after placing the overlay, so the hovered slot follows it when the player drags it. */
	@Override
	public void onMouseOver()
	{
		if (!config.modifiersBar() || !plugin.inArena())
		{
			return;
		}
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		int x = mouse.getX() - getBounds().x;
		int y = mouse.getY() - getBounds().y;
		int index = slotAt(x, y);
		int at = 0;
		for (Map.Entry<Modifier, Integer> entry : plugin.waveView().held.entrySet())
		{
			if (at++ == index)
			{
				tooltipManager.add(new Tooltip(entry.getKey().getName(entry.getValue())));
				return;
			}
		}
	}

	/** Which slot, as last drawn, is under a point `x`, `y` from the bar's top left: -1 for a gap or none. */
	private int slotAt(int x, int y)
	{
		if (x < 0 || y < 0 || y >= getBounds().height)
		{
			return -1;
		}
		int left = 0;
		for (int i = 0; i < widths.length; i++)
		{
			if (x < left + widths[i])
			{
				return i;
			}
			left += widths[i] + drawnGap;
			if (x < left)
			{
				return -1;
			}
		}
		return -1;
	}

	/** The tier held in roman numerals, "II"; nothing for a modifier without tiers. */
	static String tierOf(Modifier modifier, int tier)
	{
		return modifier.hasTiers() && tier >= 1 && tier <= 3 ? TIERS[tier - 1] : "";
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Point2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import nl.dexanddice.solsurvivor.core.NpcKind;
import nl.dexanddice.solsurvivor.core.WaveReview;

/**
 * Arrows to NPCs out of view (idea 359, Stefan's yes of 2026-11-08), off by default: for each living Colosseum NPC the
 * game view does not show, an arrow on the view's edge in the direction it is from the player, with its short name and
 * how many tiles away it is (the count the game uses for range: the nearest tile of the NPC's square). The arrow goes as
 * the NPC walks into view.
 * <p>
 * Positions only, as the minimap already gives them: the arrow is in the colour of the NPC's attack style, the wave box's
 * "Names by attack style" colours, and the Manticore's stays a neutral grey, as its style changes with its orbs. No arrow
 * says anything of line of sight or range, or of what the NPC will do (the limits Stefan accepted).
 * <p>
 * The direction is taken on the screen, from the player's point towards a point one tile from the player in the NPC's
 * direction, so that it holds for an NPC behind the camera too, which has no point on the screen of its own.
 */
class NpcArrowsOverlay extends Overlay
{
	/** How far in from the view's edge the arrow's tip sits. */
	static final int INSET = 6;
	private static final int ARROW_LENGTH = 14;
	private static final int ARROW_WIDTH = 12;
	private static final Color NEUTRAL = new Color(0xd0d0d0);
	private static final Color SHADOW = new Color(0, 0, 0, 170);

	private final Client client;
	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;

	@Inject
	NpcArrowsOverlay(Client client, SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** The wave box's icon name for a Colosseum NPC's id, which gives its style's colour, or null for any other NPC. */
	static String icon(int npcId)
	{
		switch (npcId)
		{
			case NpcKind.SHAMAN_ID:
				return "shaman";
			case NpcKind.SHOCKWAVE_ID:
				return "shockwave";
			case NpcKind.JAVELIN_ID:
				return "javelin";
			case NpcKind.JAGUAR_ID:
				return "jaguar";
			case NpcKind.MINOTAUR_ID:
			case NpcKind.MINOTAUR_RED_FLAG_ID:
				return "minotaur";
			case NpcKind.MANTICORE_ID:
				return "manticore";
			case WaveReview.FREM_ARCHER_ID:
				return "archer";
			case WaveReview.FREM_SEER_ID:
				return "seer";
			case WaveReview.FREM_BERSERKER_ID:
				return "berserker";
			default:
				return null;
		}
	}

	/** The short name an arrow carries, as the wave box gives it. */
	static String name(String icon)
	{
		switch (icon)
		{
			case "shockwave":
				return "Shockwave";
			case "javelin":
				return "Javelin";
			default:
				return Character.toUpperCase(icon.charAt(0)) + icon.substring(1);
		}
	}

	/** An arrow's colour: its NPC's style's, or neutral grey for the Manticore, whose style changes with its orbs. */
	static Color colour(String icon, SolSurvivorConfig config)
	{
		Color style = WaveBoxOverlay.styleColour(icon, config);
		return style != null ? style : NEUTRAL;
	}

	/**
	 * Where a ray from `from` in the direction (dx, dy) leaves `view`, drawn in by `inset`: the arrow's tip. Null for no
	 * direction. A `from` outside the view starts from the view's centre instead.
	 */
	static Point2D.Double edge(Rectangle view, Point2D from, double dx, double dy, int inset)
	{
		double length = Math.hypot(dx, dy);
		if (length == 0 || view.width <= 2 * inset || view.height <= 2 * inset)
		{
			return null;
		}
		double left = view.x + inset;
		double top = view.y + inset;
		double right = view.x + view.width - inset;
		double bottom = view.y + view.height - inset;
		double x0 = from.getX();
		double y0 = from.getY();
		if (x0 < left || x0 > right || y0 < top || y0 > bottom)
		{
			x0 = view.getCenterX();
			y0 = view.getCenterY();
		}
		double ux = dx / length;
		double uy = dy / length;
		double t = Double.MAX_VALUE;
		if (ux > 0)
		{
			t = Math.min(t, (right - x0) / ux);
		}
		else if (ux < 0)
		{
			t = Math.min(t, (left - x0) / ux);
		}
		if (uy > 0)
		{
			t = Math.min(t, (bottom - y0) / uy);
		}
		else if (uy < 0)
		{
			t = Math.min(t, (top - y0) / uy);
		}
		return new Point2D.Double(x0 + ux * t, y0 + uy * t);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		SolSurvivorConfig.NpcArrows mode = config.npcArrows();
		Player me = client.getLocalPlayer();
		if (mode == SolSurvivorConfig.NpcArrows.OFF || !plugin.inArena() || me == null)
		{
			return null;
		}
		WorldView world = client.getTopLevelWorldView();
		LocalPoint mine = me.getLocalLocation();
		if (world == null || mine == null)
		{
			return null;
		}
		int plane = world.getPlane();
		Point myPoint = Perspective.localToCanvas(client, mine, plane);
		if (myPoint == null)
		{
			return null;
		}
		Rectangle view = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(), client.getViewportWidth(),
			client.getViewportHeight());
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setFont(FontManager.getRunescapeSmallFont());
		for (NPC npc : world.npcs())
		{
			String icon = icon(npc.getId());
			LocalPoint at = npc.getLocalLocation();
			if (icon == null || npc.isDead() || at == null)
			{
				continue;
			}
			Point seen = Perspective.localToCanvas(client, at, plane, npc.getLogicalHeight() / 2);
			if (seen != null && view.contains(seen.getX(), seen.getY()))
			{
				continue;
			}
			// One tile from the player towards the NPC, on the screen: the arrow's direction there.
			double dx = at.getX() - mine.getX();
			double dy = at.getY() - mine.getY();
			double length = Math.hypot(dx, dy);
			if (length == 0)
			{
				continue;
			}
			LocalPoint step = new LocalPoint(mine.getX() + (int) Math.round(dx / length * Perspective.LOCAL_TILE_SIZE),
				mine.getY() + (int) Math.round(dy / length * Perspective.LOCAL_TILE_SIZE), world);
			Point toward = Perspective.localToCanvas(client, step, plane);
			if (toward == null)
			{
				continue;
			}
			double sx = toward.getX() - myPoint.getX();
			double sy = toward.getY() - myPoint.getY();
			Point2D.Double tip = edge(view, new Point2D.Double(myPoint.getX(), myPoint.getY()), sx, sy, INSET);
			if (tip == null)
			{
				continue;
			}
			Color colour = colour(icon, config);
			double angle = Math.atan2(sy, sx);
			drawArrow(graphics, tip, angle, colour);
			if (mode == SolSurvivorConfig.NpcArrows.NAME_AND_DISTANCE)
			{
				WorldArea area = npc.getWorldArea();
				int tiles = area == null ? -1 : area.distanceTo(me.getWorldLocation());
				String label = name(icon) + (tiles >= 0 && tiles < 100 ? " " + tiles : "");
				drawLabel(graphics, view, tip, angle, label, colour);
			}
		}
		return null;
	}

	/** A filled arrowhead with its tip at `tip`, pointing along `angle`, outlined in black so that it reads on the floor. */
	private static void drawArrow(Graphics2D graphics, Point2D.Double tip, double angle, Color colour)
	{
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		double baseX = tip.x - cos * ARROW_LENGTH;
		double baseY = tip.y - sin * ARROW_LENGTH;
		double half = ARROW_WIDTH / 2.0;
		Polygon arrow = new Polygon();
		arrow.addPoint((int) Math.round(tip.x), (int) Math.round(tip.y));
		arrow.addPoint((int) Math.round(baseX - sin * half), (int) Math.round(baseY + cos * half));
		arrow.addPoint((int) Math.round(baseX + sin * half), (int) Math.round(baseY - cos * half));
		graphics.setColor(colour);
		graphics.fillPolygon(arrow);
		graphics.setStroke(new BasicStroke(1.5f));
		graphics.setColor(SHADOW);
		graphics.drawPolygon(arrow);
	}

	/** The arrow's name and distance just inside it, kept within the view. */
	private static void drawLabel(Graphics2D graphics, Rectangle view, Point2D.Double tip, double angle, String label, Color colour)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int width = metrics.stringWidth(label);
		double back = ARROW_LENGTH + 4 + Math.abs(Math.cos(angle)) * width / 2.0 + Math.abs(Math.sin(angle)) * metrics.getAscent() / 2.0;
		double cx = tip.x - Math.cos(angle) * back;
		double cy = tip.y - Math.sin(angle) * back;
		int x = (int) Math.round(Math.max(view.x + 2, Math.min(view.x + view.width - width - 2, cx - width / 2.0)));
		int y = (int) Math.round(Math.max(view.y + metrics.getAscent() + 2, Math.min(view.y + view.height - 2, cy + metrics.getAscent() / 2.0)));
		graphics.setColor(Color.BLACK);
		graphics.drawString(label, x + 1, y + 1);
		graphics.setColor(colour);
		graphics.drawString(label, x, y);
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import nl.dexanddice.solsurvivor.core.NpcKind;
import nl.dexanddice.solsurvivor.core.WaveReview;

/**
 * "Frem and orb colours", a setting that is on by default: each Fremennik of the warband outlined in the colour of its
 * attack style, the archer's, the seer's and the berserker's, and the tile under each of Solarflare's orbs outlined in
 * its own colour. Players set this up by hand today, pasting NPC ids and colours into Better NPC Highlight (a community
 * Colosseum FAQ hands out the codes, checked 2026-11-02; Stefan's choice of the same day to build it in). It colours
 * NPCs by what they are, as Better NPC Highlight does on the Hub, and says nothing of when they attack or where to stand.
 * The style of each Fremennik is the one the prayer record already reads (core.PrayerFlicks).
 */
class NpcColoursOverlay extends Overlay
{
	/** The outline round a Fremennik's model, in pixels, and how far it feathers. */
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 2;
	/** How strongly an orb's tile is filled, out of 255, under its outline. */
	private static final int ORB_FILL_ALPHA = 40;

	private final Client client;
	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;
	private final ModelOutlineRenderer outlines;

	@Inject
	NpcColoursOverlay(Client client, SolSurvivorPlugin plugin, SolSurvivorConfig config, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/** The colour an NPC is drawn in, by its id: a Fremennik's style's or the orb's, null for any other NPC. */
	static Color colourFor(int npcId, SolSurvivorConfig config)
	{
		switch (npcId)
		{
			case WaveReview.FREM_ARCHER_ID:
				return config.fremArcherColour();
			case WaveReview.FREM_SEER_ID:
				return config.fremSeerColour();
			case WaveReview.FREM_BERSERKER_ID:
				return config.fremBerserkerColour();
			case NpcKind.SOLARFLARE_ORB_ID:
				return config.orbColour();
			default:
				return null;
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.npcColours() || !plugin.inArena())
		{
			return null;
		}
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			Color colour = colourFor(npc.getId(), config);
			if (colour == null || colour.getAlpha() == 0 || npc.isDead())
			{
				continue;
			}
			if (npc.getId() == NpcKind.SOLARFLARE_ORB_ID)
			{
				// The orb is small and floats: its tile is what the player reads, so the tile is outlined, not the model.
				Polygon poly = npc.getCanvasTilePoly();
				if (poly != null)
				{
					Color fill = new Color(colour.getRed(), colour.getGreen(), colour.getBlue(),
						Math.min(ORB_FILL_ALPHA, colour.getAlpha()));
					OverlayUtil.renderPolygon(graphics, poly, colour, fill, graphics.getStroke());
				}
			}
			else
			{
				outlines.drawOutline(npc, OUTLINE_WIDTH, colour, OUTLINE_FEATHER);
			}
		}
		return null;
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;
import nl.dexanddice.solsurvivor.core.NpcHitpoints;

/**
 * "NPC hitpoints", a setting that is on by default: a stone tag over each of the wave's NPCs' heads, its hitpoints in
 * the game's yellow against its full hitpoints in grey, as "172/250", over a thin bar of the share left (design B,
 * "Stone tag", of the NPC hitpoints designs of 2026-10-30, the user's choice). The number goes red at a quarter or
 * fewer and green at full health (the user's choice, 2026-10-30), a heal shows in pink for a few ticks, and "~" leads the number while only the game's health bar gives it
 * (core.NpcHitpoints). The tag wears the Doom box's ground, so the plugin's boxes on the game's screen look alike, and
 * sits above the game's own health bar and overhead icons rather than over them. Facts only, as the Doom box: nothing
 * of which NPC to attack. With "Your hit on its way" on, a hit the player has thrown that has not landed shows as
 * "172 › 131/250", what will be left in orange, or a red 0 when it kills, and its share of the bar in the same colour
 * (design 2, "Arrow forecast", of the predicted hit designs of 2026-11-08, the user's choice).
 */
class NpcHitpointsOverlay extends Overlay
{
	/** How far above an NPC's head the tag's foot sits, in local units, clear of the game's health bar. */
	private static final int ABOVE_HEAD = 60;
	private static final int PAD_X = 7;
	/** The narrowest tag, so that a short number such as a shaman's still has a bar long enough to read. */
	private static final int MIN_WIDTH = 64;
	private static final int BAR = 2;
	private static final Color GROUND = new Color(0x1a, 0x16, 0x12, 225);
	private static final Color LOW = new Color(0xff3c3c);
	private static final Color HEAL = new Color(0xff6fcf);
	private static final Color BAR_LEFT = new Color(0x22c32e);
	private static final Color BAR_GONE = new Color(0x5a1610);
	private static final Color HATCH = new Color(255, 255, 255, 160);
	private static final String ARROW = " \u203a ";

	private final Client client;
	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;

	@Inject
	NpcHitpointsOverlay(Client client, SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.npcHitpoints() || !plugin.inArena())
		{
			return null;
		}
		graphics.setFont(FontManager.getRunescapeSmallFont());
		NpcHitpoints hitpoints = plugin.npcHitpoints();
		int tick = client.getTickCount();
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			NpcHitpoints.Reading reading = hitpoints.reading(npc.getIndex(), tick);
			if (reading == null || reading.hitpoints <= 0 || npc.isDead())
			{
				continue;
			}
			if (!config.hitForecast())
			{
				reading = reading.withoutIncoming();
			}
			Point at = npc.getCanvasTextLocation(graphics, "", npc.getLogicalHeight() + ABOVE_HEAD);
			if (at != null)
			{
				paint(graphics, reading, at.getX(), at.getY());
			}
		}
		return null;
	}

	/** Draws one tag, centred across at `x`, its foot at `y`. */
	static void paint(Graphics2D graphics, NpcHitpoints.Reading reading, int x, int y)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		String number = (reading.estimated ? "~" : "") + reading.hitpoints;
		String max = "/" + reading.max;
		String healed = reading.healed > 0 ? " +" + reading.healed : "";
		String after = reading.incoming > 0 ? String.valueOf(reading.after()) : "";
		String arrow = after.isEmpty() ? "" : ARROW;
		int words = metrics.stringWidth(number) + metrics.stringWidth(arrow) + metrics.stringWidth(after)
			+ metrics.stringWidth(max) + metrics.stringWidth(healed);
		int width = Math.max(MIN_WIDTH, PAD_X + words + PAD_X);
		int textHeight = metrics.getAscent();
		int height = 2 + textHeight + 3 + BAR + 2;
		int left = x - width / 2;
		int top = y - height;

		graphics.setColor(GROUND);
		graphics.fillRoundRect(left, top, width, height, 6, 6);

		int baseline = top + 2 + textHeight;
		int cursor = left + (width - words) / 2;
		cursor = text(graphics, number, colour(reading), cursor, baseline);
		if (!after.isEmpty())
		{
			cursor = text(graphics, arrow, Stone.MUTED, cursor, baseline);
			cursor = text(graphics, after, forecastColour(reading), cursor, baseline);
		}
		cursor = text(graphics, max, Stone.MUTED, cursor, baseline);
		if (!healed.isEmpty())
		{
			text(graphics, healed, HEAL, cursor, baseline);
		}

		int barLeft = left + PAD_X;
		int barWidth = width - 2 * PAD_X;
		int barTop = top + height - 2 - BAR;
		int now = share(barWidth, reading.hitpoints, reading.max);
		int before = share(barWidth, reading.hitpoints - reading.healed, reading.max);
		graphics.setColor(BAR_GONE);
		graphics.fillRect(barLeft, barTop, barWidth, BAR);
		graphics.setColor(BAR_LEFT);
		graphics.fillRect(barLeft, barTop, before, BAR);
		if (now > before)
		{
			graphics.setColor(HEAL);
			graphics.fillRect(barLeft + before, barTop, now - before, BAR);
		}
		if (reading.incoming > 0)
		{
			// The share of the bar the hit on its way will take.
			int rest = share(barWidth, reading.after(), reading.max);
			graphics.setColor(forecastColour(reading));
			graphics.fillRect(barLeft + rest, barTop, Math.max(0, now - rest), BAR);
		}
		if (reading.estimated)
		{
			// A few dotted pixels past the bar's end, as the range the game's bar leaves open.
			graphics.setColor(HATCH);
			int band = Math.max(2, barWidth / 12);
			for (int i = 0; i < band && now + i < barWidth; i += 2)
			{
				graphics.fillRect(barLeft + now + i, barTop, 1, BAR);
			}
		}
	}

	/**
	 * The number's colour: red at a quarter or fewer, green at full health counted exactly, and the game's yellow between,
	 * and for full health the bar alone gives, which may not be quite full.
	 */
	static Color colour(NpcHitpoints.Reading reading)
	{
		if (reading.low())
		{
			return LOW;
		}
		return reading.hitpoints == reading.max && !reading.estimated ? Stone.GOOD : Stone.YELLOW;
	}

	/** The forecast's colour: red when the hit on its way kills, orange otherwise. */
	static Color forecastColour(NpcHitpoints.Reading reading)
	{
		return reading.after() == 0 ? LOW : Stone.ORANGE;
	}

	/** Draws `words` with the game's one-pixel shadow and returns where the next words start. */
	private static int text(Graphics2D graphics, String words, Color colour, int x, int baseline)
	{
		TextComponent component = new TextComponent();
		component.setText(words);
		component.setColor(colour);
		component.setFont(graphics.getFont());
		component.setPosition(new java.awt.Point(x, baseline));
		component.render(graphics);
		return x + graphics.getFontMetrics().stringWidth(words);
	}

	/** The pixels of a bar `width` wide that `part` of `whole` fills, at least one for anything above 0. */
	private static int share(int width, int part, int whole)
	{
		if (part <= 0)
		{
			return 0;
		}
		return Math.max(1, width * Math.min(part, whole) / whole);
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Color;
import java.util.List;
import java.util.function.ToIntFunction;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import nl.dexanddice.solsurvivor.core.Modifier;

/**
 * The names of Minimus's three offers, written on his screen under each offer's picture: the modifier's name in white
 * and the tier taking it brings in that tier's colour, "Frailty III", as the panel's pick names them (the user's ask of
 * 2026-10-26, so that Fortis Colosseum's names on the selector can be switched off for these). The game's screen draws
 * the pictures alone; the plugin adds a line of text to each offer's button, which the game drops with the screen.
 */
final class OfferNames
{
	/** The three offers' buttons on Minimus's screen, in the order the selector's script names the offers. */
	private static final int[] BUTTONS = {InterfaceID.ColosseumIntermission2.MOD_BUTTON_1, InterfaceID.ColosseumIntermission2.MOD_BUTTON_2,
		InterfaceID.ColosseumIntermission2.MOD_BUTTON_3};
	/**
	 * The colour of an offer's tier by the tier taking it brings: white for I, as the name, blue for II, purple for III.
	 * Neither good nor bad, so that the colour tells the tier and nothing of which offer to take (the user's choice of
	 * 2026-10-26, over green, yellow and red; tier I white rather than light blue, the user's of 2026-10-27).
	 */
	private static final String[] TIER_COLOURS = {"ffffff", "4a8cff", "c070ff"};

	/**
	 * Tier `tier`'s colour, 1 to 3, as written on the offers, for the modifiers bar to write a tier held in the same
	 * colours (the user's ask of 2026-11-08).
	 */
	static Color tierColour(int tier)
	{
		return new Color(Integer.parseInt(TIER_COLOURS[Math.max(1, Math.min(3, tier)) - 1], 16));
	}

	/** Tier `tier`'s colour, 1 to 3, as the hex a `<col=...>` tag takes. */
	static String tierColourTag(int tier)
	{
		return TIER_COLOURS[Math.max(1, Math.min(3, tier)) - 1];
	}

	private OfferNames()
	{
	}

	/**
	 * Writes each offer's name on its button, once: the screen's scripts run again as the player hovers and picks, and a
	 * button that has its line already keeps it. `held` gives the tier held of a modifier, 0 for none. On the client
	 * thread.
	 */
	static void write(Client client, List<Modifier> options, ToIntFunction<Modifier> held)
	{
		for (int i = 0; i < BUTTONS.length && i < options.size(); i++)
		{
			Modifier offer = options.get(i);
			Widget button = client.getWidget(BUTTONS[i]);
			if (offer == null || button == null)
			{
				continue;
			}
			String text = label(offer, held.applyAsInt(offer));
			if (has(button, text))
			{
				continue;
			}
			button.createChild(WidgetType.TEXT)
				.setText(text)
				.setTextColor(0xffffff)
				.setTextShadowed(true)
				.setFontId(FontID.PLAIN_11)
				.setSize(0, 0, WidgetSizeMode.MINUS, WidgetSizeMode.MINUS)
				.setPos(0, 2, WidgetPositionMode.ABSOLUTE_CENTER, WidgetPositionMode.ABSOLUTE_BOTTOM)
				.setXTextAlignment(WidgetTextAlignment.CENTER)
				.setYTextAlignment(WidgetTextAlignment.BOTTOM)
				.revalidate();
		}
	}

	/**
	 * "Frailty <col=c070ff>III</col>": the name in the screen's white and the tier taking it brings in that tier's colour;
	 * a modifier without tiers by its name alone.
	 */
	static String label(Modifier offer, int held)
	{
		if (!offer.hasTiers())
		{
			return offer.getName();
		}
		int tier = Math.min(3, held + 1);
		String name = offer.getName();
		String numeral = offer.getName(tier).substring(name.length()).trim();
		return name + " <col=" + TIER_COLOURS[tier - 1] + ">" + numeral + "</col>";
	}

	private static boolean has(Widget button, String text)
	{
		Widget[] children = button.getDynamicChildren();
		if (children == null)
		{
			return false;
		}
		for (Widget child : children)
		{
			if (child != null && child.getType() == WidgetType.TEXT && text.equals(child.getText()))
			{
				return true;
			}
		}
		return false;
	}
}

package nl.dexanddice.solsurvivor;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
import nl.dexanddice.solsurvivor.core.WaveReview;

/**
 * Which of In the game's features another enabled plugin also draws, for the panel's "also" marks (idea 375, design B,
 * Stefan's pick of 2026-11-08). Each rule names one of our features, the other plugin as the Plugin Hub lists it, the
 * setting of its that draws the same, and how to read whether that setting is on. The plugin only reads those settings,
 * never writes them: a Hub plugin leaves another plugin's settings alone, so the mark tells the player where to look.
 * <p>
 * The settings were checked in each plugin's source on 8 November 2026, at the commit the Plugin Hub builds where it
 * could be fetched: Fortis Colosseum (config group `fortiscolosseum`), Tzhaar/Colo HP Tracker (`TzhaarHPTracker`),
 * Attack Ranges (`attackRanges`), Visual Metronome (`visualmetronome`), Tzhaar/Colo Additions (`TzhaarColoAdditions`)
 * and Better NPC Highlight (`BetterNpcHighlight`). A setting the player never changed is not stored, so a null reads as
 * that plugin's default, which each rule spells out.
 */
final class Overlaps
{
	/** Reads another plugin's stored setting, null when it holds its default. */
	interface Settings
	{
		String get(String group, String key);
	}

	/** One overlap: our feature's key, the other plugin's name, where its setting is, and whether that setting draws. */
	static final class Rule
	{
		final String ours;
		final String plugin;
		final String setting;
		final Predicate<Settings> draws;

		Rule(String ours, String plugin, String setting, Predicate<Settings> draws)
		{
			this.ours = ours;
			this.plugin = plugin;
			this.setting = setting;
			this.draws = draws;
		}
	}

	static final String FORTIS = "Fortis Colosseum";
	static final String HP_TRACKER = "Tzhaar/Colo HP Tracker";
	static final String ATTACK_RANGES = "Attack Ranges";
	static final String METRONOME = "Visual Metronome";
	static final String ADDITIONS = "Tzhaar/Colo Additions";
	static final String BETTER_NPC_HIGHLIGHT = "Better NPC Highlight";

	/** The config groups the rules read, and RuneLite's own, which holds which plugins are on. */
	static final Set<String> GROUPS = new HashSet<>(Arrays.asList("fortiscolosseum", "TzhaarHPTracker", "attackRanges",
		"visualmetronome", "TzhaarColoAdditions", "BetterNpcHighlight", "runelite"));

	/** Better NPC Highlight's lists of NPC ids, each a highlight of its own. */
	private static final String[] HIGHLIGHT_ID_LISTS = {"tileIds", "trueTileIds", "swTileIds", "swTrueTileIds", "hullIds",
		"areaIds", "outlineIds", "clickboxIds"};

	/** The Fremennik warband's ids, which Frem and orb colours outline. */
	private static final Set<String> FREM_IDS = new HashSet<>(Arrays.asList(Integer.toString(WaveReview.FREM_ARCHER_ID),
		Integer.toString(WaveReview.FREM_SEER_ID), Integer.toString(WaveReview.FREM_BERSERKER_ID)));

	static final List<Rule> RULES = Collections.unmodifiableList(Arrays.asList(
		new Rule("waveBox", FORTIS, "Waves Overlay, Display", s -> !"OFF".equals(s.get("fortiscolosseum", "wavesOverlayMode"))),
		new Rule("modifiersBar", FORTIS, "Modifiers, Overlay Enabled", s -> on(s.get("fortiscolosseum", "modifiersOverlayEnabled"), true)),
		new Rule("volatilityReminder", FORTIS, "Modifiers, Volatility Reminder", s -> on(s.get("fortiscolosseum", "volatilityReminder"), false)),
		new Rule("offerNames", FORTIS, "Modifiers, Show Names on Selector", s -> on(s.get("fortiscolosseum", "modifiersNamesOnSelectWidget"), true)),
		new Rule("waveTimer", FORTIS, "Splits, Overlay Panel", s -> isSet(s.get("fortiscolosseum", "splitsOverlayMode"), "OFF")),
		new Rule("lootTotals", FORTIS, "Loot Interface, Show Loot Total", s -> !"OFF".equals(s.get("fortiscolosseum", "lootInterfaceShowTotal"))),
		new Rule("leftClickBankAll", FORTIS, "Loot Interface, Left-Click Bank-All", s -> on(s.get("fortiscolosseum", "leftClickBankAll"), true)),
		new Rule("npcHitpoints", HP_TRACKER, "Highlight Settings, Show HP", s -> !"OFF".equals(s.get("TzhaarHPTracker", "showHp"))),
		new Rule("myRange", ATTACK_RANGES, "Options, Display Overlay", s -> !"OFF".equals(s.get("attackRanges", "playerEnableState"))),
		new Rule("highlightInRange", ATTACK_RANGES, "Options, Highlight NPCs", s -> isSet(s.get("attackRanges", "npcHighlightEnableState"), "OFF")),
		// The metronome's own box carries no number; it counts ticks only with one of its two tick numbers on.
		new Rule("tickCounter", METRONOME, "Tick Number Settings, Show Metronome Tick Number",
			s -> on(s.get("visualmetronome", "enableMetronome"), true)
				&& (on(s.get("visualmetronome", "showTick"), false) || on(s.get("visualmetronome", "showPlayerTick"), false))),
		new Rule("hidePillars", ADDITIONS, "Colosseum, Hide Colosseum pillars", s -> on(s.get("TzhaarColoAdditions", "hideColosseumPillars"), true)),
		new Rule("npcColours", BETTER_NPC_HIGHLIGHT, "the Fremennik ids in its highlight ID lists", Overlaps::listsFrems)
	));

	private Overlaps()
	{
	}

	/**
	 * Each of our features that an enabled plugin also draws, in RULES' order, with its mark: the first such plugin's
	 * short name, and the tooltip's line, which names each plugin and the setting of its that draws the same. `enabled`
	 * holds the names of the plugins on.
	 */
	static Map<String, String[]> find(Collection<String> enabled, Settings settings)
	{
		Map<String, List<Rule>> found = new LinkedHashMap<>();
		for (Rule rule : RULES)
		{
			if (enabled.contains(rule.plugin) && rule.draws.test(settings))
			{
				found.computeIfAbsent(rule.ours, k -> new ArrayList<>()).add(rule);
			}
		}
		Map<String, String[]> marks = new LinkedHashMap<>();
		for (Map.Entry<String, List<Rule>> e : found.entrySet())
		{
			StringBuilder tip = new StringBuilder();
			for (Rule rule : e.getValue())
			{
				tip.append(tip.length() == 0 ? "" : " ").append(rule.plugin).append(" also draws this: its setting ")
					.append(rule.setting).append('.');
			}
			tip.append(" Switch off ours here, or theirs in its settings, to see it once.");
			marks.put(e.getKey(), new String[]{shortName(e.getValue().get(0).plugin), tip.toString()});
		}
		return marks;
	}

	/** The short name a mark shows: Fortis Colosseum as "Fortis", the HP Tracker as "HP Tracker" and so on. */
	static String shortName(String plugin)
	{
		switch (plugin)
		{
			case FORTIS:
				return "Fortis";
			case HP_TRACKER:
				return "HP Tracker";
			case ADDITIONS:
				return "Colo Additions";
			case BETTER_NPC_HIGHLIGHT:
				return "NPC Highlight";
			case METRONOME:
				return "Metronome";
			default:
				return plugin;
		}
	}

	/** A stored boolean, or the plugin's default when it holds none. */
	private static boolean on(String stored, boolean byDefault)
	{
		return stored == null ? byDefault : Boolean.parseBoolean(stored);
	}

	/** Whether a choice whose default is `off` is set to something else. */
	private static boolean isSet(String stored, String off)
	{
		return stored != null && !off.equals(stored);
	}

	/** Whether any of Better NPC Highlight's ID lists names a Fremennik, whose outline ours draws too. */
	private static boolean listsFrems(Settings settings)
	{
		for (String key : HIGHLIGHT_ID_LISTS)
		{
			String list = settings.get("BetterNpcHighlight", key);
			if (list == null)
			{
				continue;
			}
			for (String id : list.split("[,\\s]+"))
			{
				if (FREM_IDS.contains(id.trim()))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package nl.dexanddice.solsurvivor;

import java.util.Set;
import java.util.function.BooleanSupplier;
import net.runelite.api.Actor;
import net.runelite.api.GameObject;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.callback.RenderCallback;
import nl.dexanddice.solsurvivor.core.ArenaGeometry;

/**
 * Keeps the game from drawing the arena's four pillars while "Hide the pillars" is on, as the Tzhaar/Colo Additions
 * plugin on the Plugin Hub does with a setting of its own. Only the drawing goes: the game still keeps the pillars'
 * tiles out of the player's path and line of sight, and PillarOverlay marks those tiles flat on the floor. RuneLite asks
 * about each object as it builds the scene, so a change to the setting shows once the scene is built again, which the
 * plugin asks for while the player is in the arena.
 */
final class PillarHider implements RenderCallback
{
	/** The arena's pillars, the two models its four pillars are drawn with. */
	private static final Set<Integer> PILLARS = Set.of(ObjectID.PILLAR_CIVITAS01_COLOSSEUM01,
		ObjectID.PILLAR_CIVITAS01_COLOSSEUM02);

	private final BooleanSupplier on;

	PillarHider(BooleanSupplier on)
	{
		this.on = on;
	}

	@Override
	public boolean drawObject(Scene scene, TileObject object)
	{
		return !on.getAsBoolean() || !isArenaPillar(scene, object);
	}

	/**
	 * Whether the object is one of the arena's pillars: a pillar's model, in the arena's region by the scene's own
	 * instance template, so that the answer needs nothing of where the player stands while the scene is being built.
	 * The scene holds the NPCs and the players as objects too, which are never hidden.
	 */
	static boolean isArenaPillar(Scene scene, TileObject object)
	{
		if (!isPillarModel(object))
		{
			return false;
		}
		LocalPoint lp = object.getLocalLocation();
		return lp != null && WorldPoint.fromLocalInstance(scene, lp, object.getPlane()).getRegionID() == ArenaGeometry.REGION_ID;
	}

	/** Whether the object is drawn with a pillar's model, wherever it stands: an NPC or a player never is. */
	static boolean isPillarModel(TileObject object)
	{
		return object instanceof GameObject && PILLARS.contains(object.getId())
			&& !(((GameObject) object).getRenderable() instanceof Actor);
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * What "Hide the pillars" leaves on the floor (the user's ask of 2026-10-27): each hidden pillar's three by three tiles,
 * filled faintly and outlined flat on the ground in "Hidden pillars' colour", so that the player still sees where they
 * cannot walk once the pillar is gone. It marks the very objects the hider keeps from being drawn, where the game holds
 * them, and nothing else: no tile to stand on and no line of sight.
 */
class PillarOverlay extends Overlay
{
	/** How much fainter the fill is than the outline: the outline's opacity divided by this. */
	private static final int FILL_SHARE = 3;

	private final Client client;
	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;
	/** The objects drawn with a pillar's model that the scene spawned; which are the arena's is asked as they are drawn. */
	private final List<GameObject> pillars = new ArrayList<>();

	@Inject
	PillarOverlay(Client client, SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/** An object the scene spawned: kept if it is drawn with a pillar's model, whatever the setting. On the client thread. */
	void spawned(GameObject object)
	{
		if (PillarHider.isPillarModel(object))
		{
			pillars.add(object);
		}
	}

	/** An object the scene took away. On the client thread. */
	void despawned(GameObject object)
	{
		pillars.remove(object);
	}

	/** Forgets the pillars: the scene is loading again and spawns its objects anew, or the plugin stopped. */
	void clear()
	{
		pillars.clear();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Color colour = config.hiddenPillarsColour();
		if (pillars.isEmpty() || !config.hidePillars() || !plugin.inArena() || colour.getAlpha() == 0)
		{
			return null;
		}
		Color fill = new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), colour.getAlpha() / FILL_SHARE);
		graphics.setStroke(new BasicStroke(2));
		for (GameObject pillar : footprints(client.getTopLevelWorldView().getScene(), pillars))
		{
			// A pillar's local location is the middle of the tiles it stands on.
			Polygon poly = Perspective.getCanvasTileAreaPoly(client, pillar.getLocalLocation(), pillar.sizeX(), pillar.sizeY(),
				pillar.getPlane(), 0);
			if (poly != null)
			{
				graphics.setColor(fill);
				graphics.fill(poly);
				graphics.setColor(colour);
				graphics.draw(poly);
			}
		}
		return null;
	}

	/**
	 * The arena's pillars among the objects, as the hider finds them in the scene, one for each footprint: a pillar the
	 * game drew with both models would otherwise be filled twice, darker than the rest.
	 */
	static List<GameObject> footprints(Scene scene, Collection<GameObject> objects)
	{
		List<GameObject> out = new ArrayList<>();
		Set<Point> seen = new HashSet<>();
		for (GameObject object : objects)
		{
			if (PillarHider.isArenaPillar(scene, object) && seen.add(object.getSceneMinLocation()))
			{
				out.add(object);
			}
		}
		return out;
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import nl.dexanddice.solsurvivor.core.NpcKind;
import nl.dexanddice.solsurvivor.core.WaveRoster;

/**
 * The player's attack range on the floor and the NPCs in it, two settings, the first off by default and the second on: "My attack range"
 * outlines the tiles the player can hit from where they stand, their weapon's range with Myopia's cut (core.WeaponRange)
 * and in their line of sight, which RuneLite's WorldArea works out from the game's own collision data; "Highlight NPCs
 * in range" outlines the NPCs they can hit, any of whose tiles is in that range and in sight, as RuneLite's Attack Ranges
 * and Dynamic line of sight plugins do, in the look the player picks (SolSurvivorConfig.InRangeStyle). Both say where the player can attack from, never where to stand or what to do.
 * The tiles and the NPCs are worked out once a tick, on the client thread (update), and drawn each frame from those.
 */
class RangeOverlay extends Overlay
{
	/** Half a tile in local units, from a tile's centre to its edge. */
	private static final int HALF_TILE = Perspective.LOCAL_TILE_SIZE / 2;
	/** How strongly the tiles in range are filled, out of 255, under their outline. */
	private static final int FILL_ALPHA = 28;
	/** How strongly a bold tile under an NPC in range is filled, out of 255. */
	private static final int BOLD_FILL_ALPHA = 80;
	/** The model outline's width and feather in pixels, wider than NPC colours' own so that the two tell apart. */
	private static final int OUTLINE_WIDTH = 4;
	private static final int OUTLINE_FEATHER = 4;
	/** How far above an NPC's head the arrow's anchor is, in local units, as the hitpoints tag's (NpcHitpointsOverlay). */
	private static final int ABOVE_HEAD = 60;
	/** The gap in pixels between that anchor and the arrow's tip, which leaves room for the hitpoints tag under it. */
	private static final int ARROW_LIFT = 26;
	/** The arrow's half width in pixels, and its height. */
	private static final int ARROW_HALF = 9;
	private static final int ARROW_HEIGHT = 13;
	/** How far along each edge of the tile a corner bracket reaches, as a share of the edge. */
	private static final double BRACKET_SHARE = 0.28;
	private static final Color EDGE = Color.BLACK;
	private static final Stroke THIN = new BasicStroke(1.5f);
	private static final Stroke LINE = new BasicStroke(3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final Stroke EDGE_LINE = new BasicStroke(6, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

	private final Client client;
	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;
	private final ModelOutlineRenderer outlines;
	private Set<WorldPoint> tiles = Collections.emptySet();
	private List<NPC> npcs = Collections.emptyList();

	@Inject
	RangeOverlay(Client client, SolSurvivorPlugin plugin, SolSurvivorConfig config, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/**
	 * The tiles and the NPCs in range on this tick, for a range of `range` tiles, Myopia's cut taken off, that reaches only
	 * the four tiles beside the player when `cardinalOnly`. Nothing outside the arena, or with both settings off. On the
	 * client thread.
	 */
	void update(int range, boolean cardinalOnly)
	{
		tiles = Collections.emptySet();
		npcs = Collections.emptyList();
		Player player = client.getLocalPlayer();
		if (player == null || !plugin.inArena() || range < 1 || !(config.myRange() || config.highlightInRange()))
		{
			return;
		}
		WorldView view = client.getTopLevelWorldView();
		WorldPoint at = player.getWorldLocation();
		WorldArea me = new WorldArea(at, 1, 1);
		if (config.myRange())
		{
			Set<WorldPoint> out = new HashSet<>();
			for (int dx = -range; dx <= range; dx++)
			{
				for (int dy = -range; dy <= range; dy++)
				{
					boolean beside = Math.abs(dx) + Math.abs(dy) == 1;
					if ((dx == 0 && dy == 0) || (cardinalOnly && !beside))
					{
						continue;
					}
					WorldPoint tile = at.dx(dx).dy(dy);
					if (me.hasLineOfSightTo(view, tile))
					{
						out.add(tile);
					}
				}
			}
			tiles = out;
		}
		if (config.highlightInRange())
		{
			List<NPC> out = new ArrayList<>();
			for (NPC npc : view.npcs())
			{
				if (npc.isDead() || (NpcKind.forNpcId(npc.getId(), false) == null && !WaveRoster.isFrem(npc.getId())))
				{
					continue;
				}
				WorldArea area = npc.getWorldArea();
				boolean in = cardinalOnly ? me.isInMeleeDistance(area) : me.distanceTo(area) <= range && me.hasLineOfSightTo(view, area);
				if (in)
				{
					out.add(npc);
				}
			}
			npcs = out;
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.inArena())
		{
			return null;
		}
		Color colour = config.rangeColour();
		if (config.myRange() && !tiles.isEmpty())
		{
			outline(graphics, colour);
		}
		if (config.highlightInRange() && !npcs.isEmpty())
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			SolSurvivorConfig.InRangeStyle style = config.inRangeStyle();
			for (NPC npc : npcs)
			{
				mark(graphics, npc, style == null ? SolSurvivorConfig.InRangeStyle.BOLD_TILE : style, colour);
			}
		}
		return null;
	}

	/**
	 * One NPC in range, in the look picked. Each line is drawn on a black edge, so that it shows on the sand whatever
	 * the colour, the thin gold tile drawn before having been hard to see there (Stefan, 2026-11-08).
	 */
	private void mark(Graphics2D graphics, NPC npc, SolSurvivorConfig.InRangeStyle style, Color colour)
	{
		if (style == SolSurvivorConfig.InRangeStyle.OUTLINE)
		{
			outlines.drawOutline(npc, OUTLINE_WIDTH, colour, OUTLINE_FEATHER);
			return;
		}
		Polygon poly = npc.getCanvasTilePoly();
		if (style == SolSurvivorConfig.InRangeStyle.ARROW)
		{
			if (poly != null)
			{
				graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), Math.min(150, colour.getAlpha())));
				graphics.setStroke(THIN);
				graphics.draw(poly);
			}
			arrow(graphics, npc, colour);
			return;
		}
		if (poly == null)
		{
			return;
		}
		if (style == SolSurvivorConfig.InRangeStyle.BRACKETS && poly.npoints == 4)
		{
			brackets(graphics, poly, colour);
			return;
		}
		graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), Math.min(BOLD_FILL_ALPHA, colour.getAlpha())));
		graphics.fill(poly);
		edged(graphics, poly, colour);
	}

	/** The shape drawn in the colour on a black line twice its width. */
	private static void edged(Graphics2D graphics, Shape shape, Color colour)
	{
		graphics.setStroke(EDGE_LINE);
		graphics.setColor(EDGE);
		graphics.draw(shape);
		graphics.setStroke(LINE);
		graphics.setColor(colour);
		graphics.draw(shape);
	}

	/** A downward arrow over the NPC's head, its tip just above where the hitpoints tag sits. */
	private static void arrow(Graphics2D graphics, NPC npc, Color colour)
	{
		Point at = npc.getCanvasTextLocation(graphics, "", npc.getLogicalHeight() + ABOVE_HEAD);
		if (at == null)
		{
			return;
		}
		int x = at.getX();
		int tip = at.getY() - ARROW_LIFT;
		Polygon arrow = new Polygon(new int[]{x - ARROW_HALF, x + ARROW_HALF, x}, new int[]{tip - ARROW_HEIGHT, tip - ARROW_HEIGHT, tip}, 3);
		graphics.setStroke(EDGE_LINE);
		graphics.setColor(EDGE);
		graphics.draw(arrow);
		graphics.setColor(colour);
		graphics.fill(arrow);
	}

	/** Brackets on the tile's four corners, each reaching a share of the way along the two edges that meet there. */
	private static void brackets(Graphics2D graphics, Polygon poly, Color colour)
	{
		Path2D.Double path = new Path2D.Double();
		for (int i = 0; i < 4; i++)
		{
			int ax = poly.xpoints[i];
			int ay = poly.ypoints[i];
			int bx = poly.xpoints[(i + 1) % 4];
			int by = poly.ypoints[(i + 1) % 4];
			int cx = poly.xpoints[(i + 3) % 4];
			int cy = poly.ypoints[(i + 3) % 4];
			path.moveTo(ax + (bx - ax) * BRACKET_SHARE, ay + (by - ay) * BRACKET_SHARE);
			path.lineTo(ax, ay);
			path.lineTo(ax + (cx - ax) * BRACKET_SHARE, ay + (cy - ay) * BRACKET_SHARE);
		}
		edged(graphics, path, colour);
	}

	/**
	 * The tiles in range, filled faintly and outlined as one shape: each tile's edge is drawn where the tile beyond it is
	 * out of range, so that the outline shows the range's border and the gaps a pillar's shadow leaves, not a grid.
	 */
	private void outline(Graphics2D graphics, Color colour)
	{
		WorldView view = client.getTopLevelWorldView();
		int plane = view.getPlane();
		graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), Math.min(FILL_ALPHA, colour.getAlpha())));
		for (WorldPoint tile : tiles)
		{
			LocalPoint centre = LocalPoint.fromWorld(view, tile);
			Polygon poly = centre == null ? null : Perspective.getCanvasTilePoly(client, centre);
			if (poly != null)
			{
				graphics.fill(poly);
			}
		}
		graphics.setColor(colour);
		graphics.setStroke(new BasicStroke(2));
		for (WorldPoint tile : tiles)
		{
			LocalPoint centre = LocalPoint.fromWorld(view, tile);
			if (centre == null)
			{
				continue;
			}
			int x = centre.getX();
			int y = centre.getY();
			// North is +y in the scene's local coordinates, as it is in the world's.
			if (!tiles.contains(tile.dy(1)))
			{
				edge(graphics, view, plane, x - HALF_TILE, y + HALF_TILE, x + HALF_TILE, y + HALF_TILE);
			}
			if (!tiles.contains(tile.dy(-1)))
			{
				edge(graphics, view, plane, x - HALF_TILE, y - HALF_TILE, x + HALF_TILE, y - HALF_TILE);
			}
			if (!tiles.contains(tile.dx(1)))
			{
				edge(graphics, view, plane, x + HALF_TILE, y - HALF_TILE, x + HALF_TILE, y + HALF_TILE);
			}
			if (!tiles.contains(tile.dx(-1)))
			{
				edge(graphics, view, plane, x - HALF_TILE, y - HALF_TILE, x - HALF_TILE, y + HALF_TILE);
			}
		}
	}

	private void edge(Graphics2D graphics, WorldView view, int plane, int x0, int y0, int x1, int y1)
	{
		Point a = Perspective.localToCanvas(client, new LocalPoint(x0, y0, view), plane);
		Point b = Perspective.localToCanvas(client, new LocalPoint(x1, y1, view), plane);
		if (a != null && b != null)
		{
			graphics.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
		}
	}
}

package nl.dexanddice.solsurvivor;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.function.Supplier;
import nl.dexanddice.solsurvivor.core.ReplayLink;
import nl.dexanddice.solsurvivor.core.RunUpload;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * A selected recording only, sent by the plugin's injected RuneLite HTTP client on its background dispatcher. The run's
 * JSON is written and gzipped there too (LazyBody, core.RunUpload), not on the client thread; a run too large for the
 * site fails the call with RunUpload.TooLarge, whose message the player is shown.
 */
final class ReplayUpload
{
	private ReplayUpload()
	{
	}

	/** The upload of the run whose JSON `json` writes, which must be the past waves' logs as they were handed over. */
	static Request request(String site, Supplier<String> json)
	{
		return new Request.Builder().url(ReplayLink.endpoint(site)).post(new LazyBody(RunUpload.TYPE, () -> RunUpload.pack(json.get()))).build();
	}

	/**
	 * The page that opens the stored run, from the site's answer read with RuneLite's Gson: only an ID the site gave, on
	 * the site's own address, so that an answer cannot send the browser elsewhere.
	 */
	static String browserUrl(Gson gson, String site, Response response) throws IOException
	{
		return ReplayLink.browser(site, idOf(gson, response));
	}

	/** The stored run's id from the site's answer, checked as browserUrl checks it, for a link to a wave and a tick of it. */
	static String idOf(Gson gson, Response response) throws IOException
	{
		if (!response.isSuccessful())
		{
			String error = response.code() == 429 ? "Too many runs opened. Try again in a minute."
				: response.code() == 413 ? "This run is too large to open. You can still copy its wave logs."
				: response.code() == 400 ? "The site could not read this recording. Update the plugin and try again."
				: "The site could not store this run. Try again.";
			throw new IOException(error);
		}
		ResponseBody body = response.body();
		if (body == null || body.source().request(4097) || body.source().getBuffer().size() > 4096)
		{
			throw new IOException("The site returned an invalid recording link. Try again.");
		}
		try
		{
			JsonObject data = gson.fromJson(body.source().readUtf8(), JsonObject.class);
			String id = data.get("id").getAsString();
			if (!ReplayLink.isId(id))
			{
				throw new IOException("The site returned an invalid recording link. Try again.");
			}
			return id;
		}
		catch (RuntimeException ex)
		{
			throw new IOException("The site returned an invalid recording link. Try again.", ex);
		}
	}
}

