	 * waves and what the plugin sends; and what it draws on the game's screen, with its presets.
	 */
	enum Tab
	{
		WAVE("Wave"), PAST("Past"), SCREEN("Screen");

		final String label;

		Tab(String label)
		{
			this.label = label;
		}
	}

