			}
		}, new WaveCards.Pages()
		{
			@Override
			public void showPage(JComponent page)
			{
				pastResultKey = null;
				pages.remove(page);
				pages.add(page);
				showTop();
			}

			@Override
			public void closePage(JComponent page)
			{
				if (pages.remove(page))
				{
