				+ (look == SolSurvivorConfig.InRangeStyle.BOLD_TILE ? "a bold tile." : look == SolSurvivorConfig.InRangeStyle.OUTLINE
				? "an outline round them." : look == SolSurvivorConfig.InRangeStyle.ARROW ? "an arrow over them." : "corner brackets."));
