/**
 * The Sol Survivor site's stone look, painted in Swing for the plugin's own panel: raised rows, inset wells, the game's
 * buttons and the panel's icons, all drawn here so that the plugin carries no image files. The colours are the site's
 * (src/ui/styles/01-base.css), and the rows its Setup tab's (design 1, "Stone rows", of the plugin panel designs of
 * 2026-10-25). Only the panel's own components are painted: RuneLite's look and feel and its sidebar are left as they
 * are.
 */
final class Stone
{
	static final Color BACKGROUND = new Color(0x1b1712);
	static final Color WELL = new Color(0x2b251d);
	static final Color BEVEL_LIGHT = new Color(0x66573f);
	static final Color BEVEL_DARK = new Color(0x211c15);
	static final Color OUTLINE = new Color(0x0e0c09);
	static final Color TEXT = new Color(0xece0c3);
	/** Words that carry information beside the text: 4.7 to 5.6:1 on a row's face. */
	static final Color MUTED = new Color(0xbcab8b);
	/** Only for what is done, dead or cannot be used now: 2.6 to 3.0:1 on a row's face, too faint for a line to read. */
	static final Color DIM = new Color(0x8a7b62);
	static final Color ORANGE = new Color(0xff981f);
	static final Color YELLOW = new Color(0xffff00);
	static final Color GOLD = new Color(0xffd24a);
	static final Color GOOD = new Color(0x3cff3c);
	/** A step done's disc: a darker green than GOOD's words, which would outshine the yellow numbers beside it. */
	static final Color DONE = new Color(0x3a9a3a);
	/** Damage taken, and Doom on its last stack. */
	static final Color BAD = new Color(0xff5a3c);

	/** A raised thing's face: its gradient from top to bottom, its bevel's light and dark edges, and its words. */
	static final class Face
	{
		final Color top;
		final Color bottom;
		final Color light;
		final Color dark;
		final Color text;

		Face(int top, int bottom, int light, int dark, Color text)
		{
			this.top = new Color(top);
			this.bottom = new Color(bottom);
			this.light = new Color(light);
			this.dark = new Color(dark);
			this.text = text;
		}
	}

	/** A row, as the site's Setup tab has them. */
	static final Face ROW = new Face(0x483d2f, 0x3b3227, 0x66573f, 0x211c15, TEXT);
	/** A plain button, its words in the interface's orange, and the same under the mouse, its words gone yellow. */
	static final Face BUTTON = new Face(0x4e4334, 0x3e3529, 0x66573f, 0x211c15, ORANGE);
	static final Face BUTTON_HOVER = new Face(0x5d503d, 0x463c2e, 0x66573f, 0x211c15, YELLOW);
	/** The one main button of a group, the game's red-brown "accept", its words yellow. */
	static final Face PRIMARY = new Face(0x8a3b17, 0x5e250c, 0xb8622d, 0x3a1606, YELLOW);
	static final Face PRIMARY_HOVER = new Face(0xa14720, 0x6e2c10, 0xb8622d, 0x3a1606, Color.WHITE);
	/** Buttons that cannot be used now go flat, as the game greys out an option it won't take. */
	static final Face OFF = new Face(0x372f24, 0x372f24, 0x463c2e, 0x261f17, DIM);
	static final Face PRIMARY_OFF = new Face(0x50301d, 0x50301d, 0x6a4128, 0x2e1a10, new Color(0x9a8160));
	/**
	 * A switch that is on, lit the game's green, so that a column of them reads at a glance without its dots (the design
	 * pass of 2026-10-31); a switch that is off keeps the plain button's face. Neither is the red-brown of a main button.
	 */
	static final Face SWITCH_ON = new Face(0x2f5a1f, 0x1f3f14, 0x4f8a35, 0x0f2209, TEXT);
	static final Face SWITCH_ON_HOVER = new Face(0x3a6c27, 0x264b19, 0x4f8a35, 0x0f2209, Color.WHITE);

	private Stone()
	{
	}

	/**
	 * A raised face over `w` by `h`, with its outline and bevel, and with `shadow` a two-pixel shadow under it, which the
	 * height takes in. The corners are left out by a pixel, as the site's 4 px radius reads at this size.
	 */
	static void paintRaised(Graphics2D g, int w, int h, Face f, boolean shadow)
	{
		int bh = shadow ? h - 2 : h;
		if (shadow)
		{
			g.setColor(new Color(0, 0, 0, 80));
			g.fillRect(1, 2, w - 2, bh);
		}
		g.setPaint(new GradientPaint(0, 0, f.top, 0, bh, f.bottom));
		g.fillRect(1, 1, w - 2, bh - 2);
		g.setColor(OUTLINE);
		line(g, 1, 0, w - 2, 0);
		line(g, 1, bh - 1, w - 2, bh - 1);
		line(g, 0, 1, 0, bh - 2);
		line(g, w - 1, 1, w - 1, bh - 2);
		g.setColor(f.light);
		line(g, 1, 1, w - 2, 1);
		line(g, 1, 1, 1, bh - 2);
		g.setColor(f.dark);
		line(g, 2, bh - 2, w - 2, bh - 2);
		line(g, w - 2, 2, w - 2, bh - 2);
	}

	/** An inset well over `w` by `h`, as the game's item slots are: dark at its top and left edges, lit at the others. */
	static void paintWell(Graphics2D g, int w, int h)
	{
		g.setColor(WELL);
		g.fillRect(1, 1, w - 2, h - 2);
		g.setColor(OUTLINE);
		line(g, 1, 0, w - 2, 0);
		line(g, 1, h - 1, w - 2, h - 1);
		line(g, 0, 1, 0, h - 2);
		line(g, w - 1, 1, w - 1, h - 2);
		g.setColor(Color.BLACK);
		line(g, 1, 1, w - 2, 1);
		line(g, 1, 1, 1, h - 2);
		g.setColor(BEVEL_LIGHT);
		line(g, 2, h - 2, w - 2, h - 2);
		line(g, w - 2, 2, w - 2, h - 2);
	}

	/**
	 * A line a pixel wide from (x0, y0) to (x1, y1), across or down, both ends in: the pixels drawLine sets at 100%, but
	 * filled as a rectangle, so that under a display's scaling (150% on many Windows laptops) it covers the same share of
	 * the screen as the fills beside it. drawLine keeps its line a whole screen pixel there, which left a well's right and
	 * bottom edges short and the sun in the wave's slot visibly off its centre.
	 */
	private static void line(Graphics2D g, int x0, int y0, int x1, int y1)
	{
		g.fillRect(Math.min(x0, x1), Math.min(y0, y1), Math.abs(x1 - x0) + 1, Math.abs(y1 - y0) + 1);
	}

	/** The outline drawRect draws round (x, y) to (x + w, y + h), drawn as line does, each pixel once. */
	private static void ring(Graphics2D g, int x, int y, int w, int h)
	{
		line(g, x, y, x + w, y);
		line(g, x, y + h, x + w, y + h);
		line(g, x, y + 1, x, y + h - 1);
		line(g, x + w, y + 1, x + w, y + h - 1);
	}

	/** A panel on a raised row, with a shadow under it; `glow` rings it, as a row that wants the player's eye. */
	static class Row extends JPanel
	{
		private Color glow;

		Row(LayoutManager layout, int top, int left, int bottom, int right)
		{
			super(layout);
			setOpaque(false);
			setBorder(new EmptyBorder(top, left, bottom + 2, right));
		}

		/**
		 * No size while hidden: RuneLite's sidebar lays out a hidden row as if it showed, and would leave its space empty
		 * under the rows above, as the leaderboard's did with Leaderboard off.
		 */
		@Override
		public Dimension getPreferredSize()
		{
			return isVisible() ? super.getPreferredSize() : new Dimension(0, 0);
		}

		void setGlow(Color glow)
		{
			if (!java.util.Objects.equals(this.glow, glow))
			{
				this.glow = glow;
				repaint();
			}
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			paintRaised(g2, getWidth(), getHeight(), ROW, true);
			if (glow != null)
			{
				int bh = getHeight() - 2;
				g2.setColor(glow);
				ring(g2, 0, 0, getWidth() - 1, bh - 1);
				g2.setColor(new Color(glow.getRed(), glow.getGreen(), glow.getBlue(), 90));
				ring(g2, 1, 1, getWidth() - 3, bh - 3);
			}
			g2.dispose();
		}
	}

	/** A clear panel that groups rows, with no size while hidden, as Row has none. */
	static class Group extends JPanel
	{
		Group(LayoutManager layout)
		{
			super(layout);
			setOpaque(false);
		}

		@Override
		public Dimension getPreferredSize()
		{
			return isVisible() ? super.getPreferredSize() : new Dimension(0, 0);
		}
	}

	/**
	 * A count in a rounded pill, as the plugin feature designs mark damage: white on the game's hitsplat red for a hit that
	 * cost hitpoints, or muted on the well for anything else, an idle stretch's ticks or a hit of nothing.
	 */
	static class Pill extends JComponent
	{
		/** The hitsplat's red, under the white words. */
		static final Color HIT = new Color(0xa3120c);

		private final String text;
		private final boolean hit;

		Pill(String text, boolean hit, Font font)
		{
			this.text = text;
			this.hit = hit;
			setFont(font);
			FontMetrics fm = getFontMetrics(font);
			Dimension d = new Dimension(Math.max(18, fm.stringWidth(text) + 8), fm.getAscent() + 3);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_GASP);
			int w = getWidth();
			int h = getHeight();
			if (hit)
			{
				g2.setColor(HIT);
				g2.fillRoundRect(0, 0, w, h, h, h);
			}
			g2.setFont(getFont());
			FontMetrics fm = g2.getFontMetrics();
			int x = (w - fm.stringWidth(text)) / 2;
			int y = (h - fm.getAscent()) / 2 + fm.getAscent() - 1;
			if (hit)
			{
				g2.setColor(Color.BLACK);
				g2.drawString(text, x + 1, y + 1);
			}
			g2.setColor(hit ? Color.WHITE : MUTED);
			g2.drawString(text, x, y);
			g2.dispose();
		}
	}

	/**
	 * Words in a rounded outline, as the plugin feature designs tag a past wave with its mistakes: orange on a dark red
	 * outline, or the good green on a dark green one for a clean wave.
	 */
	static class Tag extends JComponent
	{
		private final String text;
		private final Color color;
		private final Color outline;

		Tag(String text, Color color, Color outline, Font font)
		{
			this.text = text;
			this.color = color;
			this.outline = outline;
			setFont(font);
			FontMetrics fm = getFontMetrics(font);
			Dimension d = new Dimension(fm.stringWidth(text) + 10, fm.getAscent() + 4);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_GASP);
			int w = getWidth();
			int h = getHeight();
			g2.setColor(outline);
			g2.drawRoundRect(0, 0, w - 1, h - 1, h - 1, h - 1);
			g2.setFont(getFont());
			FontMetrics fm = g2.getFontMetrics();
			int y = (h - fm.getAscent()) / 2 + fm.getAscent() - 1;
			g2.setColor(color);
			g2.drawString(text, (w - fm.stringWidth(text)) / 2, y);
			g2.dispose();
		}
	}

	/** A panel sunk into an inset well. */
	static class Well extends JPanel
	{
		Well(LayoutManager layout, int top, int left, int bottom, int right)
		{
			super(layout);
			setOpaque(false);
			setBorder(new EmptyBorder(top, left, bottom, right));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			paintWell(g2, getWidth(), getHeight());
			g2.dispose();
		}
	}

	/** Words on one line with the game's one-pixel black shadow under them. */
	static class Shadowed extends JLabel
	{
		Shadowed(String text, Font font, Color color)
		{
			super(text);
			setFont(font);
			setForeground(color);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			String text = getText();
			if (text == null || text.isEmpty())
			{
				return;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_GASP);
			g2.setFont(getFont());
			FontMetrics fm = g2.getFontMetrics();
			Insets in = getInsets();
			int y = in.top + (getHeight() - in.top - in.bottom - fm.getHeight()) / 2 + fm.getAscent();
			g2.setColor(Color.BLACK);
			g2.drawString(text, in.left + 1, y + 1);
			g2.setColor(getForeground());
			g2.drawString(text, in.left, y);
			g2.dispose();
		}
	}

	/**
	 * A button drawn as the game's: raised, lighter with its words yellow under the mouse, sunk while it is pressed, and
	 * flat while it cannot be used. Its icon, if any, goes before its words.
	 */
	static class Button extends JButton
	{
		private final Face face;
		private final Face hover;
		private final Face off;
		private final Dimension size;
		private final int padX;
		private final int padY;

		/** A button with words, its size theirs and its icon's with `padX` and `padY` around them. */
		Button(String text, Icon icon, boolean primary, Font font, int padX, int padY)
		{
			this(text, icon, primary, font, padX, padY, null);
		}

		/** A square button with an icon alone, `size` pixels a side. */
		Button(Icon icon, int size)
		{
			this(null, icon, false, null, 0, 0, new Dimension(size, size));
		}

		private Button(String text, Icon icon, boolean primary, Font font, int padX, int padY, Dimension size)
		{
			this(text, icon, primary ? PRIMARY : BUTTON, primary ? PRIMARY_HOVER : BUTTON_HOVER, primary ? PRIMARY_OFF : OFF, font, padX, padY,
				size);
		}

		private Button(String text, Icon icon, Face face, Face hover, Face off, Font font, int padX, int padY, Dimension size)
		{
			super(text, icon);
			this.face = face;
			this.hover = hover;
			this.off = off;
			this.size = size;
			this.padX = padX;
			this.padY = padY;
			if (font != null)
			{
				setFont(font);
			}
			if (icon instanceof ImageIcon)
			{
				setDisabledIcon(faded((ImageIcon) icon));
			}
			setContentAreaFilled(false);
			setBorderPainted(false);
			setFocusPainted(false);
			setOpaque(false);
			setRolloverEnabled(true);
			setIconTextGap(5);
		}

		/**
		 * A switch saying On or Off, with `icon` before the word: lit green while on (SWITCH_ON), a plain button while off,
		 * and as wide either way, so that a column of them lines up.
		 */
		static Button toggle(boolean on, Icon icon, Font font, int padX, int padY)
		{
			FontMetrics fm = new JLabel().getFontMetrics(font);
			int words = Math.max(fm.stringWidth("On"), fm.stringWidth("Off"));
			int iw = icon == null ? 0 : icon.getIconWidth() + 5;
			int h = Math.max(fm.getAscent(), icon == null ? 0 : icon.getIconHeight());
			return new Button(on ? "On" : "Off", icon, on ? SWITCH_ON : BUTTON, on ? SWITCH_ON_HOVER : BUTTON_HOVER, OFF, font, padX, padY,
				new Dimension(words + iw + 2 * padX, h + 2 * padY));
		}

		/** Whether it is its row's main action, in the site's orange, rather than a secondary one in stone. */
		boolean isPrimary()
		{
			return face == PRIMARY;
		}

		/** Whether it is a switch that is on, lit green. */
		boolean isLit()
		{
			return face == SWITCH_ON;
		}

		@Override
		public Dimension getPreferredSize()
		{
			if (size != null)
			{
				return size;
			}
			FontMetrics fm = getFontMetrics(getFont());
			String t = getText();
			boolean words = t != null && !t.isEmpty();
			Icon i = getIcon();
			int w = (words ? fm.stringWidth(t) : 0) + (i == null ? 0 : i.getIconWidth()) + (words && i != null ? getIconTextGap() : 0);
			int h = Math.max(words ? fm.getAscent() : 0, i == null ? 0 : i.getIconHeight());
			return new Dimension(w + 2 * padX, h + 2 * padY);
		}

		@Override
		public Dimension getMinimumSize()
		{
			return getPreferredSize();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			ButtonModel m = getModel();
			boolean pressed = isEnabled() && m.isArmed() && m.isPressed();
			Face f = !isEnabled() ? off : m.isRollover() ? hover : face;
			if (pressed)
			{
				paintWell(g2, getWidth(), getHeight());
			}
			else
			{
				paintRaised(g2, getWidth(), getHeight(), f, false);
			}
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_GASP);
			g2.setFont(getFont());
			FontMetrics fm = g2.getFontMetrics();
			String t = getText();
			boolean words = t != null && !t.isEmpty();
			Icon i = isEnabled() ? getIcon() : getDisabledIcon();
			int tw = words ? fm.stringWidth(t) : 0;
			int iw = i == null ? 0 : i.getIconWidth();
			int gap = words && i != null ? getIconTextGap() : 0;
			int x = (getWidth() - tw - iw - gap) / 2 + (pressed ? 1 : 0);
			int dy = pressed ? 1 : 0;
			if (i != null)
			{
				i.paintIcon(this, g2, x, (getHeight() - i.getIconHeight()) / 2 + dy);
			}
			if (words)
			{
				int y = (getHeight() - fm.getAscent()) / 2 + fm.getAscent() - 1 + dy;
				g2.setColor(Color.BLACK);
				g2.drawString(t, x + iw + gap + 1, y + 1);
				g2.setColor(pressed ? YELLOW : f.text);
				g2.drawString(t, x + iw + gap, y);
			}
			if (isFocusPainted() && hasFocus())
			{
				g2.setColor(YELLOW);
				g2.drawRect(2, 2, getWidth() - 5, getHeight() - 5);
			}
			g2.dispose();
		}
	}

	/** A square slot sunk into the row, holding an icon, or the wave's number in the values' yellow. */
	static class Slot extends JComponent
	{
		private final int size;
		private Icon icon;
		private String number;

		Slot(int size, Icon icon)
		{
			this.size = size;
			this.icon = icon;
			Dimension d = new Dimension(size, size);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		/** Shows `number` in the slot, or the icon while it is null. */
		void show(Icon icon, String number)
		{
			this.icon = icon;
			this.number = number;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			paintWell(g2, size, size);
			if (number != null)
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_GASP);
				// The RuneScape font is drawn for 16 px; at 1.5 times that it stays sharp enough for two digits.
				g2.setFont(getFont().deriveFont(size >= 30 ? 24f : 16f));
				FontMetrics fm = g2.getFontMetrics();
				int x = (size - fm.stringWidth(number)) / 2;
				int y = (size - fm.getAscent()) / 2 + fm.getAscent() - 1;
				g2.setColor(Color.BLACK);
				g2.drawString(number, x + 1, y + 1);
				g2.setColor(YELLOW);
				g2.drawString(number, x, y);
			}
			else if (icon != null)
			{
				icon.paintIcon(this, g2, (size - icon.getIconWidth()) / 2, (size - icon.getIconHeight()) / 2);
			}
			g2.dispose();
		}
	}

	static ImageIcon faded(ImageIcon icon)
	{
		BufferedImage out = new BufferedImage(icon.getIconWidth(), icon.getIconHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.35f));
		g.drawImage(icon.getImage(), 0, 0, null);
		g.dispose();
		return new ImageIcon(out);
	}

	/** Draws an icon `size` pixels a side. */
	private interface Painter
	{
		void paint(Graphics2D g, int n);
	}

	private static ImageIcon draw(int size, Painter p)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		p.paint(g, size);
		g.dispose();
		return new ImageIcon(image);
	}

	/** Sol's sun: a disc lit from the middle, with sixteen rays, long and short by turns. */
	static ImageIcon sun(int size)
	{
		return draw(size, (g, n) ->
		{
			double c = n / 2.0;
			double r1 = n * 0.30;
			for (int i = 0; i < 16; i++)
			{
				double a = Math.PI * i / 8;
				double r2 = n * (i % 2 == 0 ? 0.50 : 0.42);
				double half = n * 0.07 / r1 * 1.6;
				Polygon ray = new Polygon();
				ray.addPoint((int) Math.round(c + r1 * Math.cos(a - half)), (int) Math.round(c + r1 * Math.sin(a - half)));
				ray.addPoint((int) Math.round(c + r2 * Math.cos(a)), (int) Math.round(c + r2 * Math.sin(a)));
				ray.addPoint((int) Math.round(c + r1 * Math.cos(a + half)), (int) Math.round(c + r1 * Math.sin(a + half)));
				g.setColor(i % 2 == 0 ? new Color(0xff7a00) : new Color(0xd94a00));
				g.fillPolygon(ray);
			}
			float r = (float) (n * 0.31);
			g.setPaint(new RadialGradientPaint(new Point2D.Double(c - n * 0.06, c - n * 0.06), r, new float[]{0f, 0.45f, 1f},
				new Color[]{new Color(0xfffbe0), GOLD, new Color(0xff7a00)}));
			Ellipse2D disc = new Ellipse2D.Double(c - r, c - r, 2 * r, 2 * r);
			g.fill(disc);
			g.setColor(new Color(0x7a2a00));
			g.setStroke(new BasicStroke(Math.max(1f, n / 24f)));
			g.draw(disc);
		});
	}

	/** A play mark: open the wave at its start. */
	static ImageIcon play(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(color);
			g.fillPolygon(new int[]{n / 4, n - n / 6, n / 4}, new int[]{n / 8, n / 2, n - n / 8}, 3);
		});
	}

	/** Two figures, one behind the other: open the wave where its reinforcements came. */
	static ImageIcon figures(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(color.darker());
			g.fillOval(n * 7 / 12, n / 12, n / 3, n / 3);
			g.fillRoundRect(n / 2, n * 5 / 12, n / 2, n / 2 + 1, n / 4, n / 4);
			g.setColor(color);
			g.fillOval(n / 12, n / 6, n / 3, n / 3);
			g.fillRoundRect(0, n / 2, n / 2, n / 2, n / 4, n / 4);
		});
	}

	/** Two sheets, the one behind showing only its top and right edges: copy. */
	static ImageIcon copy(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			int w = n * 7 / 12;
			int h = n * 2 / 3;
			int o = Math.max(3, n / 4);
			g.setColor(color);
			g.fillRect(o, 0, w, 1);
			g.fillRect(o + w, 0, 1, h + 1);
			g.fillRect(o, 0, 1, o - 1);
			g.fillRect(w + 2, h, o - 1, 1);
			g.fillRect(0, o, w + 1, 1);
			g.fillRect(0, o + h, w + 1, 1);
			g.fillRect(0, o, 1, h);
			g.fillRect(w, o, 1, h);
		});
	}

	/** The arena from above, its round floor and four pillars, as the site draws it: the arena as it is now. */
	static ImageIcon arena(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(color);
			g.setStroke(new BasicStroke(Math.max(1.2f, n / 11f)));
			g.drawOval(1, 1, n - 3, n - 3);
			int p = Math.max(2, n / 6);
			int a = n * 3 / 10;
			int b = n - a - p;
			g.fillRect(a, a, p, p);
			g.fillRect(b, a, p, p);
			g.fillRect(a, b, p, p);
			g.fillRect(b, b, p, p);
		});
	}

	/** Three cards fanned out: Minimus's three offers. */
	static ImageIcon cards(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			AffineTransform t = g.getTransform();
			double[] turns = {-0.38, 0, 0.38};
			Color[] faces = {color.darker().darker(), color.darker(), color};
			int w = n * 5 / 12;
			int h = n * 7 / 12;
			for (int i = 0; i < 3; i++)
			{
				g.setTransform(t);
				g.rotate(turns[i], n / 2.0, n * 0.95);
				g.setColor(faces[i]);
				g.fillRoundRect((n - w) / 2, n / 8, w, h, 3, 3);
				g.setColor(BACKGROUND);
				g.drawRoundRect((n - w) / 2, n / 8, w, h, 3, 3);
			}
			g.setTransform(t);
		});
	}

	/** A film's frame with a play mark: watch a run back. */
	static ImageIcon replay(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(color);
			g.setStroke(new BasicStroke(Math.max(1.2f, n / 11f)));
			g.drawRoundRect(1, n / 6, n - 3, n * 2 / 3, 3, 3);
			g.fillPolygon(new int[]{n * 5 / 12, n * 3 / 4, n * 5 / 12}, new int[]{n / 3, n / 2, n * 2 / 3}, 3);
		});
	}

	/** Three dots in the panel's icon style, for a visible more-actions menu. */
	static ImageIcon more(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(color);
			for (int x : new int[] {1, n / 2 - 1, n - 3})
			{
				g.fillOval(x, n / 2 - 1, 2, 2);
			}
		});
	}

	/** A run folded open, pointing down, or shut, pointing right. */
	static ImageIcon caret(int size, Color color, boolean open)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(color);
			if (open)
			{
				g.fillPolygon(new int[]{1, n - 1, n / 2}, new int[]{n / 4, n / 4, n - n / 4}, 3);
			}
			else
			{
				g.fillPolygon(new int[]{n / 4, n - n / 4, n / 4}, new int[]{1, n / 2, n - 1}, 3);
			}
		});
	}

	/** A sheet with lines of writing: the wave report. */
	static ImageIcon report(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			int x = n / 5;
			int w = n - 2 * x;
			g.setColor(new Color(0x5d503d));
			g.fillRoundRect(x, 1, w, n - 2, 3, 3);
			g.setColor(color);
			int left = x + w / 5;
			int line = Math.max(1, n / 14);
			g.fillRect(left, n * 3 / 10, w * 3 / 5, line);
			g.fillRect(left, n / 2, w * 3 / 5, line);
			g.fillRect(left, n * 7 / 10, w * 2 / 5, line);
		});
	}

	/** A square of a colour, with a dark edge: a legend's key. */
	static ImageIcon square(int size, Color color)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(OUTLINE);
		g.fillRect(0, 0, size, size);
		g.setColor(color);
		g.fillRect(1, 1, size - 2, size - 2);
		g.dispose();
		return new ImageIcon(image);
	}

	static ImageIcon dot(int size, Color color)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(color);
			g.fillOval(n / 4, n / 4, n / 2, n / 2);
		});
	}

	/** A step's number, dark on a yellow disc, as the Getting started card counts its steps. */
	static ImageIcon number(int size, int number, Font font)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(YELLOW);
			g.fillOval(0, 0, n - 1, n - 1);
			// The font at its own size, which RuneScape's fonts are drawn for, its digit's height centred on the disc.
			g.setColor(BACKGROUND);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			g.setFont(font);
			FontMetrics fm = g.getFontMetrics();
			String text = String.valueOf(number);
			java.awt.geom.Rectangle2D box = font.createGlyphVector(fm.getFontRenderContext(), text).getVisualBounds();
			g.drawString(text, (float) ((n - 1 - box.getWidth()) / 2 - box.getX()), (float) ((n - 1 - box.getHeight()) / 2 - box.getY()));
		});
	}

	/** A step done, a dark tick on a green disc, in place of the step's number once the player has taken it. */
	static ImageIcon done(int size)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(DONE);
			g.fillOval(0, 0, n - 1, n - 1);
			g.setColor(BACKGROUND);
			g.setStroke(new BasicStroke(2f));
			g.drawLine(3, n / 2, n / 2 - 1, n - 5);
			g.drawLine(n / 2 - 1, n - 5, n - 4, 3);
		});
	}

	/** A question mark in a ring, which holds the panel's help in its tooltip. */
	static ImageIcon question(int size, Color color, Font font)
	{
		return draw(size, (g, n) ->
		{
			g.setColor(color);
			g.setStroke(new BasicStroke(1.2f));
			g.drawOval(0, 0, n - 1, n - 1);
			g.setFont(font.deriveFont((float) n));
			FontMetrics fm = g.getFontMetrics();
			g.drawString("?", (n - fm.stringWidth("?")) / 2 + 1, n - 2);
		});
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import nl.dexanddice.solsurvivor.core.WaveClock;

/** The small, independently movable tick number, with no distinguished tick or event; looping, optionally coloured. */
class TickCounterOverlay extends WaveClockOverlay
{
	@Inject
	TickCounterOverlay(SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		super(plugin, config);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		WaveClock.View view = plugin.waveClock();
		if (!config.tickCounter() || combined() || !plugin.inArena() || !view.counterVisible(config.quietOnSol()))
		{
			return null;
		}
		background(view);
		number(ticks(view), 20f, numberColour(view));
		return draw(graphics, 52);
	}
}

package nl.dexanddice.solsurvivor;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import nl.dexanddice.solsurvivor.core.TileMarker;

/**
 * The arena's tiles the Tile Packs plugin draws, for Arena now's link with "Send my tile markers" on, beside Ground
 * Markers' (GroundMarkers). Tile Packs (checked in its build of 31 October 2026) keeps:
 * <ul>
 * <li>its built-in packs in its own jar, as `tilePacks.jsonc`: a map from each pack's id to {id, packName, packTiles},
 * read here through the installed plugin's class, as Tile Packs itself reads it;</li>
 * <li>the player's own packs in its config group `tilePacks`, each under `pack_<id>` as {id, packName, packTiles,
 * visible}, where a built-in pack's id carries only whether it is listed, never its tiles;</li>
 * <li>the packs it draws under `packs`, a JSON list of their ids;</li>
 * <li>its settings in the group `tilepacks`: `overrideColorActive` and `overrideColor` draw every tile in one colour
 * (off, and yellow, by default), and `showLabels` its labels (on by default).</li>
 * </ul>
 * A pack's `packTiles` is Ground Markers' own format, as text.
 */
final class TilePacks
{
	/** The class of the installed Tile Packs plugin, which holds BUILT_IN beside it. */
	static final String PLUGIN_CLASS = "com.tilepacks.TilePacksPlugin";

	/** The built-in packs, a resource beside PLUGIN_CLASS. */
	static final String BUILT_IN = "tilePacks.jsonc";

	/** The config group of the packs and the list of those drawn. */
	static final String GROUP = "tilePacks";

	/** The key of the ids of the packs drawn. */
	static final String DRAWN = "packs";

	/** The prefix of each saved pack's key. */
	static final String PACK_PREFIX = "pack_";

	/** The config group of Tile Packs' settings. */
	static final String SETTINGS = "tilepacks";

	/** Tile Packs' colour for every tile while its override is on, unless the player picked another. */
	static final Color DEFAULT_OVERRIDE = Color.YELLOW;

	/** A pack as Tile Packs keeps one: its id and its tiles, as Ground Markers' text. */
	static final class Pack
	{
		Integer id;
		String packTiles;
	}

	private TilePacks()
	{
	}

	/**
	 * The built-in packs of Tile Packs' `json`, by id; none for no text or text that is not its map. `gson` is the
	 * client's, which reads the file's comments as Tile Packs' own reading does.
	 */
	static Map<Integer, Pack> builtIn(Gson gson, String json)
	{
		Map<Integer, Pack> packs = new HashMap<>();
		if (json == null || json.isEmpty())
		{
			return packs;
		}
		try
		{
			Map<String, Pack> read = gson.fromJson(json, new TypeToken<Map<String, Pack>>()
			{
			}.getType());
			for (Pack p : read == null ? Collections.<Pack>emptyList() : read.values())
			{
				if (p != null && p.id != null)
				{
					packs.put(p.id, p);
				}
			}
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return new HashMap<>();
		}
		return packs;
	}

	/**
	 * The markers of the packs Tile Packs draws on the player's `plane`, in the order of `drawn`, its list of their ids:
	 * each from `builtIn`, or from `saved`, the texts of the player's own packs, for an id not built in. A pack missing
	 * from both, or text that does not read, adds none. Every tile is in `override` when that is not null, and without
	 * its label unless `labels`, as Tile Packs draws it.
	 */
	static List<TileMarker> read(Gson gson, Map<Integer, Pack> builtIn, Collection<String> saved, String drawn, Color override,
		boolean labels, int plane)
	{
		Map<Integer, Pack> packs = new HashMap<>(builtIn);
		for (String text : saved)
		{
			Pack p = pack(gson, text);
			if (p != null && p.id != null)
			{
				packs.putIfAbsent(p.id, p);
			}
		}
		List<TileMarker> markers = new ArrayList<>();
		for (Integer id : ids(gson, drawn))
		{
			Pack p = id == null ? null : packs.get(id);
			if (p != null)
			{
				markers.addAll(GroundMarkers.read(gson, p.packTiles, plane, override, labels));
			}
		}
		return markers;
	}

	private static Pack pack(Gson gson, String text)
	{
		try
		{
			return text == null ? null : gson.fromJson(text, Pack.class);
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}

	private static List<Integer> ids(Gson gson, String drawn)
	{
		try
		{
			List<Integer> ids = drawn == null ? null : gson.fromJson(drawn, new TypeToken<List<Integer>>()
			{
			}.getType());
			return ids == null ? Collections.emptyList() : ids;
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return Collections.emptyList();
		}
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.Icon;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import nl.dexanddice.solsurvivor.core.Modifier;

/**
 * "Volatility reminder", a setting that is on by default: while the player holds Volatility, the modifier's picture
 * over each NPC that dies, for 5 ticks from its death, as a reminder that it will explode (the user's ask of 2026-10-26,
 * so that Fortis Colosseum's own reminder can be switched off for this). It marks no tile and no blast's reach: the game
 * shows the explosion itself as it goes off. Every NPC that dies gets one, as the planner has every NPC killed explode.
 */
class VolatilityOverlay extends Overlay
{
	/** How long a reminder stays, in game ticks from the NPC's death. */
	static final int TICKS = 5;
	private static final int ICON = 28;

	private final Client client;
	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;
	private final Icon icon = Icons.of("modifier-volatility", ICON);
	private final List<Reminder> reminders = new ArrayList<>();

	/** Where an NPC died, how high its middle stands, and the last tick its reminder shows on. */
	private static final class Reminder
	{
		final LocalPoint at;
		final int height;
		final int until;

		Reminder(LocalPoint at, int height, int until)
		{
			this.at = at;
			this.height = height;
			this.until = until;
		}
	}

	@Inject
	VolatilityOverlay(Client client, SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/** An NPC died on this tick: a reminder over it, with the setting on and Volatility held. On the client thread. */
	void died(NPC npc)
	{
		if (!config.volatilityReminder() || !plugin.inArena() || !plugin.waveView().held.containsKey(Modifier.VOLATILITY))
		{
			return;
		}
		LocalPoint at = npc.getLocalLocation();
		if (at != null)
		{
			reminders.add(new Reminder(at, npc.getLogicalHeight() / 2, client.getTickCount() + TICKS - 1));
		}
	}

	/** Forgets every reminder: the player left the arena, or the plugin stopped. On the client thread. */
	void clear()
	{
		reminders.clear();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int tick = client.getTickCount();
		reminders.removeIf(r -> tick > r.until);
		if (reminders.isEmpty() || !config.volatilityReminder() || !plugin.inArena())
		{
			return null;
		}
		int plane = client.getTopLevelWorldView().getPlane();
		for (Reminder r : reminders)
		{
			Point p = Perspective.localToCanvas(client, r.at, plane, r.height);
			if (p != null)
			{
				icon.paintIcon(null, graphics, p.getX() - ICON / 2, p.getY() - ICON / 2);
			}
		}
		return null;
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.Icon;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import nl.dexanddice.solsurvivor.core.ColosseumTracker;
import nl.dexanddice.solsurvivor.core.WaveRoster;

/**
 * The wave box, a setting that is on by default: the wave's NPCs on the game's screen, the same list as the panel's,
 * the next wave's, or both. Each wave sits under a dark band with its number, and each line reads its count first, then
 * the NPC's face and short name (the user's choice of the 2026-10-31 drafts). The count is coloured by how many, so that
 * a crowd stands out: yellow for one, orange for two, red for three or more, grey for none. Reinforcements still to come
 * read "+1" in the list, with their names grey, rather than under a rule. Doom's stacks are not here: Doom has its own
 * box. Only what is in the arena or on its way, as Fortis Colosseum's own box shows it, which offers the same four
 * choices: no timers, and nothing of how to play the wave. It sits at the top left, and moves like any RuneLite box, by
 * holding Alt and dragging. Each name is tinted by how its NPC attacks, with Names by attack style on (Stefan's request,
 * 2026-11-08): magic, ranged or melee in the colours the player picks, the Manticore and the warband together white, as
 * they use more than one.
 */
class WaveBoxOverlay extends OverlayPanel
{
	private static final Color TITLE = new Color(0xff981f);
	private static final Color TEXT = Color.WHITE;
	private static final Color DEAD = new Color(0xa8a8a8);
	private static final Color TO_COME = new Color(0xd0d0d0);
	private static final Color ONE = new Color(0xffff00);
	private static final Color TWO = new Color(0xff9a2e);
	private static final Color MORE = new Color(0xff5040);
	/** The bands behind the waves' titles, darker than the box. */
	private static final Color BAND = new Color(0, 0, 0, 80);
	private static final String REINFORCEMENT = "reinforcement";
	/** The faces' size, a line of the box's font high. */
	private static final int FACE = 16;
	/** The count's column, wide enough for "+3", right-aligned before the face. */
	private static final int COUNT_WIDTH = 16;
	private static final int GAP = 5;

	/** The faces drawn once, by their icon and alpha: the box is drawn every frame. */
	private final Map<String, BufferedImage> faces = new HashMap<>();

	private final SolSurvivorPlugin plugin;
	private final SolSurvivorConfig config;

	@Inject
	WaveBoxOverlay(SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setGap(new Point(0, 1));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		SolSurvivorConfig.WaveBox mode = config.waveBox();
		WaveView view = plugin.waveView();
		if (mode == SolSurvivorConfig.WaveBox.OFF || !plugin.inArena() || view.wave == null || quiet(view.wave, config.quietOnSol()))
		{
			return null;
		}
		boolean any = false;
		if (mode.showsThisWave() && view.underWay && !view.thisWave.isEmpty())
		{
			panelComponent.getChildren().add(new Band("Wave " + view.wave, "now"));
			for (WaveRoster.Line line : view.thisWave)
			{
				if (line.isDead() && !config.markDead())
				{
					continue;
				}
				panelComponent.getChildren().add(new Row(line, line.isToCome(), face(line.getIcon(), alpha(line, line.isToCome())), tint(line)));
			}
			any = true;
		}
		if (mode.showsNextWave() && view.next != null && !view.nextWave.isEmpty())
		{
			if (any)
			{
				panelComponent.getChildren().add(new Space(3));
			}
			panelComponent.getChildren().add(new Band("Wave " + view.next, "next"));
			for (WaveRoster.Line line : view.nextWave)
			{
				panelComponent.getChildren().add(new Row(line, false, face(line.getIcon(), 1f), tint(line)));
			}
			// Who joins later, in the list as "+1" and faded, as the wave under way shows its reinforcements still to come.
			for (WaveRoster.Line line : view.nextLater)
			{
				panelComponent.getChildren().add(new Row(line, true, face(line.getIcon(), alpha(line, true)), tint(line)));
			}
			any = true;
		}
		return any ? super.render(graphics) : null;
	}

	/**
	 * Whether the box steps aside for Sol Heredit's wave, under way or next, with Quiet on Sol Heredit's wave on (idea
	 * 362): it has nothing to list for that fight.
	 */
	static boolean quiet(int wave, boolean quietOnSol)
	{
		return quietOnSol && wave > ColosseumTracker.LAST_WAVE;
	}

	/** The tint of a line's name by how its NPC attacks, or null for none: Names by attack style off, or more than one style. */
	private Color tint(WaveRoster.Line line)
	{
		return config.waveBoxStyleColours() ? styleColour(line.getIcon(), config) : null;
	}

	/**
	 * The colour of an NPC's attack style, by the roster's icon name: the Serpent shaman, the Shockwave Colossus and the
	 * seer attack with magic, the Javelin Colossus and the archer with ranged, the Jaguar warrior, the Minotaur and the
	 * berserker with melee. Null for the Manticore and the warband together, which use all three.
	 */
	static Color styleColour(String icon, SolSurvivorConfig config)
	{
		if (icon == null)
		{
			return null;
		}
		switch (icon)
		{
			case "shaman":
			case "shockwave":
			case "seer":
				return config.waveBoxMagicColour();
			case "javelin":
			case "archer":
				return config.waveBoxRangedColour();
			case "jaguar":
			case "minotaur":
			case "berserker":
				return config.waveBoxMeleeColour();
			default:
				return null;
		}
	}

	/** A tinted name still to come: the tint a little darker, as an untinted one is grey rather than white. */
	static Color toCome(Color tint)
	{
		return new Color(tint.getRed() * 4 / 5, tint.getGreen() * 4 / 5, tint.getBlue() * 4 / 5);
	}

	/** How many there are as a colour: yellow for one, orange for two, red for three or more, grey for none. */
	static Color countColour(int count)
	{
		return count <= 0 ? DEAD : count == 1 ? ONE : count == 2 ? TWO : MORE;
	}

	/** The count as a line reads it: "+1" for those still to come, the dead's "0" without the sign. */
	static String count(WaveRoster.Line line, boolean toCome)
	{
		return (toCome && !line.isDead() ? "+" : "") + line.getCount();
	}

	private static float alpha(WaveRoster.Line line, boolean toCome)
	{
		return line.isDead() ? 0.45f : toCome ? 0.8f : 1f;
	}

	private BufferedImage face(String icon, float alpha)
	{
		if (icon == null)
		{
			return null;
		}
		return faces.computeIfAbsent(icon + "@" + alpha, key ->
		{
			Icon drawn = Icons.npc(icon, FACE, alpha);
			BufferedImage image = new BufferedImage(drawn.getIconWidth(), drawn.getIconHeight(), BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = image.createGraphics();
			drawn.paintIcon(null, g, 0, 0);
			g.dispose();
			return image;
		});
	}

	/** Words as RuneLite's own components draw them: a black shadow a pixel down and right. */
	private static void text(Graphics2D graphics, String words, int x, int baseline, Color colour)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(words, x + 1, baseline + 1);
		graphics.setColor(colour);
		graphics.drawString(words, x, baseline);
	}

	/** A line's height in the box's font, at least a face high, with its text's baseline centred in it. */
	private static int height(FontMetrics metrics)
	{
		return Math.max(FACE, metrics.getHeight()) + 1;
	}

	private static int baseline(FontMetrics metrics, int y)
	{
		return y + (height(metrics) - metrics.getHeight()) / 2 + metrics.getAscent();
	}

	/** A piece of the box laid out across its width: the panel tells it where it goes and how wide it is. */
	private abstract static class Piece implements LayoutableRenderableEntity
	{
		Point at = new Point();
		Dimension size = new Dimension(ComponentConstants.STANDARD_WIDTH, 0);
		final Rectangle bounds = new Rectangle();

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point position)
		{
			at = position;
		}

		@Override
		public void setPreferredSize(Dimension dimension)
		{
			size = dimension;
		}

		Dimension drawn(int height)
		{
			bounds.setBounds(at.x, at.y, size.width, height);
			return new Dimension(size.width, height);
		}
	}

	/** A wave's head: a dark band across the box, its title on the left and "now" or "next" quietly on the right. */
	private static final class Band extends Piece
	{
		private final String title;
		private final String which;

		Band(String title, String which)
		{
			this.title = title;
			this.which = which;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			FontMetrics metrics = graphics.getFontMetrics();
			int height = height(metrics);
			graphics.setColor(BAND);
			// The band runs into the box's border, two pixels each side, so that it reads as a bar across the box.
			graphics.fillRect(at.x - 2, at.y, size.width + 4, height);
			text(graphics, title, at.x + 2, baseline(metrics, at.y), TITLE);
			Font was = graphics.getFont();
			graphics.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics small = graphics.getFontMetrics();
			int y = at.y + (height - small.getHeight()) / 2 + small.getAscent();
			text(graphics, which, at.x + size.width - small.stringWidth(which) - 2, y, TO_COME);
			graphics.setFont(was);
			return drawn(height);
		}
	}

	/**
	 * A line of the box: the count, coloured by how many, then the NPC's face and short name, tinted by its attack style,
	 * and struck when all are dead.
	 */
	private static final class Row extends Piece
	{
		private final WaveRoster.Line line;
		private final boolean toCome;
		private final BufferedImage face;
		private final Color tint;

		Row(WaveRoster.Line line, boolean toCome, BufferedImage face, Color tint)
		{
			this.line = line;
			this.toCome = toCome;
			this.face = face;
			this.tint = tint;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			FontMetrics metrics = graphics.getFontMetrics();
			int height = height(metrics);
			int baseline = baseline(metrics, at.y);
			String count = count(line, toCome);
			text(graphics, count, at.x + COUNT_WIDTH - metrics.stringWidth(count), baseline, countColour(line.getCount()));
			int x = at.x + COUNT_WIDTH + GAP;
			if (face != null)
			{
				graphics.drawImage(face, x, at.y + (height - FACE) / 2, null);
			}
			x += FACE + GAP;
			boolean dead = line.isDead();
			String name = line.getShortName();
			Color colour = tint == null ? (toCome ? TO_COME : TEXT) : toCome ? toCome(tint) : tint;
			text(graphics, name, x, baseline, dead ? DEAD : colour);
			if (dead)
			{
				graphics.setColor(DEAD);
				graphics.fillRect(x - 1, at.y + height / 2, metrics.stringWidth(name) + 2, 1);
			}
			return drawn(height);
		}
	}

	/** A strip of nothing, between the wave under way and the next. */
	private static final class Space extends Piece
	{
		private final int height;

		Space(int height)
		{
			this.height = height;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			return drawn(height);
		}
	}
}

package nl.dexanddice.solsurvivor;

import static nl.dexanddice.solsurvivor.SolSurvivorPanel.bold;
