	/**
	 * The death report, a page of its own: Home to the panel; a card that says when the player died and what did it; how it
	 * happened, in steps; a card of the last ticks before, folded under the steps, each with the hitpoints, the protection
	 * prayer up, what happened and what it hit for; and the buttons; and under them the wave's report as a line, whose page Back brings the player here from.
	 */
	private void buildDeathPage(Recap r)
	{
		Stone.Button home = new Stone.Button("‹ Home", null, false, small(), 7, 5);
		home.setToolTipText("Back to the panel, where this report stays a click away until you enter the arena again.");
		home.addActionListener(e -> pages.showMain());
		JPanel bar = clear(new BorderLayout(8, 0));
		bar.add(home, BorderLayout.WEST);
		bar.add(new Stone.Shadowed("Death report", bold(), Stone.ORANGE), BorderLayout.CENTER);
		deathPage.add(left(bar));
		deathPage.add(left(deathResultBox));
		deathPage.add(SolSurvivorPanel.gap(8));

		Stone.Row head = card();
		head.setGlow(Stone.BAD);
		JPanel title = clear(new BorderLayout(8, 0));
		title.add(new Stone.Slot(30, SKULL), BorderLayout.WEST);
		JPanel text = clear(new BorderLayout(0, 1));
		text.add(new Stone.Shadowed("You died on wave " + r.wave, bold(), Stone.ORANGE), BorderLayout.NORTH);
		text.add(label(r.when, small(), Stone.MUTED), BorderLayout.CENTER);
		title.add(text, BorderLayout.CENTER);
		head.add(left(title));
		if (r.cause != null)
		{
			head.add(SolSurvivorPanel.gap(6));
			Stone.Well cause = new Stone.Well(null, 4, 6, 5, 6);
			cause.setLayout(new BoxLayout(cause, BoxLayout.Y_AXIS));
			cause.add(left(label("What did it", small(), Stone.MUTED)));
			cause.add(left(label(wrap(r.cause, 184), small(), Stone.TEXT)));
			head.add(left(cause));
		}
		deathPage.add(left(head));

		List<Step> steps = steps(r.lines);
		if (!steps.isEmpty())
		{
			// How it happened, in steps (the design review's 9, Stefan's choice of 2026-10-31): each hit that cost
			// hitpoints and each attack that got past the prayer, in order, the one past the prayer marked in yellow as
			// the moment to have done otherwise; every tick stays one click under it.
			deathPage.add(SolSurvivorPanel.gap(5));
			Stone.Row how = card();
			how.add(left(new Stone.Shadowed("How it happened", bold(), Stone.ORANGE)));
			how.add(SolSurvivorPanel.gap(4));
			for (int i = 0; i < steps.size(); i++)
			{
				how.add(left(stepLine(i + 1, steps.get(i))));
				how.add(SolSurvivorPanel.gap(3));
			}
			deathPage.add(left(how));
		}

		if (!r.lines.isEmpty())
		{
			deathPage.add(SolSurvivorPanel.gap(5));
			Stone.Row ticks = card();
			String span = r.lines.get(0).getTick() + " to " + r.lines.get(r.lines.size() - 1).getTick();
			if (steps.isEmpty())
			{
				ticks.add(left(new Stone.Shadowed("The last " + r.lines.size() + " ticks", bold(), Stone.ORANGE)));
				ticks.add(SolSurvivorPanel.gap(4));
			}
			Stone.Well well = new Stone.Well(null, 2, 2, 2, 2);
			well.setLayout(new BoxLayout(well, BoxLayout.Y_AXIS));
			well.add(recapRow(label("Tick", small(), Stone.MUTED), label("HP", small(), Stone.MUTED), new JLabel(),
				label("What happened", small(), Stone.MUTED), label("Hit", small(), Stone.MUTED), null, false));
			for (int i = 0; i < r.lines.size(); i++)
			{
				WaveReview.RecapLine l = r.lines.get(i);
				Integer hp = l.getHitpoints();
				JLabel tick = label(String.valueOf(l.getTick()), small(), Stone.MUTED);
				JLabel hitpoints = label(hp == null ? "?" : String.valueOf(hp), small(), hpColour(hp, r.maxHitpoints));
				JLabel prayer = l.getPrayer() == null || l.getPrayer().isEmpty() ? label("–", small(), Stone.DIM)
					: new JLabel(Icons.of("prayer-" + l.getPrayer(), 14));
				prayer.setToolTipText(prayerName(l.getPrayer()));
				JLabel what = label(wrap(l.getText(), 80), small(), Stone.TEXT);
				boolean hit = l.getHit().matches("[1-9][0-9]*");
				JComponent landed = recapHit(l.getHit());
				Color tint = !hit ? null : i == r.lines.size() - 1 ? new Color(232, 69, 46, 52) : new Color(232, 69, 46, 31);
				well.add(recapRow(tick, hitpoints, prayer, what, landed, tint, i == r.lines.size() - 1));
			}
			if (!steps.isEmpty())
			{
				// Under the steps the table is folded, its button saying which ticks it holds.
				Stone.Button every = new Stone.Button("Every tick, " + span + " ▸", null, false, small(), 7, 5);
				every.setToolTipText("Shows each of the last ticks: your hitpoints, your prayer, what happened and what it hit for.");
				well.setVisible(false);
				every.addActionListener(e ->
				{
					well.setVisible(!well.isVisible());
					every.setText("Every tick, " + span + (well.isVisible() ? " ▾" : " ▸"));
					deathPage.revalidate();
					deathPage.repaint();
				});
				ticks.add(left(every));
				ticks.add(SolSurvivorPanel.gap(4));
			}
			ticks.add(left(well));
			deathPage.add(left(ticks));
		}

		int from = r.lines.isEmpty() ? 0 : r.lines.get(0).getTick();
		Stone.Button open = new Stone.Button("Watch from tick " + from, null, upload, small(), 7, 6);
		open.setToolTipText("Uploads this run and opens it on the Sol Survivor site at tick " + from + " of this wave. Needs Upload past runs, in the settings.");
		open.addActionListener(e -> actions.watchAt(r.id, from));
		Stone.Button watch = new Stone.Button("Watch the run", null, false, small(), 7, 6);
		watch.setToolTipText("Uploads this run and opens it on the Sol Survivor site at this wave's start. Needs Upload past runs, in the settings.");
		watch.addActionListener(e -> actions.watchAt(r.id, null));
		JPanel foot = buttons(open, watch);
		foot.setBorder(new EmptyBorder(6, 0, 2, 0));
		deathPage.add(left(foot));
		addUploadOff(deathPage);
		if (report != null)
		{
			// The wave's report as a line: the death is the page's, and the report's page is a click away, Back to here.
			deathPage.add(SolSurvivorPanel.gap(8));
			Stone.Row line = card();
			line.add(left(reportLine(report)));
			deathPage.add(left(line));
		}
	}

	/** A step of the death: its tick, what happened, the hitpoints before and after, what it hit for, and whether it is the turn. */
	static final class Step
	{
		final int tick;
		final String text;
		final Integer before;
		final Integer after;
		final String hit;
		final String prayer;
		/** An attack that got past the prayer: the moment to have done otherwise, marked in yellow. */
		final boolean past;

		Step(int tick, String text, Integer before, Integer after, String hit, String prayer, boolean past)
		{
			this.tick = tick;
			this.text = text;
			this.before = before;
			this.after = after;
			this.hit = hit;
			this.prayer = prayer;
			this.past = past;
		}

		@Override
		public String toString()
		{
			return tick + " " + text + " " + before + "→" + after + " " + hit + (past ? " past" : "");
		}
	}

	/**
	 * The death in steps, from the recap's ticks: each tick whose attack hit for something, and each whose attack got past
	 * the prayer, in order, with the hitpoints before it (the tick before's) and after it. Empty when no tick did either,
	 * and the recap's table stands alone.
	 */
	static List<Step> steps(List<WaveReview.RecapLine> lines)
	{
		List<Step> steps = new ArrayList<>();
		Integer before = null;
		for (WaveReview.RecapLine l : lines)
		{
			boolean hit = l.getHit().matches("[1-9][0-9]*");
			boolean past = l.getText().contains("past your prayer");
			if (hit || past)
			{
				steps.add(new Step(l.getTick(), l.getText(), before, l.getHitpoints(), hit ? l.getHit() : null, l.getPrayer(), past));
			}
			before = l.getHitpoints();
		}
		return steps;
	}

	/** A step's line: its number in a dot, what happened over its tick and hitpoints, and what it hit for. */
	private static JPanel stepLine(int n, Step step)
	{
		Stone.Well line = new Stone.Well(null, 4, 5, 4, 5);
		line.setLayout(new BorderLayout(6, 0));
		JLabel number = label(String.valueOf(n), small(), step.past ? Stone.YELLOW : Stone.MUTED);
		number.setVerticalAlignment(JLabel.TOP);
		number.setPreferredSize(new Dimension(12, number.getPreferredSize().height));
		line.add(number, BorderLayout.WEST);
		JPanel words = clear(new BorderLayout(0, 1));
		words.add(label(wrap(step.text, 150), small(), Stone.TEXT), BorderLayout.NORTH);
		String hitpoints = step.before == null || step.after == null ? "" : " · " + step.before + " → " + step.after;
		String detail = step.past
			? "t" + step.tick + " · " + (step.prayer == null || step.prayer.isEmpty() ? "no protection prayer up" : prayerName(step.prayer) + " up")
			: "t" + step.tick + hitpoints;
		words.add(label(detail, small(), step.past ? Stone.YELLOW : Stone.MUTED), BorderLayout.CENTER);
		line.add(words, BorderLayout.CENTER);
		if (step.hit != null)
		{
			JPanel pill = clear(new BorderLayout());
			pill.add(new Stone.Pill(step.hit, true, small()), BorderLayout.NORTH);
			line.add(pill, BorderLayout.EAST);
		}
		if (step.past)
		{
			line.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Stone.YELLOW), new EmptyBorder(3, 4, 3, 4)));
		}
		return left(line);
	}

	/** A blocked hit stays compact in the narrow Hit column, with the full meaning on hover. */
	static JComponent recapHit(String hit)
	{
		if (hit.matches("[1-9][0-9]*"))
		{
			return new Stone.Pill(hit, true, small());
		}
		JLabel value = label("blocked".equals(hit) ? "–" : hit, small(), Stone.MUTED);
		if ("blocked".equals(hit))
		{
			value.setToolTipText("Blocked: the attack did no damage.");
		}
		return value;
	}

	/** A row of the recap's table, its columns at fixed widths so that they line up from row to row, on a tint or none. */
	private static JPanel recapRow(JComponent tick, JComponent hp, JComponent prayer, JComponent what, JComponent hit, Color tint, boolean last)
	{
		JPanel row = new JPanel(new GridBagLayout())
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				if (tint != null)
				{
					g.setColor(tint);
					g.fillRect(0, 0, getWidth(), getHeight());
				}
			}
		};
		row.setOpaque(false);
		GridBagConstraints c = new GridBagConstraints();
		c.anchor = GridBagConstraints.NORTHWEST;
		c.insets = new Insets(0, 0, 0, 4);
		cell(row, c, 0, fixed(tick, 22), 0);
		cell(row, c, 1, fixed(hp, 18), 0);
		cell(row, c, 2, fixed(prayer, 15), 0);
		cell(row, c, 3, what, 1);
		c.insets = new Insets(0, 0, 0, 0);
		c.anchor = GridBagConstraints.NORTHEAST;
		cell(row, c, 4, fixed(hit, 26), 0);
		row.setBorder(lined(last, new EmptyBorder(3, 3, 3, 4)));
		return left(row);
	}

	private static JComponent fixed(JComponent c, int width)
	{
		JPanel box = clear(new BorderLayout());
		box.add(c, BorderLayout.WEST);
		Dimension d = new Dimension(width, c.getPreferredSize().height);
		box.setPreferredSize(d);
		box.setMinimumSize(d);
		return box;
	}

	private static void cell(JPanel table, GridBagConstraints c, int x, JComponent cell, double weight)
	{
		c.gridx = x;
		c.gridy = 0;
		c.weightx = weight;
		c.fill = weight > 0 ? GridBagConstraints.HORIZONTAL : GridBagConstraints.NONE;
		table.add(cell, c);
	}

	/** Hitpoints coloured by their share of the wave's most: half or more green, a quarter or more amber, less red. */
	private static Color hpColour(Integer hp, int most)
	{
		if (hp == null || most <= 0)
		{
			return Stone.TEXT;
		}
		return hp * 2 >= most ? FINE : hp * 4 >= most ? FAIR : POOR;
	}

	private static String prayerName(String prayer)
	{
		if ("magic".equals(prayer))
		{
			return "Protect from Magic";
		}
		if ("ranged".equals(prayer))
		{
			return "Protect from Missiles";
		}
		if ("melee".equals(prayer))
		{
			return "Protect from Melee";
		}
		return prayer == null ? "Not in the log" : "No protection prayer";
	}

	/** A card of the report's page or the recap: a raised row whose parts go one under another. */
	private static Stone.Row card()
	{
		Stone.Row card = new Stone.Row(null, 6, 6, 6, 6);
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		return card;
	}

	/** Two buttons side by side, each half the width. */
	private static JPanel buttons(JComponent first, JComponent second)
	{
		JPanel row = clear(new java.awt.GridLayout(1, 2, 5, 0));
		row.add(first);
		row.add(second);
		row.setBorder(new EmptyBorder(6, 0, 0, 0));
		return row;
	}

	/** A small heading over a well, in the designs' muted words. */
	private static JComponent section(String text)
	{
		JLabel l = label(text, small(), Stone.MUTED);
		l.setBorder(new EmptyBorder(0, 1, 3, 0));
		return left(l);
	}

	/** A line of a well's list: a rule under it in the panel's ground, but under the last. */
	private static javax.swing.border.Border lined(boolean last, EmptyBorder padding)
	{
		return last ? padding : BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 0, 2, 0, Stone.BACKGROUND), padding);
	}

	/** A component held to the top of its cell, as BorderLayout's sides would stretch it to the row's height. */
	private static JPanel top(JComponent c)
	{
		JPanel box = clear(new BorderLayout());
		box.add(c, BorderLayout.NORTH);
		return box;
	}

	private static <T extends JComponent> T left(T c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		return c;
	}

	/** A legend's key: a square of the bar's colour, and its words. */
	private static JLabel key(Color colour, String text)
	{
		JLabel l = label(text, small(), Stone.TEXT);
		l.setIcon(Stone.square(9, colour));
		l.setIconTextGap(4);
		return l;
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	static String plural(int n, String one)
	{
		return n + " " + (n == 1 ? one : one + "s");
	}

	/** The prayer against the wave's attacks as one bar: on time, a tick off, the wrong prayer and none up, by their share. */
	private static final class PrayerBar extends JComponent
	{
		private final int[] parts;

		PrayerBar(Report r)
		{
			parts = new int[] {r.onTime, r.tickOff, r.wrong, r.none};
			setPreferredSize(new Dimension(180, 12));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 12));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			int w = getWidth();
			int h = getHeight();
			int total = parts[0] + parts[1] + parts[2] + parts[3];
			Color[] colours = {ON_TIME, A_TICK_OFF, WRONG, NONE_UP};
			int x = 0;
			int sum = 0;
			for (int i = 0; i < parts.length && total > 0; i++)
			{
				sum += parts[i];
				int to = (int) Math.round((double) w * sum / total);
				g2.setColor(colours[i]);
				g2.fillRect(x, 0, to - x, h);
				x = to;
			}
			g2.dispose();
		}
	}

	/**
	 * The run's mistakes wave by wave: a bar for each wave with its count over it and its number under it, green for a
	 * clean wave, amber for one or two mistakes and red for more, as the designs colour them.
	 */
	/**
	 * The wave in a strip (the design review's 8, Stefan's choice of 2026-10-31): its ticks from the start to its last
	 * across the width, and on it each mistake where it fell, in its attack's colour, the game's blue for magic, green for
	 * ranged and red for melee; orange for a special, a blast or the sand, and an idle stretch as long as it lasted in
	 * grey. Under it the start and the wave's time. So the eye sees at once whether the mistakes came together, and when.
	 */
	static final class WaveStrip extends JComponent
	{
		static final Color MAGIC = new Color(0x4d8bff);
		static final Color RANGED = new Color(0x38c246);
		static final Color MELEE = new Color(0xe23b2b);
		private static final int BAR = 16;

		private final List<Row> rows;
		private final int last;
		private final String time;

		WaveStrip(List<Row> rows, int last, String time)
		{
			this.rows = rows;
			this.last = last;
			this.time = time;
			setFont(small());
			setPreferredSize(new Dimension(190, BAR + getFontMetrics(small()).getHeight() + 2));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
			setToolTipText("<html>Each mistake where it fell in the wave, in its attack's colour:<br>blue magic, green ranged, red melee;"
				+ "<br>orange a special, a blast or the sand; grey an idle stretch.</html>");
		}

		/** A mistake's colour on the strip, by its attack's style or, for no attack's, by what it was. */
		static Color colourOf(Row row)
		{
			if ("magic".equals(row.style))
			{
				return MAGIC;
			}
			if ("ranged".equals(row.style))
			{
				return RANGED;
			}
			if ("melee".equals(row.style))
			{
				return MELEE;
			}
			return "hourglass".equals(row.icon) ? Stone.DIM : Stone.ORANGE;
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_GASP);
			int width = getWidth();
			Stone.paintWell(g2, width, BAR);
			int inner = Math.max(1, width - 4);
			// The idle stretches first, under the marks, as long as they lasted.
			for (Row row : rows)
			{
				if ("hourglass".equals(row.icon) && row.badge.matches("[0-9]+t"))
				{
					int ticks = Integer.parseInt(row.badge.substring(0, row.badge.length() - 1));
					int from = 2 + inner * row.tick / Math.max(1, last);
					int to = 2 + inner * Math.min(last, row.tick + ticks) / Math.max(1, last);
					g2.setColor(Stone.DIM);
					g2.fillRect(from, 5, Math.max(2, to - from), BAR - 10);
				}
			}
			// Marks that land within a few pixels of each other, such as a Manticore's three orbs, share the mark's height,
			// one above another in their order, so that each colour shows.
			Map<Integer, List<Row>> spots = new LinkedHashMap<>();
			for (Row row : rows)
			{
				if (!"hourglass".equals(row.icon))
				{
					int x = Math.min(2 + inner * row.tick / Math.max(1, last), width - 4);
					spots.computeIfAbsent(x / 4, k -> new ArrayList<>()).add(row);
				}
			}
			for (List<Row> spot : spots.values())
			{
				int x = Math.min(2 + inner * spot.get(0).tick / Math.max(1, last), width - 4);
				int tall = BAR - 6;
				g2.setColor(Stone.OUTLINE);
				g2.fillRect(x - 2, 2, 5, BAR - 4);
				for (int i = 0; i < spot.size(); i++)
				{
					int top = 3 + tall * i / spot.size();
					int bottom = 3 + tall * (i + 1) / spot.size();
					g2.setColor(colourOf(spot.get(i)));
					g2.fillRect(x - 1, top, 3, Math.max(1, bottom - top));
				}
			}
			g2.setFont(getFont());
			FontMetrics fm = g2.getFontMetrics();
			int base = BAR + 1 + fm.getAscent();
			g2.setColor(Stone.MUTED);
			g2.drawString("start", 0, base);
			g2.drawString(time, width - fm.stringWidth(time), base);
			g2.dispose();
		}
	}

	private static final class RunChart extends JComponent
	{
		private final int[] waves;
		private final int[] counts;
		private final int selected;

		RunChart(int[] waves, int[] counts, int selected)
		{
			this.waves = waves;
			this.counts = counts;
			this.selected = selected;
			setPreferredSize(new Dimension(190, 64));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 64));
			setFont(small());
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_GASP);
			g2.setFont(getFont());
			FontMetrics fm = g2.getFontMetrics();
			int most = 1;
			for (int c : counts)
			{
				most = Math.max(most, c);
			}
			int n = waves.length;
			// A slot for each wave across the width, as the designs share it, but no wider than a quarter of it.
			int slot = Math.max(1, getWidth() / Math.max(n, 4));
			int top = fm.getHeight() + 2;
			int bottom = getHeight() - fm.getHeight() - 1;
			int tall = Math.max(1, bottom - top);
			for (int i = 0; i < n; i++)
			{
				int x = i * slot;
				int barW = Math.max(3, slot - 3);
				int barH = counts[i] == 0 ? 2 : Math.max(3, tall * counts[i] / most);
				Color colour = counts[i] == 0 ? ON_TIME : counts[i] <= 2 ? FAIR : POOR;
				g2.setColor(colour);
				g2.fillRect(x + (slot - barW) / 2, bottom - barH, barW, barH);
				String count = String.valueOf(counts[i]);
				g2.setColor(counts[i] == 0 ? FINE : colour);
				g2.drawString(count, x + (slot - fm.stringWidth(count)) / 2, bottom - barH - 2);
				String wave = String.valueOf(waves[i]);
				g2.setColor(waves[i] == selected ? Stone.YELLOW : Stone.MUTED);
				g2.drawString(wave, x + (slot - fm.stringWidth(wave)) / 2, getHeight() - fm.getDescent());
			}
			g2.dispose();
		}
	}

	/** The report as text, for the clipboard. */
	static String text(Report r)
	{
		List<String> lines = new ArrayList<>();
		lines.add("Sol Survivor: wave " + r.wave + " report, " + r.time);
		if (r.attacks() > 0)
		{
			lines.add("Prayer against " + plural(r.attacks(), "attack") + ": " + r.onTime + " on time, " + r.tickOff + " a tick off, " + r.wrong
				+ " wrong prayer, " + r.none + " with none up.");
		}
		lines.add(r.mistakes.isEmpty() ? "No mistakes counted." : plural(r.mistakes.size(), "mistake") + ":");
		for (Row m : r.mistakes)
		{
			lines.add("Tick " + m.tick + ": " + m.text + " (" + m.badge + ")");
		}
		if (r.notCounted != null)
		{
			lines.add(r.notCounted);
		}
		if (r.common != null)
		{
			lines.add(r.common);
		}
		return String.join("\n", lines);
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TitleComponent;
import nl.dexanddice.solsurvivor.core.WaveClock;

/** Shared drawing for the movable clocks: the wave box's background, orange title and white shadowed figures. */
abstract class WaveClockOverlay extends OverlayPanel
{
	protected final SolSurvivorPlugin plugin;
	protected final SolSurvivorConfig config;

	WaveClockOverlay(SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	protected boolean combined()
	{
		return config.tickCounter() && config.waveTimer() && config.combineWaveTimers();
	}

	protected String ticks(WaveClock.View view)
	{
		return config.tickCounterCounts() == SolSurvivorConfig.TickCounterCounts.LOOP
			? view.loop(config.tickLoopLength()) : view.up();
	}

	/** The wave timer's reading at this frame: real seconds, so it moves between ticks as a clock does. */
	protected static String time(WaveClock.View view)
	{
		return view.time(System.currentTimeMillis());
	}

	/**
	 * The colour of the loop's current position, or null for the plain white look: counting up, with Loop colours off,
	 * or with the counter hidden. Every position has a colour of its own, so no tick stands out from the rest.
	 */
	protected Color loopColour(WaveClock.View view)
	{
		if (config.tickCounterCounts() != SolSurvivorConfig.TickCounterCounts.LOOP
			|| config.loopColours() == SolSurvivorConfig.LoopColours.OFF || !view.counterVisible(config.quietOnSol()))
		{
			return null;
		}
		switch (view.loopPosition(config.tickLoopLength()))
		{
			case 1: return config.tickLoopColour1();
			case 2: return config.tickLoopColour2();
			case 3: return config.tickLoopColour3();
			case 4: return config.tickLoopColour4();
			case 5: return config.tickLoopColour5();
			case 6: return config.tickLoopColour6();
			case 7: return config.tickLoopColour7();
			case 8: return config.tickLoopColour8();
			case 9: return config.tickLoopColour9();
			default: return config.tickLoopColour10();
		}
	}

	/** The number's colour: the loop's colour with Number chosen, else white. */
	protected Color numberColour(WaveClock.View view)
	{
		Color colour = loopColour(view);
		return colour != null && config.loopColours() == SolSurvivorConfig.LoopColours.NUMBER ? colour : Color.WHITE;
	}

	/**
	 * With Box chosen, the box takes a darker shade of the loop's colour, so that the white figures stay readable on it;
	 * otherwise RuneLite's standard background.
	 */
	protected void background(WaveClock.View view)
	{
		Color colour = loopColour(view);
		panelComponent.setBackgroundColor(colour != null && config.loopColours() == SolSurvivorConfig.LoopColours.BOX
			? new Color(colour.getRed() / 2, colour.getGreen() / 2, colour.getBlue() / 2, 200)
			: ComponentConstants.STANDARD_BACKGROUND_COLOR);
	}

	protected void title(WaveClock.View view)
	{
		panelComponent.getChildren().add(TitleComponent.builder().text(view.title()).color(new Color(0xff981f)).build());
	}

	protected void number(String value, float size)
	{
		number(value, size, Color.WHITE);
	}

	protected void number(String value, float size, Color colour)
	{
		panelComponent.getChildren().add(new Figures(value, FontManager.getRunescapeBoldFont().deriveFont(size), colour));
	}

	protected Dimension draw(Graphics2D graphics, int width)
	{
		panelComponent.setPreferredSize(new Dimension(width, 0));
		Font was = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		try
		{
			return super.render(graphics);
		}
		finally
		{
			graphics.setFont(was);
		}
	}

	/** Centred figures use a common digit advance, so a tick cannot make the number jump sideways. */
	private static final class Figures implements LayoutableRenderableEntity
	{
		private final String text;
		private final Font font;
		private final Color colour;
		private Point at = new Point();
		private Dimension preferred = new Dimension();
		private final Rectangle bounds = new Rectangle();

		private Figures(String text, Font font, Color colour)
		{
			this.text = text;
			this.font = font;
			this.colour = colour;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			Font was = graphics.getFont();
			graphics.setFont(font);
			FontMetrics metrics = graphics.getFontMetrics();
			int digit = 0;
			for (char c = '0'; c <= '9'; c++)
			{
				digit = Math.max(digit, metrics.charWidth(c));
			}
			int textWidth = 0;
			for (char c : text.toCharArray())
			{
				textWidth += Character.isDigit(c) ? digit : metrics.charWidth(c);
			}
			int width = Math.max(preferred.width, textWidth + 2);
			int x = at.x + (width - textWidth) / 2;
			int y = at.y + metrics.getAscent();
			for (char c : text.toCharArray())
			{
				int advance = Character.isDigit(c) ? digit : metrics.charWidth(c);
				int offset = (advance - metrics.charWidth(c)) / 2;
				graphics.setColor(Color.BLACK);
				graphics.drawString(String.valueOf(c), x + offset + 1, y + 1);
				graphics.setColor(colour);
				graphics.drawString(String.valueOf(c), x + offset, y);
				x += advance;
			}
			graphics.setFont(was);
			bounds.setBounds(at.x, at.y, width, metrics.getHeight() + 1);
			return bounds.getSize();
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point location)
		{
			at = location;
		}

		@Override
		public void setPreferredSize(Dimension size)
		{
			preferred = size;
		}
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import nl.dexanddice.solsurvivor.core.WaveClock;

/** The wave's elapsed real time from modifier confirmation, independently movable from the tick number. */
class WaveTimerOverlay extends WaveClockOverlay
{
	@Inject
	WaveTimerOverlay(SolSurvivorPlugin plugin, SolSurvivorConfig config)
	{
		super(plugin, config);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		WaveClock.View view = plugin.waveClock();
		if (!config.waveTimer() || combined() || !plugin.inArena() || !view.timerVisible(config.quietOnSol()))
		{
			return null;
		}
		title(view);
		number(time(view), 24f);
		return draw(graphics, 116);
	}
}

package nl.dexanddice.solsurvivor;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import nl.dexanddice.solsurvivor.core.Modifier;
import nl.dexanddice.solsurvivor.core.WaveRoster;

/**
 * What the panel's wave card and the wave box show on a tick, built on the client thread from the tracker: the wave
 * under way and its list, or the next wave and what it brings, the modifiers held, and Doom's stacks against its limit.
 * Only what is in the arena or on its way: no timers, and nothing of how to play the wave.
 */
final class WaveView
{
	static final WaveView NONE = new WaveView(null, false, Collections.<WaveRoster.Line>emptyList(), null, Collections.<WaveRoster.Line>emptyList(),
		Collections.<WaveRoster.Line>emptyList(), null, Collections.<Modifier, Integer>emptyMap(), 0, 0);

	/** The wave under way, or the next between waves; null before the plugin has seen one. */
	final Integer wave;
	final boolean underWay;
	/** The list of the wave under way; empty between waves. */
	final List<WaveRoster.Line> thisWave;
	/** The wave after `wave` while it is under way, or `wave` itself between waves; null when there is none to list. */
	final Integer next;
	/** The next wave at its start, its reinforcements, and those in a sentence, the panel's "Then…". */
	final List<WaveRoster.Line> nextWave;
	final List<WaveRoster.Line> nextLater;
	final String nextThen;
	final Map<Modifier, Integer> held;
	/** Doom's stacks on the player, by the game's own count, and its limit at the tier held; the limit is 0 without Doom. */
	final int doomStacks;
	final int doomLimit;

	WaveView(Integer wave, boolean underWay, List<WaveRoster.Line> thisWave, Integer next, List<WaveRoster.Line> nextWave,
		List<WaveRoster.Line> nextLater, String nextThen, Map<Modifier, Integer> held, int doomStacks, int doomLimit)
	{
		this.wave = wave;
		this.underWay = underWay;
		this.thisWave = thisWave;
		this.next = next;
		this.nextWave = nextWave;
		this.nextLater = nextLater;
		this.nextThen = nextThen;
		this.held = held;
		this.doomStacks = doomStacks;
		this.doomLimit = doomLimit;
	}

	/** Whether Doom is on its last stack: one more hit that deals damage kills. */
	boolean doomLast()
	{
		return doomLimit > 0 && doomStacks >= doomLimit - 1;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof WaveView))
		{
			return false;
		}
		WaveView v = (WaveView) o;
		return Objects.equals(v.wave, wave) && v.underWay == underWay && v.thisWave.equals(thisWave) && Objects.equals(v.next, next)
			&& v.nextWave.equals(nextWave) && v.nextLater.equals(nextLater) && Objects.equals(v.nextThen, nextThen) && v.held.equals(held)
			&& v.doomStacks == doomStacks && v.doomLimit == doomLimit;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(wave, underWay, thisWave, next, nextWave, nextLater, nextThen, held, doomStacks, doomLimit);
	}
}

package nl.dexanddice.solsurvivor;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;

/**
 * A FlowLayout that wraps and asks for the height its wrapped lines take, which FlowLayout does not: its preferred size
 * is one long line, so a row of chips in the panel would be cut off rather than wrap. The width it wraps at is the
 * container's own once it has one, or `width` before the first layout.
 */
final class WrapLayout extends FlowLayout
{
	private final int width;

	WrapLayout(int hgap, int vgap, int width)
	{
		super(FlowLayout.LEFT, hgap, vgap);
		this.width = width;
	}

	@Override
	public Dimension preferredLayoutSize(Container target)
	{
		return size(target, true);
	}

	@Override
	public Dimension minimumLayoutSize(Container target)
	{
		return size(target, false);
	}

	private Dimension size(Container target, boolean preferred)
	{
		synchronized (target.getTreeLock())
		{
			Insets in = target.getInsets();
			int room = (target.getWidth() > 0 ? target.getWidth() : width) - in.left - in.right;
			int lineWidth = 0;
			int lineHeight = 0;
			int height = 0;
			int widest = 0;
			for (Component c : target.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = preferred ? c.getPreferredSize() : c.getMinimumSize();
				if (lineWidth > 0 && lineWidth + getHgap() + d.width > room)
				{
					height += lineHeight + getVgap();
					widest = Math.max(widest, lineWidth);
					lineWidth = 0;
					lineHeight = 0;
				}
				lineWidth += (lineWidth > 0 ? getHgap() : 0) + d.width;
				lineHeight = Math.max(lineHeight, d.height);
			}
			height += lineHeight;
			widest = Math.max(widest, lineWidth);
			return new Dimension(widest + in.left + in.right, height + in.top + in.bottom);
		}
	}

	@Override
	public void layoutContainer(Container target)
	{
		synchronized (target.getTreeLock())
		{
			Insets in = target.getInsets();
			int room = target.getWidth() - in.left - in.right;
			int x = 0;
			int y = 0;
			int lineHeight = 0;
			for (Component c : target.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				if (x > 0 && x + getHgap() + d.width > room)
				{
					y += lineHeight + getVgap();
					x = 0;
					lineHeight = 0;
				}
				x += x > 0 ? getHgap() : 0;
				c.setBounds(in.left + x, in.top + y, d.width, d.height);
				x += d.width;
				lineHeight = Math.max(lineHeight, d.height);
			}
		}
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * The Colosseum's arena and the transform from the game's region coordinates to the LoS tool's grid (combat research §9):
 * x = regionX - 16 and y = 51 - regionY, in region 7216. The game gives an instance's tiles in their template's region,
 * which the RuneLite layer reads with WorldPoint.fromLocalInstance.
 */
public final class ArenaGeometry
{
	/** The arena's region, the template the instance is copied from. */
	public static final int REGION_ID = 7216;

	/** The lobby's region, where the run is entered from. */
	public static final int LOBBY_REGION_ID = 7316;

	/** The grid's width and height in tiles: 0 to 33 each way, the state link's MAP_SIZE. */
	public static final int SIZE = 34;

	private ArenaGeometry()
	{
	}

	/** The grid tile of a tile in the region, by its coordinates within it (0 to 63 each). */
	public static GridTile fromRegion(int regionX, int regionY)
	{
		return new GridTile(regionX - 16, 51 - regionY);
	}

	/** Whether a grid tile is on the grid the state link takes. */
	public static boolean onGrid(GridTile tile)
	{
		return tile.getX() >= 0 && tile.getX() < SIZE && tile.getY() >= 0 && tile.getY() < SIZE;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The arena on one tick, as the state link's `setup` holds it (src/link/statePayload.ts, SetupV1). A field the plugin
 * does not know is null, and the link leaves it out, so that the site falls back on its own: the wave when the plugin
 * started after the wave's message, the tick within the wave likewise.
 */
public final class ArenaState
{
	private final List<ExportNpc> npcs;
	private final GridTile player;
	private final boolean waveStart;
	private final Integer wave;
	private final Integer waveTick;
	private final boolean reinforcementsArrived;
	private final Map<Modifier, Integer> modifiers;
	private final boolean modifiersComplete;
	private final List<GridTile> solarflareOrbs;
	private final Integer doomStacks;
	private final List<GridTile> sand;

	public ArenaState(
		List<ExportNpc> npcs,
		GridTile player,
		boolean waveStart,
		Integer wave,
		Integer waveTick,
		boolean reinforcementsArrived,
		Map<Modifier, Integer> modifiers,
		boolean modifiersComplete,
		List<GridTile> solarflareOrbs,
		Integer doomStacks,
		List<GridTile> sand)
	{
		this.npcs = Collections.unmodifiableList(npcs);
		this.player = player;
		this.waveStart = waveStart;
		this.wave = wave;
		this.waveTick = waveTick;
		this.reinforcementsArrived = reinforcementsArrived;
		this.modifiers = Collections.unmodifiableMap(modifiers);
		this.modifiersComplete = modifiersComplete;
		this.solarflareOrbs = Collections.unmodifiableList(solarflareOrbs);
		this.doomStacks = doomStacks;
		this.sand = Collections.unmodifiableList(sand);
	}

	/**
	 * Mid-wave under Doom: the hits that dealt the player damage since the wave started, Doom's stacks; null without
	 * Doom, at the wave's start, or when the plugin did not see the wave start.
	 */
	public Integer getDoomStacks()
	{
		return doomStacks;
	}

	/** The tiles of molten sand on the floor, as far as the plugin knows them: see ColosseumTracker.capture. */
	public List<GridTile> getSand()
	{
		return sand;
	}

	/** The tiles of Solarflare's orbs on this tick, in the order the game lists them; empty without Solarflare. */
	public List<GridTile> getSolarflareOrbs()
	{
		return solarflareOrbs;
	}

	public List<ExportNpc> getNpcs()
	{
		return npcs;
	}

	public GridTile getPlayer()
	{
		return player;
	}

	/** Whether this is the wave's first tick, the LoS link's "_ws". */
	public boolean isWaveStart()
	{
		return waveStart;
	}

	/** The wave, 1 to 11, or null when the plugin has not seen it start. */
	public Integer getWave()
	{
		return wave;
	}

	/** Mid-wave: how many ticks ago the wave started, or null when the plugin has not seen it start. */
	public Integer getWaveTick()
	{
		return waveTick;
	}

	/** Mid-wave: whether the wave's reinforcements have come, after which none will. */
	public boolean isReinforcementsArrived()
	{
		return reinforcementsArrived;
	}

	/** The modifiers taken, each with its tier (1 for one without tiers). */
	public Map<Modifier, Integer> getModifiers()
	{
		return modifiers;
	}

	/**
	 * Whether the modifiers are all known. Those with tiers are read from their varbits at any time; Quartet, Red Flag and
	 * Totemic only from the modifier selector, so a plugin started mid-run knows them from the next pick on.
	 */
	public boolean isModifiersComplete()
	{
		return modifiersComplete;
	}

	/** Mantimayhem III, the LoS link's "_mm3", which lets a Manticore fire its melee orb first. */
	public boolean isMm3()
	{
		Integer level = modifiers.get(Modifier.MANTIMAYHEM);
		return level != null && level == 3;
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * The animations that mark a Colosseum NPC's attack, so that the plugin can time each NPC's next attack and count a
 * Javelin Colossus's throws (the design spec's "Attack timing"). Partly confirmed: the ids are taken from the names RuneLite
 * gives the game's animations (net.runelite.api.gameval.AnimationID), and the user's wave logs have confirmed four of them so far.
 *
 * - The first wave log (wave 2, 2026-10-18) showed the shaman casting with SHAMAN_CAST while its spells hit the player,
 *   and the Javelin Colossus with JAVELIN_THROW as its javelin hit. The second (wave 2 again) had both attack 5 ticks
 *   apart, as the site's engine has them.
 * - The third (wave 1, 2026-10-18), the first with the animation starts, showed the Jaguar warrior starting JAGUAR_CLAWS
 *   every 5 ticks from the tick after it reached a tile beside the player, each attack bringing three hitsplats on the
 *   player. The shaman started SHAMAN_CAST every 5 ticks too, and 10860 when it died.
 * - The fourth (wave 2, Reentry I and Frailty I) showed a Javelin Colossus throwing JAVELIN_THROW four times and then
 *   JAVELIN_SPECIAL as its 5th, 10th and 15th attacks, 5 ticks apart throughout. It first attacked 833 ticks after it
 *   spawned, so the special is counted by its attacks, as ColosseumTracker counts them, not by ticks since its spawn.
 *   The Jaguar there started 10848 (its block) each time the player hit it, which is not an attack.
 * - Still unconfirmed: the Minotaur's two and SHOCKWAVE_CLAP.
 *
 * The logs also showed each NPC's death: the shaman 10860, the Jaguar 10849 and the Javelin Colossus 10894.
 *
 * Each NPC shows 10861 on the wave's first ticks, its spawn, and a Jaguar that spawns mid-wave shows 10862.
 *
 * The Manticore is left out: its attacks are its orbs, which OrbOrder follows, and its timer turns on its charge. So is
 * the Minotaur's heal, which shares its attack timer but has no animation named for it.
 */
public final class AttackAnimations
{
	/** NPC_SERPENT_MAGER_CASTING: the serpent shaman's spell. */
	public static final int SHAMAN_CAST = 10859;
	/** NPC_COLOSSI_JAVELIN_01_RANGE_ATTACK: the Javelin Colossus's normal throw. */
	public static final int JAVELIN_THROW = 10892;
	/** NPC_COLOSSI_JAVELIN_01_ARTILLERY_ATTACK: the Javelin Colossus's special, the javelins that land on tiles. */
	public static final int JAVELIN_SPECIAL = 10893;
	/** NPC_JAGUAR_RANGER_CLAWS_ATTACK: the Jaguar warrior's claws. */
	public static final int JAGUAR_CLAWS = 10847;
	/** NPC_MINOTAUR_BOSS_ATTACK_MELEE: the Minotaur's melee attack. */
	public static final int MINOTAUR_MELEE = 10843;
	/** NPC_MINOTAUR_BOSS_ATTACK_MAGIC: the Minotaur's other attack animation, counted as an attack too. */
	public static final int MINOTAUR_MAGIC = 10844;
	/** NPC_COLOSSI_SHOCKWAVE_01_CLAPATTACK: the Shockwave Colossus's clap. */
	public static final int SHOCKWAVE_CLAP = 10903;

	private AttackAnimations()
	{
	}

	/** Whether an animation of an NPC of this id is one of its attacks. */
	public static boolean isAttack(int npcId, int animationId)
	{
		switch (npcId)
		{
			case NpcKind.SHAMAN_ID:
				return animationId == SHAMAN_CAST;
			case NpcKind.JAVELIN_ID:
				return animationId == JAVELIN_THROW || animationId == JAVELIN_SPECIAL;
			case NpcKind.JAGUAR_ID:
				return animationId == JAGUAR_CLAWS;
			case NpcKind.MINOTAUR_ID:
			case NpcKind.MINOTAUR_RED_FLAG_ID:
				return animationId == MINOTAUR_MELEE || animationId == MINOTAUR_MAGIC;
			case NpcKind.SHOCKWAVE_ID:
				return animationId == SHOCKWAVE_CLAP;
			default:
				return false;
		}
	}

	/** Whether an animation of an NPC of this id is a Javelin Colossus's special. */
	public static boolean isSpecial(int npcId, int animationId)
	{
		return npcId == NpcKind.JAVELIN_ID && animationId == JAVELIN_SPECIAL;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Locale;
import java.util.Random;
import java.util.regex.Pattern;

/**
 * The site's speed leaderboard (its src/edge/board.ts and docs/leaderboard.md), with "Leaderboard" and "Share wave logs"
 * on: once the site has taken a wave's log, the plugin asks for that wave to go on the boards under the player's
 * RuneScape name, or the Leaderboard name they typed, by the game's own wave clock, which the log carries. The request names the run's id, which only the plugin knows, so
 * that nobody else can add waves to the player's run, and the player's key: a random secret made once and kept in the
 * settings, which holds the name and the times as the player's and lets "Remove my times" take them all off. The
 * RuneLite layer sends the requests; this class makes their bodies and says the site's answers in words. It holds no
 * RuneLite import, as the rest of the core.
 */
public final class BoardEntry
{
	/** The bodies' type: JSON. */
	public static final String TYPE = "application/json";

	/**
	 * A name the site takes (its NAME): 1 to 12 letters, digits, spaces, hyphens or underscores, beginning and ending with
	 * a letter or a digit, as RuneScape's names are.
	 */
	private static final Pattern NAME = Pattern.compile("[A-Za-z0-9](?:[A-Za-z0-9 _-]{0,10}[A-Za-z0-9])?");

	/** A run's id or a key: 32 hexadecimal digits (the site's SECRET). */
	private static final Pattern SECRET = Pattern.compile("[a-f0-9]{32}");

	private BoardEntry()
	{
	}

	/** The site's endpoint that puts a wave on the boards. */
	public static String endpoint(String site)
	{
		return ReplayLink.origin(site) + "/api/board/waves";
	}

	/** The site's endpoint that takes all of a player's times off. */
	public static String removeEndpoint(String site)
	{
		return ReplayLink.origin(site) + "/api/board/remove";
	}

	/** The leaderboard's page. */
	public static String page(String site)
	{
		return ReplayLink.origin(site) + "/leaderboard";
	}

	/**
	 * The name as the site takes it, `typed` with the spaces at its ends dropped, or null when it is blank or not a name
	 * the site takes.
	 */
	public static String name(String typed)
	{
		String name = typed == null ? "" : typed.trim();
		return NAME.matcher(name).matches() ? name : null;
	}

	/**
	 * The player's RuneScape name as the site takes it, or null for one it does not: the game writes the spaces in a name
	 * as no-break spaces, which go up as plain ones.
	 */
	public static String fromPlayer(String rsn)
	{
		return rsn == null ? null : name(rsn.replace('\u00A0', ' '));
	}

	/** Whether `typed` is no name at all, which goes up as the RuneScape name, rather than one the site does not take. */
	public static boolean isBlank(String typed)
	{
		return typed == null || typed.trim().isEmpty();
	}

	/** Whether `key` is a key the plugin made. */
	public static boolean isKey(String key)
	{
		return key != null && SECRET.matcher(key).matches();
	}

	/** A new key: 32 random hexadecimal digits. */
	public static String newKey(Random random)
	{
		byte[] bytes = new byte[16];
		random.nextBytes(bytes);
		StringBuilder key = new StringBuilder(32);
		for (byte b : bytes)
		{
			key.append(Character.forDigit((b >> 4) & 0xf, 16)).append(Character.forDigit(b & 0xf, 16));
		}
		return key.toString();
	}

	/**
	 * The body that asks for wave `wave` of the run `run` to go on the boards under `name` (a name() that is not null) for
	 * the player whose key is `key`. Each is a run's id, a wave, a name or a key, which hold no character JSON escapes.
	 */
	public static String body(String run, int wave, String name, String key)
	{
		return "{\"run\":\"" + run + "\",\"wave\":" + wave + ",\"name\":\"" + name + "\",\"key\":\"" + key + "\"}";
	}

	/** The body that takes all of the times of the player whose key is `key` off the boards. */
	public static String removeBody(String key)
	{
		return "{\"key\":\"" + key + "\"}";
	}

	/** A time in ticks as the game's clock shows it, minutes, seconds and hundredths: a tick is 0.6 seconds. */
	public static String gameTime(int ticks)
	{
		int hundredths = ticks * 60;
		int seconds = hundredths / 100;
		return String.format(Locale.ROOT, "%d:%02d.%02d", seconds / 60, seconds % 60, hundredths % 100);
	}

	/** A place as it is said: 1st, 2nd, 3rd, 4th, 11th, 12th, 13th, 21st. */
	public static String place(int place)
	{
		int tens = place % 100;
		String suffix = tens >= 11 && tens <= 13 ? "th"
			: place % 10 == 1 ? "st"
			: place % 10 == 2 ? "nd"
			: place % 10 == 3 ? "rd"
			: "th";
		return place + suffix;
	}

	/** The site's answer to a wave, as its JSON holds it (the site's Entered); a figure the answer leaves out is null. */
	public static final class Answer
	{
		/** "entered", "held", "not counted" or "taken". */
		public String board;
		/** The name the player's times show under, or null when they have none yet. */
		public String name;
		public Integer wave;
		public Integer time;
		public Integer place;
		public Integer runTime;
		public Integer runPlace;
	}

	/** What the site's answer means for the player, in words for the panel, or null for one this plugin does not know. */
	public static String said(Answer answer, String asked)
	{
		if (answer == null || answer.board == null || answer.wave == null)
		{
			return null;
		}
		String wave = "wave " + answer.wave;
		switch (answer.board)
		{
			case "entered":
				return "Leaderboard: " + wave + (answer.time == null ? "" : " in " + gameTime(answer.time))
					+ (answer.place == null ? "" : ", " + place(answer.place)) + "."
					+ (answer.runTime == null ? "" : " Your full run: " + gameTime(answer.runTime)
					+ (answer.runPlace == null ? "" : ", " + place(answer.runPlace)) + ".");
			case "held":
				return "Leaderboard: " + wave + (answer.time == null ? "" : " in " + gameTime(answer.time))
					+ " is held for a look before it shows.";
			case "not counted":
				return "Leaderboard: " + wave + " is not on it, as the game's wave clock did not time it to its end.";
			case "taken":
				return answer.name == null
					? "Leaderboard: the name " + asked + " is another player's. Pick another in the plugin's settings."
					: "Leaderboard: the name " + asked + " is another player's, so " + wave + " went up as " + answer.name
					+ (answer.place == null ? "" : ", " + place(answer.place)) + ".";
			default:
				return null;
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * What one attack uses up inside a charged weapon, estimated (Stefan's ask of 2026-11-04: estimates are fine), from
 * the OSRS Wiki's page for each weapon, said here in our own words: the items a charge is made of and how many of each,
 * by item id, which the RuneLite side prices. Weapons are matched by name, so that an ornament or holy variant counts as
 * its weapon. The RuneLite side counts the attacks (RunProfit.Tracker.onAttack) by how each weapon spends its charges
 * (Counting): a ranged or magic weapon's by its projectiles leaving the player, so that a cast whose target dies before
 * it lands, which shows no hitsplat, still counts (Stefan's friend's Shadow, 2026-11-04); the scythe's by a tick with a
 * hit of the player's that did damage, as it uses a charge only then; the blade of Saeldor's and the toxic staff of the
 * dead's, melee too, by a tick with any hit of the player's, a miss's 0 too.
 *
 * Estimates: the blowpipe's darts assume Ava's assembler or Dizana's quiver keeps four in five, and a dragon dart; its
 * scales are two in three shots. A crystal shard has no Grand Exchange price, so the bow of Faerdhinen's, the crystal
 * bow's and the blade of Saeldor's charge is valued in coins at a shard's worth as the wiki values it, about 131 coins
 * for 100 charges. The toxic staff of the dead uses its scales over time in combat, here about 0.4 an attack.
 */
public final class ChargeCosts
{
	static final int COINS = 995;
	static final int FIRE_RUNE = 554;
	static final int EARTH_RUNE = 557;
	static final int DEATH_RUNE = 560;
	static final int CHAOS_RUNE = 562;
	static final int BLOOD_RUNE = 565;
	static final int SOUL_RUNE = 566;
	static final int DRAGON_DART = 11230;
	static final int ZULRAHS_SCALES = 12934;
	static final int REVENANT_ETHER = 21820;
	static final int VIAL_OF_BLOOD = 22446;
	static final int ANCIENT_ESSENCE = 27616;

	/** How the attacks that use a weapon's charges are counted. */
	public enum Counting
	{
		/** None: the weapon has no charges. */
		NONE,
		/** A projectile from the player, once a tick. */
		PROJECTILE,
		/** A tick with a hit of the player's that did damage. */
		DAMAGE,
		/** A tick with any hit of the player's. */
		HIT
	}

	/** Each weapon's name in lower case, as part of its variants' names, with what one attack uses. */
	private static final Map<String, Map<Integer, Double>> COSTS = new LinkedHashMap<>();

	static
	{
		put("toxic blowpipe", ZULRAHS_SCALES, 2 / 3.0, DRAGON_DART, 0.2);
		put("blazing blowpipe", ZULRAHS_SCALES, 2 / 3.0, DRAGON_DART, 0.2);
		put("trident of the seas", FIRE_RUNE, 5, CHAOS_RUNE, 1, DEATH_RUNE, 1, COINS, 10);
		put("trident of the swamp", FIRE_RUNE, 5, CHAOS_RUNE, 1, DEATH_RUNE, 1, ZULRAHS_SCALES, 1);
		put("sanguinesti staff", BLOOD_RUNE, 3);
		put("tumeken's shadow", SOUL_RUNE, 2, CHAOS_RUNE, 5);
		put("scythe of vitur", BLOOD_RUNE, 2, VIAL_OF_BLOOD, 0.01);
		put("bow of faerdhinen", COINS, 1.31);
		put("crystal bow", COINS, 1.31);
		put("blade of saeldor", COINS, 1.31);
		put("venator bow", ANCIENT_ESSENCE, 1);
		put("accursed sceptre", REVENANT_ETHER, 1);
		put("webweaver bow", REVENANT_ETHER, 1);
		put("warped sceptre", CHAOS_RUNE, 2, EARTH_RUNE, 5);
		put("eye of ayak", DEATH_RUNE, 2, CHAOS_RUNE, 1);
		put("toxic staff of the dead", ZULRAHS_SCALES, 0.4);
	}

	/** How a weapon's attacks are counted, by its name. */
	public static Counting counting(String weapon)
	{
		if (perAttack(weapon).isEmpty())
		{
			return Counting.NONE;
		}
		String name = weapon.toLowerCase(Locale.ROOT);
		if (name.contains("scythe of vitur"))
		{
			return Counting.DAMAGE;
		}
		// The two melee weapons with a charge a swing, hit or miss.
		return name.contains("blade of saeldor") || name.contains("toxic staff of the dead") ? Counting.HIT : Counting.PROJECTILE;
	}

	private ChargeCosts()
	{
	}

	private static void put(String name, double... idThenAmount)
	{
		Map<Integer, Double> each = new LinkedHashMap<>();
		for (int i = 0; i < idThenAmount.length; i += 2)
		{
			each.put((int) idThenAmount[i], idThenAmount[i + 1]);
		}
		COSTS.put(name, Collections.unmodifiableMap(each));
	}

	/** What one attack with the weapon of that name uses up, by item id; nothing for a weapon with no charges. */
	public static Map<Integer, Double> perAttack(String weapon)
	{
		if (weapon == null)
		{
			return Collections.emptyMap();
		}
		String name = weapon.toLowerCase(Locale.ROOT);
		for (Map.Entry<String, Map<Integer, Double>> c : COSTS.entrySet())
		{
			if (name.contains(c.getKey()))
			{
				return c.getValue();
			}
		}
		return Collections.emptyMap();
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * An item of the Colosseum's reward chest as the game holds it between waves: the name the game gives it, noted or not,
 * and how many. The pick link carries the next wave's reward and the chest so far as lists of them (PickPayload's
 * `chest`), so that the site's Claim the chest or go on needs nothing typed. The plugin prices nothing: the site matches
 * each name to its own table of the chest's items, and leaves one it does not know, such as wave 3's Varlamore token,
 * unpriced.
 */
public final class ChestItem
{
	private final String name;
	private final int quantity;

	public ChestItem(String name, int quantity)
	{
		this.name = name;
		this.quantity = quantity;
	}

	public String getName()
	{
		return name;
	}

	public int getQuantity()
	{
		return quantity;
	}
}

package nl.dexanddice.solsurvivor.core;

/**
 * The game's own counters for the wave and the run under way, which the wave log keeps on the wave's first tick and on
 * each tick one changes (WaveLogWriter's `counters`): each is a varp or a varbit, by the id RuneLite's gameval names it
 * by (VarPlayerID, VarbitID), and its key in the log is that name in camel case without COLOSSEUM_. What each holds is
 * the game's to say and the logs' to show: nothing in the plugin or on the site reads them yet. They are there so that
 * the logs can check the planner's Doom count and price a wave in the game's own glory.
 *
 * Only the counters of the wave and the run under way are logged: none of the account's own, such as its best glory or
 * waves completed, which the hiscores could tie to the player in a shared log. A shared log leaves out the wave's start
 * time and the run's total duration too (`shared`): nobody has seen what they hold, and a count of the world's ticks
 * would date the wave, which the Privacy page says a shared log does not. Copy wave log keeps them.
 */
public enum ColosseumCounter
{
	/** Doom's stacks on the player: VarbitID.COLOSSEUM_DOOM_STACKS_CLIENT. */
	DOOM_STACKS("doomStacks", true, 9801, true),
	/** VarPlayerID.COLOSSEUM_CURRENT_GLORY. */
	CURRENT_GLORY("currentGlory", false, 4132, true),
	/** VarPlayerID.COLOSSEUM_WAVE_START_TIME: not shared. */
	WAVE_START_TIME("waveStartTime", false, 4133, false),
	/** VarPlayerID.COLOSSEUM_WAVE_DAMAGE_TAKEN. */
	WAVE_DAMAGE_TAKEN("waveDamageTaken", false, 4134, true),
	/** VarPlayerID.COLOSSEUM_LAST_MODIFIER_GLORY. */
	LAST_MODIFIER_GLORY("lastModifierGlory", false, 4135, true),
	/** VarPlayerID.COLOSSEUM_LAST_WAVE_DURATION. */
	LAST_WAVE_DURATION("lastWaveDuration", false, 4136, true),
	/** VarPlayerID.COLOSSEUM_TOTAL_DURATION: not shared. */
	TOTAL_DURATION("totalDuration", false, 4137, false);

	private final String key;
	private final boolean varbit;
	private final int id;
	private final boolean shared;

	ColosseumCounter(String key, boolean varbit, int id, boolean shared)
	{
		this.key = key;
		this.varbit = varbit;
		this.id = id;
		this.shared = shared;
	}

	/** Its key in the log's `counters`. */
	public String getKey()
	{
		return key;
	}

	/** Whether it is a varbit; else it is a varp. */
	public boolean isVarbit()
	{
		return varbit;
	}

	/** The game's id for the varbit or the varp. */
	public int getId()
	{
		return id;
	}

	/** Whether a shared log (WaveLogWriter.toShare) holds it. */
	public boolean isShared()
	{
		return shared;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What the plugin remembers of a Colosseum run between ticks, fed the game's events by the RuneLite layer and free of
 * RuneLite itself, so that its tests run on mocked game data. It follows the wave from the game's chat messages, which
 * NPCs spawned after the wave's first tick (the reinforcements), the orbs each Manticore has shown, each NPC's attacks
 * and health bar, the hits that dealt the player damage this wave (Doom's stacks), the molten sand on the floor, and the
 * modifiers taken; capture() turns that and the NPCs and player of a tick into an ArenaState.
 *
 * It only reads: nothing here acts on the game. What the plugin draws, each overlay one the player can switch off,
 * is facts the game shows: the wave's NPCs and the player's own range (SolSurvivorPlugin).
 */
public final class ColosseumTracker
{
	/** The last wave Sol Survivor plans: wave 12 is Sol Heredit. */
	public static final int LAST_WAVE = 11;

	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	private static final Pattern WAVE_START = Pattern.compile("Wave: (\\d+)");
	private static final Pattern WAVE_DONE = Pattern.compile("Wave (\\d+) completed!");
	private static final String SOL_START = "Sol Heredit jumps down from his seat";

	/**
	 * The graphic on a Javelin Colossus's special's landing tile as it lands (RuneLite's SpotanimID
	 * WILD_FALLOFF_METEOR_BLAST_RED), with Reentry or without: in the user's logs it comes on the tile of the shadow, three
	 * ticks after it.
	 */
	public static final int JAVELIN_LANDING_GRAPHIC = 2265;
	/** Molten Sand, the scenery that Reentry's and Volatility III's sand is (the OSRS Wiki's Molten Sand page). */
	public static final int MOLTEN_SAND_ID = 50746;
	/** A hitsplat that heals (RuneLite's HitsplatID.HEAL). */
	public static final int HEAL_HITSPLAT = 6;
	/**
	 * The hitsplats with an amount that is not damage taken, by RuneLite's HitsplatID: a heal, the cyan ones, a prayer
	 * drain, sanity's drain and restore, and Doom's own. Any other with an amount above 0 counts as a stack of Doom.
	 */
	private static final Set<Integer> NOT_DAMAGE = new HashSet<>(Arrays.asList(HEAL_HITSPLAT, 11, 15, 60, 71, 72, 73));
	/**
	 * The tiles a Javelin special's landing turns to sand at each Reentry tier, 0 to 3, as [dx, dy] from the landing tile:
	 * the site's REENTRY_SAND_OFFSETS (src/data/calibration.ts), from the wiki, unconfirmed in game.
	 */
	private static final int[][][] SAND_OFFSETS = {{}, {{0, 0}}, {{0, 0}, {-1, 1}}, {{0, 0}, {-1, 1}, {-1, 0}}};

	private Integer wave;
	private boolean waveStarted;
	private int waveStartTick = -1;

	/** The NPCs, by index, that spawned after their wave's first tick. */
	private final Set<Integer> reinforcements = new HashSet<>();
	/** Whether a reinforcement has come this wave, even one that has since died. */
	private boolean reinforcementsArrived;
	private final Map<Integer, OrbOrder> orbs = new HashMap<>();
	/** The tick each NPC's last attack animation started on, by index. */
	private final Map<Integer, Integer> lastAttack = new HashMap<>();
	/**
	 * The attacks each NPC has made, by index, for those whose count is known: it spawned while the plugin watched, or for
	 * a Javelin Colossus the plugin saw a special. Kept across the wave's start, since the game may spawn the wave's NPCs
	 * before or after its message on the same tick; an NPC's despawn clears its entries.
	 */
	private final Map<Integer, Integer> attackCounts = new HashMap<>();
	/** Each NPC's health bar as the game last showed it, [ratio, scale], by index; an NPC's despawn or a heal clears it. */
	private final Map<Integer, int[]> healthBars = new HashMap<>();
	/** The hitsplats on the player that dealt damage since the wave the plugin saw start: Doom's stacks. */
	private int damageTaken;
	/**
	 * The most the game's wave damage counter read in the wave under way or the one just finished (RunWave's `damage`),
	 * from the tick after the wave's first: on that first tick the counter may still hold the last wave's.
	 */
	private int waveDamage;
	/** Whether the next run tick is the first of the wave, whose damage counter is not read (waveDamage). */
	private boolean freshWave;
	/** The sand the Javelins' landings laid this wave below Reentry II, which goes when the wave does. */
	private final Set<GridTile> waveSand = new LinkedHashSet<>();
	/** The sand they laid at Reentry II or III, which lasts the run. */
	private final Set<GridTile> lastingSand = new LinkedHashSet<>();
	/** The Molten Sand objects in the scene, by tile, each with how many stand there. */
	private final Map<GridTile, Integer> sandObjects = new LinkedHashMap<>();

	/** The frem of which two have been seen alive at once this wave, Quartet's fourth's kind, by id; 0 while none has. */
	private int quartetFrem;

	private final Set<Modifier> taken = EnumSet.noneOf(Modifier.class);
	private boolean modifiersComplete;
	private final List<Modifier> options = new ArrayList<>(3);

	/** The waves of the run finished so far, oldest first, for the pick link (RunWave). */
	private final List<RunWave> run = new ArrayList<>();
	/**
	 * A wave the game just said was completed, until the next tick (onRunTick) adds it to the run with the modifiers held:
	 * its number, its ticks and whether it hurt the player, the last two null when the plugin did not see it start.
	 */
	private Integer doneWave;
	private Integer doneTicks;
	private Boolean doneHit;
	/**
	 * The potions' doses carried as the last wave of the run ended, or at the run's first tick the plugin saw, from which
	 * the next wave's `drunk` is counted (RunWave); null before the plugin has looked. `dosesWhole` says whether they
	 * were read before the wave under way or next began, so that its count is whole: not when read mid-wave.
	 */
	private Map<String, Integer> dosesBefore;
	private boolean dosesWhole;

	/** Forget the run: the player left the Colosseum, hopped or logged out. */
	public void reset()
	{
		wave = null;
		waveStarted = false;
		waveStartTick = -1;
		taken.clear();
		modifiersComplete = false;
		options.clear();
		lastAttack.clear();
		attackCounts.clear();
		healthBars.clear();
		lastingSand.clear();
		sandObjects.clear();
		run.clear();
		doneWave = null;
		dosesBefore = null;
		waveDamage = 0;
		freshWave = false;
		resetWave();
	}

	/**
	 * A wave starts or ends: its reinforcements, orbs and Doom stacks go (the wiki: Doom's stacks clear at the end of the
	 * wave), and so does the sand laid below Reentry II (the wiki's Javelin Colossus page).
	 */
	private void resetWave()
	{
		reinforcements.clear();
		reinforcementsArrived = false;
		orbs.clear();
		damageTaken = 0;
		waveSand.clear();
		quartetFrem = 0;
	}

	/** A game message, on the tick it came. */
	public void onGameMessage(String message, int tick)
	{
		String text = TAG.matcher(message).replaceAll("");
		Matcher m;
		if (text.contains(SOL_START))
		{
			startWave(LAST_WAVE + 1, tick);
		}
		else if ((m = WAVE_START.matcher(text)).find())
		{
			startWave(Integer.parseInt(m.group(1)), tick);
		}
		else if ((m = WAVE_DONE.matcher(text)).find())
		{
			int done = Integer.parseInt(m.group(1));
			boolean seen = waveStarted && wave != null && wave == done;
			doneWave = done;
			doneTicks = seen ? Integer.valueOf(tick - waveStartTick + 1) : null;
			doneHit = seen ? Boolean.valueOf(damageTaken > 0) : null;
			wave = done + 1;
			waveStarted = false;
			resetWave();
		}
	}

	private void startWave(int number, int tick)
	{
		// Wave 1, or a wave the run has already finished, starts a new run.
		if (number == 1 || (!run.isEmpty() && number <= run.get(run.size() - 1).getWave()))
		{
			// Doses read before a wave 1 count from there; those of a run before it do not.
			if (!run.isEmpty())
			{
				dosesBefore = null;
			}
			run.clear();
		}
		wave = number;
		waveStarted = true;
		waveStartTick = tick;
		waveDamage = 0;
		freshWave = true;
		resetWave();
	}

	/** Whether this tick is the first of a wave the plugin saw start. */
	public boolean isWaveStartTick(int tick)
	{
		return waveStarted && tick == waveStartTick;
	}

	/** Whether a wave is under way that the plugin saw start. */
	public boolean isWaveStarted()
	{
		return waveStarted;
	}

	/** Whether a reinforcement has spawned in the wave under way, even one that has since died. */
	public boolean isReinforcementsArrived()
	{
		return reinforcementsArrived;
	}

	/** The wave under way, or the next one between waves; null when the plugin has not seen a wave's message yet. */
	public Integer getWave()
	{
		return wave;
	}

	/**
	 * Each tick in the Colosseum, with the modifiers' varbits and the game's current glory and wave damage counters: a
	 * wave the game has just said was completed joins the run with the modifiers held through it, and until the next wave
	 * starts the last wave finished takes the glory counter as it reads and the most the damage counter has read, since
	 * when the game updates and clears them is not known.
	 */
	public void onRunTick(ModifierLevels levels, int glory, int damage)
	{
		onRunTick(levels, glory, damage, null);
	}

	/**
	 * The same, with the potions' doses carried (`doses`, Potions.doses of the inventory, null to count none), asked for
	 * only on the ticks that need them: the first the plugin sees of a run, and the one a finished wave joins the run on,
	 * which takes the doses gone since the wave before as its `drunk`.
	 */
	public void onRunTick(ModifierLevels levels, int glory, int damage, Supplier<Map<String, Integer>> doses)
	{
		if (doses != null && dosesBefore == null && doneWave == null)
		{
			dosesBefore = doses.get();
			// Whole only when read between waves or on a wave's first tick.
			dosesWhole = !waveStarted || freshWave;
		}
		if (waveStarted && freshWave)
		{
			freshWave = false;
		}
		else if (waveStarted)
		{
			waveDamage = Math.max(waveDamage, damage);
		}
		if (doneWave != null)
		{
			int done = doneWave;
			run.removeIf(w -> w.getWave() >= done);
			Map<String, Integer> drunk = null;
			if (doses != null)
			{
				Map<String, Integer> now = doses.get();
				drunk = dosesBefore != null && dosesWhole ? Potions.drunk(dosesBefore, now) : null;
				dosesBefore = now;
				dosesWhole = true;
			}
			run.add(new RunWave(done, doneTicks, doneHit, doneTicks == null ? null : Math.max(waveDamage, damage), modifiers(levels), glory, drunk));
			doneWave = null;
		}
		else if (!waveStarted && !run.isEmpty())
		{
			run.set(run.size() - 1, run.get(run.size() - 1).withCounters(glory, damage));
		}
	}

	/** The waves of the run finished so far, oldest first: none before the first, or after leaving the Colosseum. */
	public List<RunWave> getRun()
	{
		return Collections.unmodifiableList(new ArrayList<>(run));
	}

	/** Whether the modifiers taken are all known: see ArenaState.isModifiersComplete. */
	public boolean isModifiersComplete()
	{
		return modifiersComplete;
	}

	/** An NPC spawned, on the tick it did. One that spawns after its wave's first tick is a reinforcement. */
	public void onNpcSpawned(int index, int npcId, int tick)
	{
		if (NpcKind.forNpcId(npcId, false) == null)
		{
			return;
		}
		if (waveStarted && tick != waveStartTick)
		{
			reinforcements.add(index);
			reinforcementsArrived = true;
		}
		if (npcId == NpcKind.MANTICORE_ID)
		{
			orbs.put(index, new OrbOrder());
		}
		else
		{
			lastAttack.remove(index);
			attackCounts.put(index, 0);
		}
	}

	public void onNpcDespawned(int index)
	{
		reinforcements.remove(index);
		orbs.remove(index);
		lastAttack.remove(index);
		attackCounts.remove(index);
		healthBars.remove(index);
	}

	/**
	 * An NPC's health bar on this tick: its ratio of `scale`, or a ratio below 0 while the game hides the bar, which it
	 * does some ticks after the last hit. The last bar shown is kept until the NPC despawns or is healed: in the user's
	 * logs no bar came back higher after it hid, for up to 71 ticks, so the NPCs did not heal unseen in that time.
	 */
	public void onHealthBar(int index, int ratio, int scale)
	{
		if (ratio >= 0 && scale > 0 && ratio <= scale)
		{
			healthBars.put(index, new int[] {ratio, scale});
		}
	}

	/**
	 * A hitsplat on an NPC. A heal forgets its bar, which no longer says how hurt it is, until the game shows the bar again:
	 * the link then gives the NPC at full health rather than more hurt than it is.
	 */
	public void onNpcHit(int index, int amount, int type)
	{
		if (type == HEAL_HITSPLAT)
		{
			healthBars.remove(index);
		}
	}

	/**
	 * A hitsplat on the player. Doom's stacks are the hits that dealt damage in the wave (the wiki: a stack for each
	 * instance of damage taken), so each one with an amount above 0 counts, while a wave the plugin saw start is under
	 * way; a block, a heal or a drain does not (NOT_DAMAGE). Which hitsplats the game counts is unconfirmed: those of
	 * Reentry's sand and Solarflare count here, as the site's Doom counts them.
	 */
	public void onPlayerHit(int amount, int type)
	{
		if (waveStarted && isDamage(amount, type))
		{
			damageTaken++;
		}
	}

	/** Whether a hitsplat of `amount` and `type` is damage: an amount above 0, not a heal, a drain or the like (NOT_DAMAGE). */
	public static boolean isDamage(int amount, int type)
	{
		return amount > 0 && !NOT_DAMAGE.contains(type);
	}

	/**
	 * A graphic on a tile, with Reentry's tier at the time. A Javelin special landing under Reentry lays sand on its tile
	 * and, from tier II, the tiles SAND_OFFSETS adds, those on the grid: below tier II for the rest of the wave, from it
	 * for good. A tile the game moves to another, when one is a wall or a pillar, is not known here; the Molten Sand
	 * objects show it, if they show at all.
	 */
	public void onTileGraphic(GridTile tile, int graphicId, int reentryTier)
	{
		if (graphicId != JAVELIN_LANDING_GRAPHIC || tile == null || reentryTier < 1 || reentryTier > 3)
		{
			return;
		}
		for (int[] offset : SAND_OFFSETS[reentryTier])
		{
			GridTile sand = new GridTile(tile.getX() + offset[0], tile.getY() + offset[1]);
			if (ArenaGeometry.onGrid(sand))
			{
				(reentryTier >= 2 ? lastingSand : waveSand).add(sand);
			}
		}
	}

	/** A Molten Sand object came into the scene on `tile`, or left it; any other object is ignored by the caller. */
	public void onSandObject(GridTile tile, boolean spawned)
	{
		if (tile == null || !ArenaGeometry.onGrid(tile))
		{
			return;
		}
		int count = sandObjects.getOrDefault(tile, 0) + (spawned ? 1 : -1);
		if (count > 0)
		{
			sandObjects.put(tile, count);
		}
		else
		{
			sandObjects.remove(tile);
		}
	}

	/** The scene is loading again, which spawns its objects anew: the Molten Sand objects are counted from there. */
	public void onSceneLoading()
	{
		sandObjects.clear();
	}

	/**
	 * An NPC started an animation, on the tick it did. An attack (AttackAnimations, unconfirmed) restarts its attack timer
	 * and adds to its count. A Javelin Colossus's special is its 5th attack (JAVELIN_SPECIAL_EVERY on the site), so it
	 * sets the count to the next multiple of 5, which fixes the phase of its specials even when the plugin missed its
	 * spawn.
	 */
	public void onNpcAnimation(int index, int npcId, int animationId, int tick)
	{
		if (!AttackAnimations.isAttack(npcId, animationId))
		{
			return;
		}
		lastAttack.put(index, tick);
		Integer count = attackCounts.get(index);
		if (AttackAnimations.isSpecial(npcId, animationId))
		{
			int next = count == null ? 1 : count + 1;
			attackCounts.put(index, (next + 4) / 5 * 5);
		}
		else if (count != null)
		{
			attackCounts.put(index, count + 1);
		}
	}

	/** An orb graphic on a Manticore this tick. */
	public void onOrb(int index, OrbStyle style)
	{
		orbs.computeIfAbsent(index, i -> new OrbOrder()).see(style);
	}

	/**
	 * The modifier selector opened between waves: the game ids of the three on offer, and the mask of those already taken,
	 * which settles every modifier taken so far.
	 */
	public void onModifierOptions(int first, int second, int third, int takenMask)
	{
		options.clear();
		options.add(Modifier.forId(first));
		options.add(Modifier.forId(second));
		options.add(Modifier.forId(third));
		taken.addAll(Modifier.forMask(takenMask));
		modifiersComplete = true;
	}

	/**
	 * The three modifiers the selector offers while it is open, in its order, each null for an id this plugin does not
	 * know; empty while it is closed.
	 */
	public List<Modifier> getOptions()
	{
		return Collections.unmodifiableList(new ArrayList<>(options));
	}

	/** The selector closed with the option at `choice`, 1 to 3; 0 when none was picked. */
	public void onModifierChosen(int choice)
	{
		if (choice >= 1 && choice <= options.size() && options.get(choice - 1) != null)
		{
			taken.add(options.get(choice - 1));
		}
		options.clear();
	}

	/**
	 * The arena on this tick: the NPCs the game shows, the player's tile and the modifiers' tiers, with what the tracker
	 * remembers. An ExportException says why there is nothing to export, such as no NPCs or Sol Heredit's wave.
	 */
	public ArenaState capture(int tick, GridTile player, List<SeenNpc> seen, ModifierLevels levels) throws ExportException
	{
		if (wave != null && wave > LAST_WAVE)
		{
			throw new ExportException("Sol Survivor plans waves 1 to 11, not Sol Heredit's.");
		}
		if (player == null || !ArenaGeometry.onGrid(player))
		{
			throw new ExportException("You are not in the Colosseum's arena.");
		}

		Map<Modifier, Integer> modifiers = modifiers(levels);
		boolean mm3 = Integer.valueOf(3).equals(modifiers.get(Modifier.MANTIMAYHEM));
		boolean waveStart = isWaveStartTick(tick);

		List<ExportNpc> npcs = new ArrayList<>();
		List<GridTile> solarflareOrbs = new ArrayList<>();
		boolean arrived = reinforcementsArrived;
		for (SeenNpc n : seen)
		{
			if (n.getNpcId() == NpcKind.SOLARFLARE_ORB_ID && ArenaGeometry.onGrid(n.getTile()))
			{
				solarflareOrbs.add(n.getTile());
				continue;
			}
			NpcKind kind = NpcKind.forNpcId(n.getNpcId(), isReinforcement(n));
			if (kind == null || !ArenaGeometry.onGrid(n.getTile()))
			{
				continue;
			}
			// The Jaguar, the Minotaur and the second shaman only ever come as reinforcements.
			arrived |= kind == NpcKind.JAGUAR_WARRIOR || kind == NpcKind.MINOTAUR || kind == NpcKind.REINFORCEMENT_SHAMAN;
			String code = null;
			Integer sinceAttack = null;
			Integer attacks = null;
			if (kind == NpcKind.MANTICORE)
			{
				OrbOrder order = orbs.get(n.getIndex());
				code = order == null ? "u" : order.losCode(mm3);
			}
			else if (!waveStart)
			{
				Integer last = lastAttack.get(n.getIndex());
				sinceAttack = last == null ? null : Integer.valueOf(tick - last);
				attacks = attackCounts.get(n.getIndex());
			}
			// Mid-wave only: at its start every NPC is at full health.
			int[] health = waveStart ? null : healthBars.get(n.getIndex());
			npcs.add(new ExportNpc(kind, n.getTile(), code, sinceAttack, attacks, health));
		}
		if (npcs.isEmpty())
		{
			throw new ExportException("The arena has no NPCs yet: try again once the wave starts.");
		}

		Integer waveTick = waveStarted && !waveStart ? Integer.valueOf(tick - waveStartTick) : null;
		// Doom's stacks only when the plugin saw every hit of the wave, from its start.
		Integer doomStacks = waveStarted && !waveStart && modifiers.containsKey(Modifier.DOOM) ? Integer.valueOf(damageTaken) : null;
		return new ArenaState(npcs, player, waveStart, waveStarted ? wave : null, waveTick, !waveStart && arrived, modifiers, modifiersComplete,
			solarflareOrbs, doomStacks, sand());
	}

	/**
	 * The list of the wave under way that the panel and the wave box show (WaveRoster), from the NPCs alive on this tick:
	 * the dead ones left out, a serpent shaman that came as a reinforcement told apart. `eachFrem` lists the warband's
	 * three one by one. Empty while no wave the plugin saw start is under way, or for a wave Sol Survivor does not know.
	 */
	public List<WaveRoster.Line> roster(int tick, List<SeenNpc> alive, ModifierLevels levels, boolean eachFrem)
	{
		if (!waveStarted)
		{
			return Collections.emptyList();
		}
		WaveRoster.Alive counts = new WaveRoster.Alive();
		Map<Integer, Integer> frems = new HashMap<>();
		for (SeenNpc n : alive)
		{
			if (WaveRoster.isFrem(n.getNpcId()))
			{
				counts.addFrem(n.getNpcId());
				if (frems.merge(n.getNpcId(), 1, Integer::sum) >= 2)
				{
					quartetFrem = n.getNpcId();
				}
				continue;
			}
			NpcKind kind = NpcKind.forNpcId(n.getNpcId(), isReinforcement(n));
			if (kind != null)
			{
				counts.add(kind);
			}
		}
		return WaveRoster.thisWave(wave, modifiers(levels), counts, reinforcementsArrived, isWaveStartTick(tick), quartetFrem, eachFrem);
	}

	/** Doom's stacks the plugin counted this wave: the hits that dealt the player damage since the wave it saw start. */
	public int getDamageTaken()
	{
		return damageTaken;
	}

	/** Whether the tracker knows of molten sand on the tile, as the link sends it (sand). */
	public boolean isSand(GridTile tile)
	{
		return tile != null && (lastingSand.contains(tile) || waveSand.contains(tile) || sandObjects.containsKey(tile));
	}

	/**
	 * The molten sand on the floor: that the Javelins' landings laid (onTileGraphic), lasting sand first, and the tiles of
	 * the Molten Sand objects, each tile once. How long a tile has left is not sent: below Reentry II it lasts the wave,
	 * and from it the run, which is what the site models.
	 */
	private List<GridTile> sand()
	{
		Set<GridTile> tiles = new LinkedHashSet<>(lastingSand);
		tiles.addAll(waveSand);
		tiles.addAll(sandObjects.keySet());
		return new ArrayList<>(tiles);
	}

	/**
	 * Whether an NPC came as a reinforcement: it spawned after its wave's first tick. A shaman already there when the
	 * plugin started is the reinforcement one from wave 7 on, where no wave starts with a shaman; before, it is taken for
	 * the wave's own.
	 */
	private boolean isReinforcement(SeenNpc n)
	{
		if (reinforcements.contains(n.getIndex()))
		{
			return true;
		}
		return n.getNpcId() == NpcKind.SHAMAN_ID && wave != null && wave >= 7;
	}

	/** The modifiers taken, with their tiers: those with tiers by their varbits. The wave log names them too. */
	public Map<Modifier, Integer> modifiers(ModifierLevels levels)
	{
		Map<Modifier, Integer> out = new EnumMap<>(Modifier.class);
		for (Modifier m : Modifier.values())
		{
			if (m.hasTiers())
			{
				int level = Math.max(0, Math.min(3, levels.level(m)));
				// A modifier the selector says is taken is at tier I at least, whatever its varbit reads.
				if (level == 0 && taken.contains(m))
				{
					level = 1;
				}
				if (level > 0)
				{
					out.put(m, level);
				}
			}
			else if (taken.contains(m))
			{
				out.put(m, 1);
			}
		}
		return out;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.IntPredicate;
import java.util.function.IntToLongFunction;

/**
 * What a death in the Colosseum costs to reclaim, estimated (Stefan's word of 2026-11-04: the death is not safe, and
 * the grave is in the Colosseum's lobby). By the OSRS Wiki's Fortis Colosseum and Grave pages: the player keeps their
 * most valuable items, 3 or 4 with Protect Item, and the rest goes to a grave, whose fee is a flat amount for each item
 * by its value, nothing under 100K, 1,000 coins under 1M, 10,000 under 10M and 100,000 from 10M up, at most 500,000 in
 * all; an ironman pays half. Until the player has cleared 100 Colosseum waves the fee is a quarter of that, so at most
 * 125,000. The fee comes out of Death's coffer, or the bank, which the plugin cannot see paid: this is the fee as the
 * grave would ask it, at the Grand Exchange's own guide prices, which the grave goes by, not the live trade prices
 * RuneLite shows by default (Stefan's gravestone of 2026-11-04: the estimate 2,250 over the fee, with Protect Item and
 * without, as one item over 1M at the live price is under it at the guide price, so a 2,500 fee where the grave asked
 * 250). A stack is one item, worth the whole stack, which is kept or lost
 * whole; an item that does not stack is one item for each of it, so that eight brews are eight items each under 100K
 * and free, not one worth more.
 */
public final class DeathFee
{
	/** The most a grave asks before a discount. */
	public static final long CAP = 500_000;
	/** The waves a player clears before the Colosseum's discount ends. */
	public static final int DISCOUNT_WAVES = 100;

	private DeathFee()
	{
	}

	/**
	 * The fee for `carried` as the player died: the `kept` most valuable items stay with them, a stack counting as one
	 * item worth the whole stack, and what is left goes to the grave. `stackable` says which items stack. `discounted` while the player has cleared fewer than DISCOUNT_WAVES waves.
	 */
	public static long estimate(Map<Integer, Integer> carried, IntToLongFunction price, IntPredicate stackable, int kept, boolean discounted,
		boolean ironman)
	{
		// The grave's items: a stack is one item, worth the whole stack, and an item that does not stack is one for each
		// of it. The kept ones are the most valuable of these, a stack kept whole. Unconfirmed: the wiki does not say how
		// the game ranks a stack for keeping.
		List<long[]> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> item : carried.entrySet())
		{
			long each = price.applyAsLong(item.getKey());
			if (stackable.test(item.getKey()))
			{
				items.add(new long[] {each * item.getValue()});
			}
			else
			{
				for (int i = 0; i < item.getValue(); i++)
				{
					items.add(new long[] {each});
				}
			}
		}
		items.sort((x, y) -> Long.compare(y[0], x[0]));
		long fee = 0;
		for (int i = Math.max(0, kept); i < items.size(); i++)
		{
			fee += tier(items.get(i)[0]);
		}
		fee = Math.min(fee, CAP);
		if (discounted)
		{
			fee /= 4;
		}
		if (ironman)
		{
			fee /= 2;
		}
		return fee;
	}

	/** A grave's fee for one item (a stack) worth `value`. */
	static long tier(long value)
	{
		if (value < 100_000)
		{
			return 0;
		}
		if (value < 1_000_000)
		{
			return 1_000;
		}
		if (value < 10_000_000)
		{
			return 10_000;
		}
		return 100_000;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * The player's gear and stats as the game shows them (design spec, "Equipment"): each worn item by its slot, with its id,
 * name and quantity; the weapon's attack speed in ticks, its category and the attack style picked, as the game numbers
 * them; the items in the inventory that can be worn, the switches a player brings; each item's attack and strength bonuses; each worn item's defence bonuses; the gear's prayer bonus; the prayer points now; each combat skill's boosted and real level; and the flags of the offensive prayers that need more than levels. The site maps
 * them to its kill table; the plugin passes on what the game says and works nothing out.
 */
public final class Equipment
{
	/** A worn item. */
	public static final class Item
	{
		private final int id;
		private final String name;
		private final int quantity;

		public Item(int id, String name, int quantity)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
		}

		public int getId()
		{
			return id;
		}

		public String getName()
		{
			return name;
		}

		public int getQuantity()
		{
			return quantity;
		}
	}

	/** An item in the inventory that can be worn, the slot it goes in, and a weapon's attack speed in ticks (0 unknown). */
	public static final class Switch
	{
		private final String slot;
		private final Item item;
		private final int speed;

		public Switch(String slot, Item item, int speed)
		{
			this.slot = slot;
			this.item = item;
			this.speed = speed;
		}

		public int getSpeed()
		{
			return speed;
		}

		public String getSlot()
		{
			return slot;
		}

		public Item getItem()
		{
			return item;
		}
	}

	/** The numbers an item's bonuses hold (bonuses). */
	public static final int BONUS_COUNT = 9;

	/** The numbers an item's defence bonuses hold (defences). */
	public static final int DEFENCE_COUNT = 5;

	/** The most switches kept: the inventory's 28 places. */
	public static final int MAX_SWITCHES = 28;

	/** The names of the prayer unlock flags (unlocks), in the order they are given and written. */
	public static final String[] UNLOCK_FLAGS = {"rigour", "augury", "deadeye", "mysticVigour", "knightWaves", "zeal"};

	private final Map<String, Item> items = new LinkedHashMap<>();
	private final List<Switch> switches = new ArrayList<>();
	private final Map<String, int[]> stats = new LinkedHashMap<>();
	private final Map<Integer, int[]> bonuses = new LinkedHashMap<>();
	private final Map<Integer, int[]> defences = new LinkedHashMap<>();
	private int weaponSpeed;
	private int weaponCategory;
	private int attackStyle;
	private final List<String> styleNames = new ArrayList<>();
	private int prayerBonus;
	private int prayerPoints;
	private int[] unlocks;

	/** An item worn in a slot, by the slot's name in lower case, such as "weapon" or "ammo". */
	public Equipment item(String slot, Item item)
	{
		items.put(slot, item);
		return this;
	}

	/**
	 * An item in the inventory that can be worn, by the slot it goes in, in the inventory's order; past MAX_SWITCHES it is
	 * passed over.
	 */
	public Equipment switchItem(String slot, Item item)
	{
		return switchItem(slot, item, 0);
	}

	/** A weapon in the inventory, with its attack speed in ticks (0 unknown). */
	public Equipment switchItem(String slot, Item item, int speed)
	{
		if (switches.size() < MAX_SWITCHES)
		{
			switches.add(new Switch(slot, item, speed));
		}
		return this;
	}

	/**
	 * An item's bonuses, by its id: stab, slash, crush, magic and ranged attack, melee and ranged strength, magic damage
	 * in tenths of a percent, and 1 when it takes both hands, else 0. The site works out kill times from them.
	 */
	public Equipment bonuses(int id, int[] values)
	{
		if (values.length != BONUS_COUNT)
		{
			throw new IllegalArgumentException("expected " + BONUS_COUNT + " bonuses, not " + values.length);
		}
		bonuses.put(id, values.clone());
		return this;
	}

	/**
	 * A worn item's defence bonuses, by its id: stab, slash, crush, magic and ranged. With the Defence and Magic levels
	 * the site works out how often the NPCs' attacks land on the player. Apart from bonuses, which the site's readers
	 * before plugin 0.5.0 take only at nine numbers an item.
	 */
	public Equipment defences(int id, int[] values)
	{
		if (values.length != DEFENCE_COUNT)
		{
			throw new IllegalArgumentException("expected " + DEFENCE_COUNT + " defence bonuses, not " + values.length);
		}
		defences.put(id, values.clone());
		return this;
	}

	/** A skill's boosted and real level, by the skill's name in lower case, such as "ranged". */
	public Equipment stat(String skill, int boosted, int real)
	{
		stats.put(skill, new int[]{boosted, real});
		return this;
	}

	/** The weapon's attack speed in ticks (0 when unknown), its category varbit and the attack style varp. */
	public Equipment weapon(int speed, int category, int style)
	{
		this.weaponSpeed = speed;
		this.weaponCategory = category;
		this.attackStyle = style;
		return this;
	}

	/**
	 * The names the game's data gives the weapon's combat options, in attackStyle's order ("Ranging", "Longrange", and
	 * "Other" for an empty place), which tell the site which style is picked.
	 */
	public Equipment styleNames(List<String> names)
	{
		styleNames.clear();
		styleNames.addAll(names);
		return this;
	}

	/** The gear's prayer bonus, summed over the worn items, and the prayer points now. */
	public Equipment prayer(int bonus, int points)
	{
		this.prayerBonus = bonus;
		this.prayerPoints = points;
		return this;
	}

	/**
	 * The flags of the offensive prayers that need more than levels, as the game's varbits hold them: Rigour's, Augury's,
	 * Deadeye's and Mystic Vigour's unlocks, the state of the Knight Waves Training Grounds, which Piety and Chivalry need
	 * finished, and Zeal's unlock, from the Horn of Bran; none of the unlocks is 0 once the prayer is unlocked. The site
	 * works out from them, with the Prayer, Defence, Attack and Strength levels, which prayers the kill times take (its
	 * src/viewer/offensivePrayers.ts).
	 */
	public Equipment unlocks(int rigour, int augury, int deadeye, int mysticVigour, int knightWaves, int zeal)
	{
		this.unlocks = new int[]{rigour, augury, deadeye, mysticVigour, knightWaves, zeal};
		return this;
	}

	/**
	 * A copy without what could point to the player's account, for the wave log they share (WaveShare): the skills'
	 * levels and the prayer unlock flags are left out, and the gear, its bonuses and the prayer points stay as they are.
	 */
	public Equipment withoutLevels()
	{
		Equipment copy = new Equipment();
		copy.items.putAll(items);
		copy.switches.addAll(switches);
		copy.bonuses.putAll(bonuses);
		copy.defences.putAll(defences);
		copy.weaponSpeed = weaponSpeed;
		copy.weaponCategory = weaponCategory;
		copy.attackStyle = attackStyle;
		copy.styleNames.addAll(styleNames);
		copy.prayerBonus = prayerBonus;
		copy.prayerPoints = prayerPoints;
		return copy;
	}

	public Map<String, Item> getItems()
	{
		return Collections.unmodifiableMap(items);
	}

	public List<Switch> getSwitches()
	{
		return Collections.unmodifiableList(switches);
	}

	public Map<Integer, int[]> getBonuses()
	{
		return Collections.unmodifiableMap(bonuses);
	}

	public Map<Integer, int[]> getDefences()
	{
		return Collections.unmodifiableMap(defences);
	}

	public Map<String, int[]> getStats()
	{
		return Collections.unmodifiableMap(stats);
	}

	public int getWeaponSpeed()
	{
		return weaponSpeed;
	}

	public int getWeaponCategory()
	{
		return weaponCategory;
	}

	public int getAttackStyle()
	{
		return attackStyle;
	}

	public List<String> getStyleNames()
	{
		return Collections.unmodifiableList(styleNames);
	}

	public int getPrayerBonus()
	{
		return prayerBonus;
	}

	public int getPrayerPoints()
	{
		return prayerPoints;
	}

	/** The prayer unlock flags in UNLOCK_FLAGS's order, or null when they were not read. */
	public int[] getUnlocks()
	{
		return unlocks == null ? null : unlocks.clone();
	}
}

