/**
 * The plugin's version, which the wave log names so that a log can be read with the plugin that wrote it in mind. It
 * must match the version in build.gradle; PluginVersionTest checks that it does.
 */
public final class PluginVersion
{
	public static final String VERSION = "1.4.0";

	private PluginVersion()
	{
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Potions by their doses, for the pick link's `potions` and each run wave's `drunk` (PickPayload): the site's Claim the
 * chest or go on weighs whether the brews and prayer restores carried last the next wave (src/viewer/potionSupply.ts). A
 * potion is an item whose name ends in its doses, "Saradomin brew(4)", and counts as that many doses of
 * "Saradomin brew". The plugin sends every such item and the site picks the ones it weighs, so a charged item named the
 * same way, an "Amulet of glory(4)", rides along and is ignored there.
 */
public final class Potions
{
	/** A potion's name: its name, then its doses in brackets, one to four. */
	private static final Pattern DOSES = Pattern.compile("^(.+?)\\s*\\(([1-4])\\)$");

	private Potions()
	{
	}

	/** The doses of each potion among `items` (the inventory, by name), in the order first met. */
	public static Map<String, Integer> doses(List<ChestItem> items)
	{
		Map<String, Integer> doses = new LinkedHashMap<>();
		for (ChestItem item : items)
		{
			Matcher m = DOSES.matcher(item.getName());
			if (m.matches() && item.getQuantity() > 0)
			{
				doses.merge(m.group(1), Integer.parseInt(m.group(2)) * item.getQuantity(), Integer::sum);
			}
		}
		return doses;
	}

	/** The doses of each potion gone from `before` to `after`, in `before`'s order: none for one that did not go down. */
	public static Map<String, Integer> drunk(Map<String, Integer> before, Map<String, Integer> after)
	{
		Map<String, Integer> drunk = new LinkedHashMap<>();
		for (Map.Entry<String, Integer> e : before.entrySet())
		{
			int gone = e.getValue() - after.getOrDefault(e.getKey(), 0);
			if (gone > 0)
			{
				drunk.put(e.getKey(), gone);
			}
		}
		return drunk;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * The player's prayer against the attacks at them in one wave's log, for the site's Prayer reliability, "Mine": how often
 * a flick of theirs comes a tick late. The same count as the site's run review makes of a log (src/viewer/prayerRecord.ts,
 * flickCounts, on the attacks src/viewer/runReview.ts finds), so that a wave counted here and one counted there agree;
 * src/test/resources/fixtures/prayer-flicks.json is a log both count.
 *
 * Each attack at the player, by the NPCs the site models (a Manticore's each orb) and the Fremennik warband, is one of:
 * <ul>
 * <li>a flick: the right protection prayer went on as the attack was checked, off or another the tick before;</li>
 * <li>held: the right prayer was on since the tick before, so no flick was at stake;</li>
 * <li>late: a flick that missed, the right prayer on a tick after the check, on the tick before and switched off on it,
 * or caught half-way, both prayers showing on the tick and the wrong one counting;</li>
 * <li>unprayed: no protection prayer on the tick before, the tick or the tick after, with prayer points left.</li>
 * </ul>
 * The rest are left out: a Javelin Colossus's special, which no prayer blocks; an attack met with another prayer and the
 * right one nowhere near, as tanking one is often the plan; and one checked on the same tick as another of another
 * style that the prayer blocked, as only one could be.
 */
public final class PrayerFlicks
{
	/** No attack prayed against. */
	public static final PrayerFlicks NONE = new PrayerFlicks(0, 0, 0, 0);

	/** A tick's protection prayer when none is on; null is a tick the log does not say. */
	static final String NO_PRAYER = "";

	/** The graphics a Manticore shows for its orbs as it charges them, by style: the site's runReview.ts, ORB_GRAPHICS. */
	private static final Map<Integer, String> ORB_GRAPHICS = new HashMap<>();

	/** The Fremennik warband's attack animations, by NPC id, and their styles: the site's waveLog.ts, FREMENNIK_WARBAND. */
	private static final Map<Integer, int[]> FREM_ATTACKS = new HashMap<>();
	private static final Map<Integer, String> FREM_STYLES = new HashMap<>();

	/** The deaths the logs showed: the shaman's, the Jaguar warrior's, the Javelin Colossus's and the Manticore's. */
	private static final int[] DEATHS = {10860, 10849, 10894, 10866};

	/** The ticks after a Minotaur's swing that its hit checks the prayer: the site's MINOTAUR_PRAYER_DELAY. */
	static final int MINOTAUR_PRAYER_DELAY = 1;

	static
	{
		ORB_GRAPHICS.put(2681, "magic");
		ORB_GRAPHICS.put(2683, "ranged");
		ORB_GRAPHICS.put(2685, "melee");
		FREM_ATTACKS.put(12814, new int[] {10850});
		FREM_ATTACKS.put(12815, new int[] {10853});
		FREM_ATTACKS.put(12816, new int[] {10856});
		FREM_STYLES.put(12814, "ranged");
		FREM_STYLES.put(12815, "magic");
		FREM_STYLES.put(12816, "melee");
	}

	private final int flicks;
	private final int held;
	private final int late;
	private final int unprayed;

	public PrayerFlicks(int flicks, int held, int late, int unprayed)
	{
		this.flicks = flicks;
		this.held = held;
		this.late = late;
		this.unprayed = unprayed;
	}

	public int getFlicks()
	{
		return flicks;
	}

	public int getHeld()
	{
		return held;
	}

	public int getLate()
	{
		return late;
	}

	public int getUnprayed()
	{
		return unprayed;
	}

	/** Whether any attack was prayed against, so that the wave says something of the player's prayer. */
	public boolean isEmpty()
	{
		return flicks + held + late + unprayed == 0;
	}

	/** These counts and `other`'s together. */
	public PrayerFlicks plus(PrayerFlicks other)
	{
		return new PrayerFlicks(flicks + other.flicks, held + other.held, late + other.late, unprayed + other.unprayed);
	}

	/** An attack at the player: its style, the tick its prayer was checked on and the protection prayer on then. */
	private static final class Attack
	{
		final String style;
		final int checked;
		final String prayer;

		Attack(String style, int checked, String prayer)
		{
			this.style = style;
			this.checked = checked;
			this.prayer = prayer;
		}
	}

	/** An NPC the count follows from tick to tick: its id, its style and the tick it died on, or null. */
	private static final class Seen
	{
		final int npcId;
		Integer death;

		Seen(int npcId)
		{
			this.npcId = npcId;
		}
	}

	/** The player's prayer in a wave's log. */
	public static PrayerFlicks count(WaveLog log)
	{
		return count(log.getTicks());
	}

	static PrayerFlicks count(List<WaveLog.Tick> ticks)
	{
		Map<Integer, WaveLog.Tick> byT = new HashMap<>();
		Integer died = null;
		for (WaveLog.Tick tick : ticks)
		{
			byT.put(tick.t, tick);
			if (died == null && tick.player != null && tick.player.getHitpoints() == 0)
			{
				died = tick.t;
			}
		}
		List<Attack> attacks = attacks(ticks, byT, died);

		int flicks = 0;
		int held = 0;
		int late = 0;
		int unprayed = 0;
		for (Attack a : attacks)
		{
			String before = protectionOn(byT.get(a.checked - 1), byT.get(a.checked - 2), byT.get(a.checked));
			if (a.style.equals(a.prayer))
			{
				if (before == null || before.equals(a.style))
				{
					held++;
				}
				else
				{
					flicks++;
				}
				continue;
			}
			if (blockedOther(attacks, a))
			{
				continue;
			}
			String after = protectionOn(byT.get(a.checked + 1), byT.get(a.checked), byT.get(a.checked + 2));
			WaveLog.Tick at = byT.get(a.checked);
			boolean halfWay = at != null && at.player != null && at.player.getPrayers().contains(a.style);
			if (halfWay || a.style.equals(after) || a.style.equals(before))
			{
				late++;
			}
			else if (NO_PRAYER.equals(a.prayer) && NO_PRAYER.equals(before) && NO_PRAYER.equals(after) && at.player.getPrayerPoints() > 0)
			{
				unprayed++;
			}
		}
		return new PrayerFlicks(flicks, held, late, unprayed);
	}

	/** Whether the prayer on as `a` was checked blocked another attack of another style checked on the same tick. */
	private static boolean blockedOther(List<Attack> attacks, Attack a)
	{
		for (Attack b : attacks)
		{
			if (b != a && b.checked == a.checked && !b.style.equals(a.style) && b.style.equals(b.prayer))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The attacks at the player that a prayer could block, a tick at a time, as the site's run review finds them: each NPC
	 * by its index, a new one where the id changes, the index was not on the tick before or a dead NPC's bar comes back;
	 * none by an NPC after the tick it died on, and none after the player died. A Manticore's attacks are its orbs: each
	 * graphic it showed on the tick before and no longer shows. The others' are their attack animations' starts, a
	 * Javelin's special left out.
	 */
	private static List<Attack> attacks(List<WaveLog.Tick> ticks, Map<Integer, WaveLog.Tick> byT, Integer died)
	{
		List<Attack> out = new ArrayList<>();
		Map<Integer, Seen> latest = new HashMap<>();
		WaveLog.Tick before = null;
		for (WaveLog.Tick tick : ticks)
		{
			for (WaveLog.NpcTick npc : tick.npcs)
			{
				WaveLog.NpcTick prior = before == null ? null : npcOf(before, npc.getIndex());
				Seen s = latest.get(npc.getIndex());
				boolean fresh = s == null || s.npcId != npc.getNpcId() || prior == null || (prior.getHealthRatio() == 0 && npc.getHealthRatio() > 0);
				if (fresh)
				{
					s = new Seen(npc.getNpcId());
					latest.put(npc.getIndex(), s);
				}
				NpcKind kind = NpcKind.forNpcId(npc.getNpcId(), false);
				boolean frem = FREM_STYLES.containsKey(npc.getNpcId());
				if (s.death == null && (npc.getHealthRatio() == 0 || (kind != null && dies(tick, npc))))
				{
					s.death = tick.t;
				}
				boolean playerDead = died != null && tick.t > died;
				if ((kind == null && !frem) || playerDead || (s.death != null && s.death < tick.t))
				{
					continue;
				}
				WaveLog.NpcTick previous = fresh ? null : prior;
				if (frem)
				{
					if (started(tick, npc.getIndex(), FREM_ATTACKS.get(npc.getNpcId())))
					{
						out.add(new Attack(FREM_STYLES.get(npc.getNpcId()), tick.t, protectionOn(tick, before, byT.get(tick.t + 1))));
					}
					continue;
				}
				if (kind == NpcKind.MANTICORE)
				{
					if (s.death != null || previous == null || before.t != tick.t - 1)
					{
						continue;
					}
					for (String style : orbsFired(previous, npc))
					{
						out.add(new Attack(style, tick.t, protectionOn(tick, before, byT.get(tick.t + 1))));
					}
					continue;
				}
				int animation = attackStarted(tick, npc);
				if (animation == -1 || AttackAnimations.isSpecial(npc.getNpcId(), animation))
				{
					continue;
				}
				int checked = tick.t + (kind == NpcKind.MINOTAUR ? MINOTAUR_PRAYER_DELAY : 0);
				String prayer = protectionOn(byT.get(checked), byT.get(checked - 1), byT.get(checked + 1));
				if (prayer != null)
				{
					out.add(new Attack(styleOf(kind), checked, prayer));
				}
			}
			before = tick;
		}
		// An attack whose tick the log does not say is left out.
		out.removeIf(a -> a.prayer == null);
		return out;
	}

	/** The style of an NPC's attacks; a Manticore's come from its orbs. */
	private static String styleOf(NpcKind kind)
	{
		switch (kind)
		{
			case JAVELIN_COLOSSUS:
				return "ranged";
			case JAGUAR_WARRIOR:
			case MINOTAUR:
				return "melee";
			default:
				return "magic";
		}
	}

	private static WaveLog.NpcTick npcOf(WaveLog.Tick tick, int index)
	{
		for (WaveLog.NpcTick n : tick.npcs)
		{
			if (n.getIndex() == index)
			{
				return n;
			}
		}
		return null;
	}

	/** The attack animation the NPC started on the tick, the last of them, or -1 for none. */
	private static int attackStarted(WaveLog.Tick tick, WaveLog.NpcTick npc)
	{
		int started = -1;
		for (int[] a : tick.animations)
		{
			if (a[0] == npc.getIndex() && AttackAnimations.isAttack(npc.getNpcId(), a[1]))
			{
				started = a[1];
			}
		}
		return started;
	}

	/** Whether the NPC at `index` started one of `animations` on the tick. */
	private static boolean started(WaveLog.Tick tick, int index, int[] animations)
	{
		for (int[] a : tick.animations)
		{
			for (int animation : animations)
			{
				if (a[0] == index && a[1] == animation)
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Whether the NPC shows a death on the tick, in its animation or among the tick's animation starts. */
	private static boolean dies(WaveLog.Tick tick, WaveLog.NpcTick npc)
	{
		return started(tick, npc.getIndex(), DEATHS) || contains(DEATHS, npc.getAnimation());
	}

	private static boolean contains(int[] values, int value)
	{
		for (int v : values)
		{
			if (v == value)
			{
				return true;
			}
		}
		return false;
	}

	/** The orbs a Manticore fired: the orb graphics it showed on the tick before and no longer shows, in the order shown. */
	private static List<String> orbsFired(WaveLog.NpcTick before, WaveLog.NpcTick now)
	{
		List<String> out = new ArrayList<>();
		int[] still = now.getSpotAnims();
		for (int graphic : before.getSpotAnims())
		{
			String style = ORB_GRAPHICS.get(graphic);
			if (style != null && !contains(still, graphic))
			{
				out.add(style);
			}
		}
		return out;
	}

	/**
	 * The player's protection prayer on a tick, by the style it blocks: NO_PRAYER for none, null where the log does not
	 * say. Two on at once is a switch the log caught half-way, a click the client showed before the game took it: the one
	 * also on `before`, the tick before, is the game's, and where neither was, the one gone on `after`, the tick after,
	 * where the late click shows alone. The site's runReview.ts has it, from Stefan's logs of 19, 25 and 26 October.
	 */
	static String protectionOn(WaveLog.Tick tick, WaveLog.Tick before, WaveLog.Tick after)
	{
		List<String> on = protectionsOn(tick);
		if (on == null)
		{
			return null;
		}
		if (on.size() > 1)
		{
			String was = protectionOn(before, null, null);
			if (was != null && on.contains(was))
			{
				return was;
			}
			List<String> next = after != null && after.t == tick.t + 1 ? protectionsOn(after) : null;
			if (next != null && next.size() == 1)
			{
				List<String> gone = new ArrayList<>(on);
				gone.removeAll(next);
				if (gone.size() == 1)
				{
					return gone.get(0);
				}
			}
		}
		return on.isEmpty() ? NO_PRAYER : on.get(0);
	}

	/** The protection prayers a tick shows, by the styles they block; null where the log does not say. */
	private static List<String> protectionsOn(WaveLog.Tick tick)
	{
		if (tick == null || tick.player == null)
		{
			return null;
		}
		List<String> on = new ArrayList<>();
		for (String prayer : tick.player.getPrayers())
		{
			if (prayer.equals("magic") || prayer.equals("ranged") || prayer.equals("melee"))
			{
				on.add(prayer);
			}
		}
		return on;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof PrayerFlicks))
		{
			return false;
		}
		PrayerFlicks p = (PrayerFlicks) o;
		return flicks == p.flicks && held == p.held && late == p.late && unprayed == p.unprayed;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(flicks, held, late, unprayed);
	}

	@Override
	public String toString()
	{
		return flicks + " flicks, " + held + " held, " + late + " late, " + unprayed + " unprayed";
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The player's prayer over the newest waves the plugin counted (PrayerFlicks), for the site's Prayer reliability, "Mine":
 * the state links give their totals to the site as their `prayerRecord` (src/link/statePayload.ts), which sets the
 * reliability from them, kept to the safe side of what they show (src/viewer/prayerRecord.ts). It keeps the newest
 * MAX_WAVES waves that had an attack prayed against, as the site's own record does, so that it follows how the player
 * plays now; RuneLite's settings keep it between sessions as its text (toText).
 */
public final class PrayerRecord
{
	/** The most waves kept, about five whole runs: the site's RECORD_WAVES. */
	public static final int MAX_WAVES = 60;

	/** The text's version, its first part. */
	private static final String VERSION = "v1";

	private final List<PrayerFlicks> waves;

	private PrayerRecord(List<PrayerFlicks> waves)
	{
		this.waves = Collections.unmodifiableList(waves);
	}

	/** No wave counted. */
	public static PrayerRecord empty()
	{
		return new PrayerRecord(new ArrayList<>());
	}

	/** The record with a wave's counts added, and the oldest dropped past MAX_WAVES; itself for a wave with nothing prayed. */
	public PrayerRecord with(PrayerFlicks wave)
	{
		if (wave.isEmpty())
		{
			return this;
		}
		List<PrayerFlicks> next = new ArrayList<>(waves);
		next.add(wave);
		while (next.size() > MAX_WAVES)
		{
			next.remove(0);
		}
		return new PrayerRecord(next);
	}

	/** How many waves it holds. */
	public int getWaves()
	{
		return waves.size();
	}

	/** Its waves' counts together. */
	public PrayerFlicks total()
	{
		PrayerFlicks total = PrayerFlicks.NONE;
		for (PrayerFlicks w : waves)
		{
			total = total.plus(w);
		}
		return total;
	}

	/**
	 * The record as the state links give it to the site: [waves, flicks, held, late, unprayed], the totals of its waves
	 * (PrayerFlicks).
	 */
	public String toJson()
	{
		PrayerFlicks t = total();
		return "[" + waves.size() + "," + t.getFlicks() + "," + t.getHeld() + "," + t.getLate() + "," + t.getUnprayed() + "]";
	}

	/** The record as RuneLite's settings keep it: "v1", then each wave's flicks, held, late and unprayed, oldest first. */
	public String toText()
	{
		StringBuilder b = new StringBuilder(VERSION);
		for (PrayerFlicks w : waves)
		{
			b.append(';').append(w.getFlicks()).append(',').append(w.getHeld()).append(',').append(w.getLate()).append(',').append(w.getUnprayed());
		}
		return b.toString();
	}

	/** The record from its text (toText); empty when there is none, or it cannot be read. */
	public static PrayerRecord of(String text)
	{
		if (text == null || !text.startsWith(VERSION))
		{
			return empty();
		}
		String[] parts = text.split(";");
		if (!parts[0].equals(VERSION))
		{
			return empty();
		}
		List<PrayerFlicks> waves = new ArrayList<>();
		for (int i = 1; i < parts.length; i++)
		{
			String[] n = parts[i].split(",");
			if (n.length != 4)
			{
				return empty();
			}
			try
			{
				int[] v = new int[4];
				for (int k = 0; k < 4; k++)
				{
					v[k] = Integer.parseInt(n[k]);
					if (v[k] < 0)
					{
						return empty();
					}
				}
				waves.add(new PrayerFlicks(v[0], v[1], v[2], v[3]));
			}
			catch (NumberFormatException ex)
			{
				return empty();
			}
		}
		PrayerRecord record = empty();
		for (PrayerFlicks w : waves)
		{
			record = record.with(w);
		}
		return record;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Locale;

/**
 * The runs' profit added up (RunProfit), for the panel's Profit card: how many runs, how many ended in a death, what the
 * chest gave, what the runs used up and what the deaths' graves asked, and the last run on its own. The plugin keeps one for the session and one for
 * every run since the player last reset it, which RuneLite's settings keep for each account as its text (toText).
 */
public final class ProfitRecord
{
	/** The text's version, its first part; v1, before the deaths' fees, is read with none. */
	private static final String VERSION = "v2";
	private static final String VERSION_1 = "v1";

	private static final ProfitRecord EMPTY = new ProfitRecord(0, 0, 0, 0, 0, null);

	private final int runs;
	private final int deaths;
	private final long loot;
	private final long supplies;
	private final long deathFees;
	private final RunProfit last;

	private ProfitRecord(int runs, int deaths, long loot, long supplies, long deathFees, RunProfit last)
	{
		this.deathFees = deathFees;
		this.runs = runs;
		this.deaths = deaths;
		this.loot = loot;
		this.supplies = supplies;
		this.last = last;
	}

	/** No run counted. */
	public static ProfitRecord empty()
	{
		return EMPTY;
	}

	/** The record with `run` added as the last; itself for a run with nothing to count (RunProfit.counts). */
	public ProfitRecord with(RunProfit run)
	{
		if (!run.counts())
		{
			return this;
		}
		return new ProfitRecord(runs + 1, deaths + (run.isDied() ? 1 : 0), loot + run.getLoot(), supplies + run.getSupplies(),
			deathFees + run.getDeathFee(), run);
	}

	public int getRuns()
	{
		return runs;
	}

	public int getDeaths()
	{
		return deaths;
	}

	public long getLoot()
	{
		return loot;
	}

	public long getSupplies()
	{
		return supplies;
	}

	/** What the deaths' graves asked, estimated. */
	public long getDeathFees()
	{
		return deathFees;
	}

	/**
	 * The record with the last run's death fee set to `fee`, the grave's own as the player opened it, in place of the
	 * estimate; itself when the last run was no death.
	 */
	public ProfitRecord withLastDeathFee(long fee)
	{
		if (last == null || !last.isDied() || fee < 0)
		{
			return this;
		}
		RunProfit run = new RunProfit(last.getLoot(), last.getSupplies(), fee, true, last.getWave());
		return new ProfitRecord(runs, deaths, loot, supplies, Math.max(0, deathFees - last.getDeathFee() + fee), run);
	}

	/** The loot less the supplies and the deaths' fees. */
	public long getProfit()
	{
		return loot - supplies - deathFees;
	}

	/** The last run counted, or null for none. */
	public RunProfit getLast()
	{
		return last;
	}

	/** Whether it holds no run. */
	public boolean isEmpty()
	{
		return runs == 0;
	}

	/**
	 * The record as RuneLite's settings keep it: "v2", then the runs, deaths, loot, supplies and deaths' fees, then the last
	 * run's loot, supplies, fee, 1 for a death or 0, and its wave or nothing. A "v1" text has no fees.
	 */
	public String toText()
	{
		StringBuilder b = new StringBuilder(VERSION).append(';').append(runs).append(',').append(deaths).append(',').append(loot).append(',')
			.append(supplies).append(',').append(deathFees);
		if (last != null)
		{
			b.append(';').append(last.getLoot()).append(',').append(last.getSupplies()).append(',').append(last.getDeathFee()).append(',')
				.append(last.isDied() ? 1 : 0).append(',')
				.append(last.getWave() == null ? "" : last.getWave().toString());
		}
		return b.toString();
	}

	/** The record from its text (toText); empty when there is none, or it cannot be read. */
	public static ProfitRecord of(String text)
	{
		if (text == null)
		{
			return EMPTY;
		}
		String[] parts = text.split(";", -1);
		boolean v1 = parts[0].equals(VERSION_1);
		if (!(v1 || parts[0].equals(VERSION)) || parts.length < 2 || parts.length > 3)
		{
			return EMPTY;
		}
		// A v1 text is a v2 one with no fees, in the totals and in the last run.
		int fields = v1 ? 4 : 5;
		try
		{
			String[] t = parts[1].split(",", -1);
			if (t.length != fields)
			{
				return EMPTY;
			}
			int runs = Integer.parseInt(t[0]);
			int deaths = Integer.parseInt(t[1]);
			long loot = Long.parseLong(t[2]);
			long supplies = Long.parseLong(t[3]);
			long fees = v1 ? 0 : Long.parseLong(t[4]);
			if (runs < 0 || deaths < 0 || deaths > runs || loot < 0 || supplies < 0 || fees < 0)
			{
				return EMPTY;
			}
			RunProfit last = null;
			if (parts.length == 3)
			{
				String[] l = parts[2].split(",", -1);
				if (l.length != fields)
				{
					return EMPTY;
				}
				String died = l[fields - 2];
				if (!(died.equals("0") || died.equals("1")))
				{
					return EMPTY;
				}
				long lastLoot = Long.parseLong(l[0]);
				long lastSupplies = Long.parseLong(l[1]);
				long lastFee = v1 ? 0 : Long.parseLong(l[2]);
				if (lastLoot < 0 || lastSupplies < 0 || lastFee < 0)
				{
					return EMPTY;
				}
				String wave = l[fields - 1];
				last = new RunProfit(lastLoot, lastSupplies, lastFee, died.equals("1"), wave.isEmpty() ? null : Integer.valueOf(wave));
			}
			return new ProfitRecord(runs, deaths, loot, supplies, fees, last);
		}
		catch (NumberFormatException ex)
		{
			return EMPTY;
		}
	}

	/**
	 * Coins as the game's stacks show them, short: "950", "12.5K", "310K", "1.23M", "2.1B", with no sign, so that the panel
	 * stays narrow.
	 */
	public static String coins(long gp)
	{
		long a = Math.abs(gp);
		if (a < 10_000)
		{
			return String.format(Locale.UK, "%,d", a);
		}
		if (a < 100_000)
		{
			return trim(String.format(Locale.UK, "%.1f", a / 1_000.0)) + "K";
		}
		if (a < 1_000_000)
		{
			return (a / 1_000) + "K";
		}
		if (a < 1_000_000_000)
		{
			return trim(String.format(Locale.UK, "%.2f", a / 1_000_000.0)) + "M";
		}
		return trim(String.format(Locale.UK, "%.2f", a / 1_000_000_000.0)) + "B";
	}

	/** Coins with their sign: "+1.23M", "-310K", or "0" for none. */
	public static String signed(long gp)
	{
		return (gp > 0 ? "+" : gp < 0 ? "-" : "") + coins(gp);
	}

	/** "12.50" to "12.5", "3.00" to "3". */
	private static String trim(String number)
	{
		if (!number.contains("."))
		{
			return number;
		}
		String t = number.replaceAll("0+$", "");
		return t.endsWith(".") ? t.substring(0, t.length() - 1) : t;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.net.URI;
import java.net.URISyntaxException;

/** The upload and browser always use the plugin's site (SolSurvivorPlugin.SITE), never a URL returned by the server. */
public final class ReplayLink
{
	private ReplayLink()
	{
	}

	public static String endpoint(String site)
	{
		return origin(site) + "/api/replays";
	}

	public static String browser(String site, String id)
	{
		return browser(site, id, null, null);
	}

	/**
	 * The page that opens the stored run at wave `wave` and at `tick` of it, as the wave report and the death recap ask:
	 * "#replay=<id>.<wave>.<tick>", or without the tick, or without either when `wave` is null.
	 */
	public static String browser(String site, String id, Integer wave, Integer tick)
	{
		if (!isId(id))
		{
			throw new IllegalArgumentException("The site returned an invalid recording link. Try again.");
		}
		String at = wave == null ? "" : "." + wave + (tick == null ? "" : "." + Math.max(0, tick));
		return origin(site) + "/#replay=" + id + at;
	}

	/** Whether `id` is a stored run's id as the site gives them, 32 hexadecimal digits: nothing else goes in a link. */
	public static boolean isId(String id)
	{
		return id != null && id.matches("[a-f0-9]{32}");
	}

	/** The site's origin, its scheme, host and port: HTTPS, or HTTP on localhost for development. WaveShare posts to it too. */
	static String origin(String site)
	{
		try
		{
			URI uri = new URI(site.trim());
			String host = uri.getHost();
			boolean local = "localhost".equalsIgnoreCase(host) || "127.0.0.1".equals(host) || "[::1]".equals(host);
			if (host == null || uri.getRawUserInfo() != null || !("https".equalsIgnoreCase(uri.getScheme()) || local && "http".equalsIgnoreCase(uri.getScheme())))
			{
				throw new URISyntaxException(site, "Use HTTPS, or localhost for development");
			}
			return new URI(uri.getScheme(), null, host, uri.getPort(), null, null, null).toString();
		}
		catch (URISyntaxException | NullPointerException ex)
		{
			throw new IllegalArgumentException("The site's address must be HTTPS, or localhost for development.");
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.List;

/**
 * The run log's JSON: every wave of the newest run in one paste, which the panel's "Copy whole run" copies, so that the
 * site can review the run one wave after another. Like WaveLogWriter it is written by hand, ASCII only and in a fixed
 * order, so that a run always gives the same text and the tests can compare it whole. Each wave's log starts on a line
 * of its own and keeps its own lines, a tick on each, so that a run reads and diffs a wave and a tick at a time.
 *
 * <pre>
 * {"v":1,"kind":"solSurvivorRun","plugin":"0.2.0","waves":[
 * {"v":1,"kind":"solSurvivorWaveLog","plugin":"0.2.0","wave":1,...,"ticks":[
 * {"t":0,...},
 * ...
 * ]},
 * {"v":1,"kind":"solSurvivorWaveLog","plugin":"0.2.0","wave":2,...},
 * ...
 * ]}
 * </pre>
 *
 * <ul>
 * <li>`v`: the run log's version, 1; `kind`: always "solSurvivorRun", which tells it apart from a wave log and a state
 * link's payload; `plugin`: the version of the plugin that copied it.</li>
 * <li>`waves`: the run's wave logs, oldest first, each exactly as Copy wave log copies it (WaveLogWriter documents its
 * shape), with its own `plugin` and `wave`. The run is the one WaveLog.getRun picks: the newest wave logged and the
 * waves before it, one after another, back to wave 1, or to the oldest of them the plugin logged when it did not see the
 * run from wave 1. The last wave may still be under way, its `end` null. Empty when there is no log.</li>
 * </ul>
 */
public final class RunLogWriter
{
	/** The run log's version. */
	public static final int VERSION = 1;

	/** The run log's `kind`. */
	public static final String KIND = "solSurvivorRun";

	private RunLogWriter()
	{
	}

	/** The run's JSON: `run` is its logs, oldest first, as WaveLog.getRun gives them; `plugin` is the plugin's version. */
	public static String toJson(List<WaveLog.Past> run, String plugin)
	{
		StringBuilder b = new StringBuilder();
		b.append("{\"v\":").append(VERSION).append(",\"kind\":");
		StatePayload.string(b, KIND);
		b.append(",\"plugin\":");
		StatePayload.string(b, plugin);
		b.append(",\"waves\":[");
		boolean first = true;
		for (WaveLog.Past wave : run)
		{
			b.append(first ? "\n" : ",\n");
			first = false;
			b.append(wave.getJson());
		}
		b.append(first ? "]}" : "\n]}");
		return b.toString();
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntPredicate;
import java.util.function.IntToLongFunction;

/**
 * "Am I making a profit" for one run (Stefan's ask of 2026-11-04): what the reward chest gave against what the run used
 * up, both at the Grand Exchange's prices, which the plugin's RuneLite side passes in. A death in the arena loses the
 * chest (the site's src/viewer/chest.ts) and is not safe (Stefan, 2026-11-04): the items not kept go to a grave in the
 * Colosseum's lobby, whose fee is estimated (DeathFee). So a run the player died in costs its supplies and the fee, and
 * gains nothing.
 *
 * It follows a run from the plugin's first tick in the arena to its last. What the player carries, the inventory and
 * what they wear together, is taken as the run starts and as each tick ends; what it used up is the value carried at the
 * start less the value carried at the end. The chest's loot is what leaves the chest while the player is alive: Bank-all
 * and taking items alike. Loot taken into the inventory raises what is carried at the end, so what the inventory gained of
 * an item on the tick it left the chest, up to what left it, is taken back off before the supplies are counted. What is
 * carried stops changing at a death, so that what went to the grave is not counted as used. The runes in a rune pouch
 * count as carried. Charges inside a weapon, a blowpipe's scales and darts or a staff's runes, are not items: they are
 * estimated from the attacks the player made with it (ChargeCosts).
 *
 * Item ids are the RuneLite side's canonical ones, noted and placeholder items folded onto the item itself.
 */
public final class RunProfit
{
	private final long loot;
	private final long supplies;
	private final long deathFee;
	private final boolean died;
	private final Integer wave;

	public RunProfit(long loot, long supplies, long deathFee, boolean died, Integer wave)
	{
		this.loot = loot;
		this.supplies = supplies;
		this.deathFee = deathFee;
		this.died = died;
		this.wave = wave;
	}

	/** What the chest gave, in coins. */
	public long getLoot()
	{
		return loot;
	}

	/** What the run used up, in coins, never below nothing. */
	public long getSupplies()
	{
		return supplies;
	}

	/** What the grave asks after a death, estimated (DeathFee); nothing without one. */
	public long getDeathFee()
	{
		return deathFee;
	}

	/** Whether the player died in the arena, which loses the chest. */
	public boolean isDied()
	{
		return died;
	}

	/** The last wave the run reached, or null when the plugin saw none start. */
	public Integer getWave()
	{
		return wave;
	}

	/** The loot less the supplies and any death's fee. */
	public long getProfit()
	{
		return loot - supplies - deathFee;
	}

	/** Whether the run did anything to count: a walk into the arena and out again does not. */
	public boolean counts()
	{
		return died || loot != 0 || supplies != 0 || deathFee != 0;
	}

	/**
	 * Follows one run as the RuneLite side sees it, on the client thread. Not thread-safe; a new one for each run.
	 */
	public static final class Tracker
	{
		private final Map<Integer, Integer> start;
		private Map<Integer, Integer> carried;
		private Map<Integer, Integer> chest;
		private final Map<Integer, Integer> claimed = new HashMap<>();
		/** The part of the claimed loot that went into the inventory. */
		private final Map<Integer, Integer> taken = new HashMap<>();
		/** The attacks made with each weapon, by its name, for the charges inside it (ChargeCosts). */
		private final Map<String, Integer> attacks = new HashMap<>();
		private boolean died;
		private int kept;
		private boolean discounted;
		private boolean ironman;

		/**
		 * A run that starts with `carried` and the chest as the game holds it now (`chest`): empty after a run that ended
		 * in a death, as the chest that died with the player is no one's to claim, whatever the game still shows of it.
		 */
		public Tracker(Map<Integer, Integer> carried, Map<Integer, Integer> chest)
		{
			this.start = new HashMap<>(carried);
			this.carried = new HashMap<>(carried);
			this.chest = new HashMap<>(chest);
		}

		/**
		 * What the player carries and the chest holds as a tick ends. What left the chest while the player lives is loot
		 * claimed, and as much of it as the inventory gained on the same tick went into the inventory: taken, not banked.
		 */
		public void onTick(Map<Integer, Integer> nowCarried, Map<Integer, Integer> nowChest)
		{
			if (!died)
			{
				for (Map.Entry<Integer, Integer> was : chest.entrySet())
				{
					int left = was.getValue() - nowChest.getOrDefault(was.getKey(), 0);
					if (left > 0)
					{
						claimed.merge(was.getKey(), left, Integer::sum);
						int gained = nowCarried.getOrDefault(was.getKey(), 0) - carried.getOrDefault(was.getKey(), 0);
						if (gained > 0)
						{
							taken.merge(was.getKey(), Math.min(left, gained), Integer::sum);
						}
					}
				}
			}
			if (!died)
			{
				carried = new HashMap<>(nowCarried);
			}
			chest = new HashMap<>(nowChest);
		}

		/** An attack with the weapon of that name, which may use up charges inside it. */
		public void onAttack(String weapon)
		{
			if (!died && weapon != null)
			{
				attacks.merge(weapon, 1, Integer::sum);
			}
		}

		/**
		 * The player died in the arena: the chest is lost, nothing that leaves it after is theirs, and what they carried as
		 * they died is what the grave's fee is for, `kept` items kept, with the Colosseum's discount while `discounted`.
		 */
		public void onDeath(int kept, boolean discounted, boolean ironman)
		{
			if (died)
			{
				return;
			}
			died = true;
			this.kept = kept;
			this.discounted = discounted;
			this.ironman = ironman;
		}

		/** Whether the player died in this run. */
		public boolean isDied()
		{
			return died;
		}

		/**
		 * The run as it ended, at the prices `price` gives each item id, for each one of it. A death's fee (DeathFee) is at
		 * `guidePrice`, the Grand Exchange's own guide prices, which the grave goes by, and `stackable` says which items
		 * stack.
		 */
		public RunProfit finish(IntToLongFunction price, IntToLongFunction guidePrice, IntPredicate stackable, Integer wave)
		{
			// The loot taken into the inventory raises what is carried at the end: it is loot, not supplies left unused.
			long used = Math.max(0, value(start, price) - value(carried, price) + value(taken, price));
			double charges = 0;
			for (Map.Entry<String, Integer> a : attacks.entrySet())
			{
				for (Map.Entry<Integer, Double> each : ChargeCosts.perAttack(a.getKey()).entrySet())
				{
					charges += price.applyAsLong(each.getKey()) * each.getValue() * a.getValue();
				}
			}
			long fee = died ? DeathFee.estimate(carried, guidePrice, stackable, kept, discounted, ironman) : 0;
			return new RunProfit(value(claimed, price), used + Math.round(charges), fee, died, wave);
		}

		private static long value(Map<Integer, Integer> items, IntToLongFunction price)
		{
			long total = 0;
			for (Map.Entry<Integer, Integer> i : items.entrySet())
			{
				total += price.applyAsLong(i.getKey()) * i.getValue();
			}
			return total;
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

/**
 * The body a run's Watch uploads to the site's /api/replays (its src/edge/replays.ts): the run's JSON, as RunLogWriter
 * writes it, gzipped here, so that the site, with its few milliseconds of CPU a request, only unpacks it to check it and
 * stores the bytes it got. The site takes at most MAX_PACKED_BYTES gzipped, which unpack to at most MAX_JSON_BYTES; a
 * run past either is refused here, with what the player can do instead, before anything is sent. It holds no RuneLite
 * import, as the rest of the core.
 */
public final class RunUpload
{
	/** The body's type: the run's JSON, gzipped (the site's REPLAY_GZIP_TYPE). */
	public static final String TYPE = "application/gzip";

	/** The most JSON a run may be (the site's MAX_REPLAY_BYTES). */
	public static final int MAX_JSON_BYTES = 8 * 1024 * 1024;

	/** The most the gzipped run may be (the site's MAX_STORED_REPLAY_BYTES). */
	public static final int MAX_PACKED_BYTES = 256 * 1024;

	/** A run too large to upload, with the message the player is shown. */
	public static final class TooLarge extends IOException
	{
		TooLarge(String message)
		{
			super(message);
		}
	}

	private RunUpload()
	{
	}

	/** The run's JSON gzipped, as the site takes it; TooLarge past either of its limits. */
	public static byte[] pack(String json) throws TooLarge
	{
		if (json.getBytes(StandardCharsets.UTF_8).length > MAX_JSON_BYTES)
		{
			throw new TooLarge("This run is too large to open (8 MiB maximum). You can still copy its wave logs.");
		}
		byte[] packed = WaveShare.gzip(json);
		if (packed.length > MAX_PACKED_BYTES)
		{
			throw new TooLarge("This run is too large to store on the site. You can still copy its wave logs.");
		}
		return packed;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A wave of the run under way that the player finished, as the tracker kept it for the pick link (PickPayload's `run`):
 * what the site needs to work the wave's glory out by the game's rules, as its run review does from a wave log. The
 * plugin works nothing out itself.
 *
 * <ul>
 * <li>`ticks`: the ticks from the tick of the game's "Wave: N" message to that of "Wave N completed!", both counted, as
 * the wave log holds them; null when the plugin did not see the wave start.</li>
 * <li>`hit`: whether a hitsplat dealt the player damage in the wave (ColosseumTracker.onPlayerHit, the hits Doom counts):
 * Solarflare's and the sand's among them, which do not cost the game's no-damage bonus, so it can say true where the
 * game paid the bonus. Null when the plugin did not see the wave start.</li>
 * <li>`damage`: the most the game's own VarPlayerID.COLOSSEUM_WAVE_DAMAGE_TAKEN read in the wave, from the tick after
 * its first to the last before the next wave starts. Whether it counts only the damage that costs the no-damage bonus
 * is unconfirmed: it is sent beside `hit` so that the site and the shared logs can settle that, not to price the wave.
 * Null when the plugin did not see the wave start.</li>
 * <li>`modifiers`: the modifiers held through the wave, with their tiers.</li>
 * <li>`glory`: the game's own VarPlayerID.COLOSSEUM_CURRENT_GLORY as the wave ended, its last value before the next wave
 * starts. What it holds is unconfirmed: it is sent so that the site can check its sums against it, not to show it.</li>
 * <li>`drunk`: the doses of each potion gone from the inventory from the end of the wave before, or the run's first tick
 * the plugin saw, to the wave's end (Potions), for the site's verdict on the chest. Null when the plugin did not see the
 * run from before the wave.</li>
 * </ul>
 */
public final class RunWave
{
	private final int wave;
	private final Integer ticks;
	private final Boolean hit;
	private final Integer damage;
	private final Map<Modifier, Integer> modifiers;
	private final int glory;
	private final Map<String, Integer> drunk;

	public RunWave(int wave, Integer ticks, Boolean hit, Integer damage, Map<Modifier, Integer> modifiers, int glory)
	{
		this(wave, ticks, hit, damage, modifiers, glory, null);
	}

	public RunWave(int wave, Integer ticks, Boolean hit, Integer damage, Map<Modifier, Integer> modifiers, int glory, Map<String, Integer> drunk)
	{
		this.drunk = drunk == null ? null : Collections.unmodifiableMap(new LinkedHashMap<>(drunk));
		this.wave = wave;
		this.ticks = ticks;
		this.hit = hit;
		this.damage = damage;
		this.modifiers = modifiers.isEmpty() ? Collections.emptyMap() : Collections.unmodifiableMap(new EnumMap<>(modifiers));
		this.glory = glory;
	}

	/**
	 * The same wave with the game's counters as they read now: its glory as it is, and its damage the higher of the one
	 * kept and this, since the game may clear the counter before the next wave.
	 */
	public RunWave withCounters(int gloryNow, int damageNow)
	{
		return new RunWave(wave, ticks, hit, damage == null ? null : Math.max(damage, damageNow), modifiers, gloryNow, drunk);
	}

	public int getWave()
	{
		return wave;
	}

	public Integer getTicks()
	{
		return ticks;
	}

	public Boolean getHit()
	{
		return hit;
	}

	public Integer getDamage()
	{
		return damage;
	}

	public Map<Modifier, Integer> getModifiers()
	{
		return modifiers;
	}

	public int getGlory()
	{
		return glory;
	}

	/** The doses of each potion drunk in the wave, or null when the plugin did not count them. */
	public Map<String, Integer> getDrunk()
	{
		return drunk;
	}
}

