package nl.dexanddice.solsurvivor.core;

/**
 * The Sol Survivor site the plugin's links open and its uploads go to. A player's plugin always has the live site: only
 * a development run sets the system property PROPERTY, which `gradlew run` does on a release's holding branch, such as
 * release/1.1, so that its links open that branch's preview, the site that reads what the branch's plugin sends
 * (docs/release.md, "Working on plugin 1.1"). A preview runs on the live site's data, so its uploads land where the live
 * site's do.
 */
public final class Site
{
	/** The live site. */
	public static final String LIVE = "https://solsurvivor.app/";

	/** The system property a development run names another site in. */
	public static final String PROPERTY = "solsurvivor.site";

	private Site()
	{
	}

	/**
	 * The site for `override`, the system property's value: the live site for none, or for anything but an https address
	 * of a host of its own; otherwise that address, ending in "/" as LIVE does.
	 */
	public static String of(String override)
	{
		if (override == null || !override.trim().matches("https://[A-Za-z0-9.-]+/?"))
		{
			return LIVE;
		}
		String site = override.trim();
		return site.endsWith("/") ? site : site + "/";
	}
}

package nl.dexanddice.solsurvivor.core;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.List;
import java.util.Map;
import java.util.zip.Deflater;

/**
 * Sol Survivor's state link, version 1, as src/link/statePayload.ts defines it: the site's address, "#s=", and the
 * JSON payload packed as the site packs its own (src/ui/linkPacking.ts): "1", then the JSON deflated against the site's
 * preset dictionary and written as unpadded base64url. Plugins before 0.5.0 wrote the JSON's base64url unpacked, which
 * the site still reads. The plugin writes the `setup`, the arena as the game shows it (mid-wave with the fight so far:
 * the NPCs' health bars, Doom's stacks; and the molten sand on the floor), and with the player's gear the `prayer`
 * values and the `equipment`; with the player's setting for it, the place of the dot on the site's Safe / Fast / Easy
 * triangle (`triangle`, withTriangle); and with theirs for that, their prayer over the waves the plugin counted, which
 * sets the site's Prayer reliability (`prayerRecord`, withPrayerRecord); on the plugin's first link, a mark that
 * says so (`first`, withFirst); and with the player's setting for it, their own tile markers from Ground Markers
 * and Tile Packs (`markers`, withMarkers). The site keeps its own kill table and solver settings.
 *
 * The JSON is written by hand, ASCII only and in a fixed order, so that a state always gives the same link and the
 * tests can compare links whole.
 */
public final class StatePayload
{
	/** The payload's version, the site's STATE_VERSION. */
	public static final int VERSION = 1;

	/** The site's state hash, STATE_HASH. */
	public static final String STATE_HASH = "#s=";

	/** The leading character of text packed with the site's first dictionary, the site's PACKED_V1. */
	public static final String PACKED_V1 = "1";

	/**
	 * The site's first preset dictionary, STATE_DICTIONARY_V1, byte for byte: the site's tests compare the two
	 * (test/link/pluginFixtures.test.ts). It is frozen, so a link packed with it reads on every later site. Null when
	 * the resource cannot be read, and the links are then written unpacked, as before 0.5.0, which the site reads too.
	 */
	static final byte[] DICTIONARY_V1 = readDictionary();

	private static byte[] readDictionary()
	{
		try (InputStream in = StatePayload.class.getResourceAsStream("state-dictionary-v1.txt"))
		{
			return in == null ? null : in.readAllBytes();
		}
		catch (IOException e)
		{
			return null;
		}
	}

	private StatePayload()
	{
	}

	/** The prayer bonus's range the site reads (PRAYER_BONUS_LIMITS); a bonus outside it is clamped to it. */
	private static final int MAX_PRAYER_BONUS = 73;
	/** The most prayer points the site reads (PRAYER_POINTS_LIMITS), the most a level 99 has. */
	private static final int MAX_PRAYER_POINTS = 99;

	/**
	 * Mid-wave: `attacks`, one entry per NPC in the order of `npcs`, each [ticks since its last attack, attacks made] with
	 * null for what the plugin does not know, or null for an NPC it knows nothing of (a Manticore always). Left out when
	 * it knows nothing of any.
	 */
	private static void attacks(StringBuilder b, ArenaState state)
	{
		boolean any = false;
		for (ExportNpc n : state.getNpcs())
		{
			any |= n.getSinceAttack() != null || n.getAttacks() != null;
		}
		if (!any)
		{
			return;
		}
		b.append(",\"attacks\":[");
		boolean first = true;
		for (ExportNpc n : state.getNpcs())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			if (n.getSinceAttack() == null && n.getAttacks() == null)
			{
				b.append("null");
			}
			else
			{
				b.append('[').append(n.getSinceAttack()).append(',').append(n.getAttacks()).append(']');
			}
		}
		b.append(']');
	}

	/**
	 * Mid-wave: `health`, one entry per NPC in the order of `npcs`, each its health bar as the game last showed it,
	 * [ratio, scale], or null for an NPC whose bar the plugin has not seen. Left out when it has seen none.
	 */
	private static void health(StringBuilder b, ArenaState state)
	{
		boolean any = false;
		for (ExportNpc n : state.getNpcs())
		{
			any |= n.getHealth() != null;
		}
		if (!any)
		{
			return;
		}
		b.append(",\"health\":[");
		boolean first = true;
		for (ExportNpc n : state.getNpcs())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			int[] health = n.getHealth();
			if (health == null)
			{
				b.append("null");
			}
			else
			{
				b.append('[').append(health[0]).append(',').append(health[1]).append(']');
			}
		}
		b.append(']');
	}

	/** A list of tiles, such as `[[16,10],[15,11]]`. */
	private static void tiles(StringBuilder b, List<GridTile> tiles)
	{
		b.append('[');
		boolean first = true;
		for (GridTile t : tiles)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(t.getX()).append(',').append(t.getY()).append(']');
		}
		b.append(']');
	}

	/** The payload's JSON, without the gear. */
	public static String toJson(ArenaState state)
	{
		return toJson(state, null);
	}

	/** The payload's JSON, with the player's gear and stats when `equipment` is not null. */
	public static String toJson(ArenaState state, Equipment equipment)
	{
		StringBuilder b = new StringBuilder();
		b.append("{\"v\":").append(VERSION).append(",\"setup\":{\"npcs\":[");
		boolean first = true;
		for (ExportNpc n : state.getNpcs())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(n.getTile().getX()).append(',').append(n.getTile().getY()).append(',').append(n.getKind().getCode());
			if (n.getOrbs() != null)
			{
				b.append(',');
				string(b, n.getOrbs());
			}
			b.append(']');
		}
		b.append("],\"player\":[").append(state.getPlayer().getX()).append(',').append(state.getPlayer().getY()).append(']');
		b.append(",\"waveStart\":").append(state.isWaveStart());
		if (state.isMm3())
		{
			b.append(",\"mm3\":true");
		}
		if (state.getWave() != null)
		{
			b.append(",\"wave\":").append(state.getWave());
		}
		if (!state.isWaveStart())
		{
			// Once the reinforcements have come, none will; before, the plugin gives the tick within the wave and leaves
			// the timer to the site.
			if (state.isReinforcementsArrived())
			{
				b.append(",\"timer\":\"none\"");
			}
			if (state.getWaveTick() != null)
			{
				b.append(",\"waveTick\":").append(state.getWaveTick());
			}
			attacks(b, state);
			health(b, state);
			if (state.getDoomStacks() != null)
			{
				b.append(",\"doomStacks\":").append(state.getDoomStacks());
			}
		}
		b.append(",\"modifiers\":{");
		first = true;
		for (Map.Entry<Modifier, Integer> e : state.getModifiers().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			string(b, e.getKey().getKey());
			b.append(':').append(valueOf(e.getKey(), e.getValue()));
		}
		b.append('}');
		if (!state.getSolarflareOrbs().isEmpty())
		{
			b.append(",\"solarflareOrbs\":");
			tiles(b, state.getSolarflareOrbs());
		}
		// The sand on the floor, at a wave's start too, where Reentry II's and III's from earlier waves lie.
		if (!state.getSand().isEmpty())
		{
			b.append(",\"sand\":");
			tiles(b, state.getSand());
		}
		b.append('}');
		if (equipment != null)
		{
			gear(b, equipment);
		}
		b.append('}');
		return b.toString();
	}

	/** The `prayer` values the site plans with, and the `equipment` it does not read yet. */
	private static void gear(StringBuilder b, Equipment e)
	{
		b.append(",\"prayer\":{");
		// The site reads 1 to 99 points: with none left, it keeps its own.
		if (e.getPrayerPoints() >= 1)
		{
			b.append("\"start\":").append(Math.min(e.getPrayerPoints(), MAX_PRAYER_POINTS)).append(',');
		}
		b.append("\"bonus\":").append(Math.max(0, Math.min(e.getPrayerBonus(), MAX_PRAYER_BONUS))).append('}');

		b.append(",\"equipment\":{\"items\":{");
		boolean first = true;
		for (Map.Entry<String, Equipment.Item> i : e.getItems().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			string(b, i.getKey());
			b.append(":[").append(i.getValue().getId()).append(',');
			string(b, i.getValue().getName());
			b.append(',').append(i.getValue().getQuantity()).append(']');
		}
		b.append('}');
		if (!e.getSwitches().isEmpty())
		{
			// The switches: each [id, name, quantity, slot], in the inventory's order, and a weapon's attack speed after
			// them when it is known.
			b.append(",\"switches\":[");
			for (int i = 0; i < e.getSwitches().size(); i++)
			{
				Equipment.Switch sw = e.getSwitches().get(i);
				if (i > 0)
				{
					b.append(',');
				}
				b.append('[').append(sw.getItem().getId()).append(',');
				string(b, sw.getItem().getName());
				b.append(',').append(sw.getItem().getQuantity()).append(',');
				string(b, sw.getSlot());
				if (sw.getSpeed() > 0)
				{
					b.append(',').append(sw.getSpeed());
				}
				b.append(']');
			}
			b.append(']');
		}
		b.append(",\"weaponSpeed\":").append(e.getWeaponSpeed());
		b.append(",\"weaponCategory\":").append(e.getWeaponCategory());
		b.append(",\"attackStyle\":").append(e.getAttackStyle());
		if (!e.getStyleNames().isEmpty())
		{
			b.append(",\"styleNames\":[");
			for (int i = 0; i < e.getStyleNames().size(); i++)
			{
				if (i > 0)
				{
					b.append(',');
				}
				string(b, e.getStyleNames().get(i));
			}
			b.append(']');
		}
		b.append(",\"stats\":{");
		first = true;
		for (Map.Entry<String, int[]> st : e.getStats().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			string(b, st.getKey());
			b.append(":[").append(st.getValue()[0]).append(',').append(st.getValue()[1]).append(']');
		}
		b.append('}');
		byItem(b, "bonuses", e.getBonuses());
		byItem(b, "defences", e.getDefences());
		int[] unlocks = e.getUnlocks();
		if (unlocks != null)
		{
			b.append(",\"unlocks\":{");
			for (int i = 0; i < Equipment.UNLOCK_FLAGS.length; i++)
			{
				if (i > 0)
				{
					b.append(',');
				}
				b.append('"').append(Equipment.UNLOCK_FLAGS[i]).append("\":").append(unlocks[i]);
			}
			b.append('}');
		}
		b.append('}');
	}

	/** A map of numbers by item id, as `,"name":{"id":[...],...}`, or nothing when it is empty. */
	private static void byItem(StringBuilder b, String name, Map<Integer, int[]> values)
	{
		if (values.isEmpty())
		{
			return;
		}
		b.append(",\"").append(name).append("\":{");
		boolean first = true;
		for (Map.Entry<Integer, int[]> item : values.entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('"').append(item.getKey()).append("\":[");
			for (int i = 0; i < item.getValue().length; i++)
			{
				if (i > 0)
				{
					b.append(',');
				}
				b.append(item.getValue()[i]);
			}
			b.append(']');
		}
		b.append('}');
	}

	/**
	 * A modifier's value in the link: its tier, true for Dynamic Duo, Red Flag and Totemic, and "random" for Quartet. The
	 * wave log writes its modifiers the same way, so that the site reads both with one reader.
	 */
	static String valueOf(Modifier m, int level)
	{
		switch (m)
		{
			case QUARTET:
				// The engine draws the fourth frem's kind at the wave start, as the game does.
				return "\"random\"";
			case DYNAMIC_DUO:
			case RED_FLAG:
			case TOTEMIC:
				return "true";
			default:
				return String.valueOf(level);
		}
	}

	/**
	 * A JSON string, ASCII only: an item's name may hold any character, which is escaped past ASCII and below a space. The
	 * wave log writes its strings with it too.
	 */
	static void string(StringBuilder b, String s)
	{
		b.append('"');
		for (char c : (s == null ? "" : s).toCharArray())
		{
			if (c == '"' || c == '\\')
			{
				b.append('\\').append(c);
			}
			else if (c < 0x20 || c > 0x7e)
			{
				b.append(String.format("\\u%04x", (int) c));
			}
			else
			{
				b.append(c);
			}
		}
		b.append('"');
	}

	/** The payload's text in a link: its JSON packed (pack). */
	public static String encode(ArenaState state)
	{
		return encode(state, null);
	}

	/** The payload's text in a link, with the player's gear when `equipment` is not null. */
	public static String encode(ArenaState state, Equipment equipment)
	{
		return pack(toJson(state, equipment));
	}

	/**
	 * A payload's JSON as link text, packed as the site packs its own: PACKED_V1, then the JSON deflated at the highest
	 * level against DICTIONARY_V1, raw (no zlib header), as unpadded base64url. The twelve wave starts of Stefan's logs of
	 * 2026-10-18 and 19, each with three switches, went from 1,796 to 1,921 characters to 849 to 884, well under the
	 * 2,047 or so at which Windows is reported to cut a link that another program opens. Without the dictionary the
	 * JSON's base64url, unpacked.
	 */
	public static String pack(String json)
	{
		byte[] bytes = json.getBytes(StandardCharsets.US_ASCII);
		if (DICTIONARY_V1 == null)
		{
			return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
		}
		Deflater deflater = new Deflater(Deflater.BEST_COMPRESSION, true);
		try
		{
			deflater.setDictionary(DICTIONARY_V1);
			deflater.setInput(bytes);
			deflater.finish();
			ByteArrayOutputStream out = new ByteArrayOutputStream(bytes.length / 2 + 64);
			byte[] buffer = new byte[4096];
			while (!deflater.finished())
			{
				out.write(buffer, 0, deflater.deflate(buffer));
			}
			return PACKED_V1 + Base64.getUrlEncoder().withoutPadding().encodeToString(out.toByteArray());
		}
		finally
		{
			deflater.end();
		}
	}

	/**
	 * The whole link: the site's address, "#s=" and the payload's text. The address loses any hash it had and ends in a
	 * slash.
	 */
	public static String link(String siteUrl, ArenaState state)
	{
		return link(siteUrl, state, null);
	}

	/** The whole link, with the player's gear when `equipment` is not null. */
	public static String link(String siteUrl, ArenaState state, Equipment equipment)
	{
		return link(siteUrl, state, equipment, null);
	}

	/**
	 * The whole link, with the player's gear when `equipment` is not null, and the place they set for the site's triangle
	 * when `triangle` is not null (withTriangle).
	 */
	public static String link(String siteUrl, ArenaState state, Equipment equipment, TriangleDot triangle)
	{
		return link(siteUrl, state, equipment, triangle, null);
	}

	/**
	 * The whole link, with the player's gear when `equipment` is not null, the place they set for the site's triangle when
	 * `triangle` is not null (withTriangle), and their prayer over the waves counted when `prayer` is not null
	 * (withPrayerRecord).
	 */
	public static String link(String siteUrl, ArenaState state, Equipment equipment, TriangleDot triangle, PrayerRecord prayer)
	{
		return link(siteUrl, state, equipment, triangle, prayer, false);
	}

	/**
	 * The whole link, with the player's gear when `equipment` is not null, the place they set for the site's triangle when
	 * `triangle` is not null (withTriangle), their prayer over the waves counted when `prayer` is not null
	 * (withPrayerRecord), and the mark of the plugin's first link when `first` (withFirst).
	 */
	public static String link(String siteUrl, ArenaState state, Equipment equipment, TriangleDot triangle, PrayerRecord prayer, boolean first)
	{
		return link(siteUrl, state, equipment, triangle, prayer, first, null);
	}

	/**
	 * The whole link, with the player's gear when `equipment` is not null, the place they set for the site's triangle when
	 * `triangle` is not null (withTriangle), their prayer over the waves counted when `prayer` is not null
	 * (withPrayerRecord), the mark of the plugin's first link when `first` (withFirst), and their own tile markers when
	 * `markers` holds any (withMarkers).
	 */
	public static String link(String siteUrl, ArenaState state, Equipment equipment, TriangleDot triangle, PrayerRecord prayer, boolean first, List<TileMarker> markers)
	{
		String json = withMarkers(toJson(state, equipment), markers);
		return linkOfJson(siteUrl, first ? withFirst(json) : json, triangle, prayer);
	}

	/**
	 * A payload's JSON with the player's own tile markers, `markers`, after the rest: each [x, y, colour] or, with a label,
	 * [x, y, colour, label], at most TileMarker.MAX_MARKERS of them, the first. The site draws them on its map in their
	 * colours with their labels. The JSON as it was when `markers` is null or empty. Only Arena now's links take them: the
	 * wave log keeps its payloads without, as it keeps them without the triangle.
	 */
	public static String withMarkers(String json, List<TileMarker> markers)
	{
		if (markers == null || markers.isEmpty())
		{
			return json;
		}
		// toJson's JSON is one object, so its last character closes it.
		StringBuilder b = new StringBuilder(json.substring(0, json.lastIndexOf('}')));
		b.append(",\"markers\":[");
		for (int i = 0; i < Math.min(markers.size(), TileMarker.MAX_MARKERS); i++)
		{
			TileMarker m = markers.get(i);
			if (i > 0)
			{
				b.append(',');
			}
			b.append('[').append(m.getTile().getX()).append(',').append(m.getTile().getY()).append(',');
			string(b, m.getColour());
			if (m.getLabel() != null)
			{
				b.append(',');
				string(b, m.getLabel());
			}
			b.append(']');
		}
		return b.append("]}").toString();
	}

	/**
	 * A payload's JSON with the mark of the plugin's first link, `"first":true`, after the rest (the onboarding ideas of
	 * 2026-10-27, O4): the site opens a plugin player's first page with a short tour of its own, and counts how many such
	 * pages it opens and how many are solved. Only the first arena the plugin opens on the site takes it.
	 */
	public static String withFirst(String json)
	{
		// toJson's JSON is one object, so its last character closes it.
		return json.substring(0, json.lastIndexOf('}')) + ",\"first\":true}";
	}

	/**
	 * A payload's JSON with the place the player set for the dot of the site's Safe / Fast / Easy triangle, `triangle`,
	 * after the rest: its three shares, as TriangleDot holds them. The site opens the link with the dot there, in place of
	 * where the viewer last left it. The JSON as it was when `triangle` is null. Only the links take it: the wave log keeps
	 * its payloads without, so that a past wave opens with the setting as it is when the player opens it.
	 */
	public static String withTriangle(String json, TriangleDot triangle)
	{
		if (triangle == null)
		{
			return json;
		}
		// toJson's JSON is one object, so its last character closes it.
		StringBuilder b = new StringBuilder(json.substring(0, json.lastIndexOf('}')));
		b.append(",\"triangle\":[").append(triangle.getSafe()).append(',').append(triangle.getFast()).append(',').append(triangle.getEasy()).append("]}");
		return b.toString();
	}

	/**
	 * A payload's JSON with the player's prayer over the waves the plugin counted, `prayer`, after the rest: its totals,
	 * [waves, flicks, held, late, unprayed] (PrayerRecord.toJson). The site sets its Prayer reliability from them, its
	 * Mine, for the page the link opens. The JSON as it was when `prayer` is null or holds no wave. Only the links take it,
	 * as they take the triangle (withTriangle).
	 */
	public static String withPrayerRecord(String json, PrayerRecord prayer)
	{
		if (prayer == null || prayer.getWaves() == 0)
		{
			return json;
		}
		// toJson's JSON is one object, so its last character closes it.
		return json.substring(0, json.lastIndexOf('}')) + ",\"prayerRecord\":" + prayer.toJson() + "}";
	}

	/** The whole link of a payload toJson wrote earlier, such as a past wave's start the wave log kept. */
	public static String linkOfJson(String siteUrl, String json)
	{
		return linkOfJson(siteUrl, json, null);
	}

	/**
	 * The whole link of a payload toJson wrote earlier, with the place the player set for the site's triangle when
	 * `triangle` is not null (withTriangle).
	 */
	public static String linkOfJson(String siteUrl, String json, TriangleDot triangle)
	{
		return linkOfJson(siteUrl, json, triangle, null);
	}

	/**
	 * The whole link of a payload toJson wrote earlier, with the place the player set for the site's triangle when
	 * `triangle` is not null (withTriangle), and their prayer over the waves counted when `prayer` is not null
	 * (withPrayerRecord).
	 */
	public static String linkOfJson(String siteUrl, String json, TriangleDot triangle, PrayerRecord prayer)
	{
		String base = siteUrl.trim();
		int hash = base.indexOf('#');
		if (hash >= 0)
		{
			base = base.substring(0, hash);
		}
		if (!base.endsWith("/"))
		{
			base += "/";
		}
		return base + STATE_HASH + pack(withPrayerRecord(withTriangle(json, triangle), prayer));
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * One of the player's own tile markers in the arena, from RuneLite's Ground Markers, as the state links give it to the
 * site (`markers`, src/link/statePayload.ts's TileMarkerV1): its grid tile, its colour as "#rrggbb" and its label, or
 * null for none. The plugin only sends the tiles the player marked by hand; it draws nothing new in the game.
 */
public final class TileMarker
{
	/** The most markers a link holds, the site's MAX_TILE_MARKERS. */
	public static final int MAX_MARKERS = 100;

	/** The longest label a link holds, the site's MAX_TILE_MARKER_LABEL; a longer one is cut to it. */
	public static final int MAX_LABEL = 40;

	/** Ground Markers' own colour for a tile marked without one: its "Color of the tile" setting's default, yellow. */
	static final int DEFAULT_RGB = 0xFFFF00;

	/**
	 * The faintest colour a marker is sent in, by its alpha: one fainter cannot be seen in the game, such as the pillars'
	 * edges Tile Packs' Colosseum pack marks at an alpha of 1, and would show on the site's map as a tile the player never
	 * saw.
	 */
	static final int MIN_ALPHA = 0x10;

	private final GridTile tile;
	private final String colour;
	private final String label;

	private TileMarker(GridTile tile, String colour, String label)
	{
		this.tile = tile;
		this.colour = colour;
		this.label = label;
	}

	/**
	 * The marker of a point Ground Markers saved: in `regionId`, at `regionX` and `regionY` within it on plane `z`, in the
	 * colour `argb` (null for Ground Markers' default) with `label` (null or blank for none). Null for a point outside the
	 * arena's region, off its grid, on another plane than `plane`, the player's, or too faint to see (MIN_ALPHA).
	 */
	public static TileMarker of(int regionId, int regionX, int regionY, int z, int plane, Integer argb, String label)
	{
		if (regionId != ArenaGeometry.REGION_ID || z != plane || (argb != null && argb >>> 24 < MIN_ALPHA))
		{
			return null;
		}
		GridTile tile = ArenaGeometry.fromRegion(regionX, regionY);
		if (!ArenaGeometry.onGrid(tile))
		{
			return null;
		}
		String colour = String.format("#%06x", (argb == null ? DEFAULT_RGB : argb) & 0xFFFFFF);
		return new TileMarker(tile, colour, labelOf(label));
	}

	/** A label as a link holds it: trimmed, cut to MAX_LABEL without splitting a character in two, and null when blank. */
	private static String labelOf(String label)
	{
		if (label == null || label.trim().isEmpty())
		{
			return null;
		}
		String s = label.trim();
		if (s.length() <= MAX_LABEL)
		{
			return s;
		}
		int end = Character.isHighSurrogate(s.charAt(MAX_LABEL - 1)) ? MAX_LABEL - 1 : MAX_LABEL;
		return s.substring(0, end);
	}

	/**
	 * `markers` with one marker on a tile, the first given for it, in their order, and at most MAX_MARKERS: the player's
	 * own Ground Markers come before a tile pack's, so theirs win a tile both mark.
	 */
	public static List<TileMarker> distinct(List<TileMarker> markers)
	{
		Map<GridTile, TileMarker> byTile = new LinkedHashMap<>();
		for (TileMarker m : markers)
		{
			if (byTile.size() < MAX_MARKERS)
			{
				byTile.putIfAbsent(m.getTile(), m);
			}
		}
		return new ArrayList<>(byTile.values());
	}

	public GridTile getTile()
	{
		return tile;
	}

	/** The colour as "#rrggbb", lower case. */
	public String getColour()
	{
		return colour;
	}

	/** The label, or null for none. */
	public String getLabel()
	{
		return label;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof TileMarker))
		{
			return false;
		}
		TileMarker m = (TileMarker) o;
		return tile.equals(m.tile) && colour.equals(m.colour) && Objects.equals(label, m.label);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(tile, colour, label);
	}

	@Override
	public String toString()
	{
		return tile + " " + colour + (label == null ? "" : " " + label);
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.Objects;

/**
 * Where the player wants the dot of the site's Safe / Fast / Easy triangle, which picks the plan the site suggests: the
 * three shares as the plugin's settings hold them, each from 0 to MAX_SHARE. The state links give it to the site as
 * their `triangle` (src/link/statePayload.ts), which reads each share as its part of the three's total, so they need not
 * add up to 100: 10, 0 and 90 is the dot the site reads out as "Safe 10% · Fast 0% · Easy 90%".
 */
public final class TriangleDot
{
	/** The most a share can be, the settings' range. */
	public static final int MAX_SHARE = 100;

	private final int safe;
	private final int fast;
	private final int easy;

	private TriangleDot(int safe, int fast, int easy)
	{
		this.safe = safe;
		this.fast = fast;
		this.easy = easy;
	}

	/**
	 * The dot of three shares, each kept within 0 and MAX_SHARE; null when none is above 0, which places no dot, so that
	 * the site keeps its own.
	 */
	public static TriangleDot of(int safe, int fast, int easy)
	{
		int s = share(safe);
		int f = share(fast);
		int e = share(easy);
		return s + f + e == 0 ? null : new TriangleDot(s, f, e);
	}

	private static int share(int value)
	{
		return Math.max(0, Math.min(MAX_SHARE, value));
	}

	public int getSafe()
	{
		return safe;
	}

	public int getFast()
	{
		return fast;
	}

	public int getEasy()
	{
		return easy;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof TriangleDot))
		{
			return false;
		}
		TriangleDot d = (TriangleDot) o;
		return safe == d.safe && fast == d.fast && easy == d.easy;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(safe, fast, easy);
	}

	@Override
	public String toString()
	{
		return "Safe " + safe + " · Fast " + fast + " · Easy " + easy;
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The two plain clocks. The tick counter runs on every game tick in the arena from the moment it is first seen there,
 * and only the player's hotkey resets it; counting up, the modifier confirmation also resets it to 0. The wave timer is
 * real time, in seconds, from the player's modifier confirmation to the wave's completion. Nothing here knows an
 * NPC's timing, a spawn tick or a plan; each number has exactly the same meaning and appearance.
 */
public final class WaveClock
{
	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	private static final Pattern COMPLETE = Pattern.compile("Wave (\\d+) completed!");
	private int wave;
	private long startMillis;
	private long endMillis = -1;
	private boolean running;
	private boolean sol;
	private int resetTick = -1;
	private int now = -1;
	private volatile View view = View.HIDDEN;

	/**
	 * A modifier was confirmed on this tick, at this time: the wave timer starts again. Counting up, the tick counter
	 * restarts at 0 too; a loop keeps its own origin, which only the player's hotkey moves.
	 */
	public void onModifierChosen(int number, int tick, long millis, boolean resetCounter)
	{
		sol = number > ColosseumTracker.LAST_WAVE;
		running = false;
		wave = 0;
		endMillis = -1;
		// Sol Heredit's wave is timed too, for a player who keeps the clocks there (View.timerVisible's `quiet`).
		if (number >= 1)
		{
			wave = number;
			startMillis = millis;
			running = true;
		}
		if (resetCounter)
		{
			resetTick = tick;
			now = Math.max(now, tick);
		}
		publish();
	}

	/** Each game tick in the arena. The first one starts the tick counter, with no press or pick needed. */
	public void onTick(int tick)
	{
		if (resetTick < 0)
		{
			resetTick = tick;
		}
		now = Math.max(now, tick);
		publish();
	}

	/**
	 * The player's hotkey: counting up, the counter shows 0 now and 1 on the next tick; looping, the next tick is 1.
	 * Picks, spawns and wave starts never call this.
	 */
	public void resetCounter(int tick)
	{
		resetTick = tick;
		now = Math.max(now, tick);
		publish();
	}

	/** The game's completion message freezes the wave timer. The tick counter goes on. */
	public void onGameMessage(String message, long millis)
	{
		Matcher completed = COMPLETE.matcher(TAG.matcher(message).replaceAll(""));
		if (running && completed.find() && Integer.parseInt(completed.group(1)) == wave)
		{
			running = false;
			endMillis = millis;
			publish();
		}
	}

	/**
	 * A wave's start message. Sol Heredit's wave hides both clocks, unless Quiet on Sol Heredit's wave is off. A wave whose pick the plugin missed, as when it was
	 * switched on mid-run, starts its timer here instead, so the timer is never left blank for a whole wave.
	 */
	public void onWaveStarted(int number, long millis)
	{
		sol = number > ColosseumTracker.LAST_WAVE;
		if (number != wave)
		{
			wave = number;
			startMillis = millis;
			endMillis = -1;
			running = true;
		}
		publish();
	}

	/** Leaving the arena, hopping, logging out or disabling the plugin forgets both clocks. */
	public void clear()
	{
		wave = 0;
		startMillis = 0;
		endMillis = -1;
		running = false;
		sol = false;
		resetTick = -1;
		now = -1;
		view = View.HIDDEN;
	}

	/** An immutable snapshot for the overlay renderer, which must not read a count half way through an event. */
	public View view()
	{
		return view;
	}

	private void publish()
	{
		view = new View(wave, running, startMillis, endMillis, resetTick < 0 ? -1 : now - resetTick, sol);
	}

	/** The facts an overlay may draw, with no timing marks or changes of colour. */
	public static final class View
	{
		public static final View HIDDEN = new View(0, false, 0, -1, -1, false);
		public final int wave;
		public final boolean running;
		private final long startMillis;
		private final long endMillis;
		/** Ticks since the counter's last reset, or -1 while it is hidden. */
		public final int ticks;
		private final boolean sol;

		private View(int wave, boolean running, long startMillis, long endMillis, int ticks, boolean sol)
		{
			this.wave = wave;
			this.running = running;
			this.startMillis = startMillis;
			this.endMillis = endMillis;
			this.ticks = ticks;
			this.sol = sol;
		}

		/** The tick counter shows in the arena from its first tick, but never on Sol Heredit's wave. */
		public boolean counterVisible()
		{
			return counterVisible(true);
		}

		/**
		 * The tick counter shows in the arena from its first tick; on Sol Heredit's wave only with `quiet` off (Quiet on
		 * Sol Heredit's wave, idea 362).
		 */
		public boolean counterVisible(boolean quiet)
		{
			return ticks >= 0 && !(sol && quiet);
		}

		/** The wave timer shows from a pick or a wave's start, waves 1 to 11. */
		public boolean timerVisible()
		{
			return timerVisible(true);
		}

		/** The wave timer shows from a pick or a wave's start, waves 1 to 11, and on Sol Heredit's with `quiet` off. */
		public boolean timerVisible(boolean quiet)
		{
			return wave >= 1 && (wave <= ColosseumTracker.LAST_WAVE || !quiet);
		}

		public String title()
		{
			return "Wave " + wave + (running ? "" : " done");
		}

		public String up()
		{
			return Integer.toString(Math.max(0, ticks));
		}

		/**
		 * 1 to the length and round again, the tick after a reset being 1. A length outside the setting's limits is
		 * bounded first, including imported configurations.
		 */
		public String loop(int length)
		{
			return Integer.toString(loopPosition(length));
		}

		/** The loop's position, 1 to the bounded length, which picks the position's colour when colours are on. */
		public int loopPosition(int length)
		{
			int bounded = Math.max(2, Math.min(10, length));
			return Math.floorMod(ticks - 1, bounded) + 1;
		}

		/** Whole seconds of real time, as m:ss, or h:mm:ss from an hour; frozen at the wave's completion. */
		public String time(long nowMillis)
		{
			long seconds = Math.max(0, ((endMillis >= 0 ? endMillis : nowMillis) - startMillis) / 1000);
			long hours = seconds / 3600;
			long minutes = seconds / 60 % 60;
			String ss = (seconds % 60 < 10 ? "0" : "") + seconds % 60;
			return hours > 0 ? hours + ":" + (minutes < 10 ? "0" : "") + minutes + ":" + ss : minutes + ":" + ss;
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Supplier;

/**
 * A tick-by-tick record of one wave as the player played it, for the site's wave reviewer to replay; WaveLogWriter turns
 * it into JSON. It only reads and exports: nothing here is drawn in the game.
 *
 * The RuneLite layer starts it on the first tick of a wave the tracker saw start, feeds it every hitsplat as it comes, each
 * projectile as it first sees it, and one snapshot of the player, the arena's NPCs and the game's Colosseum counters
 * (ColosseumCounter) each game tick, and finishes it when the wave is completed or the player
 * leaves. The log is kept after that, so that the player can copy it once the wave is over. When the next wave starts,
 * the finished log is kept among the past ones, its JSON written the first time it is asked for (snapshot), so that any
 * wave since the plugin started can still be copied and reviewed, up to MAX_PAST of them. Nothing is written on the
 * wave's first tick, the one tick a player least wants a hitch on, and a log that is written may be written on another
 * thread than the client's, as a snapshot never changes. It holds at most MAX_TICKS ticks, so that a wave left running cannot
 * fill the memory; past that it says it was cut.
 *
 * The animation ids are logged as the game gives them, unfiltered: they are how each NPC's attack animation will be
 * confirmed (an open question in the design spec), so nothing here decides which of them matter.
 */
public final class WaveLog
{
	/** The most ticks a log holds: 15 minutes, far longer than a wave lasts. */
	public static final int MAX_TICKS = 1500;

	/** The most past waves kept besides the one under way: two whole runs. As JSON, each is at most a few hundred kB. */
	public static final int MAX_PAST = 24;

	/** An actor's target when it is interacting with nothing. */
	public static final int TARGET_NONE = -1;
	/** An actor's target when it is interacting with a player, which in the Colosseum is the player themself. */
	public static final int TARGET_PLAYER = -2;

	/** How a wave's log ended: with the game's "Wave N completed!", or with the player leaving the arena. */
	public enum End
	{
		COMPLETED("completed"),
		LEFT("left");

		private final String key;

		End(String key)
		{
			this.key = key;
		}

		/** Its name in the log's JSON. */
		public String getKey()
		{
			return key;
		}
	}

	/** A hitsplat: its amount and the game's hitsplat type id, unfiltered. */
	public static final class Hit
	{
		private final int amount;
		private final int type;

		public Hit(int amount, int type)
		{
			this.amount = amount;
			this.type = type;
		}

		public int getAmount()
		{
			return amount;
		}

		public int getType()
		{
			return type;
		}
	}

	/** The player on one tick. */
	public static final class PlayerTick
	{
		private final GridTile tile;
		private final int hitpoints;
		private final int prayerPoints;
		private final List<String> prayers;
		private final int animation;
		private final int target;
		private final int[] worn;

		/** The player without their gear, as when "Include gear and stats" is off. */
		public PlayerTick(GridTile tile, int hitpoints, int prayerPoints, List<String> prayers, int animation, int target)
		{
			this(tile, hitpoints, prayerPoints, prayers, animation, target, null);
		}

		/**
		 * `tile` is null when the player is off the grid; `prayers` names the prayers on, as prayerName gives them;
		 * `animation` is the game's id, -1 for none; `target` is an NPC's index, TARGET_PLAYER or TARGET_NONE; `worn` is the
		 * item id in each of the link's gear slots, in its order (WORN_SLOTS), -1 for an empty one, or null to leave the gear
		 * out.
		 */
		public PlayerTick(GridTile tile, int hitpoints, int prayerPoints, List<String> prayers, int animation, int target, int[] worn)
		{
			this.tile = tile;
			this.hitpoints = hitpoints;
			this.prayerPoints = prayerPoints;
			this.prayers = Collections.unmodifiableList(new ArrayList<>(prayers));
			this.animation = animation;
			this.target = target;
			this.worn = worn == null ? null : worn.clone();
		}

		public GridTile getTile()
		{
			return tile;
		}

		public int getHitpoints()
		{
			return hitpoints;
		}

		public int getPrayerPoints()
		{
			return prayerPoints;
		}

		public List<String> getPrayers()
		{
			return prayers;
		}

		public int getAnimation()
		{
			return animation;
		}

		public int getTarget()
		{
			return target;
		}

		/** The item ids worn, slot by slot in WORN_SLOTS' order, or null when the gear is left out. */
		public int[] getWorn()
		{
			return worn == null ? null : worn.clone();
		}
	}

	/** An NPC on one tick, any NPC in the arena by its raw id: the waves' NPCs, the frems, Solarflare's orbs and the rest. */
	public static final class NpcTick
	{
		private final int index;
		private final int npcId;
		private final GridTile tile;
		private final int animation;
		private final int healthRatio;
		private final int healthScale;
		private final int target;
		private final int[] spotAnims;

		/** An NPC that shows no graphics. */
		public NpcTick(int index, int npcId, GridTile tile, int animation, int healthRatio, int healthScale, int target)
		{
			this(index, npcId, tile, animation, healthRatio, healthScale, target, new int[0]);
		}

		/**
		 * `tile` is its south-west tile; `animation` is the game's id, -1 for none; the health ratio and scale are as the
		 * game gives them, -1 when unknown; `target` is an NPC's index, TARGET_PLAYER or TARGET_NONE; `spotAnims` are the
		 * ids of the graphics it shows, such as a Manticore's orbs, unfiltered.
		 */
		public NpcTick(int index, int npcId, GridTile tile, int animation, int healthRatio, int healthScale, int target, int[] spotAnims)
		{
			this.index = index;
			this.npcId = npcId;
			this.tile = tile;
			this.animation = animation;
			this.healthRatio = healthRatio;
			this.healthScale = healthScale;
			this.target = target;
			this.spotAnims = spotAnims.clone();
		}

		public int getIndex()
		{
			return index;
		}

		public int getNpcId()
		{
			return npcId;
		}

		public GridTile getTile()
		{
			return tile;
		}

		public int getAnimation()
		{
			return animation;
		}

		public int getHealthRatio()
		{
			return healthRatio;
		}

		public int getHealthScale()
		{
			return healthScale;
		}

		public int getTarget()
		{
			return target;
		}

		/** The ids of the graphics it shows on the tick. */
		public int[] getSpotAnims()
		{
			return spotAnims.clone();
		}
	}

	/**
	 * A projectile the game showed, as the RuneLite layer first saw it: its graphic's id, where it flies from and to, and
	 * when it sets off and lands. Each end is an actor, an NPC by its index or TARGET_PLAYER, or, where the projectile has
	 * no actor at that end, such as a Javelin Colossus's special aimed at a tile, TARGET_NONE with the tile it flies from
	 * or to (null off the grid). Like the animations, the ids are logged as the game gives them, unfiltered.
	 */
	public static final class Projectile
	{
		private final int id;
		private final int from;
		private final GridTile fromTile;
		private final int to;
		private final GridTile toTile;
		private final int start;
		private final int end;

		/**
		 * `start` and `end` are the client cycles (20 ms, 30 to a game tick) from the tick it is logged on to when it sets
		 * off and when it lands: below 0 for one that set off before that tick, as one first seen a tick late may have.
		 * A tile is only kept for an end with no actor.
		 */
		public Projectile(int id, int from, GridTile fromTile, int to, GridTile toTile, int start, int end)
		{
			this.id = id;
			this.from = from;
			this.fromTile = from == TARGET_NONE ? fromTile : null;
			this.to = to;
			this.toTile = to == TARGET_NONE ? toTile : null;
			this.start = start;
			this.end = end;
		}

		public int getId()
		{
			return id;
		}

		/** The actor it flies from: an NPC's index, TARGET_PLAYER, or TARGET_NONE when it has none. */
		public int getFrom()
		{
			return from;
		}

		/** The tile it flies from when it has no actor there, or null. */
		public GridTile getFromTile()
		{
			return fromTile;
		}

		/** The actor it flies to: an NPC's index, TARGET_PLAYER, or TARGET_NONE when it has none. */
		public int getTo()
		{
			return to;
		}

		/** The tile it flies to when it has no actor there, or null. */
		public GridTile getToTile()
		{
			return toTile;
		}

		public int getStart()
		{
			return start;
		}

		public int getEnd()
		{
			return end;
		}

		/** Whether either end says where it is: an actor, or a tile on the grid. */
		boolean isPlaced()
		{
			return from != TARGET_NONE || to != TARGET_NONE || (fromTile != null && ArenaGeometry.onGrid(fromTile))
				|| (toTile != null && ArenaGeometry.onGrid(toTile));
		}
	}

	/**
	 * A past wave's log, kept as its JSON once the next wave started, with the state links' payloads on its first tick and
	 * on the tick its reinforcements came, the glory it earned, and whether the player died in it. getRun and getRuns give the wave under way or the last
	 * one the same way, its JSON written when it is asked for, so that the panel can list the waves every tick without
	 * writing any. A wave saved in an earlier session (WaveStore) comes back as one too, its JSON read with it.
	 */
	public static final class Past
	{
		private final int id;
		private final int wave;
		private final int size;
		private final End end;
		private final boolean recording;
		private final Supplier<String> json;
		private final String startState;
		private final String reinforcementState;
		private final Integer glory;
		private final boolean died;

		Past(int id, int wave, int size, End end, boolean recording, Supplier<String> json, String startState, String reinforcementState,
			Integer glory)
		{
			this(id, wave, size, end, recording, json, startState, reinforcementState, glory, false);
		}

		Past(int id, int wave, int size, End end, boolean recording, Supplier<String> json, String startState, String reinforcementState,
			Integer glory, boolean died)
		{
			this.id = id;
			this.wave = wave;
			this.size = size;
			this.end = end;
			this.recording = recording;
			this.json = json;
			this.startState = startState;
			this.reinforcementState = reinforcementState;
			this.glory = glory;
			this.died = died;
		}

		/** The same wave under the id `newId`, as WaveLog.restore gives a saved one. */
		Past withId(int newId)
		{
			return new Past(newId, wave, size, end, recording, json, startState, reinforcementState, glory, died);
		}

		/** The log's id, as getId gave it while it was the one under way. */
		public int getId()
		{
			return id;
		}

		public int getWave()
		{
			return wave;
		}

		/** How many ticks it holds. */
		public int size()
		{
			return size;
		}

		/** How the wave ended, or null when the next wave started before its end was seen. */
		public End getEnd()
		{
			return end;
		}

		/** Whether this is the wave under way, still recording. */
		public boolean isRecording()
		{
			return recording;
		}

		/** The log as WaveLogWriter wrote it. */
		public String getJson()
		{
			return json.get();
		}

		/** The state link's payload on the wave's first tick (StatePayload.toJson), or null when it could not be taken. */
		public String getStartState()
		{
			return startState;
		}

		/** The state link's payload on the tick the wave's reinforcements came, or null when they were not seen to come. */
		public String getReinforcementState()
		{
			return reinforcementState;
		}

		/** The glory the wave earned, by the game's own counter (WaveLog.getGlory), or null when that is not known. */
		public Integer getGlory()
		{
			return glory;
		}

		/**
		 * Whether the player died in the wave: a tick recorded with no hitpoints. The log ends a death as LEFT, as it does
		 * leaving, so that Past waves can tell the two apart only by this (the UX review of 2026-10-27, F6).
		 */
		public boolean isDied()
		{
			return died;
		}
	}

	/**
	 * One tick of the wave: the player, the NPCs, the hitsplats that came with it, Solarflare's orbs, and the rest that
	 * came since the tick before.
	 */
	static final class Tick
	{
		final int t;
		final PlayerTick player;
		final List<Hit> playerHits;
		final List<NpcTick> npcs;
		/** The hitsplats on NPCs, by NPC index, in the order they came. */
		final Map<Integer, List<Hit>> npcHits;
		final List<GridTile> orbs;
		/**
		 * The animations NPCs started since the last tick, [index, animation id] each, in the order they came. Unlike the
		 * animation an NPC shows on a tick, these mark each start, an attack that repeats the one before included, which
		 * is what times the NPCs' attacks.
		 */
		final List<int[]> animations;
		/** The animations the player started since the last tick, in the order they came: each attack, a repeat included. */
		final List<Integer> playerAnimations;
		/** The item ids worn, on the wave's first tick and on each tick the gear changed; null on the others. */
		final int[] worn;
		/** The graphics the game put on the grid's tiles since the last tick, [x, y, graphic id] each, in the order they came. */
		final List<int[]> tileGraphics;
		/** The projectiles first seen since the last tick, in the order they were seen. */
		final List<Projectile> projectiles;
		/** The game's counters (ColosseumCounter) that changed since the last tick, every one on the wave's first tick. */
		final Map<ColosseumCounter, Integer> counters;

		/** A tick with no projectiles and no counters, as a test builds one. */
		Tick(int t, PlayerTick player, List<Hit> playerHits, List<NpcTick> npcs, Map<Integer, List<Hit>> npcHits, List<GridTile> orbs,
			List<int[]> animations, List<Integer> playerAnimations, int[] worn, List<int[]> tileGraphics)
		{
			this(t, player, playerHits, npcs, npcHits, orbs, animations, playerAnimations, worn, tileGraphics, Collections.<Projectile>emptyList(),
				Collections.<ColosseumCounter, Integer>emptyMap());
		}

		Tick(int t, PlayerTick player, List<Hit> playerHits, List<NpcTick> npcs, Map<Integer, List<Hit>> npcHits, List<GridTile> orbs,
			List<int[]> animations, List<Integer> playerAnimations, int[] worn, List<int[]> tileGraphics, List<Projectile> projectiles,
			Map<ColosseumCounter, Integer> counters)
		{
			this.t = t;
			this.player = player;
			this.playerHits = playerHits;
			this.npcs = npcs;
			this.npcHits = npcHits;
			this.orbs = orbs;
			this.animations = animations;
			this.playerAnimations = playerAnimations;
			this.worn = worn;
			this.tileGraphics = tileGraphics;
			this.projectiles = projectiles;
			this.counters = counters;
		}
	}

	/** The gear slots `worn` lists, in its order: those the state link names (Equipment), not the player's look. */
	public static final List<String> WORN_SLOTS = Collections.unmodifiableList(Arrays.asList(
		"head", "cape", "amulet", "weapon", "body", "shield", "legs", "gloves", "boots", "ring", "ammo"));

	private Integer wave;
	private int startTick;
	private Map<Modifier, Integer> modifiers = new EnumMap<>(Modifier.class);
	private boolean modifiersComplete;
	private String version = "";
	/** The state link's payload on the wave's first tick, as StatePayload wrote it, or null when it could not be taken. */
	private String startState;
	/**
	 * The same payload with the gear's levels left out (Equipment.withoutLevels), for the log the player shares
	 * (WaveLogWriter.toShare), or null when it could not be taken.
	 */
	private String shareState;
	/** The state link's payload on the tick the reinforcements came, or null before then. */
	private String reinforcementState;
	private final List<Tick> ticks = new ArrayList<>();
	private boolean cut;
	private End end;
	private boolean recording;
	/** The log's id, which tells it apart from the past ones, and the last id given. */
	private int id;
	private int lastId;
	/** The past waves' logs, newest first. */
	private final List<Past> past = new ArrayList<>();
	/** The gear worn on the last tick recorded, so that a tick lists it only when it changed. */
	private int[] lastWorn;
	/** The game's counters on the last tick recorded, so that a tick lists only those that changed; null before the first. */
	private int[] lastCounters;
	/** The game's glory counter on the first tick recorded that read it, null before then, and on the last. */
	private Integer firstGlory;
	private int lastGlory;
	/** Whether a tick recorded had the player with no hitpoints: a death, which ends the log as LEFT. */
	private boolean died;

	/** The hitsplats since the last tick was recorded, which go in the next one. */
	private final List<Hit> pendingPlayerHits = new ArrayList<>();
	private final Map<Integer, List<Hit>> pendingNpcHits = new LinkedHashMap<>();
	/** The animations NPCs started since the last tick was recorded, which go in the next one. */
	private final List<int[]> pendingAnimations = new ArrayList<>();
	/** The animations the player started since the last tick was recorded. */
	private final List<Integer> pendingPlayerAnimations = new ArrayList<>();
	/** The graphics put on tiles since the last tick was recorded. */
	private final List<int[]> pendingTileGraphics = new ArrayList<>();
	/** The projectiles first seen since the last tick was recorded. */
	private final List<Projectile> pendingProjectiles = new ArrayList<>();

	/**
	 * A wave starts on game tick `gameTick`: the last wave's log goes among the past ones, and the log records this one.
	 * `startState` is the state link's payload on this tick (StatePayload.toJson), or null. The hitsplats already passed on
	 * this tick are kept for it.
	 */
	public void start(int wave, int gameTick, Map<Modifier, Integer> modifiers, boolean modifiersComplete, String version, String startState)
	{
		start(wave, gameTick, modifiers, modifiersComplete, version, startState, startState);
	}

	/**
	 * A wave starts, as start above, with `shareState` the state link's payload on this tick without the gear's levels, for
	 * the log the player shares, or null.
	 */
	public void start(int wave, int gameTick, Map<Modifier, Integer> modifiers, boolean modifiersComplete, String version, String startState,
		String shareState)
	{
		if (this.wave != null)
		{
			WaveLog done = snapshot();
			past.add(0, new Past(id, this.wave, ticks.size(), end, false, once(() -> WaveLogWriter.toJson(done)), this.startState, reinforcementState,
				getGlory(), died));
			while (past.size() > MAX_PAST)
			{
				past.remove(past.size() - 1);
			}
		}
		this.wave = wave;
		this.startTick = gameTick;
		this.modifiers = new EnumMap<>(Modifier.class);
		this.modifiers.putAll(modifiers);
		this.modifiersComplete = modifiersComplete;
		this.version = version;
		this.startState = startState;
		this.shareState = shareState;
		reinforcementState = null;
		ticks.clear();
		cut = false;
		end = null;
		recording = true;
		id = ++lastId;
		lastWorn = null;
		lastCounters = null;
		firstGlory = null;
		lastGlory = 0;
		died = false;
	}

	/** A hitsplat on the player, as it comes; it goes in the next tick recorded. */
	public void onPlayerHit(int amount, int type)
	{
		pendingPlayerHits.add(new Hit(amount, type));
	}

	/** A hitsplat on the NPC at `index`, as it comes; it goes in the next tick recorded. */
	public void onNpcHit(int index, int amount, int type)
	{
		pendingNpcHits.computeIfAbsent(index, i -> new ArrayList<>()).add(new Hit(amount, type));
	}

	/** An NPC started an animation, as it comes; it goes in the next tick recorded. */
	public void onNpcAnimation(int index, int animation)
	{
		pendingAnimations.add(new int[] {index, animation});
	}

	/** The player started an animation, as it comes; it goes in the next tick recorded. */
	public void onPlayerAnimation(int animation)
	{
		pendingPlayerAnimations.add(animation);
	}

	/**
	 * The game put a graphic on a tile, such as where a Javelin Colossus's special lands, as it comes; it goes in the next
	 * tick recorded. One off the grid, or with no tile, is left out.
	 */
	public void onTileGraphic(GridTile tile, int graphic)
	{
		if (tile != null && ArenaGeometry.onGrid(tile))
		{
			pendingTileGraphics.add(new int[] {tile.getX(), tile.getY(), graphic});
		}
	}

	/**
	 * A projectile the RuneLite layer saw for the first time, as it comes; it goes in the next tick recorded. One with
	 * neither an actor nor a tile on the grid at either end is left out.
	 */
	public void onProjectile(Projectile projectile)
	{
		if (projectile.isPlaced())
		{
			pendingProjectiles.add(projectile);
		}
	}

	/**
	 * Game tick `gameTick` of the wave: the player and every NPC the game shows. NPCs off the grid are left out, and the
	 * tiles of Solarflare's orbs are taken from the orb NPCs. The player's gear is kept for the tick only when it changed
	 * since the tick before. A tick already recorded, or one past MAX_TICKS, is passed over; either way the hitsplats since
	 * the last tick are used up.
	 */
	public void record(int gameTick, PlayerTick player, List<NpcTick> npcs)
	{
		record(gameTick, player, npcs, null);
	}

	/**
	 * Game tick `gameTick` of the wave, as record above, with `counters` the game's counters on it, one for each
	 * ColosseumCounter in its order, or null when they could not be read. The tick keeps those that changed since the tick
	 * before, and every one on the wave's first tick.
	 */
	public void record(int gameTick, PlayerTick player, List<NpcTick> npcs, int[] counters)
	{
		if (!recording)
		{
			discardPending();
			return;
		}
		int t = gameTick - startTick;
		if (!ticks.isEmpty() && ticks.get(ticks.size() - 1).t >= t)
		{
			discardPending();
			return;
		}
		if (ticks.size() >= MAX_TICKS)
		{
			cut = true;
			discardPending();
			return;
		}
		List<NpcTick> onGrid = new ArrayList<>();
		List<GridTile> orbs = new ArrayList<>();
		for (NpcTick n : npcs)
		{
			if (n.getTile() == null || !ArenaGeometry.onGrid(n.getTile()))
			{
				continue;
			}
			onGrid.add(n);
			if (n.getNpcId() == NpcKind.SOLARFLARE_ORB_ID)
			{
				orbs.add(n.getTile());
			}
		}
		Map<Integer, List<Hit>> npcHits = new LinkedHashMap<>();
		for (Map.Entry<Integer, List<Hit>> e : pendingNpcHits.entrySet())
		{
			npcHits.put(e.getKey(), Collections.unmodifiableList(new ArrayList<>(e.getValue())));
		}
		int[] worn = player == null ? null : player.getWorn();
		int[] changed = worn != null && !Arrays.equals(worn, lastWorn) ? worn : null;
		if (worn != null)
		{
			lastWorn = worn;
		}
		Map<ColosseumCounter, Integer> changedCounters = new EnumMap<>(ColosseumCounter.class);
		if (counters != null && counters.length == ColosseumCounter.values().length)
		{
			for (ColosseumCounter c : ColosseumCounter.values())
			{
				int value = counters[c.ordinal()];
				if (lastCounters == null || lastCounters[c.ordinal()] != value)
				{
					changedCounters.put(c, value);
				}
			}
			lastCounters = counters.clone();
			int glory = counters[ColosseumCounter.CURRENT_GLORY.ordinal()];
			if (firstGlory == null)
			{
				firstGlory = glory;
			}
			lastGlory = glory;
		}
		if (player != null && player.getHitpoints() == 0)
		{
			died = true;
		}
		ticks.add(new Tick(t, player, Collections.unmodifiableList(new ArrayList<>(pendingPlayerHits)), Collections.unmodifiableList(onGrid),
			Collections.unmodifiableMap(npcHits), Collections.unmodifiableList(orbs), Collections.unmodifiableList(new ArrayList<>(pendingAnimations)),
			Collections.unmodifiableList(new ArrayList<>(pendingPlayerAnimations)), changed, Collections.unmodifiableList(new ArrayList<>(pendingTileGraphics)),
			Collections.unmodifiableList(new ArrayList<>(pendingProjectiles)), Collections.unmodifiableMap(changedCounters)));
		discardPending();
	}

	/**
	 * Forget the hitsplats and the rest since the last tick: the RuneLite layer calls this on each tick it does not
	 * record.
	 */
	public void discardPending()
	{
		pendingPlayerHits.clear();
		pendingNpcHits.clear();
		pendingAnimations.clear();
		pendingPlayerAnimations.clear();
		pendingTileGraphics.clear();
		pendingProjectiles.clear();
	}

	/** The wave ended: the log stops recording and is kept until the next wave starts. */
	public void finish(End how)
	{
		if (recording)
		{
			recording = false;
			end = how;
		}
		discardPending();
	}

	/** Forget the log and the past ones altogether: the plugin or its log was switched off. */
	public void clear()
	{
		wave = null;
		ticks.clear();
		cut = false;
		end = null;
		recording = false;
		modifiers = new EnumMap<>(Modifier.class);
		modifiersComplete = false;
		version = "";
		startState = null;
		shareState = null;
		reinforcementState = null;
		id = 0;
		lastWorn = null;
		lastCounters = null;
		firstGlory = null;
		lastGlory = 0;
		died = false;
		past.clear();
		discardPending();
	}

	/**
	 * The wave's reinforcements came on this tick: `state` is the state link's payload on it (StatePayload.toJson), which
	 * the panel opens on the site. Only the first is kept, while the wave records.
	 */
	public void reinforcementsCame(String state)
	{
		if (recording && reinforcementState == null)
		{
			reinforcementState = state;
		}
	}

	/** Whether the reinforcements' state was taken this wave. */
	public boolean hasReinforcementState()
	{
		return reinforcementState != null;
	}

	/** Whether a wave is being recorded. */
	public boolean isRecording()
	{
		return recording;
	}

	/** Whether there is a log to copy: a wave was started, while recording or after. */
	public boolean hasLog()
	{
		return wave != null;
	}

	/** The log's id, given when its wave started, or 0 when there is none. */
	public int getId()
	{
		return id;
	}

	/** The past waves' logs, newest first. */
	public List<Past> getPast()
	{
		return Collections.unmodifiableList(past);
	}

	/**
	 * The newest run's logs, oldest first, for RunLogWriter: the newest log, the wave under way or the last one, and going
	 * back from it each log whose wave is the one before the wave of the log after it. The run starts at wave 1, which has
	 * no wave before it, so that it never reaches back into the run before; or, when the plugin did not log the run from
	 * wave 1, such as when it started mid-run, at the oldest wave of the series it logged. A wave missing from the series
	 * or logged twice parts it there, and the run is the newer part. How a wave ended does not part a run: the next run
	 * starts at wave 1 again, which parts the two already. The past waves kept, MAX_PAST, are more than a run's 12 waves
	 * (wave 12 is Sol Heredit's), so that a run is always whole. Each log is as Copy wave log copies it: a past one as
	 * its JSON, and the newest as WaveLogWriter writes it now. Empty when there is no log.
	 */
	public List<Past> getRun()
	{
		List<List<Past>> runs = getRuns();
		return runs.isEmpty() ? Collections.<Past>emptyList() : runs.get(0);
	}

	/**
	 * Every run logged, newest first, each its logs oldest first: the newest is getRun's, and each run before it is
	 * parted from the next the same way, where a log's wave is not the one before the wave of the log after it. The
	 * wave under way or the last one comes as it is now (snapshot), its JSON written when it is asked for, and the waves
	 * restored from an earlier session after this session's. Empty when there is no log, past or present.
	 */
	public List<List<Past>> getRuns()
	{
		List<Past> newestFirst = new ArrayList<>();
		if (wave != null)
		{
			newestFirst.add(current());
		}
		newestFirst.addAll(past);
		List<List<Past>> runs = new ArrayList<>();
		List<Past> run = new ArrayList<>();
		for (Past p : newestFirst)
		{
			if (!run.isEmpty() && p.getWave() != run.get(0).getWave() - 1)
			{
				runs.add(Collections.unmodifiableList(run));
				run = new ArrayList<>();
			}
			run.add(0, p);
		}
		if (!run.isEmpty())
		{
			runs.add(Collections.unmodifiableList(run));
		}
		return Collections.unmodifiableList(runs);
	}

	/**
	 * The wave under way or the last one as a Past, as it is now (snapshot), its JSON written when it is asked for, on
	 * any thread: what getRuns lists first, and what the plugin saves as the wave ends (WaveStore). Null when there is no
	 * log.
	 */
	public Past current()
	{
		if (wave == null)
		{
			return null;
		}
		WaveLog now = snapshot();
		return new Past(id, wave, ticks.size(), end, recording, once(() -> WaveLogWriter.toJson(now)), startState, reinforcementState,
			getGlory(), died);
	}

	/**
	 * Waves saved in an earlier session (WaveStore), newest first, go behind the past ones, each under a new id, so that
	 * Past waves lists them as it lists this session's: getRuns parts them into runs the same way. Those past MAX_PAST
	 * are let go.
	 */
	public void restore(List<Past> saved)
	{
		for (Past p : saved)
		{
			if (past.size() >= MAX_PAST)
			{
				break;
			}
			past.add(p.withId(++lastId));
		}
	}

	/**
	 * The glory the wave earned by the game's own counter, COLOSSEUM_CURRENT_GLORY: what it read on the last tick
	 * recorded less what it read on the first, which matched the site's sums by the game's rules on every wave finished
	 * in the user's shared runs of 25 and 26 October (the site's test/viewer/runGlory.test.ts). Only for a wave completed:
	 * a wave the player died in or left earns none, and one under way has not earned its yet. Null too when the counter
	 * could not be read.
	 */
	public Integer getGlory()
	{
		return end == End.COMPLETED && firstGlory != null ? lastGlory - firstGlory : null;
	}

	/**
	 * The log as it is now, which records nothing more: what WaveLogWriter writes of it, copied, so that its JSON can be
	 * written later, on any thread, while this log goes on. The ticks themselves never change once recorded, so only
	 * their list is copied.
	 */
	public WaveLog snapshot()
	{
		WaveLog copy = new WaveLog();
		copy.wave = wave;
		copy.startTick = startTick;
		copy.modifiers = new EnumMap<>(Modifier.class);
		copy.modifiers.putAll(modifiers);
		copy.modifiersComplete = modifiersComplete;
		copy.version = version;
		copy.startState = startState;
		copy.shareState = shareState;
		copy.reinforcementState = reinforcementState;
		copy.ticks.addAll(ticks);
		copy.cut = cut;
		copy.end = end;
		copy.id = id;
		copy.lastId = lastId;
		copy.firstGlory = firstGlory;
		copy.lastGlory = lastGlory;
		copy.died = died;
		return copy;
	}

	/**
	 * `make`'s text, made the first time it is asked for and kept: a log's JSON, which may be asked for on the client
	 * thread or on OkHttp's, hence the lock. Once made, `make` is let go, and with it the snapshot it writes.
	 */
	static Supplier<String> once(Supplier<String> make)
	{
		return new Supplier<String>()
		{
			private Supplier<String> maker = make;
			private String text;

			@Override
			public synchronized String get()
			{
				if (text == null)
				{
					text = maker.get();
					maker = null;
				}
				return text;
			}
		};
	}

	/** The wave logged, or null when there is none. */
	public Integer getWave()
	{
		return wave;
	}

	/** How many ticks the log holds. */
	public int size()
	{
		return ticks.size();
	}

	/** Whether ticks were left out because the log was full. */
	public boolean isCut()
	{
		return cut;
	}

	/** How the wave ended, or null while it is under way or when the log was never finished. */
	public End getEnd()
	{
		return end;
	}

	Map<Modifier, Integer> getModifiers()
	{
		return Collections.unmodifiableMap(modifiers);
	}

	boolean isModifiersComplete()
	{
		return modifiersComplete;
	}

	String getVersion()
	{
		return version;
	}

	String getStartState()
	{
		return startState;
	}

	String getShareState()
	{
		return shareState;
	}

	/** The state link's payload on the tick the reinforcements came, or null before then. */
	public String getReinforcementState()
	{
		return reinforcementState;
	}

	List<Tick> getTicks()
	{
		return Collections.unmodifiableList(ticks);
	}

	/**
	 * A prayer's name in the log, from the name of RuneLite's Prayer constant: the three protection prayers are "magic",
	 * "ranged" and "melee", as the site names them, and every other prayer is its constant's name in lower case, such as
	 * "piety" or "rp_ancient_strength".
	 */
	public static String prayerName(String prayerConstant)
	{
		switch (prayerConstant)
		{
			case "PROTECT_FROM_MAGIC":
				return "magic";
			case "PROTECT_FROM_MISSILES":
				return "ranged";
			case "PROTECT_FROM_MELEE":
				return "melee";
			default:
				return prayerConstant.toLowerCase(Locale.ROOT);
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The wave log's JSON, for the site's log checker (src/viewer/waveLogCheck.ts). Like StatePayload it is written by
 * hand, ASCII only and in a fixed order, so that a log always gives the same text and the tests can compare it whole;
 * each tick is on a line of its own, so that a log reads and diffs a tick at a time.
 *
 * <pre>
 * {"v":1,"kind":"solSurvivorWaveLog","plugin":"0.2.0","wave":4,
 *  "modifiers":{"reentry":2,"quartet":"random"},"modifiersComplete":true,
 *  "maxTicks":1500,"cut":false,"end":"completed","start":{"v":1,"setup":{...}},"ticks":[
 * {"t":0,"player":[7,15,99,77,["magic","piety"],-1,null],"hits":[],
 *  "npcs":[[11,12811,13,20,-1,-1,-1,"player",[]],[12,12818,16,24,7590,30,30,"player",[[0,12]]]],"orbs":[],
 *  "worn":[26382,21295,-1,20997,26384,-1,26386,-1,-1,-1,-1]},
 * {"t":1,...,"anims":[[11,10859]],"playerAnims":[426],"spots":[[12,2681]],"projectiles":[[2678,12,"player",0,51]],
 *  "counters":{"waveDamageTaken":13}},
 * ...
 * ]}
 * </pre>
 *
 * <ul>
 * <li>`v`: the log's version, 1; `kind`: always "solSurvivorWaveLog", which tells it apart from a state link's payload;
 * `plugin`: the plugin's version.</li>
 * <li>`wave`: the wave, 1 to 11, or 12 for Sol Heredit's.</li>
 * <li>`modifiers`: the modifiers taken at the wave's start, written as the state link writes them (its tier, true or
 * "random"); `modifiersComplete`: whether Quartet, Red Flag and Totemic are known (see ArenaState).</li>
 * <li>`maxTicks`: the most ticks a log holds; `cut`: whether the wave ran past it and the rest was left out.</li>
 * <li>`end`: "completed" when the game said the wave was completed, "left" when the player left the arena (died, ran or
 * logged out), null while the wave is under way, or when the next wave started before its end was seen.</li>
 * <li>`start`: the state link's payload on the wave's first tick (StatePayload, the site's src/link/statePayload.ts),
 * with the gear and stats when "Include gear and stats" is on, so that the site can plan the wave from where it began
 * and put the plan beside what the player did; null when it could not be taken.</li>
 * <li>`ticks`: one object a game tick, from the wave's first tick on, but for the repeats a tick's `repeats` stands for:
 * <ul>
 * <li>`t`: the tick within the wave, 0 on the tick of the game's "Wave: N" message;</li>
 * <li>`player`: [x, y, hitpoints, prayer points, [prayers on], animation id, target], with x and y the grid tile (null
 * off the grid), the prayers as WaveLog.prayerName names them, -1 for no animation, and the target an NPC's index,
 * "player" or null;</li>
 * <li>`hits`: the hitsplats on the player that came with this tick, [amount, hitsplat type id] each;</li>
 * <li>`npcs`: every NPC on the grid, by its raw id: [index, NPC id, x, y, animation id, health ratio, health scale,
 * target, [hitsplats]], with x and y its south-west tile, -1 for no animation and for an unknown health ratio or scale,
 * the target as the player's, and its hitsplats this tick as the player's;</li>
 * <li>`orbs`: the tiles of Solarflare's orbs (NPC 12826), [x, y] each, which are in `npcs` too;</li>
 * <li>`strayHits`, only when there are any: hitsplats on an NPC that is not in `npcs` this tick, [index, amount, type]
 * each;</li>
 * <li>`anims`, only when there are any: the animations NPCs started since the tick before, [index, animation id] each,
 * in the order they came. Each start is there, an attack that repeats the one before included, where the animation in
 * `npcs` only shows what an NPC is doing on the tick. An NPC whose animation stops is there too, with -1.</li>
 * <li>`playerAnims`, only when there are any: the animations the player started since the tick before, as `anims` has
 * the NPCs', so that each of the player's attacks is there even when the weapon's animation runs on unbroken.</li>
 * <li>`spots`, only when there are any: the graphics the NPCs in `npcs` show on the tick, [index, graphic id] each, such
 * as a Manticore's orbs as it charges them, unfiltered.</li>
 * <li>`worn`, on the wave's first tick and on each tick the player's gear changed, when "Include gear and stats" is on:
 * the item id in each slot of WaveLog.WORN_SLOTS, in its order, -1 for an empty one.</li>
 * <li>`tileGraphics`, only when there are any: the graphics the game put on the grid's tiles since the tick before,
 * [x, y, graphic id] each, in the order they came, unfiltered, such as where a Javelin Colossus's special lands.</li>
 * <li>`projectiles`, only when there are any (from 0.8.0): the projectiles first seen since the tick before, [graphic id,
 * from, to, start, end] each, in the order they were seen, unfiltered. From and to are each an NPC's index, "player",
 * or, at an end with no actor, such as a Javelin Colossus's special aimed at a tile, that tile as [x, y], null off the
 * grid. Start and end are the client cycles (20 ms, 30 to a tick) from this tick to when it sets off and when it lands,
 * below 0 for one that set off before this tick, as one first seen a tick late may have; end less start is its flight.
 * The Venator bow's bounces are each one from the NPC it bounces off to the next.</li>
 * <li>`counters`, on the wave's first tick and on each tick one changed (from 0.8.0): the game's own counters for the
 * wave and the run (ColosseumCounter), by key, such as Doom's stacks ("doomStacks") and the game's current glory
 * ("currentGlory"); those that did not change since the tick before are left out.</li>
 * <li>`repeats`, only when there are any (from 0.8.4): how many ticks after this one were the same as it in all but their
 * `t`, which are left out. A reader puts each back as a copy of this tick, `t` aside. A wait where nothing changes, as
 * while the player plans the next move on the site, is then one line rather than hundreds.</li>
 * </ul>
 * </li>
 * </ul>
 * The hitsplats of a tick are those the game showed since the tick before, which RuneLite passes on between ticks.
 */
public final class WaveLogWriter
{
	/** The log's version. */
	public static final int VERSION = 1;

	/** The log's `kind`. */
	public static final String KIND = "solSurvivorWaveLog";

	private WaveLogWriter()
	{
	}

	/** The log's JSON; an empty log, with no wave, has a null wave and no ticks. */
	public static String toJson(WaveLog log)
	{
		return toJson(log, log.getStartState(), false);
	}

	/**
	 * The log as the player shares it with "Share wave logs" (WaveShare): the same JSON, but with its `start` written
	 * without the gear's levels and prayer unlocks (Equipment.withoutLevels), which the site refuses in a shared log, and
	 * its ticks' counters without those that are not shared (ColosseumCounter.isShared).
	 */
	public static String toShare(WaveLog log)
	{
		return toJson(log, log.getShareState(), true);
	}

	private static String toJson(WaveLog log, String start, boolean shared)
	{
		StringBuilder b = new StringBuilder();
		b.append("{\"v\":").append(VERSION).append(",\"kind\":");
		StatePayload.string(b, KIND);
		b.append(",\"plugin\":");
		StatePayload.string(b, log.getVersion());
		b.append(",\"wave\":").append(log.getWave());
		b.append(",\"modifiers\":{");
		boolean first = true;
		for (Map.Entry<Modifier, Integer> e : log.getModifiers().entrySet())
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			StatePayload.string(b, e.getKey().getKey());
			b.append(':').append(StatePayload.valueOf(e.getKey(), e.getValue()));
		}
		b.append("},\"modifiersComplete\":").append(log.isModifiersComplete());
		b.append(",\"maxTicks\":").append(WaveLog.MAX_TICKS);
		b.append(",\"cut\":").append(log.isCut());
		b.append(",\"end\":");
		if (log.getEnd() == null)
		{
			b.append("null");
		}
		else
		{
			StatePayload.string(b, log.getEnd().getKey());
		}
		b.append(",\"start\":").append(start == null ? "null" : start);
		b.append(",\"ticks\":[");
		// A tick the same as the one before it, its t aside, is left out, and the tick before says how many repeat it.
		List<WaveLog.Tick> ticks = log.getTicks();
		List<String> bodies = new ArrayList<>(ticks.size());
		for (WaveLog.Tick tick : ticks)
		{
			StringBuilder body = new StringBuilder();
			tick(body, tick, shared);
			bodies.add(body.toString());
		}
		for (int i = 0; i < ticks.size(); )
		{
			int repeats = 0;
			while (i + repeats + 1 < ticks.size() && ticks.get(i + repeats + 1).t == ticks.get(i).t + repeats + 1
				&& bodies.get(i + repeats + 1).equals(bodies.get(i)))
			{
				repeats++;
			}
			b.append(i == 0 ? "\n" : ",\n").append("{\"t\":").append(ticks.get(i).t).append(bodies.get(i));
			if (repeats > 0)
			{
				b.append(",\"repeats\":").append(repeats);
			}
			b.append('}');
			i += repeats + 1;
		}
		b.append(ticks.isEmpty() ? "]}" : "\n]}");
		return b.toString();
	}

	/** A tick's JSON after its `t`, up to its closing brace: the same text for two ticks that showed the same. */
	private static void tick(StringBuilder b, WaveLog.Tick tick, boolean shared)
	{
		b.append(",\"player\":");
		WaveLog.PlayerTick p = tick.player;
		if (p == null)
		{
			b.append("null");
		}
		else
		{
			b.append('[');
			tile(b, p.getTile());
			b.append(',').append(p.getHitpoints()).append(',').append(p.getPrayerPoints()).append(",[");
			boolean first = true;
			for (String prayer : p.getPrayers())
			{
				if (!first)
				{
					b.append(',');
				}
				first = false;
				StatePayload.string(b, prayer);
			}
			b.append("],").append(p.getAnimation()).append(',');
			target(b, p.getTarget());
			b.append(']');
		}
		b.append(",\"hits\":");
		hits(b, tick.playerHits);

		b.append(",\"npcs\":[");
		boolean first = true;
		for (WaveLog.NpcTick n : tick.npcs)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(n.getIndex()).append(',').append(n.getNpcId()).append(',');
			tile(b, n.getTile());
			b.append(',').append(n.getAnimation()).append(',').append(n.getHealthRatio()).append(',').append(n.getHealthScale()).append(',');
			target(b, n.getTarget());
			b.append(',');
			hits(b, tick.npcHits.getOrDefault(n.getIndex(), Collections.emptyList()));
			b.append(']');
		}
		b.append("],\"orbs\":[");
		first = true;
		for (GridTile t : tick.orbs)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(t.getX()).append(',').append(t.getY()).append(']');
		}
		b.append(']');

		// Hitsplats on an NPC the tick does not list, such as one that despawned before the tick's snapshot, are kept.
		StringBuilder stray = new StringBuilder();
		for (Map.Entry<Integer, List<WaveLog.Hit>> e : tick.npcHits.entrySet())
		{
			if (listed(tick.npcs, e.getKey()))
			{
				continue;
			}
			for (WaveLog.Hit h : e.getValue())
			{
				stray.append(stray.length() == 0 ? "" : ",").append('[').append(e.getKey()).append(',').append(h.getAmount()).append(',')
					.append(h.getType()).append(']');
			}
		}
		if (stray.length() > 0)
		{
			b.append(",\"strayHits\":[").append(stray).append(']');
		}
		if (!tick.animations.isEmpty())
		{
			b.append(",\"anims\":[");
			for (int i = 0; i < tick.animations.size(); i++)
			{
				int[] a = tick.animations.get(i);
				b.append(i == 0 ? "" : ",").append('[').append(a[0]).append(',').append(a[1]).append(']');
			}
			b.append(']');
		}
		if (!tick.playerAnimations.isEmpty())
		{
			b.append(",\"playerAnims\":[");
			for (int i = 0; i < tick.playerAnimations.size(); i++)
			{
				b.append(i == 0 ? "" : ",").append(tick.playerAnimations.get(i));
			}
			b.append(']');
		}
		StringBuilder spots = new StringBuilder();
		for (WaveLog.NpcTick n : tick.npcs)
		{
			for (int id : n.getSpotAnims())
			{
				spots.append(spots.length() == 0 ? "" : ",").append('[').append(n.getIndex()).append(',').append(id).append(']');
			}
		}
		if (spots.length() > 0)
		{
			b.append(",\"spots\":[").append(spots).append(']');
		}
		if (tick.worn != null)
		{
			b.append(",\"worn\":[");
			for (int i = 0; i < tick.worn.length; i++)
			{
				b.append(i == 0 ? "" : ",").append(tick.worn[i]);
			}
			b.append(']');
		}
		if (!tick.tileGraphics.isEmpty())
		{
			b.append(",\"tileGraphics\":[");
			for (int i = 0; i < tick.tileGraphics.size(); i++)
			{
				int[] g = tick.tileGraphics.get(i);
				b.append(i == 0 ? "" : ",").append('[').append(g[0]).append(',').append(g[1]).append(',').append(g[2]).append(']');
			}
			b.append(']');
		}
		if (!tick.projectiles.isEmpty())
		{
			b.append(",\"projectiles\":[");
			for (int i = 0; i < tick.projectiles.size(); i++)
			{
				WaveLog.Projectile shot = tick.projectiles.get(i);
				b.append(i == 0 ? "" : ",").append('[').append(shot.getId()).append(',');
				end(b, shot.getFrom(), shot.getFromTile());
				b.append(',');
				end(b, shot.getTo(), shot.getToTile());
				b.append(',').append(shot.getStart()).append(',').append(shot.getEnd()).append(']');
			}
			b.append(']');
		}
		boolean firstCounter = true;
		for (Map.Entry<ColosseumCounter, Integer> e : tick.counters.entrySet())
		{
			if (shared && !e.getKey().isShared())
			{
				continue;
			}
			b.append(firstCounter ? ",\"counters\":{" : ",");
			firstCounter = false;
			StatePayload.string(b, e.getKey().getKey());
			b.append(':').append(e.getValue());
		}
		if (!firstCounter)
		{
			b.append('}');
		}
	}

	private static boolean listed(List<WaveLog.NpcTick> npcs, int index)
	{
		for (WaveLog.NpcTick n : npcs)
		{
			if (n.getIndex() == index)
			{
				return true;
			}
		}
		return false;
	}

	/** A tile as two numbers, x and y, or two nulls for none. */
	private static void tile(StringBuilder b, GridTile t)
	{
		if (t == null)
		{
			b.append("null,null");
		}
		else
		{
			b.append(t.getX()).append(',').append(t.getY());
		}
	}

	/** A projectile's end: its actor as a target is written, or with none the tile as [x, y], null off the grid. */
	private static void end(StringBuilder b, int actor, GridTile tile)
	{
		if (actor != WaveLog.TARGET_NONE)
		{
			target(b, actor);
		}
		else if (tile == null || !ArenaGeometry.onGrid(tile))
		{
			b.append("null");
		}
		else
		{
			b.append('[').append(tile.getX()).append(',').append(tile.getY()).append(']');
		}
	}

	private static void target(StringBuilder b, int target)
	{
		if (target == WaveLog.TARGET_PLAYER)
		{
			b.append("\"player\"");
		}
		else if (target < 0)
		{
			b.append("null");
		}
		else
		{
			b.append(target);
		}
	}

	private static void hits(StringBuilder b, List<WaveLog.Hit> hits)
	{
		b.append('[');
		boolean first = true;
		for (WaveLog.Hit h : hits)
		{
			if (!first)
			{
				b.append(',');
			}
			first = false;
			b.append('[').append(h.getAmount()).append(',').append(h.getType()).append(']');
		}
		b.append(']');
	}
}

package nl.dexanddice.solsurvivor.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;

/**
 * One wave's log read for the wave report and the death recap, which the panel shows once the wave is over: each attack
 * at the player and the protection prayer that met it, each hit the player took and what likeliest dealt it, and the
 * stretches the player stood idle. It reads the log as the site's run review does (src/viewer/runReview.ts, reviewRun),
 * so that the report and the site agree on a wave: the same attacks, the same ticks from an attack to its hitsplat, and
 * the same order of likelihood when two attacks could have dealt a hit. src/test/resources/fixtures/wave-review.json is
 * a log both read (test/link/pluginFixtures.test.ts).
 *
 * The prayer against each attack is judged as the site's Prayer reliability judges it (PrayerFlicks): on time, a tick
 * late or off a tick early, the wrong prayer, or none up. Unlike that count, an attack met with another prayer is kept,
 * as a wrong prayer: the report says what got past, whether or not tanking it was the plan.
 *
 * Nothing here is shown during a wave, and nothing here says how to play one: it says what the log saw.
 */
public final class WaveReview
{
	/** How the player's protection prayer met an attack. */
	public enum Prayed
	{
		/** The right prayer was on as the attack was checked. */
		ON_TIME,
		/** The right prayer came on a tick after the check, or the switch was caught half-way, the old prayer counting. */
		LATE,
		/** The right prayer was on the tick before and switched off on it. */
		EARLY,
		/** Another protection prayer was on. */
		WRONG,
		/** No protection prayer was on. */
		NONE
	}

	/** What the report counts as a mistake, each with a switch of its own in the settings. */
	public enum Kind
	{
		/** An attack that met the wrong prayer or none, with what it hit for. */
		PAST_PRAYER,
		/** An attack whose prayer came a tick late or went a tick early. */
		LATE_FLICK,
		/** A Javelin Colossus's special that landed on the player. */
		SPECIAL,
		/** A Volatility explosion the player stood in. */
		VOLATILITY,
		/** A hit of Solarflare's orb, or one no attack explains while the player stood on molten sand. */
		SOLARFLARE_SAND,
		/** A stretch of ticks with the weapon ready, no attack and no step. */
		IDLE
	}

	/**
	 * A mistake of the wave: its tick, its kind, what happened, the damage it cost or the idle stretch's ticks, and the
	 * picture of what did it.
	 */
	public static final class Mistake
	{
		private final int tick;
		private final Kind kind;
		private final String text;
		private final Integer damage;
		private final int ticks;
		private final String icon;
		private final String summary;
		private final String group;
		private final String style;

		Mistake(int tick, Kind kind, String text, Integer damage, int ticks, String icon)
		{
			this(tick, kind, text, damage, ticks, icon, kind == Kind.IDLE ? "Idle with the weapon ready" : text);
		}

		Mistake(int tick, Kind kind, String text, Integer damage, int ticks, String icon, String summary)
		{
			this(tick, kind, text, damage, ticks, icon, summary, kind + ":" + summary);
		}

		Mistake(int tick, Kind kind, String text, Integer damage, int ticks, String icon, String summary, String group)
		{
			this(tick, kind, text, damage, ticks, icon, summary, group, null);
		}

		Mistake(int tick, Kind kind, String text, Integer damage, int ticks, String icon, String summary, String group, String style)
		{
			this.style = style;
			this.tick = tick;
			this.kind = kind;
			this.text = text;
			this.damage = damage;
			this.ticks = ticks;
			this.icon = icon;
			this.summary = summary;
			this.group = group;
		}

		/**
		 * The style of the attack it was about, "magic", "ranged" or "melee", for an attack past the prayer or a flick a
		 * tick off; null for the other kinds, a special, a blast, the sand or an idle stretch.
		 */
		public String getStyle()
		{
			return style;
		}

		/** A stable description of this kind and attacker, for grouping the short report without changing its full detail. */
		public String getSummary()
		{
			return summary;
		}

		/** The kind and recorded attacker, stable even when the attacker's directional name changes as the player moves. */
		public String getGroup()
		{
			return group;
		}

		/**
		 * The picture of what did it, by the plugin's icon names: the NPC's face ("npc-javelin"), the modifier's
		 * ("modifier-volatility"), "molten-sand", or "hourglass" for an idle stretch; null when nothing in the log says.
		 */
		public String getIcon()
		{
			return icon;
		}

		/** The wave's tick it happened on: the attack's check, the hit's landing or the idle stretch's first. */
		public int getTick()
		{
			return tick;
		}

		public Kind getKind()
		{
			return kind;
		}

		public String getText()
		{
			return text;
		}

		/** The damage it cost, 0 for an attack past the prayer that hit for nothing; null for an idle stretch. */
		public Integer getDamage()
		{
			return damage;
		}

		/** An idle stretch's length in ticks; 0 for the other kinds. */
		public int getTicks()
		{
			return ticks;
		}

		@Override
		public String toString()
		{
			return "t" + tick + " " + kind + " " + text + (damage == null ? "" : " " + damage);
		}
	}

	/** A line of the death recap: the tick, the player's hitpoints and protection prayer on it, and what happened. */
	public static final class RecapLine
	{
		private final int tick;
		private final Integer hitpoints;
		private final String prayer;
		private final String text;
		private final String hit;

		public RecapLine(int tick, Integer hitpoints, String prayer, String text, String hit)
		{
			this.tick = tick;
			this.hitpoints = hitpoints;
			this.prayer = prayer;
			this.text = text;
			this.hit = hit;
		}

		public int getTick()
		{
			return tick;
		}

		/** The hitpoints the log has on the tick; null where it has no player. */
		public Integer getHitpoints()
		{
			return hitpoints;
		}

		/** The protection prayer on, "magic", "ranged" or "melee"; "" for none, null where the log does not say. */
		public String getPrayer()
		{
			return prayer;
		}

		public String getText()
		{
			return text;
		}

		/** The damage that landed, "blocked", "0" for a hit of nothing, or "–" for none. */
		public String getHit()
		{
			return hit;
		}

		@Override
		public String toString()
		{
			return tick + " " + hitpoints + " " + prayer + " " + text + " " + hit;
		}
	}

	/** The site's PROTECT names, by the style each blocks. */
	private static final Map<String, String> PRAYER_NAMES = new HashMap<>();

	/** The NPC ids the site's review models (its LOG_NPC_TYPES), each with its footprint's size. */
	private static final Map<Integer, Integer> SIZES = new HashMap<>();

	/**
	 * The Fremennik warband by id: its name and the style of its attack, whose animation PrayerFlicks's FREM_ATTACKS
	 * holds. Each frem's hitsplat is on the player on the tick after it attacks (the site's FREM_HIT_DELAY).
	 */
	private static final Map<Integer, String[]> FREMS = new HashMap<>();
	private static final Map<Integer, Integer> FREM_ATTACKS = new HashMap<>();
	public static final int FREM_ARCHER_ID = 12814;
	public static final int FREM_SEER_ID = 12815;
	public static final int FREM_BERSERKER_ID = 12816;
	private static final int FREM_HIT_DELAY = 1;

	/** The NPC whose attacks the log cannot show but which can hurt the player: Solarflare's orb (the site's UNSEEN_ATTACKERS). */
	private static final int SOLARFLARE_ORB = NpcKind.SOLARFLARE_ORB_ID;

	/**
	 * Volatility's explosions, by id: the NPC the game puts on a dead NPC's tile for the ticks its explosion shows, and
	 * the size of the footprint it stands for, 0 where it stands for more than one and the dead NPC's own tells (the
	 * site's VOLATILITY_EXPLOSIONS).
	 */
	private static final Map<Integer, Integer> EXPLOSIONS = new HashMap<>();

	/** How many tiles beyond an NPC's footprint its explosion reaches, by Volatility's tier: the site's VOLATILITY_REACH. */
	private static final int[] VOLATILITY_REACH = {0, 1, 2, 2};

	/** Ticks from a Javelin special's throw to its landing: the site's JAVELIN_SPECIAL_LANDING. */
	private static final int JAVELIN_SPECIAL_LANDING = 6;

	/** From Mantimayhem I, each Manticore orb is two projectiles, each with its hitsplat (MANTIMAYHEM_PROJECTILES_PER_ORB). */
	private static final int MANTIMAYHEM_PROJECTILES_PER_ORB = 2;

	/** The player eating or drinking, which is no attack (the site's EAT_ANIM). */
	public static final int EAT_ANIMATION = 829;

	/** The most lines the death recap shows: the ticks up to the one the player died on. */
	public static final int RECAP_TICKS = 8;

	static
	{
		PRAYER_NAMES.put("magic", "Protect from Magic");
		PRAYER_NAMES.put("ranged", "Protect from Missiles");
		PRAYER_NAMES.put("melee", "Protect from Melee");
		SIZES.put(NpcKind.SHAMAN_ID, 1);
		SIZES.put(NpcKind.JAGUAR_ID, 2);
		SIZES.put(NpcKind.MINOTAUR_ID, 3);
		SIZES.put(NpcKind.MINOTAUR_RED_FLAG_ID, 3);
		SIZES.put(NpcKind.JAVELIN_ID, 3);
		SIZES.put(NpcKind.MANTICORE_ID, 3);
		SIZES.put(NpcKind.SHOCKWAVE_ID, 3);
		FREMS.put(FREM_ARCHER_ID, new String[] {"Archer", "ranged"});
		FREMS.put(FREM_SEER_ID, new String[] {"Seer", "magic"});
		FREMS.put(FREM_BERSERKER_ID, new String[] {"Berserker", "melee"});
		FREM_ATTACKS.put(FREM_ARCHER_ID, 10850);
		FREM_ATTACKS.put(FREM_SEER_ID, 10853);
		FREM_ATTACKS.put(FREM_BERSERKER_ID, 10856);
		EXPLOSIONS.put(12828, 0);
		EXPLOSIONS.put(12829, 3);
		EXPLOSIONS.put(12831, 3);
	}

	/** An attack at the player, with what the review made of it. */
	private static final class Attack
	{
		final int tick;
		final int checked;
		final int index;
		final int npcId;
		final String name;
		final String style;
		final boolean special;
		final boolean frem;
		/** The protection prayer on as it was checked: "" for none, null where the log does not say. */
		final String prayer;
		final Integer distance;
		Prayed prayed;
		int damage;
		int matches;

		Attack(int tick, int checked, int index, int npcId, String name, String style, boolean special, boolean frem, String prayer,
			Integer distance)
		{
			this.tick = tick;
			this.checked = checked;
			this.index = index;
			this.npcId = npcId;
			this.name = name;
			this.style = style;
			this.special = special;
			this.frem = frem;
			this.prayer = prayer;
			this.distance = distance;
		}

		boolean blocked()
		{
			return !special && style.equals(prayer);
		}

		/** "East Manticore's magic orb", "Javelin's throw", "Archer's ranged attack". */
		String text()
		{
			return name + "'s " + (special ? "special" : what(npcId, style));
		}
	}

	/** A hit on the player that did damage, and what the review put it down to. */
	private static final class Hit
	{
		final int tick;
		final int damage;
		final Attack attack;
		/** What dealt it when no attack did, as a line says it and as a sentence names it; null for nothing the review knows. */
		final String other;
		final String otherNoun;
		final Kind otherKind;

		Hit(int tick, int damage, Attack attack)
		{
			this(tick, damage, attack, null, null, null);
		}

		Hit(int tick, int damage, Attack attack, String other, String otherNoun, Kind otherKind)
		{
			this.tick = tick;
			this.damage = damage;
			this.attack = attack;
			this.other = other;
			this.otherNoun = otherNoun;
			this.otherKind = otherKind;
		}

		/** What dealt it, as a line of the report or the recap says it: "Javelin's special landed on your tile". */
		String text()
		{
			if (attack != null)
			{
				return attack.special ? attack.name + "'s special landed on your tile" : attack.text();
			}
			return other == null ? "A hit no attack in the log explains" : other;
		}

		/** What dealt it, as a sentence names it: "the Javelin's special", "molten sand". */
		String noun()
		{
			if (attack != null)
			{
				return "the " + (attack.special ? attack.name + "'s special" : attack.text());
			}
			return otherNoun == null ? "a hit no attack in the log explains" : otherNoun;
		}
	}

	/** What the review remembers of an NPC from the ticks before. */
	private static final class Seen
	{
		final int npcId;
		final int first;
		int last;
		Integer death;

		Seen(int npcId, int first)
		{
			this.npcId = npcId;
			this.first = first;
			this.last = first;
		}
	}

	private final Integer wave;
	private final Integer died;
	private final int last;
	private final Map<Prayed, Integer> prayed;
	private final List<Mistake> mistakes;
	private final int damage;
	private final List<RecapLine> recap;
	private final String cause;
	private final int maxHitpoints;

