	@Test
	public void theTipSitsOnTheEdgeTheDirectionLeavesBy()
	{
		Point2D.Double centre = new Point2D.Double(260, 171);
		Point2D.Double right = NpcArrowsOverlay.edge(view, centre, 1, 0, 6);
		assertEquals(4 + 512 - 6, right.x, 1e-9);
