package nl.dexanddice.solsurvivor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

/**
 * The panel's drawn parts at a display's scaling. Windows scales RuneLite by 125%, 150% or 200% on many laptops, and a
 * line drawn there with drawLine stays a whole screen pixel, so a well's right and bottom edges fell a pixel short of
 * its fill and the sun in the wave's slot sat off its centre (Stefan's screenshot of 2026-10-26).
 */
public class StoneTest
{
	private static final int KEY = Color.MAGENTA.getRGB();

	/** The wave's slot with its sun, painted at `scale` onto magenta, which nothing in it uses. */
	private static BufferedImage slotAt(double scale)
	{
		Stone.Slot slot = new Stone.Slot(34, Stone.sun(24));
		slot.setSize(34, 34);
		int side = (int) Math.ceil(34 * scale) + 2;
		BufferedImage image = new BufferedImage(side, side, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		g.setColor(Color.MAGENTA);
		g.fillRect(0, 0, side, side);
		g.scale(scale, scale);
		slot.paintComponent(g);
		g.dispose();
		return image;
	}

	/** The gaps between the slot's edges and its sun's orange: left, right, top and bottom, in screen pixels. */
	private static int[] gaps(BufferedImage image)
	{
		int fx0 = Integer.MAX_VALUE, fx1 = -1, fy0 = Integer.MAX_VALUE, fy1 = -1;
		int sx0 = Integer.MAX_VALUE, sx1 = -1, sy0 = Integer.MAX_VALUE, sy1 = -1;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int p = image.getRGB(x, y);
				if (p == KEY)
				{
					continue;
				}
				fx0 = Math.min(fx0, x);
				fx1 = Math.max(fx1, x);
				fy0 = Math.min(fy0, y);
				fy1 = Math.max(fy1, y);
				int r = (p >> 16) & 255, b = p & 255;
				if (r > 150 && r - b > 100)
				{
					sx0 = Math.min(sx0, x);
					sx1 = Math.max(sx1, x);
					sy0 = Math.min(sy0, y);
					sy1 = Math.max(sy1, y);
				}
			}
		}
		assertTrue("the slot shows its sun", sx1 >= 0);
		return new int[]{sx0 - fx0, fx1 - sx1, sy0 - fy0, fy1 - sy1};
	}

	@Test
	public void theSunSitsInTheMiddleOfTheWavesSlotAtWholeScalings()
	{
		// 125% is left out: there the 34-pixel slot is 42.5 screen pixels, which no drawing can halve.
		for (double scale : new double[]{1, 1.5, 2})
		{
			int[] g = gaps(slotAt(scale));
			assertEquals("left and right at " + scale, g[0], g[1]);
			assertEquals("top and bottom at " + scale, g[2], g[3]);
		}
	}

	@Test
	public void theToolbarSunIsTheSameMirroredEitherWay()
	{
		BufferedImage icon = SolSurvivorPanel.icon();
		for (int y = 0; y < 16; y++)
		{
			for (int x = 0; x < 16; x++)
			{
				// The sun is set out pixel by pixel, so each pixel is its mirror's colour exactly.
				int p = icon.getRGB(x, y);
				assertEquals("left and right at " + x + ", " + y, p, icon.getRGB(15 - x, y));
				assertEquals("top and bottom at " + x + ", " + y, p, icon.getRGB(x, 15 - y));
			}
		}
		assertEquals("the middle is white", 0xfffffffd, icon.getRGB(7, 7));
		assertEquals("a corner is clear", 0, icon.getRGB(0, 0) >>> 24);
	}
}

package nl.dexanddice.solsurvivor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.http.api.RuneLiteAPI;
import nl.dexanddice.solsurvivor.core.TileMarker;
import org.junit.Test;

/**
 * The tiles Tile Packs draws in the arena, read as its build of 31 October 2026 keeps them, with the client's Gson: its
 * built-in packs in a commented JSON file in its jar, the player's own under tilePacks.pack_<id>, and the ids drawn
 * under tilePacks.packs. The packs here are made up in that format.
 */
public class TilePacksTest
{
	private static final String BUILT_IN = "//this file is sorted by bosses\n"
		+ "//next id: 92\n"
		+ "{\n"
		+ "//  PVM\n"
		+ "  \"1\": {\"id\": 1, \"packName\": \"Somewhere else\", \"link\": \"https://example.org\",\n"
		+ "    \"packTiles\": \"[{\\\"regionId\\\":11850,\\\"regionX\\\":27,\\\"regionY\\\":44,\\\"z\\\":0,\\\"color\\\":\\\"#FFFFFF00\\\"}]\"},\n"
		+ "  \"55\": {\"id\": 55, \"packName\": \"Colosseum\",\n"
		+ "    \"packTiles\": \"[{\\\"regionId\\\":7216,\\\"regionX\\\":23,\\\"regionY\\\":43,\\\"z\\\":0,\\\"color\\\":\\\"#FF00FFFF\\\",\\\"label\\\":\\\"A\\\"},"
		+ "{\\\"regionId\\\":7216,\\\"regionX\\\":27,\\\"regionY\\\":40,\\\"z\\\":0,\\\"color\\\":\\\"#01000000\\\"},"
		+ "{\\\"regionId\\\":7216,\\\"regionX\\\":26,\\\"regionY\\\":50,\\\"z\\\":0,\\\"color\\\":\\\"#FFFFA500\\\"}]\"}\n"
		+ "}";

	private static final String CUSTOM = "{\"id\":10001,\"packName\":\"Mine\",\"packTiles\":\"[{\\\"regionId\\\":7216,\\\"regionX\\\":21,"
		+ "\\\"regionY\\\":42,\\\"z\\\":0,\\\"color\\\":\\\"#7AFF0000\\\",\\\"label\\\":\\\"skip\\\"}]\",\"visible\":true}";

	/** A built-in pack's id saved by the player, which carries whether it is listed and never replaces its tiles. */
	private static final String BUILT_IN_SAVED = "{\"id\":55,\"visible\":false}";

	private static List<TileMarker> read(String drawn, Color override, boolean labels)
	{
		Map<Integer, TilePacks.Pack> builtIn = TilePacks.builtIn(RuneLiteAPI.GSON, BUILT_IN);
		return TilePacks.read(RuneLiteAPI.GSON, builtIn, Arrays.asList(CUSTOM, BUILT_IN_SAVED, "{broken"), drawn, override, labels, 0);
	}

	@Test
	public void theArenasTilesOfThePacksDrawnAreMarkersInTheirOrder()
	{
		assertEquals("[(5,9) #ff0000 skip, (7,8) #00ffff A, (10,1) #ffa500]", read("[10001,1,55]", null, true).toString());
	}

	@Test
	public void aPackNotDrawnOrUnknownAddsNone()
	{
		assertEquals("[(5,9) #ff0000 skip]", read("[10001,77]", null, true).toString());
		assertTrue(read("[]", null, true).isEmpty());
		assertTrue(read(null, null, true).isEmpty());
		assertTrue(read("{not a list", null, true).isEmpty());
	}

	@Test
	public void theOverrideColourAndHiddenLabelsAreAsTilePacksDrawsThem()
	{
		// The override draws even a tile the pack made too faint to see, so the game shows it, and so does the link.
		assertEquals("[(7,8) #ffff00, (11,11) #ffff00, (10,1) #ffff00]", read("[55]", Color.YELLOW, false).toString());
	}

	@Test
	public void aMissingOrBrokenBuiltInFileIsNoBuiltInPacks()
	{
		assertTrue(TilePacks.builtIn(RuneLiteAPI.GSON, null).isEmpty());
		assertTrue(TilePacks.builtIn(RuneLiteAPI.GSON, "{\"55\": [").isEmpty());
		assertEquals("[(5,9) #ff0000 skip]", TilePacks.read(RuneLiteAPI.GSON, Collections.emptyMap(), Collections.singletonList(CUSTOM),
			"[55,10001]", null, true, 0).toString());
	}

	@Test
	public void theKeysAreTilePacksOwn()
	{
		assertEquals("com.tilepacks.TilePacksPlugin", TilePacks.PLUGIN_CLASS);
		assertEquals("tilePacks.jsonc", TilePacks.BUILT_IN);
		assertEquals("tilePacks", TilePacks.GROUP);
		assertEquals("packs", TilePacks.DRAWN);
		assertEquals("pack_", TilePacks.PACK_PREFIX);
		assertEquals("tilepacks", TilePacks.SETTINGS);
	}
}

package nl.dexanddice.solsurvivor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Proxy;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.client.ui.FontManager;
import nl.dexanddice.solsurvivor.core.Modifier;
import nl.dexanddice.solsurvivor.core.WaveRoster;
import org.junit.Test;

/** The wave box: each count first, coloured by how many, "+1" for those still to come, and Doom left to its own box. */
public class WaveBoxOverlayTest
{
	private final AtomicReference<SolSurvivorConfig.WaveBox> mode = new AtomicReference<>(SolSurvivorConfig.WaveBox.BOTH);
	private final AtomicReference<WaveView> view = new AtomicReference<>();
	private final AtomicBoolean styles = new AtomicBoolean(true);
	private final SolSurvivorConfig defaults = new SolSurvivorConfig()
	{
	};
	private final SolSurvivorPlugin plugin = new SolSurvivorPlugin()
	{
		@Override
		boolean inArena()
		{
			return true;
		}

		@Override
		WaveView waveView()
		{
			return view.get();
		}
	};
	private final SolSurvivorConfig config = (SolSurvivorConfig) Proxy.newProxyInstance(getClass().getClassLoader(),
		new Class<?>[] {SolSurvivorConfig.class}, (p, m, a) ->
		{
			switch (m.getName())
			{
				case "waveBox": return mode.get();
				case "markDead": return true;
				case "doomLimit": return true;
				case "quietOnSol": return true;
				case "waveBoxStyleColours": return styles.get();
				case "waveBoxMagicColour": return defaults.waveBoxMagicColour();
				case "waveBoxRangedColour": return defaults.waveBoxRangedColour();
				case "waveBoxMeleeColour": return defaults.waveBoxMeleeColour();
				default: return null;
			}
		});
	private final WaveBoxOverlay box = new WaveBoxOverlay(plugin, config);
	private final Map<Modifier, Integer> held = Collections.emptyMap();

	@Test
	public void aCountIsColouredByHowMany()
	{
		assertEquals(WaveBoxOverlay.countColour(0), WaveBoxOverlay.countColour(-1));
		assertNotEquals(WaveBoxOverlay.countColour(1), WaveBoxOverlay.countColour(2));
		assertNotEquals(WaveBoxOverlay.countColour(2), WaveBoxOverlay.countColour(3));
		assertEquals(WaveBoxOverlay.countColour(3), WaveBoxOverlay.countColour(7));
	}

	@Test
	public void eachNameIsTintedByHowItsNpcAttacks()
	{
		// The shaman blue, the Javelin green and the melee NPCs red (Stefan's request, 2026-11-08); the Shockwave
		// Colossus attacks with magic, so it shares the shaman's tint.
		assertEquals(defaults.waveBoxMagicColour(), WaveBoxOverlay.styleColour("shaman", defaults));
		assertEquals(defaults.waveBoxMagicColour(), WaveBoxOverlay.styleColour("shockwave", defaults));
		assertEquals(defaults.waveBoxMagicColour(), WaveBoxOverlay.styleColour("seer", defaults));
		assertEquals(defaults.waveBoxRangedColour(), WaveBoxOverlay.styleColour("javelin", defaults));
		assertEquals(defaults.waveBoxRangedColour(), WaveBoxOverlay.styleColour("archer", defaults));
		assertEquals(defaults.waveBoxMeleeColour(), WaveBoxOverlay.styleColour("jaguar", defaults));
		assertEquals(defaults.waveBoxMeleeColour(), WaveBoxOverlay.styleColour("minotaur", defaults));
		assertEquals(defaults.waveBoxMeleeColour(), WaveBoxOverlay.styleColour("berserker", defaults));
		// More than one style: no tint.
		assertNull(WaveBoxOverlay.styleColour("manticore", defaults));
		assertNull(WaveBoxOverlay.styleColour("warband", defaults));
		assertNull(WaveBoxOverlay.styleColour(null, defaults));
		// Light tints, so that the names stay easy to read on the box's dark ground.
		for (java.awt.Color c : new java.awt.Color[] {defaults.waveBoxMagicColour(), defaults.waveBoxRangedColour(),
			defaults.waveBoxMeleeColour()})
		{
			assertTrue(c.toString(), c.getRed() + c.getGreen() + c.getBlue() > 3 * 180);
		}
	}

	@Test
	public void theBoxDrawsWithTheTintsOnOrOff()
	{
		List<WaveRoster.Line> roster = WaveRoster.thisWave(5, held, new WaveRoster.Alive(), false, true, 0, false);
		view.set(new WaveView(5, true, roster, 6, roster, Collections.emptyList(), null, held, 4, 10));
		Dimension tinted = render();
		styles.set(false);
		assertEquals(tinted, render());
	}

	@Test
	public void thoseStillToComeReadPlusAndTheDeadReadZero()
	{
		// On a wave's first tick its reinforcements are still to come; once they have come and nobody is left, all are dead.
		List<WaveRoster.Line> fresh = WaveRoster.thisWave(5, held, new WaveRoster.Alive(), false, true, 0, false);
		WaveRoster.Line toCome = fresh.stream().filter(WaveRoster.Line::isToCome).findFirst().orElse(null);
		assertNotNull(fresh.toString(), toCome);
		assertEquals("+" + toCome.getCount(), WaveBoxOverlay.count(toCome, true));
		WaveRoster.Line here = fresh.stream().filter(l -> !l.isToCome() && !l.isDead()).findFirst().orElse(null);
		assertNotNull(here);
		assertEquals(String.valueOf(here.getCount()), WaveBoxOverlay.count(here, false));
		List<WaveRoster.Line> cleared = WaveRoster.thisWave(5, held, new WaveRoster.Alive(), true, false, 0, false);
		WaveRoster.Line dead = cleared.stream().filter(WaveRoster.Line::isDead).findFirst().orElse(null);
		assertNotNull(cleared.toString(), dead);
		assertEquals("0", WaveBoxOverlay.count(dead, true));
	}

	@Test
	public void theBoxDrawsTheWaveAndTheNextAndHidesWhenOff()
	{
		List<WaveRoster.Line> roster = WaveRoster.thisWave(5, held, new WaveRoster.Alive(), false, true, 0, false);
		view.set(new WaveView(5, true, roster, 6, roster, Collections.emptyList(), null, held, 4, 10));
		Dimension both = render();
		assertNotNull(both);
		mode.set(SolSurvivorConfig.WaveBox.THIS_WAVE);
		Dimension one = render();
		assertNotNull(one);
		assertEquals(both.width, one.width);
		mode.set(SolSurvivorConfig.WaveBox.OFF);
		assertNull(render());
	}

	private Dimension render()
	{
		Graphics2D graphics = new BufferedImage(300, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();
		graphics.setFont(FontManager.getRunescapeFont());
		try
		{
			// Two frames, as the game draws one after another: a panel sizes itself from the frame before.
			box.render(graphics);
			return box.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}
}

package nl.dexanddice.solsurvivor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.HashSet;
import java.util.Set;
import javax.imageio.ImageIO;
import nl.dexanddice.solsurvivor.core.WaveClock;
import org.junit.Test;

/** The real RuneLite overlays rendered headlessly, including settings that must never leave duplicate boxes. */
public class WaveClockOverlayTest
{
	private final ClockPlugin plugin = new ClockPlugin();
	private final Settings config = new Settings();
	private final TickCounterOverlay ticks = new TickCounterOverlay(plugin, config);
	private final WaveTimerOverlay time = new WaveTimerOverlay(plugin, config);
	private final CombinedWaveTimerOverlay both = new CombinedWaveTimerOverlay(plugin, config);

	@Test
	public void onlyEnabledOverlaysDrawAndCombiningRequiresBothToBeEnabled()
	{
		plugin.clock.onTick(90);
		plugin.clock.onModifierChosen(7, 100, 0, true);
		assertNull(render(ticks));
		assertNull(render(time));
		assertNull(render(both));
		config.tick = true;
		config.combine = true;
		assertNotNull(render(ticks));
		assertNull(render(time));
		assertNull(render(both));
		config.timer = true;
		assertNull(render(ticks));
		assertNull(render(time));
		assertNotNull(render(both));
		config.tick = false;
		assertNull(render(ticks));
		assertNotNull(render(time));
		assertNull(render(both));
	}

	@Test
	public void theCounterAloneShowsBeforeAnyPickAndTheCombinedBoxLeavesOutTheTime()
	{
		plugin.clock.onTick(90);
		config.tick = true;
		config.timer = true;
		assertNotNull(render(ticks));
		assertNull(render(time));
		config.combine = true;
		assertFits(both, 170, 120);
		config.rows = true;
		assertFits(both, 170, 90);
	}

	@Test
	public void separateAndEveryCombinedLookFitAtTheirNativeSizeAndMoveAsRuneLitePanels()
	{
		plugin.clock.onTick(90);
		plugin.clock.onModifierChosen(7, 100, System.currentTimeMillis() - 22_000, true);
		plugin.clock.onTick(137);
		config.tick = true;
		config.timer = true;
		assertFits(ticks, 80, 50);
		assertFits(time, 160, 100);
		config.combine = true;
		assertFits(both, 170, 120);
		config.large = SolSurvivorConfig.LargeTimerNumber.TIME;
		assertFits(both, 170, 120);
		config.rows = true;
		assertFits(both, 170, 90);
		config.loop = true;
		assertFits(both, 170, 90);
		plugin.clock.resetCounter(137);
		plugin.clock.onTick(138);
		assertFits(both, 170, 90);
	}

	@Test
	public void eachLoopPositionTakesItsOwnColourOnlyWhenLoopingWithColoursOn()
	{
		plugin.clock.onTick(100);
		config.tick = true;
		assertEquals(Color.WHITE, ticks.numberColour(plugin.clock.view()));
		config.loop = true;
		assertEquals(Color.WHITE, ticks.numberColour(plugin.clock.view()));
		assertNull(ticks.loopColour(plugin.clock.view()));
		config.colours = SolSurvivorConfig.LoopColours.NUMBER;
		Set<Color> seen = new HashSet<>();
		Color[] expected = {config.tickLoopColour1(), config.tickLoopColour2(), config.tickLoopColour3(), config.tickLoopColour4(),
			config.tickLoopColour5()};
		for (int count = 1; count <= 10; count++)
		{
			plugin.clock.onTick(100 + count);
			Color colour = ticks.numberColour(plugin.clock.view());
			assertEquals(expected[(count - 1) % 5], colour);
			seen.add(colour);
			assertNotNull(render(ticks));
		}
		assertEquals(5, seen.size());
		config.colours = SolSurvivorConfig.LoopColours.BOX;
		assertEquals(Color.WHITE, ticks.numberColour(plugin.clock.view()));
		assertNotNull(ticks.loopColour(plugin.clock.view()));
		assertFits(ticks, 80, 50);
		config.timer = true;
		config.combine = true;
		assertFits(both, 170, 120);
		config.loop = false;
		assertNull(ticks.loopColour(plugin.clock.view()));
	}

	@Test
	public void allLooksHideOutsideTheArenaAndOnSolsWaveAndRetainTheCompletedWave()
	{
		config.tick = true;
		config.timer = true;
		plugin.clock.onTick(90);
		plugin.clock.onModifierChosen(11, 100, 0, true);
		plugin.clock.onGameMessage("Wave 11 completed!", 22_200);
		assertNotNull(render(ticks));
		assertNotNull(render(time));
		plugin.arena = false;
		assertNull(render(ticks));
		assertNull(render(time));
		config.combine = true;
		assertNull(render(both));
		plugin.arena = true;
		plugin.clock.onModifierChosen(12, 200, 0, true);
		assertNull(render(both));
		config.combine = false;
		assertNull(render(ticks));
		assertNull(render(time));
	}

	private static Dimension render(WaveClockOverlay overlay)
	{
		Graphics2D graphics = new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try
		{
			// RuneLite's panel uses the preceding frame's child measurements for its background and returned size.
			// Warm that layout before checking or capturing it, including a change between stacked and row layouts.
			overlay.render(graphics);
			overlay.render(graphics);
			return overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}

	private static void assertFits(WaveClockOverlay overlay, int width, int height)
	{
		Dimension size = render(overlay);
		assertNotNull(size);
		assertTrue(size.toString(), size.width > 0 && size.width <= width && size.height > 0 && size.height <= height);
		assertTrue(overlay.isMovable());
	}

	/** Writes the actual rendered overlays, at native size, for the release's visual review. */
	public static void main(String[] args) throws Exception
	{
		File folder = new File(args[0]);
		folder.mkdirs();
		WaveClockOverlayTest scene = new WaveClockOverlayTest();
		scene.plugin.clock.onTick(90);
		scene.plugin.clock.onModifierChosen(7, 100, System.currentTimeMillis() - 22_000, true);
		scene.plugin.clock.onTick(137);
		scene.config.tick = true;
		scene.config.timer = true;
		save(scene.ticks, new File(folder, "tick-counter.png"));
		save(scene.time, new File(folder, "wave-timer.png"));
		scene.config.combine = true;
		save(scene.both, new File(folder, "combined-tick.png"));
		scene.config.large = SolSurvivorConfig.LargeTimerNumber.TIME;
		save(scene.both, new File(folder, "combined-time.png"));
		scene.config.rows = true;
		save(scene.both, new File(folder, "combined-rows.png"));
		scene.config.loop = true;
		save(scene.both, new File(folder, "loop.png"));
		scene.config.colours = SolSurvivorConfig.LoopColours.NUMBER;
		scene.config.combine = false;
		for (int position = 1; position <= 5; position++)
		{
			scene.plugin.clock.resetCounter(200);
			scene.plugin.clock.onTick(200 + position);
			save(scene.ticks, new File(folder, "loop-number-" + position + ".png"));
		}
		scene.config.colours = SolSurvivorConfig.LoopColours.BOX;
		for (int position = 1; position <= 5; position++)
		{
			scene.plugin.clock.resetCounter(300);
			scene.plugin.clock.onTick(300 + position);
			save(scene.ticks, new File(folder, "loop-box-" + position + ".png"));
		}
		scene.config.colours = SolSurvivorConfig.LoopColours.OFF;
		scene.config.combine = true;
		scene.plugin.clock.onGameMessage("Wave 7 completed!", System.currentTimeMillis());
		save(scene.both, new File(folder, "wave-done.png"));
	}

	private static void save(WaveClockOverlay overlay, File file) throws Exception
	{
		Dimension size = render(overlay);
		BufferedImage image = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setColor(new Color(0x282828));
		graphics.fillRect(0, 0, size.width, size.height);
		overlay.render(graphics);
		graphics.dispose();
		ImageIO.write(image, "png", file);
	}

	private static final class ClockPlugin extends SolSurvivorPlugin
	{
		private final WaveClock clock = new WaveClock();
		private boolean arena = true;

		@Override
		boolean inArena()
		{
			return arena;
		}

		@Override
		WaveClock.View waveClock()
		{
			return clock.view();
		}
	}

	private static final class Settings implements SolSurvivorConfig
	{
		private boolean tick;
		private boolean timer;
		private boolean combine;
		private boolean rows;
		private boolean loop;
		private LargeTimerNumber large = LargeTimerNumber.TICK;
		private LoopColours colours = LoopColours.OFF;

		@Override
		public boolean tickCounter() { return tick; }
		@Override
		public boolean waveTimer() { return timer; }
		@Override
		public boolean combineWaveTimers() { return combine; }
		@Override
		public CombinedTimerLayout combinedTimerLayout() { return rows ? CombinedTimerLayout.ROWS : CombinedTimerLayout.STACKED; }
		@Override
		public TickCounterCounts tickCounterCounts() { return loop ? TickCounterCounts.LOOP : TickCounterCounts.UP_FROM_ZERO; }
		@Override
		public LargeTimerNumber largeTimerNumber() { return large; }
		@Override
		public LoopColours loopColours() { return colours; }
	}
}

