	/**
	 * Ranged gear as the RuneLite layer reads it from the worn items, the varps, the varbits and the skills. The worn
	 * items' defence bonuses are numbers made up for the test, the mask's and the quiver's; the prayer unlocks are Rigour
	 * and Deadeye, not Augury or Mystic Vigour, and the Knight Waves done.
	 */
	private static Equipment rangedGear()
	{
		return new Equipment()
			.item("head", new Equipment.Item(27235, "Masori mask (f)", 1))
			.item("cape", new Equipment.Item(28947, "Dizana's quiver", 1))
			.item("weapon", new Equipment.Item(20997, "Twisted bow", 1))
			.item("ammo", new Equipment.Item(11212, "Dragon arrow", 812))
			.switchItem("weapon", new Equipment.Item(22325, "Scythe of vitur", 1), 5)
			.switchItem("body", new Equipment.Item(26384, "Torva platebody", 1))
			.bonuses(20997, new int[]{0, 0, 0, 0, 70, 0, 20, 0, 1})
			.bonuses(22325, new int[]{70, 125, 30, -6, 0, 75, 0, 0, 1})
			.defences(27235, new int[]{8, 10, 12, 12, 9})
			.defences(28947, new int[]{2, 2, 2, 5, 15})
			.defences(20997, new int[]{0, 0, 0, 0, 0})
			.weapon(5, 3, 1)
			.prayer(9, 77)
			.stat("defence", 99, 99)
			.stat("ranged", 112, 99)
			.stat("magic", 94, 94)
			.stat("hitpoints", 88, 99)
			.stat("prayer", 77, 77)
			.unlocks(1, 0, 1, 0, 8, 0);
	}

