	@Test
	public void doomsStacksAreTheDamagingHitsOfAWaveThePluginSawStart() throws Exception
	{
		spawn(11, NpcKind.SHAMAN_ID, 13, 20, 50);
		// Without Doom, none are sent.
		tracker.onGameMessage("Wave: 1", 40);
		tracker.onPlayerHit(10, 16);
		assertNull(capture(60, 16, 8).getDoomStacks());
		varbits.put(Modifier.DOOM, 3);
		assertEquals(Integer.valueOf(1), capture(60, 16, 8).getDoomStacks());
		// A max hit, a burn and a poison are damage too; a heal is not.
		tracker.onPlayerHit(30, 43);
		tracker.onPlayerHit(4, 74);
		tracker.onPlayerHit(6, 65);
		tracker.onPlayerHit(10, ColosseumTracker.HEAL_HITSPLAT);
		assertEquals(Integer.valueOf(4), capture(61, 16, 8).getDoomStacks());
		// A plugin that did not see the wave start does not know them all, and sends none.
		tracker.reset();
		varbits.put(Modifier.DOOM, 3);
		tracker.onPlayerHit(10, 16);
		assertNull(capture(62, 16, 8).getDoomStacks());
	}

	@Test
	public void anNpcsBarIsKeptUntilItDespawnsOrIsHealed() throws Exception
	{
		tracker.onGameMessage("Wave: 3", 100);
		spawn(11, NpcKind.SHAMAN_ID, 13, 20, 100);
		tracker.onHealthBar(11, 12, 30);
		// A bar the game hides, or one that makes no sense, changes nothing.
		tracker.onHealthBar(11, -1, -1);
		tracker.onHealthBar(11, 31, 30);
		tracker.onHealthBar(11, 5, 0);
		assertTrue(Arrays.equals(new int[] {12, 30}, capture(120, 16, 8).getNpcs().get(0).getHealth()));
		// A hit that heals nothing keeps it; a heal forgets it until the bar shows again.
		tracker.onNpcHit(11, 9, 16);
		assertTrue(Arrays.equals(new int[] {12, 30}, capture(121, 16, 8).getNpcs().get(0).getHealth()));
		tracker.onNpcHit(11, 9, ColosseumTracker.HEAL_HITSPLAT);
		assertNull(capture(122, 16, 8).getNpcs().get(0).getHealth());
		tracker.onHealthBar(11, 20, 30);
		assertTrue(Arrays.equals(new int[] {20, 30}, capture(123, 16, 8).getNpcs().get(0).getHealth()));
		// An NPC of the same index spawned after starts at full health.
		tracker.onNpcDespawned(11);
		tracker.onNpcSpawned(11, NpcKind.SHAMAN_ID, 130);
		assertNull(capture(131, 16, 8).getNpcs().get(0).getHealth());
	}

	@Test
	public void reentryIsSandGoesWithItsWaveAndTheObjectsAreCounted() throws Exception
	{
		varbits.put(Modifier.REENTRY, 1);
		tracker.onGameMessage("Wave: 2", 10);
		spawn(11, NpcKind.SHAMAN_ID, 13, 20, 10);
		// Reentry I lays sand on the landing tile alone; a landing without Reentry lays none.
		tracker.onTileGraphic(new GridTile(16, 10), ColosseumTracker.JAVELIN_LANDING_GRAPHIC, 1);
		tracker.onTileGraphic(new GridTile(12, 10), ColosseumTracker.JAVELIN_LANDING_GRAPHIC, 0);
		// Off the grid, nothing: neither a landing's tile nor an object's.
		tracker.onTileGraphic(new GridTile(0, 40), ColosseumTracker.JAVELIN_LANDING_GRAPHIC, 1);
		tracker.onSandObject(new GridTile(40, 3), true);
		tracker.onSandObject(null, true);
		assertEquals(Arrays.asList(new GridTile(16, 10)), capture(50, 16, 8).getSand());
		tracker.onGameMessage("Wave 2 completed!", 60);
		assertTrue(capture(61, 16, 8).getSand().isEmpty());
		// The objects are counted, and a scene loading again spawns them anew.
		tracker.onSandObject(new GridTile(20, 14), true);
		tracker.onSandObject(new GridTile(20, 14), true);
		tracker.onSandObject(new GridTile(20, 14), false);
		assertEquals(Arrays.asList(new GridTile(20, 14)), capture(62, 16, 8).getSand());
		tracker.onSceneLoading();
		assertTrue(capture(63, 16, 8).getSand().isEmpty());
		// Leaving the Colosseum forgets the lasting sand too.
		tracker.onTileGraphic(new GridTile(16, 10), ColosseumTracker.JAVELIN_LANDING_GRAPHIC, 2);
		tracker.reset();
		assertTrue(capture(64, 16, 8).getSand().isEmpty());
	}

	@Test
	public void theLinkPointsAtTheSite() throws Exception
	{
		startWave4();
		ArenaState state = capture(100, 7, 15);
		String expected = "https://solsurvivor.app/#s=" + StatePayload.encode(state);
		assertEquals(expected, StatePayload.link("https://solsurvivor.app", state));
		assertEquals(expected, StatePayload.link(" https://solsurvivor.app/#s=old ", state));
	}

	private interface Capture
	{
		void run() throws ExportException;
	}

	private static void assertExportFails(String reason, Capture capture)
	{
		try
		{
			capture.run();
			fail("expected an ExportException saying " + reason);
		}
		catch (ExportException e)
		{
			assertTrue(e.getMessage(), e.getMessage().contains(reason));
		}
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/**
 * The NPC hitpoints' count, fed the spawns, hitsplats and health bars the RuneLite layer passes on: the count from the
 * hitsplats, the bar's range keeping it honest, and the tag's heal and estimate.
 */
public class NpcHitpointsTest
{
	private static final int DAMAGE = 16;
	private static final int BLOCK = 12;
	private static final int FREM_BERSERKER_ID = 12816;

	private NpcHitpoints hitpoints;

	@Before
	public void setUp()
	{
		hitpoints = new NpcHitpoints();
	}

	@Test
	public void anNpcThatSpawnsStartsAtItsKindsFullHitpoints()
	{
		hitpoints.onSpawned(1, NpcKind.MANTICORE_ID);
		NpcHitpoints.Reading reading = hitpoints.reading(1, 10);
		assertEquals(250, reading.hitpoints);
		assertEquals(250, reading.max);
		assertFalse(reading.estimated);
		assertEquals(0, reading.healed);
	}

	@Test
	public void damageComesOffAndAHealGoesBackUpToFull()
	{
		hitpoints.onSpawned(1, NpcKind.SHAMAN_ID);
		hitpoints.onHit(1, 40, DAMAGE, 5);
		hitpoints.onHit(1, 0, BLOCK, 6);
		assertEquals(85, hitpoints.reading(1, 6).hitpoints);
		hitpoints.onHit(1, 60, ColosseumTracker.HEAL_HITSPLAT, 7);
		NpcHitpoints.Reading reading = hitpoints.reading(1, 7);
		assertEquals(125, reading.hitpoints);
		assertEquals(60, reading.healed);
		assertEquals(0, hitpoints.reading(1, 7 + NpcHitpoints.HEAL_SHOWN_TICKS).healed);
	}

	@Test
	public void healsCloseTogetherShowAsOne()
	{
		hitpoints.onSpawned(1, NpcKind.MINOTAUR_ID);
		hitpoints.onHit(1, 100, DAMAGE, 1);
		hitpoints.onHit(1, 5, ColosseumTracker.HEAL_HITSPLAT, 2);
		hitpoints.onHit(1, 5, ColosseumTracker.HEAL_HITSPLAT, 3);
		assertEquals(10, hitpoints.reading(1, 3).healed);
		assertEquals(135, hitpoints.reading(1, 3).hitpoints);
	}

	@Test
	public void theCountNeverGoesBelowNothing()
	{
		hitpoints.onSpawned(1, NpcKind.JAGUAR_ID);
		hitpoints.onHit(1, 200, DAMAGE, 1);
		assertEquals(0, hitpoints.reading(1, 1).hitpoints);
	}

	@Test
	public void aBarThatAgreesLeavesTheCountExact()
	{
		hitpoints.onSpawned(1, NpcKind.MANTICORE_ID);
		hitpoints.onHit(1, 78, DAMAGE, 1);
		// 172 of 250 shows as 20 of 30 by the game's rounding.
		hitpoints.onTick(1, NpcKind.MANTICORE_ID, 20, 30);
		NpcHitpoints.Reading reading = hitpoints.reading(1, 1);
		assertEquals(172, reading.hitpoints);
		assertFalse(reading.estimated);
	}

	@Test
	public void aBarThatDisagreesMovesTheCountIntoItsRangeAsAnEstimate()
	{
		// The Minotaur regenerates without a hitsplat, so the count falls behind it.
		hitpoints.onSpawned(1, NpcKind.MINOTAUR_ID);
		hitpoints.onHit(1, 150, DAMAGE, 1);
		int[] range = NpcHitpoints.range(225, 12, 30);
		hitpoints.onTick(1, NpcKind.MINOTAUR_ID, 12, 30);
		NpcHitpoints.Reading reading = hitpoints.reading(1, 2);
		assertEquals(range[0], reading.hitpoints);
		assertTrue(reading.estimated);
		// A full bar pins it again.
		hitpoints.onTick(1, NpcKind.MINOTAUR_ID, 30, 30);
		assertFalse(hitpoints.reading(1, 3).estimated);
		assertEquals(225, hitpoints.reading(1, 3).hitpoints);
	}

	@Test
	public void anNpcFirstSeenAfterItSpawnedIsAnEstimate()
	{
		hitpoints.onTick(4, NpcKind.JAVELIN_ID, -1, -1);
		NpcHitpoints.Reading reading = hitpoints.reading(4, 1);
		assertEquals(220, reading.hitpoints);
		assertTrue(reading.estimated);
	}

	@Test
	public void npcsThePlannerDoesNotKnowAreNotCounted()
	{
		hitpoints.onSpawned(2, FREM_BERSERKER_ID);
		hitpoints.onTick(3, NpcKind.SOLARFLARE_ORB_ID, 10, 30);
		assertNull(hitpoints.reading(2, 1));
		assertNull(hitpoints.reading(3, 1));
	}

	@Test
	public void aDespawnOrLeavingForgetsTheCount()
	{
		hitpoints.onSpawned(1, NpcKind.SHAMAN_ID);
		hitpoints.onSpawned(2, NpcKind.SHAMAN_ID);
		hitpoints.onDespawned(1);
		assertNull(hitpoints.reading(1, 1));
		hitpoints.clear();
		assertNull(hitpoints.reading(2, 1));
	}

	@Test
	public void theBarsRangeFollowsTheGamesRounding()
	{
		assertArrayEquals(new int[] {0, 0}, NpcHitpoints.range(250, 0, 30));
		assertArrayEquals(new int[] {250, 250}, NpcHitpoints.range(250, 30, 30));
		assertArrayEquals(new int[] {1, 9}, NpcHitpoints.range(250, 1, 30));
		assertArrayEquals(new int[] {242, 249}, NpcHitpoints.range(250, 29, 30));
		for (int ratio = 1; ratio < 30; ratio++)
		{
			int[] range = NpcHitpoints.range(250, ratio, 30);
			assertTrue("ratio " + ratio, range[0] <= range[1]);
		}
	}

	@Test
	public void aQuarterOrFewerIsLow()
	{
		hitpoints.onSpawned(1, NpcKind.MINOTAUR_ID);
		hitpoints.onHit(1, 168, DAMAGE, 1);
		assertFalse(hitpoints.reading(1, 1).low());
		hitpoints.onHit(1, 1, DAMAGE, 2);
		assertTrue(hitpoints.reading(1, 2).low());
	}

	@Test
	public void aThrownHitIsForecastFromItsHitpointsExperienceUntilItLands()
	{
		hitpoints.onSpawned(1, NpcKind.SHAMAN_ID);
		// 41 damage gives 54.67 Hitpoints experience, which the client shows as 54 or 55.
		hitpoints.onHitpointsXp(1, 55, 10);
		NpcHitpoints.Reading reading = hitpoints.reading(1, 10);
		assertEquals(125, reading.hitpoints);
		assertEquals(41, reading.incoming);
		assertEquals(84, reading.after());
		hitpoints.onHit(1, 41, DAMAGE, 12);
		hitpoints.onMyHit(1, 41, 12);
		reading = hitpoints.reading(1, 12);
		assertEquals(84, reading.hitpoints);
		assertEquals(0, reading.incoming);
	}

	@Test
	public void theForecastDividesOutTheNpcsBonusExperience()
	{
		assertEquals(41, NpcHitpoints.forecast(55, 0));
		// The Minotaur's +10%: 41 damage gives 60.13.
		assertEquals(41, NpcHitpoints.forecast(60, 10));
		hitpoints.onSpawned(1, NpcKind.MINOTAUR_ID);
		hitpoints.onHitpointsXp(1, 60, 4);
		assertEquals(41, hitpoints.reading(1, 4).incoming);
	}

	@Test
	public void aHitThatKillsLeavesNothing()
	{
		hitpoints.onSpawned(1, NpcKind.SHAMAN_ID);
		hitpoints.onHit(1, 100, DAMAGE, 3);
		hitpoints.onHitpointsXp(1, 33, 5);
		NpcHitpoints.Reading reading = hitpoints.reading(1, 5);
		assertEquals(25, reading.incoming);
		assertEquals(0, reading.after());
	}

	@Test
	public void aSpecialsSplatsTakeItsForecastOffBetweenThem()
	{
		hitpoints.onSpawned(1, NpcKind.MANTICORE_ID);
		hitpoints.onHitpointsXp(1, 80, 1);
		assertEquals(60, hitpoints.reading(1, 1).incoming);
		hitpoints.onMyHit(1, 30, 2);
		assertEquals(30, hitpoints.reading(1, 2).incoming);
		hitpoints.onMyHit(1, 15, 3);
		assertEquals(15, hitpoints.reading(1, 3).incoming);
		hitpoints.onMyHit(1, 15, 3);
		assertEquals(0, hitpoints.reading(1, 3).incoming);
	}

	@Test
	public void aForecastThatOverstatedItsHitGoesATickAfterItLands()
	{
		// A barrage's one drop for every NPC it hit, forecast on the one attacked.
		hitpoints.onSpawned(1, NpcKind.MANTICORE_ID);
		hitpoints.onHitpointsXp(1, 120, 1);
		hitpoints.onMyHit(1, 30, 3);
		assertEquals(60, hitpoints.reading(1, 4).incoming);
		assertEquals(0, hitpoints.reading(1, 5).incoming);
	}

	@Test
	public void aForecastThatNeverLandsGoesAfterItsTicks()
	{
		hitpoints.onSpawned(1, NpcKind.MANTICORE_ID);
		hitpoints.onHitpointsXp(1, 40, 1);
		assertEquals(30, hitpoints.reading(1, NpcHitpoints.FORECAST_TICKS).incoming);
		assertEquals(0, hitpoints.reading(1, 1 + NpcHitpoints.FORECAST_TICKS).incoming);
	}

	@Test
	public void aHitThrownOnTheTickAnEarlierOneLandsWaitsForItsOwn()
	{
		hitpoints.onSpawned(1, NpcKind.MANTICORE_ID);
		hitpoints.onHitpointsXp(1, 40, 1);
		hitpoints.onHitpointsXp(1, 20, 3);
		hitpoints.onMyHit(1, 30, 3);
		assertEquals(15, hitpoints.reading(1, 3).incoming);
	}

	@Test
	public void nothingIsForecastOnAnNpcThePluginDoesNotCount()
	{
		hitpoints.onSpawned(1, FREM_BERSERKER_ID);
		hitpoints.onHitpointsXp(1, 40, 1);
		assertNull(hitpoints.reading(1, 1));
	}
}

package nl.dexanddice.solsurvivor.core;

import static nl.dexanddice.solsurvivor.core.OrbStyle.MAGIC;
import static nl.dexanddice.solsurvivor.core.OrbStyle.MELEE;
import static nl.dexanddice.solsurvivor.core.OrbStyle.RANGED;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class OrbOrderTest
{
	private static OrbOrder seen(OrbStyle... styles)
	{
		OrbOrder order = new OrbOrder();
		for (OrbStyle s : styles)
		{
			order.see(s);
		}
		return order;
	}

	@Test
	public void noOrbIsUnchargedWithItsOrderUnknown()
	{
		assertEquals("u", seen().losCode(false));
		assertEquals("u", seen().losCode(true));
	}

	@Test
	public void theStandardOrdersAreNamedByTheirFirstOrb()
	{
		assertEquals("r", seen(RANGED, MAGIC, MELEE).losCode(false));
		assertEquals("m", seen(MAGIC, RANGED, MELEE).losCode(false));
	}

	@Test
	public void mantimayhemIIIsOrdersAreNamedInFull()
	{
		assertEquals("Mrm", seen(MELEE, RANGED, MAGIC).losCode(true));
		assertEquals("Mmr", seen(MELEE, MAGIC, RANGED).losCode(true));
		assertEquals("rMm", seen(RANGED, MELEE, MAGIC).losCode(true));
		assertEquals("mMr", seen(MAGIC, MELEE, RANGED).losCode(true));
		assertEquals("r", seen(RANGED, MAGIC, MELEE).losCode(true));
	}

	@Test
	public void withoutMantimayhemIIITheFirstOrbSettlesTheOrder()
	{
		assertEquals("ur", seen(RANGED).losCode(false));
		assertEquals("um", seen(MAGIC, RANGED).losCode(false));
	}

	@Test
	public void withMantimayhemIIITwoOrbsSettleTheOrder()
	{
		assertEquals("u", seen(MELEE).losCode(true));
		assertEquals("uMrm", seen(MELEE, RANGED).losCode(true));
		assertEquals("urMm", seen(RANGED, MELEE).losCode(true));
		assertEquals("ur", seen(RANGED, MAGIC).losCode(true));
	}

	@Test
	public void anOrbSeenAgainIsPassedOver()
	{
		// A graphic stays on for several ticks, and the order repeats once all three have fired.
		assertEquals("m", seen(MAGIC, MAGIC, RANGED, RANGED, MELEE, MAGIC, RANGED).losCode(false));
		assertEquals(3, seen(MAGIC, MAGIC, RANGED, MELEE, MELEE).getCount());
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * The pick link, from the tracker as the selector's script and varbits feed it. The JSON is compared whole with
 * src/test/resources/fixtures/pick.json, which test/link/pluginFixtures.test.ts reads as the site does.
 */
public class PickPayloadTest
{
	private static String fixture(String name) throws IOException
	{
		try (InputStream in = PickPayloadTest.class.getResourceAsStream("/fixtures/" + name))
		{
			if (in == null)
			{
				throw new IOException("no fixture " + name);
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}

	@Test
	public void theOffersAfterWave3()
	{
		ColosseumTracker tracker = new ColosseumTracker();
		Map<Modifier, Integer> varbits = new EnumMap<>(Modifier.class);
		varbits.put(Modifier.RELENTLESS, 2);
		varbits.put(Modifier.BEES, 1);
		tracker.onGameMessage("Wave 3 completed!", 500);
		// Relentless at its next tier, Totemic, which has none, and an id this plugin does not know.
		tracker.onModifierOptions(Modifier.RELENTLESS.getId(), Modifier.TOTEMIC.getId(), 99,
			(1 << Modifier.RELENTLESS.getId()) | (1 << Modifier.BEES.getId()) | (1 << Modifier.QUARTET.getId())
				| (1 << Modifier.DYNAMIC_DUO.getId()));
		assertEquals(3, tracker.getOptions().size());

		String json = PickPayload.toJson(tracker.getWave(), tracker.modifiers(m -> varbits.getOrDefault(m, 0)), tracker.getOptions());
		try
		{
			assertEquals(fixture("pick.json"), json);
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}

		String link = PickPayload.link("https://example.org/sol#s=old", tracker.getWave(), tracker.modifiers(m -> varbits.getOrDefault(m, 0)),
			tracker.getOptions());
		assertTrue(link, link.startsWith("https://example.org/sol/#pick="));
		String payload = link.substring(link.indexOf("#pick=") + "#pick=".length());
		assertEquals(json, new String(Base64.getUrlDecoder().decode(payload), StandardCharsets.US_ASCII));

		// Once one is picked, the selector closes and there is nothing to open.
		tracker.onModifierChosen(1);
		assertTrue(tracker.getOptions().isEmpty());
	}

	@Test
	public void beforeAnyWaveTheWaveIsNull()
	{
		ColosseumTracker tracker = new ColosseumTracker();
		tracker.onModifierOptions(Modifier.DOOM.getId(), Modifier.FRAILTY.getId(), Modifier.MYOPIA.getId(), 0);
		assertEquals("{\"v\":1,\"kind\":\"solSurvivorPick\",\"wave\":null,\"modifiers\":{},\"offers\":[[\"doom\",1],[\"frailty\",1],[\"myopia\",1]]}",
			PickPayload.toJson(tracker.getWave(), tracker.modifiers(m -> 0), tracker.getOptions()));
	}

	/**
	 * A run's waves finished go into the pick link: wave 1 clean in 101 ticks, then Blasphemy I taken and wave 2 hit once
	 * in 121. The game's glory counter is taken as it last read before the next wave started: 600 and 1,660, what the
	 * site's rules make of the two waves, as a made-up check. Its wave damage counter, 7 after wave 2's hit, is kept at
	 * the most it read, though it reads 0 again before wave 3.
	 */
	@Test
	public void theRunSoFarAfterWave2()
	{
		ColosseumTracker tracker = new ColosseumTracker();
		Map<Modifier, Integer> varbits = new EnumMap<>(Modifier.class);
		ModifierLevels levels = m -> varbits.getOrDefault(m, 0);
		tracker.onGameMessage("Wave: 1", 100);
		tracker.onRunTick(levels, 0, 0);
		tracker.onGameMessage("Wave 1 completed!", 200);
		// The counter may move a tick after the message: the run keeps its last value before the next wave.
		tracker.onRunTick(levels, 0, 0);
		tracker.onRunTick(levels, 600, 0);
		tracker.onModifierOptions(Modifier.BLASPHEMY.getId(), Modifier.DOOM.getId(), Modifier.FRAILTY.getId(), 0);
		tracker.onModifierChosen(1);
		varbits.put(Modifier.BLASPHEMY, 1);
		tracker.onRunTick(levels, 600, 0);

		tracker.onGameMessage("Wave: 2", 300);
		tracker.onRunTick(levels, 600, 0);
		tracker.onPlayerHit(7, 16);
		tracker.onRunTick(levels, 600, 7);
		tracker.onGameMessage("Wave 2 completed!", 420);
		tracker.onRunTick(levels, 1660, 7);
		tracker.onRunTick(levels, 1660, 0);
		tracker.onModifierOptions(Modifier.DOOM.getId(), Modifier.BLASPHEMY.getId(), Modifier.FRAILTY.getId(), 1 << Modifier.BLASPHEMY.getId());

		assertEquals(2, tracker.getRun().size());
		String json = PickPayload.toJson(tracker.getWave(), tracker.modifiers(levels), tracker.getOptions(), tracker.getRun());
		try
		{
			assertEquals(fixture("pick-run.json"), json);
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	/**
	 * The reward chest after wave 4 rides in the pick link as the game holds it: wave 5's reward, and the chest so far,
	 * waves 1 and 2's splinters stacked as the game stacks them. The JSON is compared whole with
	 * src/test/resources/fixtures/pick-chest.json, which the site's tests read too.
	 */
	@Test
	public void theChestAfterWave4()
	{
		ColosseumTracker tracker = new ColosseumTracker();
		tracker.onGameMessage("Wave 4 completed!", 500);
		tracker.onModifierOptions(Modifier.DOOM.getId(), Modifier.FRAILTY.getId(), Modifier.MYOPIA.getId(), 0);
		List<ChestItem> next = Arrays.asList(new ChestItem("Dragon platelegs", 1));
		List<ChestItem> held = Arrays.asList(new ChestItem("Sunfire splinters", 230), new ChestItem("Death rune", 150), new ChestItem("Rune platebody", 1));
		String json = PickPayload.toJson(tracker.getWave(), tracker.modifiers(m -> 0), tracker.getOptions(), Collections.emptyList(), next, held);
		try
		{
			assertEquals(fixture("pick-chest.json"), json);
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
		// Without the chest, as before the game sends it, the link has none.
		assertTrue(PickPayload.toJson(tracker.getWave(), tracker.modifiers(m -> 0), tracker.getOptions(), Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList()).endsWith("[\"myopia\",1]]}"));
	}

	/**
	 * The potions ride in the pick link: each wave's doses drunk, counted from the run's first tick in the arena to the
	 * wave's end and then wave to wave, so the sip between waves 1 and 2 counts with wave 2; and the doses carried now. A
	 * wave the plugin first saw part-way has none, as its count would be short. The JSON is compared whole with
	 * src/test/resources/fixtures/pick-potions.json, which the site's tests read too.
	 */
	@Test
	public void thePotionsDrunkEachWaveAndCarried()
	{
		ColosseumTracker tracker = new ColosseumTracker();
		ModifierLevels none = m -> 0;
		Map<String, Integer>[] inventory = new Map[1];
		inventory[0] = doses("Saradomin brew(4)", 6, "Super restore(4)", 6, "Divine ranging potion(4)", 1, "Amulet of glory(4)", 1);
		java.util.function.Supplier<Map<String, Integer>> carried = () -> inventory[0];

		tracker.onRunTick(none, 0, 0, carried);
		tracker.onGameMessage("Wave: 1", 100);
		tracker.onRunTick(none, 0, 0, carried);
		inventory[0] = doses("Saradomin brew(4)", 5, "Saradomin brew(2)", 1, "Super restore(4)", 6, "Divine ranging potion(3)", 1, "Amulet of glory(4)", 1);
		tracker.onGameMessage("Wave 1 completed!", 200);
		tracker.onRunTick(none, 600, 0, carried);
		// A sip of restore between the waves, and six doses of brew and a restore in wave 2.
		inventory[0] = doses("Saradomin brew(4)", 5, "Saradomin brew(2)", 1, "Super restore(4)", 5, "Super restore(3)", 1, "Divine ranging potion(3)", 1,
			"Amulet of glory(4)", 1);
		tracker.onRunTick(none, 600, 0, carried);
		tracker.onGameMessage("Wave: 2", 300);
		tracker.onRunTick(none, 600, 0, carried);
		inventory[0] = doses("Saradomin brew(4)", 4, "Super restore(4)", 5, "Super restore(2)", 1, "Divine ranging potion(3)", 1, "Amulet of glory(4)", 1);
		tracker.onGameMessage("Wave 2 completed!", 420);
		tracker.onRunTick(none, 1660, 0, carried);
		tracker.onModifierOptions(Modifier.DOOM.getId(), Modifier.BLASPHEMY.getId(), Modifier.FRAILTY.getId(), 0);

		assertEquals(doses("Saradomin brew(2)", 1, "Divine ranging potion(1)", 1), tracker.getRun().get(0).getDrunk());
		assertEquals(doses("Saradomin brew(3)", 2, "Super restore(2)", 1), tracker.getRun().get(1).getDrunk());
		String json = PickPayload.toJson(tracker.getWave(), tracker.modifiers(none), tracker.getOptions(), tracker.getRun(),
			Collections.emptyList(), Collections.emptyList(), inventory[0]);
		try
		{
			assertEquals(fixture("pick-potions.json"), json);
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}

		// Seen first part-way through a wave, that wave has no count, and the next wave counts from its end.
		ColosseumTracker late = new ColosseumTracker();
		inventory[0] = doses("Saradomin brew(4)", 4);
		late.onGameMessage("Wave: 5", 100);
		late.onRunTick(none, 0, 0);
		late.onRunTick(none, 0, 0, carried);
		inventory[0] = doses("Saradomin brew(4)", 3);
		late.onGameMessage("Wave 5 completed!", 200);
		late.onRunTick(none, 0, 0, carried);
		assertNull(late.getRun().get(0).getDrunk());
		// Without the doses, as from the tests' older ticks, no wave is counted.
		assertNull(new RunWave(1, 100, false, 0, Collections.emptyMap(), 0).getDrunk());
	}

	/** Potions by their doses from items and how many of each, as the inventory holds them. */
	private static Map<String, Integer> doses(Object... items)
	{
		List<ChestItem> list = new java.util.ArrayList<>();
		for (int i = 0; i < items.length; i += 2)
		{
			list.add(new ChestItem((String) items[i], (Integer) items[i + 1]));
		}
		return Potions.doses(list);
	}

	/** A wave the plugin did not see start has no ticks and no hits; a new run's wave 1 forgets the last run. */
	@Test
	public void aWaveSeenPartWayAndANewRun()
	{
		ColosseumTracker tracker = new ColosseumTracker();
		ModifierLevels none = m -> 0;
		tracker.onGameMessage("Wave 4 completed!", 50);
		tracker.onRunTick(none, 3000, 25);
		assertEquals(1, tracker.getRun().size());
		RunWave four = tracker.getRun().get(0);
		assertEquals(4, four.getWave());
		assertNull(four.getTicks());
		assertNull(four.getHit());
		assertNull(four.getDamage());
		assertEquals(3000, four.getGlory());
		assertTrue(PickPayload.toJson(5, tracker.modifiers(none), tracker.getOptions(), tracker.getRun())
			.endsWith(",\"run\":[{\"wave\":4,\"ticks\":null,\"hit\":null,\"damage\":null,\"modifiers\":{},\"glory\":3000}]}"));

		tracker.onGameMessage("Wave: 1", 900);
		assertTrue(tracker.getRun().isEmpty());
		tracker.onGameMessage("Wave 1 completed!", 999);
		tracker.onRunTick(none, 0, 0);
		tracker.reset();
		assertTrue(tracker.getRun().isEmpty());
	}

	/** On a wave's first tick the damage counter may still hold the last wave's, which the wave does not take. */
	@Test
	public void theWaveDamageCounterSkipsTheWavesFirstTick()
	{
		ColosseumTracker tracker = new ColosseumTracker();
		ModifierLevels none = m -> 0;
		tracker.onGameMessage("Wave: 3", 100);
		tracker.onRunTick(none, 1500, 12);
		tracker.onRunTick(none, 1500, 0);
		tracker.onGameMessage("Wave 3 completed!", 160);
		tracker.onRunTick(none, 2400, 0);
		assertEquals(Integer.valueOf(0), tracker.getRun().get(0).getDamage());
	}
}

