package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

/**
 * The run log, which "Copy whole run" copies: which of the waves logged make the newest run (WaveLog.getRun), and its
 * JSON (RunLogWriter), compared whole with src/test/resources/fixtures/run-log.json. The waves are started and recorded
 * as the RuneLite layer does it, with the plugin's version given as "test"; the NPC, animation and hitsplat type ids are
 * made up, as in WaveLogTest.
 */
public class RunLogTest
{
	/** The state link's payload on wave 1's first tick, as the RuneLite layer passes it on: here a short made-up one. */
	private static final String START_STATE = "{\"v\":1,\"setup\":{\"npcs\":[[13,20,\"2\"]],\"player\":[7,15],\"waveStart\":true,\"wave\":1}}";

	private WaveLog log;

	@Before
	public void setUp()
	{
		log = new WaveLog();
	}

	private static String fixture(String name) throws IOException
	{
		try (InputStream in = RunLogTest.class.getResourceAsStream("/fixtures/" + name))
		{
			if (in == null)
			{
				throw new IOException("no fixture " + name);
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}

	private static WaveLog.PlayerTick player(int x, int y, int hp)
	{
		return new WaveLog.PlayerTick(new GridTile(x, y), hp, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE);
	}

	private static WaveLog.NpcTick shaman(int index, int x, int y, int animation)
	{
		return new WaveLog.NpcTick(index, NpcKind.SHAMAN_ID, new GridTile(x, y), animation, -1, -1, WaveLog.TARGET_PLAYER);
	}

	/** Wave `wave` starts on game tick `gameTick` with no modifiers, and `ticks` ticks of it are recorded. */
	private void wave(int wave, int gameTick, int ticks)
	{
		log.start(wave, gameTick, Collections.emptyMap(), true, "test", null);
		for (int t = 0; t < ticks; t++)
		{
			log.record(gameTick + t, player(7, 15, 99), Collections.emptyList());
		}
	}

	/** The waves of the newest run, in the order the run gives them. */
	private List<Integer> runWaves()
	{
		List<Integer> out = new ArrayList<>();
		for (WaveLog.Past p : log.getRun())
		{
			out.add(p.getWave());
		}
		return out;
	}

	@Test
	public void aRunLog() throws Exception
	{
		// An earlier run, which the player left in wave 2.
		wave(1, 100, 2);
		log.finish(WaveLog.End.COMPLETED);
		wave(2, 200, 1);
		log.finish(WaveLog.End.LEFT);

		// The newest run: wave 1, completed; wave 2, whose end the plugin missed, with Reentry I taken; and wave 3 under way.
		Map<Modifier, Integer> reentry = new EnumMap<>(Modifier.class);
		reentry.put(Modifier.REENTRY, 1);
		log.start(1, 1000, Collections.emptyMap(), true, "test", START_STATE);
		log.record(1000, player(7, 15, 99), Collections.singletonList(shaman(11, 13, 20, -1)));
		log.onNpcHit(11, 14, 12);
		log.onNpcAnimation(11, 10859);
		log.record(1001, player(7, 14, 99), Collections.singletonList(shaman(11, 13, 19, 10859)));
		log.finish(WaveLog.End.COMPLETED);
		log.start(2, 1100, reentry, true, "test", null);
		log.record(1100, player(7, 15, 99), Arrays.asList(shaman(14, 13, 20, -1), shaman(15, 15, 20, -1)));
		log.start(3, 1200, reentry, true, "test", null);
		log.onPlayerHit(9, 16);
		log.record(1200, player(7, 15, 90), Collections.singletonList(shaman(16, 13, 20, -1)));

		assertEquals(Arrays.asList(1, 2, 3), runWaves());
		assertEquals(fixture("run-log.json"), RunLogWriter.toJson(log.getRun(), "test"));
	}

	@Test
	public void eachWaveIsAsCopyWaveLogCopiesIt()
	{
		wave(4, 100, 2);
		log.finish(WaveLog.End.COMPLETED);
		wave(5, 200, 3);
		log.finish(WaveLog.End.COMPLETED);
		wave(6, 300, 1);

		// The past waves as they were kept, and the wave under way as WaveLogWriter writes it now.
		String wave4 = log.getPast().get(1).getJson();
		String wave5 = log.getPast().get(0).getJson();
		String wave6 = WaveLogWriter.toJson(log);
		List<WaveLog.Past> run = log.getRun();
		assertEquals(Arrays.asList(wave4, wave5, wave6), Arrays.asList(run.get(0).getJson(), run.get(1).getJson(), run.get(2).getJson()));
		assertEquals(Arrays.asList(2, 3, 1), Arrays.asList(run.get(0).size(), run.get(1).size(), run.get(2).size()));
		assertEquals(log.getId(), run.get(2).getId());
		assertEquals("{\"v\":1,\"kind\":\"solSurvivorRun\",\"plugin\":\"test\",\"waves\":[\n" + wave4 + ",\n" + wave5 + ",\n" + wave6 + "\n]}",
			RunLogWriter.toJson(run, "test"));

		// The newest is written when the run is asked for, so that it holds the ticks recorded since.
		log.record(301, player(7, 14, 99), Collections.emptyList());
		assertEquals(2, log.getRun().get(2).size());
		assertEquals(WaveLogWriter.toJson(log), log.getRun().get(2).getJson());
	}

	@Test
	public void theRunStartsAtWave1AndNeverReachesIntoTheRunBefore()
	{
		wave(1, 100, 1);
		wave(2, 200, 1);
		wave(3, 300, 1);
		log.finish(WaveLog.End.LEFT);
		wave(1, 1000, 1);
		assertEquals(Collections.singletonList(1), runWaves());
		wave(2, 1100, 1);
		assertEquals(Arrays.asList(1, 2), runWaves());
	}

	@Test
	public void aRunThePluginJoinedLateStartsAtTheFirstWaveItLogged()
	{
		wave(4, 100, 1);
		wave(5, 200, 1);
		wave(6, 300, 1);
		log.finish(WaveLog.End.COMPLETED);
		assertEquals(Arrays.asList(4, 5, 6), runWaves());
	}

	@Test
	public void aWaveMissingOrLoggedTwicePartsTheRun()
	{
		// Wave 4 was not logged: the run is the newer part.
		wave(2, 100, 1);
		wave(3, 200, 1);
		wave(5, 300, 1);
		wave(6, 400, 1);
		assertEquals(Arrays.asList(5, 6), runWaves());

		log.clear();
		wave(3, 100, 1);
		wave(4, 200, 1);
		wave(4, 300, 1);
		assertEquals(Collections.singletonList(4), runWaves());
	}

	@Test
	public void howAWaveEndedDoesNotPartTheRun()
	{
		wave(1, 100, 1);
		log.finish(WaveLog.End.COMPLETED);
		wave(2, 200, 1);
		log.finish(WaveLog.End.LEFT);
		wave(3, 300, 1);
		assertEquals(Arrays.asList(1, 2, 3), runWaves());
	}

	@Test
	public void aWholeRunIsAlwaysKept()
	{
		// Three runs of all 12 waves, Sol Heredit's included: the logs kept are more than a run's waves, so that the newest
		// run is whole at each wave even once the oldest logs are dropped.
		int tick = 0;
		for (int run = 0; run < 3; run++)
		{
			for (int w = 1; w <= ColosseumTracker.LAST_WAVE + 1; w++)
			{
				tick += 100;
				wave(w, tick, 1);
				log.finish(WaveLog.End.COMPLETED);
				List<Integer> expected = new ArrayList<>();
				for (int i = 1; i <= w; i++)
				{
					expected.add(i);
				}
				assertEquals(expected, runWaves());
			}
		}
		assertEquals(WaveLog.MAX_PAST, log.getPast().size());
	}

	@Test
	public void theRunsBeforeTheNewestArePartedTheSameWay()
	{
		// A run of waves 1 to 3, then a new run from wave 1, then the plugin picking up at wave 6 after missing some.
		int tick = 100;
		for (int w : new int[]{1, 2, 3, 1, 2, 6, 7})
		{
			wave(w, tick, 1);
			log.finish(WaveLog.End.COMPLETED);
			tick += 100;
		}
		List<List<Integer>> runs = new ArrayList<>();
		for (List<WaveLog.Past> run : log.getRuns())
		{
			List<Integer> waves = new ArrayList<>();
			for (WaveLog.Past p : run)
			{
				waves.add(p.getWave());
			}
			runs.add(waves);
		}
		assertEquals(Arrays.asList(Arrays.asList(6, 7), Arrays.asList(1, 2), Arrays.asList(1, 2, 3)), runs);
		assertEquals(Arrays.asList(6, 7), runWaves());
		assertTrue(log.getRuns().get(2).get(0).getJson().contains("\"wave\":1"));
	}

	@Test
	public void eachWaveKeepsItsStartAndTheTickItsReinforcementsCame()
	{
		log.start(4, 100, Collections.emptyMap(), true, "test", START_STATE);
		log.record(100, player(7, 15, 99), Collections.emptyList());
		assertTrue(!log.hasReinforcementState());
		log.reinforcementsCame("{\"first\":true}");
		// Only the first tick they came is kept.
		log.reinforcementsCame("{\"second\":true}");
		WaveLog.Past now = log.getRun().get(0);
		assertTrue(now.isRecording());
		assertEquals(Arrays.asList(START_STATE, "{\"first\":true}"), Arrays.asList(now.getStartState(), now.getReinforcementState()));

		log.finish(WaveLog.End.COMPLETED);
		// After the wave, none are taken: the next wave's come with its own.
		log.reinforcementsCame("{\"late\":true}");
		log.start(5, 200, Collections.emptyMap(), true, "test", null);
		WaveLog.Past four = log.getPast().get(0);
		assertEquals(Arrays.asList(START_STATE, "{\"first\":true}"), Arrays.asList(four.getStartState(), four.getReinforcementState()));
		assertTrue(!four.isRecording());
		WaveLog.Past five = log.getRun().get(1);
		assertEquals(Arrays.asList(null, null), Arrays.asList(five.getStartState(), five.getReinforcementState()));
		log.finish(WaveLog.End.LEFT);
		log.reinforcementsCame("{\"after\":true}");
		assertEquals(null, log.getReinforcementState());
	}

	@Test
	public void noLogNoRun()
	{
		assertTrue(log.getRun().isEmpty());
		assertEquals("{\"v\":1,\"kind\":\"solSurvivorRun\",\"plugin\":\"test\",\"waves\":[]}", RunLogWriter.toJson(log.getRun(), "test"));

		wave(1, 100, 1);
		wave(2, 200, 1);
		log.clear();
		assertTrue(log.getRun().isEmpty());
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntPredicate;
import java.util.function.IntToLongFunction;
import org.junit.Test;

/** A run's profit: the chest's loot claimed alive, less what the inventory and gear lost, at the prices given. */
public class RunProfitTest
{
	private static final int SHARK = 385;
	private static final int BREW_4 = 6685;
	private static final int BREW_3 = 6687;
	private static final int BOW = 20997;
	private static final int ARROWS = 11212;
	private static final int SPLINTERS = 28924;
	private static final int DEATH_RUNE = 560;

	private static final IntToLongFunction PRICE = id ->
	{
		switch (id)
		{
			case SHARK:
				return 800;
			case BREW_4:
				return 8_000;
			case BREW_3:
				return 6_000;
			case BOW:
				return 1_500_000_000L;
			case ARROWS:
				return 1_000;
			case SPLINTERS:
				return 100;
			case DEATH_RUNE:
				return 200;
			default:
				return 0;
		}
	};

	/** Which items stack: the arrows, the runes and the splinters. */
	private static final IntPredicate STACKS = id -> id == ARROWS || id == DEATH_RUNE || id == SPLINTERS;

	private static Map<Integer, Integer> items(int... idThenQuantity)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < idThenQuantity.length; i += 2)
		{
			m.put(idThenQuantity[i], idThenQuantity[i + 1]);
		}
		return m;
	}

	@Test
	public void aBankedChestLessTheSuppliesEatenDrunkAndShot()
	{
		RunProfit.Tracker run = new RunProfit.Tracker(items(SHARK, 10, BREW_4, 4, BOW, 1, ARROWS, 500), items());
		Map<Integer, Integer> start = items(SHARK, 10, BREW_4, 4, BOW, 1, ARROWS, 500);
		run.onTick(start, items(SPLINTERS, 300));
		// Four sharks eaten, a brew sipped once and 120 arrows shot.
		Map<Integer, Integer> end = items(SHARK, 6, BREW_4, 3, BREW_3, 1, BOW, 1, ARROWS, 380);
		run.onTick(end, items(SPLINTERS, 800, DEATH_RUNE, 1_000));
		// Bank-all: everything leaves the chest and none of it reaches the inventory.
		run.onTick(end, items());
		RunProfit p = run.finish(PRICE, PRICE, STACKS, 9);
		assertEquals(800 * 100 + 1_000 * 200, p.getLoot());
		assertEquals(4 * 800 + (8_000 - 6_000) + 120 * 1_000, p.getSupplies());
		assertEquals(p.getLoot() - p.getSupplies(), p.getProfit());
		assertFalse(p.isDied());
		assertEquals(Integer.valueOf(9), p.getWave());
		assertTrue(p.counts());
	}

	@Test
	public void lootTakenIntoTheInventoryIsLootNotSuppliesSaved()
	{
		RunProfit.Tracker run = new RunProfit.Tracker(items(SHARK, 10, DEATH_RUNE, 100), items());
		// Two sharks eaten and 40 death runes cast, the same as the chest holds.
		run.onTick(items(SHARK, 8, DEATH_RUNE, 60), items(SPLINTERS, 50, DEATH_RUNE, 500));
		// The chest taken into the inventory.
		run.onTick(items(SHARK, 8, DEATH_RUNE, 560, SPLINTERS, 50), items());
		RunProfit p = run.finish(PRICE, PRICE, STACKS, 5);
		assertEquals(50 * 100 + 500 * 200, p.getLoot());
		assertEquals(2 * 800 + 40 * 200, p.getSupplies());
	}

	@Test
	public void aDeathLosesTheChestAndCostsTheSupplies()
	{
		RunProfit.Tracker run = new RunProfit.Tracker(items(SHARK, 10, BOW, 1), items());
		run.onTick(items(SHARK, 2, BOW, 1), items(SPLINTERS, 800));
		run.onDeath(3, false, false);
		// The game empties the chest once the player has died, and the items go to the grave: none of that is used up.
		run.onTick(items(), items());
		RunProfit p = run.finish(PRICE, PRICE, STACKS, 7);
		assertTrue(p.isDied());
		assertEquals(0, p.getLoot());
		assertEquals(8 * 800, p.getSupplies());
		// The bow and both sharks are kept: nothing goes to the grave worth a fee.
		assertEquals(0, p.getDeathFee());
		assertEquals(-6_400, p.getProfit());
	}

	@Test
	public void aChestTheRunStartsWithIsClaimedWhenItEmpties()
	{
		// The plugin came back mid-run, after a login: the chest so far is in the game's container already.
		RunProfit.Tracker run = new RunProfit.Tracker(items(SHARK, 4), items(SPLINTERS, 400));
		run.onTick(items(SHARK, 4), items());
		RunProfit p = run.finish(PRICE, PRICE, STACKS, null);
		assertEquals(40_000, p.getLoot());
		assertEquals(0, p.getSupplies());
		assertNull(p.getWave());
	}

	@Test
	public void gearOnlyMovedBetweenTheInventoryAndTheBodyCostsNothing()
	{
		RunProfit.Tracker run = new RunProfit.Tracker(items(BOW, 1, SHARK, 3), items());
		run.onTick(items(SHARK, 3), items());
		run.onTick(items(BOW, 1, SHARK, 3), items());
		RunProfit p = run.finish(PRICE, PRICE, STACKS, 1);
		assertEquals(0, p.getSupplies());
		assertFalse(p.counts());
	}

	@Test
	public void itemsPickedUpNeverMakeTheSuppliesNegative()
	{
		RunProfit.Tracker run = new RunProfit.Tracker(items(SHARK, 1), items());
		run.onTick(items(SHARK, 1, ARROWS, 10), items());
		assertEquals(0, run.finish(PRICE, PRICE, STACKS, 1).getSupplies());
	}

	@Test
	public void chargesInsideAWeaponCountForEachAttack()
	{
		RunProfit.Tracker run = new RunProfit.Tracker(items(), items());
		for (int i = 0; i < 30; i++)
		{
			run.onAttack("Holy scythe of vitur");
		}
		run.onAttack("Dragon claws");
		run.onAttack(null);
		IntToLongFunction price = id -> id == ChargeCosts.BLOOD_RUNE ? 300 : id == ChargeCosts.VIAL_OF_BLOOD ? 1_000 : 0;
		// 2 blood runes and a hundredth of a vial a swing.
		assertEquals(30 * (2 * 300 + 10), run.finish(price, price, STACKS, 3).getSupplies());
	}

	@Test
	public void theGravesFeeIsForTheItemsNotKept()
	{
		Map<Integer, Integer> carried = items(BOW, 1, SHARK, 10, ARROWS, 500, DEATH_RUNE, 2_000);
		// The bow is kept; 500 arrows (500K) and 2,000 runes (400K) are a stack each and cost 1,000 each, the sharks nothing.
		assertEquals(2_000, DeathFee.estimate(carried, PRICE, STACKS, 1, false, false));
		assertEquals(500, DeathFee.estimate(carried, PRICE, STACKS, 1, true, false));
		assertEquals(250, DeathFee.estimate(carried, PRICE, STACKS, 1, true, true));
		// Four kept: the bow and both stacks, whole, and a shark.
		assertEquals(0, DeathFee.estimate(carried, PRICE, STACKS, 4, false, false));
		// Kept nothing, the bow's 1.5B costs 100,000 more.
		assertEquals(102_000, DeathFee.estimate(carried, PRICE, STACKS, 0, false, false));
		Map<Integer, Integer> rich = new HashMap<>();
		for (int id = 1; id <= 10; id++)
		{
			rich.put(id, 1);
		}
		assertEquals(DeathFee.CAP, DeathFee.estimate(rich, i -> 50_000_000L, STACKS, 0, false, false));
		assertEquals(125_000, DeathFee.estimate(rich, i -> 50_000_000L, STACKS, 0, true, false));
	}

	@Test
	public void eachWeaponsAttacksAreCountedAsItSpendsItsCharges()
	{
		// A cast whose target dies before it lands shows no hitsplat: the projectile counts it.
		assertEquals(ChargeCosts.Counting.PROJECTILE, ChargeCosts.counting("Tumeken's shadow"));
		assertEquals(ChargeCosts.Counting.PROJECTILE, ChargeCosts.counting("Toxic blowpipe"));
		assertEquals(ChargeCosts.Counting.DAMAGE, ChargeCosts.counting("Sanguine scythe of vitur"));
		assertEquals(ChargeCosts.Counting.HIT, ChargeCosts.counting("Blade of saeldor (c)"));
		assertEquals(ChargeCosts.Counting.NONE, ChargeCosts.counting("Twisted bow"));
		assertEquals(ChargeCosts.Counting.NONE, ChargeCosts.counting(null));
	}

	@Test
	public void itemsThatDoNotStackAreEachAnItemForTheGrave()
	{
		// Stefan's check in game, 2026-11-04: eight brews at 8,000 are eight free items, not one worth 64,000; and 20 at
		// 8,000 are not one item worth 160,000 either.
		assertEquals(0, DeathFee.estimate(items(BREW_4, 20), PRICE, STACKS, 0, false, false));
		// 200 arrows at 1,000 are one stack, worth 200,000.
		assertEquals(1_000, DeathFee.estimate(items(BREW_4, 20, ARROWS, 200), PRICE, STACKS, 0, false, false));
	}

	@Test
	public void aStackIsKeptWholeByTheValueOfTheWholeStack()
	{
		// Stefan's gravestone, 2026-11-04: a stack of thousands kept whole while dearer single items went to the grave.
		// 5,000 death runes at 200 are worth 1M, more than the 1,000-coin arrows the grave then charges.
		Map<Integer, Integer> carried = items(DEATH_RUNE, 5_000, ARROWS, 150, SHARK, 3);
		assertEquals(1_000, DeathFee.estimate(carried, PRICE, STACKS, 1, false, false));
	}

	@Test
	public void theGravesFeeGoesByTheGuidePriceNotTheLivePrice()
	{
		// Stefan's gravestone, 2026-11-04: an item over 1M at the live price but under it at the guide price costs 250
		// with the discount, not 2,500.
		RunProfit.Tracker run = new RunProfit.Tracker(items(BOW, 1, ARROWS, 1), items());
		run.onDeath(1, true, false);
		IntToLongFunction live = id -> id == BOW ? 2_000_000_000L : id == ARROWS ? 1_050_000 : 0;
		IntToLongFunction guide = id -> id == BOW ? 2_000_000_000L : id == ARROWS ? 980_000 : 0;
		assertEquals(250, run.finish(live, guide, STACKS, 6).getDeathFee());
		assertEquals(2_500, run.finish(live, live, STACKS, 6).getDeathFee());
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Random;
import java.util.zip.GZIPInputStream;
import org.junit.Test;

/**
 * The body of a run's Watch: the run's JSON gzipped, which the site stores as it comes, and a run past the site's limits
 * refused before anything is sent, with what the player can do instead.
 */
public class RunUploadTest
{
	@Test
	public void aRunIsSentGzippedAndUnpacksToItsJson() throws IOException
	{
		String json = "{\"v\":1,\"kind\":\"solSurvivorRun\",\"waves\":[" + "{\"t\":1},".repeat(10_000) + "{}]}";
		byte[] packed = RunUpload.pack(json);
		assertTrue(packed.length < json.length() / 10);
		try (GZIPInputStream in = new GZIPInputStream(new ByteArrayInputStream(packed)))
		{
			assertEquals(json, new String(in.readAllBytes(), StandardCharsets.UTF_8));
		}
		assertEquals("application/gzip", RunUpload.TYPE);
	}

	@Test
	public void aRunPastTheSitesLimitsIsRefusedWithWhatThePlayerCanDo()
	{
		String tooLong = "x".repeat(RunUpload.MAX_JSON_BYTES + 1);
		assertRefused(tooLong, "This run is too large to open (8 MiB maximum). You can still copy its wave logs.");
		// Noise does not pack: past the stored size, it is refused too.
		byte[] noise = new byte[RunUpload.MAX_PACKED_BYTES];
		new Random(7).nextBytes(noise);
		StringBuilder hex = new StringBuilder();
		for (byte b : noise)
		{
			hex.append(String.format("%02x", b));
		}
		assertRefused(hex.toString(), "This run is too large to store on the site. You can still copy its wave logs.");
	}

	private static void assertRefused(String json, String message)
	{
		try
		{
			RunUpload.pack(json);
			fail("packed a run past the site's limits");
		}
		catch (RunUpload.TooLarge ex)
		{
			assertEquals(message, ex.getMessage());
		}
	}
}

package nl.dexanddice.solsurvivor.core;

