package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import org.junit.Test;

/**
 * The packed link text (StatePayload.pack): it unpacks, against the site's dictionary, to the JSON it was made from, and
 * it is about half as long. The site's tests unpack the plugin's packed fixture and compare the plugin's copy of the
 * dictionary with the site's, byte for byte (test/link/pluginFixtures.test.ts).
 */
public class StatePayloadTest
{
	/** The state fixtures, each a payload as toJson writes it. */
	private static final String[] FIXTURES = {"wave4-start.json", "wave4-mid.json", "late-start.json", "wave8-gear.json"};

	static String fixture(String name) throws IOException
	{
		try (InputStream in = StatePayloadTest.class.getResourceAsStream("/fixtures/" + name))
		{
			if (in == null)
			{
				throw new IOException("no fixture " + name);
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}

	/** Packed link text unpacked to its JSON, as the site's unpackStateText does it; an AssertionError if it does not unpack. */
	static String unpack(String text)
	{
		assertTrue(text.startsWith(StatePayload.PACKED_V1));
		Inflater inflater = new Inflater(true);
		try
		{
			inflater.setDictionary(StatePayload.DICTIONARY_V1);
			inflater.setInput(Base64.getUrlDecoder().decode(text.substring(StatePayload.PACKED_V1.length())));
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buffer = new byte[4096];
			while (!inflater.finished())
			{
				int n = inflater.inflate(buffer);
				if (n == 0 && inflater.needsInput())
				{
					throw new AssertionError("the packed text is cut short");
				}
				out.write(buffer, 0, n);
			}
			return out.toString(StandardCharsets.US_ASCII);
		}
		catch (DataFormatException e)
		{
			throw new AssertionError("the packed text does not unpack", e);
		}
		finally
		{
			inflater.end();
		}
	}

	@Test
	public void theSitesDictionaryIsThere()
	{
		assertNotNull(StatePayload.DICTIONARY_V1);
		assertEquals(1496, StatePayload.DICTIONARY_V1.length);
	}

	@Test
	public void aPackedPayloadUnpacksToItsJsonAtLessThanThreeFifthsOfTheLength() throws Exception
	{
		for (String name : FIXTURES)
		{
			String json = fixture(name);
			String packed = StatePayload.pack(json);
			String plain = Base64.getUrlEncoder().withoutPadding().encodeToString(json.getBytes(StandardCharsets.US_ASCII));
			assertEquals(name, json, unpack(packed));
			assertTrue(name + ": " + packed.length() + " against " + plain.length(), packed.length() * 5 < plain.length() * 3);
		}
	}

	@Test
	public void theTrianglesPlaceComesAfterTheRestOfTheLink() throws Exception
	{
		// wave4-triangle.json is wave4-start.json with the dot of the site's readout "Safe 10% · Fast 0% · Easy 90%", which
		// the site's tests open (test/link/pluginFixtures.test.ts).
		String start = fixture("wave4-start.json");
		TriangleDot dot = TriangleDot.of(10, 0, 90);
		assertEquals(fixture("wave4-triangle.json"), StatePayload.withTriangle(start, dot));
		String link = StatePayload.linkOfJson("https://solsurvivor.app/", start, dot);
		assertEquals(fixture("wave4-triangle.json"), unpack(link.substring(link.indexOf(StatePayload.STATE_HASH) + StatePayload.STATE_HASH.length())));
		// Without one, the link is as it was.
		assertEquals(start, StatePayload.withTriangle(start, null));
		assertEquals(StatePayload.linkOfJson("https://solsurvivor.app/", start), StatePayload.linkOfJson("https://solsurvivor.app/", start, null));
	}

	@Test
	public void thePlayersTileMarkersComeAfterTheRestOfTheLink() throws Exception
	{
		// wave4-markers.json is wave4-start.json with the markers of points as Ground Markers saves them, which the site's
		// tests open (test/link/pluginFixtures.test.ts): a red "A" west of the north-west pillar, the start tile marked in
		// Ground Markers' own yellow, and a green label longer than a link holds, cut to its 40 characters.
		String start = fixture("wave4-start.json");
		List<TileMarker> markers = new ArrayList<>();
		markers.add(TileMarker.of(7216, 23, 43, 0, 0, 0xFFFF0000, "A"));
		markers.add(TileMarker.of(7216, 23, 36, 0, 0, null, " "));
		markers.add(TileMarker.of(7216, 21, 26, 0, 0, 0xFF00FF00, "stall at the SW pillar for the reinforcement shaman"));
		assertEquals(fixture("wave4-markers.json"), StatePayload.withMarkers(start, markers));
		String link = StatePayload.linkOfJson("https://solsurvivor.app/", StatePayload.withMarkers(start, markers));
		assertEquals(fixture("wave4-markers.json"), unpack(link.substring(link.indexOf(StatePayload.STATE_HASH) + StatePayload.STATE_HASH.length())));
		// Without any, the link is as it was.
		assertEquals(start, StatePayload.withMarkers(start, null));
		assertEquals(start, StatePayload.withMarkers(start, new ArrayList<>()));
	}

	@Test
	public void aMarkerOffTheArenaOrOnAnotherPlaneIsLeftOut()
	{
		// Another region, the lobby's; another plane than the player's; and a tile of the arena's region off its grid.
		assertNull(TileMarker.of(ArenaGeometry.LOBBY_REGION_ID, 23, 43, 0, 0, null, null));
		assertNull(TileMarker.of(7216, 23, 43, 1, 0, null, null));
		assertNull(TileMarker.of(7216, 60, 43, 0, 0, null, null));
		assertNotNull(TileMarker.of(7216, 23, 43, 1, 1, null, null));
	}

	@Test
	public void aMarkerTooFaintToSeeInTheGameIsLeftOut()
	{
		assertNull(TileMarker.of(7216, 23, 43, 0, 0, 0x01000000, null));
		assertNull(TileMarker.of(7216, 23, 43, 0, 0, 0x0FFFFFFF, null));
		assertNotNull(TileMarker.of(7216, 23, 43, 0, 0, 0x10FFFFFF, null));
	}

	@Test
	public void aTileMarkedTwiceKeepsItsFirstMarker()
	{
		List<TileMarker> markers = new ArrayList<>();
		markers.add(TileMarker.of(7216, 23, 43, 0, 0, 0xFFFF0000, "mine"));
		markers.add(TileMarker.of(7216, 23, 36, 0, 0, null, null));
		markers.add(TileMarker.of(7216, 23, 43, 0, 0, 0xFF00FFFF, "A"));
		assertEquals("[(7,8) #ff0000 mine, (7,15) #ffff00]", TileMarker.distinct(markers).toString());
	}

	@Test
	public void aLinkHoldsAtMostAHundredMarkers()
	{
		String start = "{\"v\":1}";
		List<TileMarker> markers = new ArrayList<>();
		for (int i = 0; i < 150; i++)
		{
			markers.add(TileMarker.of(7216, 16 + i % 34, 51 - i / 34, 0, 0, null, null));
		}
		String json = StatePayload.withMarkers(start, markers);
		assertEquals(TileMarker.MAX_MARKERS, json.split("#ffff00").length - 1);
	}

	@Test
	public void theFirstLinksMarkComesAfterTheRestOfTheLink() throws Exception
	{
		// wave4-first.json is wave4-start.json with the mark of the plugin's first link, which the site's tests open
		// (test/link/pluginFixtures.test.ts) and count as a plugin player's first page.
		String start = fixture("wave4-start.json");
		assertEquals(fixture("wave4-first.json"), StatePayload.withFirst(start));
		String link = StatePayload.linkOfJson("https://solsurvivor.app/", StatePayload.withFirst(start));
		assertEquals(fixture("wave4-first.json"), unpack(link.substring(link.indexOf(StatePayload.STATE_HASH) + StatePayload.STATE_HASH.length())));
	}

	@Test
	public void theTrianglesSharesAreKeptToTheSettingsRangeAndNoneAboveNothingPlacesNoDot()
	{
		assertEquals(TriangleDot.of(0, 100, 0), TriangleDot.of(-5, 200, 0));
		assertEquals(TriangleDot.MAX_SHARE, TriangleDot.of(33, 101, 33).getFast());
		assertNull(TriangleDot.of(0, 0, 0));
		assertNull(TriangleDot.of(-1, 0, -40));
	}

	@Test
	public void thePackedFixtureIsAWaveStartsLink() throws Exception
	{
		// wave4-start.packed.txt is this plugin's packing of wave4-start.json, which the site's tests unpack too. It is not
		// compared with pack's text today: another zlib may deflate the same bytes otherwise, and both read the same.
		assertEquals(fixture("wave4-start.json"), unpack(fixture("wave4-start.packed.txt")));
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The counter's origins are its first tick in the arena, the player's hotkey and, counting up, the pick; never an NPC. */
public class WaveClockTest
{
	private final WaveClock clock = new WaveClock();

	@Test
	public void theCounterRunsFromItsFirstTickWithNoPickOrPress()
	{
		assertFalse(clock.view().counterVisible());
		clock.onTick(50);
		assertTrue(clock.view().counterVisible());
		assertFalse(clock.view().timerVisible());
		assertEquals("0", clock.view().up());
		for (int count = 1; count <= 37; count++)
		{
			clock.onTick(50 + count);
			assertEquals(Integer.toString(count), clock.view().up());
		}
		clock.onTick(87);
		assertEquals("37", clock.view().up());
	}

	@Test
	public void countingUpThePickAndTheHotkeyEachRestartAtZero()
	{
		clock.onTick(50);
		clock.onModifierChosen(7, 100, 0, true);
		assertEquals("0", clock.view().up());
		clock.onTick(105);
		assertEquals("5", clock.view().up());
		clock.resetCounter(106);
		assertEquals("0", clock.view().up());
		clock.onTick(107);
		assertEquals("1", clock.view().up());
	}

	@Test
	public void theLoopStartsAtOnceAndOnlyTheHotkeyRestartsIt()
	{
		clock.onTick(100);
		for (int count = 1; count <= 13; count++)
		{
			clock.onTick(100 + count);
			assertEquals(Integer.toString((count - 1) % 5 + 1), clock.view().loop(5));
		}
		clock.onModifierChosen(7, 114, 0, false);
		clock.onWaveStarted(7, 0);
		clock.onTick(115);
		assertEquals("5", clock.view().loop(5));
		clock.resetCounter(120);
		clock.onTick(121);
		assertEquals("1", clock.view().loop(5));
		clock.onTick(122);
		assertEquals("2", clock.view().loop(5));
	}

	@Test
	public void theCounterGoesOnPastTheWavesEndWhileTheTimerFreezes()
	{
		clock.onTick(100);
		clock.onModifierChosen(7, 100, 1_000, true);
		clock.onTick(137);
		clock.onGameMessage("Wave 6 completed!", 23_000);
		assertTrue(clock.view().running);
		clock.onGameMessage("<col=ff0000>Wave 7 completed!</col>", 23_200);
		assertEquals("Wave 7 done", clock.view().title());
		assertEquals("0:22", clock.view().time(99_000));
		clock.onTick(140);
		assertEquals("40", clock.view().up());
		clock.onModifierChosen(8, 141, 50_000, true);
		assertEquals("Wave 8", clock.view().title());
		assertEquals("0:00", clock.view().time(50_999));
	}

	@Test
	public void theTimerIsRealSecondsWithMinutesAndHours()
	{
		clock.onModifierChosen(3, 0, 10_000, true);
		assertEquals("0:00", clock.view().time(10_000));
		assertEquals("0:59", clock.view().time(69_999));
		assertEquals("1:00", clock.view().time(70_000));
		assertEquals("59:59", clock.view().time(10_000 + 3_599_000));
		assertEquals("1:00:00", clock.view().time(10_000 + 3_600_000));
		assertEquals("2:03:04", clock.view().time(10_000 + (2 * 3600 + 3 * 60 + 4) * 1000L));
	}

	@Test
	public void aWaveWhosePickWasMissedStartsItsTimerAtItsStartMessage()
	{
		clock.onTick(10);
		clock.onWaveStarted(4, 5_000);
		assertTrue(clock.view().timerVisible());
		assertEquals("Wave 4", clock.view().title());
		assertEquals("0:03", clock.view().time(8_000));
		clock.onModifierChosen(5, 40, 30_000, true);
		clock.onWaveStarted(5, 33_000);
		assertEquals("0:05", clock.view().time(35_000));
	}

	@Test
	public void solsWaveAndLeavingHideBothClocks()
	{
		clock.onTick(10);
		clock.onModifierChosen(11, 100, 0, true);
		clock.onWaveStarted(12, 0);
		assertFalse(clock.view().counterVisible());
		assertFalse(clock.view().timerVisible());
		clock.onTick(120);
		assertFalse(clock.view().counterVisible());
		clock.clear();
		assertFalse(clock.view().counterVisible());
		clock.onModifierChosen(12, 200, 0, true);
		assertFalse(clock.view().counterVisible());
		assertFalse(clock.view().timerVisible());
	}

	@Test
	public void quietOffKeepsBothClocksOnSolsWave()
	{
		clock.onTick(10);
		clock.onModifierChosen(12, 100, 0, true);
		clock.onWaveStarted(12, 1_000);
		clock.onTick(120);
		assertTrue(clock.view().counterVisible(false));
		assertTrue(clock.view().timerVisible(false));
		assertFalse(clock.view().counterVisible(true));
		assertFalse(clock.view().timerVisible(true));
		assertEquals("Wave 12", clock.view().title());
		assertEquals("0:04", clock.view().time(4_000));
	}

	@Test
	public void loopLengthsAreBoundedEvenWhenAnImportedSettingBypassesTheSettingsPanel()
	{
		clock.onTick(0);
		clock.onTick(3);
		assertEquals("1", clock.view().loop(0));
		clock.onTick(11);
		assertEquals("1", clock.view().loop(99));
	}
}

package nl.dexanddice.solsurvivor.core;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import org.junit.Before;
import org.junit.Test;

/**
 * The wave log, fed mocked game data as the RuneLite layer passes it on: a wave's start from the tracker, the hitsplats
 * as they come and a snapshot of the player and the NPCs each tick. The JSON is compared whole with
 * src/test/resources/fixtures/wave-log.json. The animation, graphic, item and hitsplat type ids here are made up: the
 * log passes on whatever the game gives.
 */
public class WaveLogTest
{
	private static final int FREM_RANGER_ID = 12814;
	/** An NPC the plugin has no kind for, logged by its raw id all the same: Minimus, here standing on the grid. */
	private static final int MINIMUS_ID = 12808;
	/** The state link's payload on the wave's first tick, as the RuneLite layer passes it on: here a short made-up one. */
	private static final String START_STATE = "{\"v\":1,\"setup\":{\"npcs\":[[13,20,\"2\"]],\"player\":[7,15],\"waveStart\":true,\"wave\":4}}";
	/** Gear worn, slot by slot in WaveLog.WORN_SLOTS' order: a bow, then a fang in its place. */
	private static final int[] BOW = {1001, 1002, -1, 1004, 1005, -1, 1007, -1, -1, -1, 1011};
	private static final int[] FANG = {1001, 1002, -1, 2004, 1005, -1, 1007, -1, -1, -1, 1011};
	/** The game's counters, one for each ColosseumCounter in its order: Doom's stacks, the glory, the times and the damage. */
	private static final int[] COUNTERS = {0, 1200, 51000, 0, 150, 120, 900};
	private static final int[] COUNTERS_HIT = {0, 1200, 51000, 13, 150, 120, 900};

	private WaveLog log;

	@Before
	public void setUp()
	{
		log = new WaveLog();
	}

	private static String fixture(String name) throws IOException
	{
		try (InputStream in = WaveLogTest.class.getResourceAsStream("/fixtures/" + name))
		{
			if (in == null)
			{
				throw new IOException("no fixture " + name);
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}

	private static WaveLog.PlayerTick player(int x, int y, int hp, int prayer, List<String> prayers, int animation, int target)
	{
		return new WaveLog.PlayerTick(new GridTile(x, y), hp, prayer, prayers, animation, target);
	}

	private static WaveLog.PlayerTick wearing(int[] worn, int x, int y)
	{
		return new WaveLog.PlayerTick(new GridTile(x, y), 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE, worn);
	}

	private static WaveLog.NpcTick npc(int index, int id, int x, int y, int animation, int ratio, int scale, int target)
	{
		return new WaveLog.NpcTick(index, id, new GridTile(x, y), animation, ratio, scale, target);
	}

	/** Wave 4 started by the tracker, with Reentry II, Quartet and Totemic taken and Solarflare I's varbit set. */
	private void startWave4(int gameTick)
	{
		ColosseumTracker tracker = new ColosseumTracker();
		tracker.onModifierOptions(Modifier.SOLARFLARE.getId(), Modifier.QUARTET.getId(), Modifier.DOOM.getId(),
			(1 << Modifier.REENTRY.getId()) | (1 << Modifier.TOTEMIC.getId()));
		tracker.onModifierChosen(2);
		Map<Modifier, Integer> varbits = new EnumMap<>(Modifier.class);
		varbits.put(Modifier.REENTRY, 2);
		varbits.put(Modifier.SOLARFLARE, 1);
		tracker.onGameMessage("<col=ef1020>Wave: 4</col>", gameTick);
		assertTrue(tracker.isWaveStartTick(gameTick));
		log.start(tracker.getWave(), gameTick, tracker.modifiers(m -> varbits.getOrDefault(m, 0)), tracker.isModifiersComplete(), "test",
			START_STATE);
	}

	@Test
	public void aWaveLog() throws Exception
	{
		// A hitsplat that came on the wave's first tick, before the tracker saw its message, is kept for that tick.
		log.onNpcHit(12, 0, 12);
		startWave4(100);
		log.record(100, new WaveLog.PlayerTick(new GridTile(7, 15), 99, 77, Arrays.asList("magic", "piety"), -1, WaveLog.TARGET_NONE, BOW),
			Arrays.asList(
			npc(11, NpcKind.SHAMAN_ID, 13, 20, -1, -1, -1, WaveLog.TARGET_PLAYER),
			npc(12, NpcKind.MANTICORE_ID, 16, 24, 7590, 30, 30, WaveLog.TARGET_PLAYER),
			npc(13, FREM_RANGER_ID, 7, 14, -1, -1, -1, WaveLog.TARGET_NONE),
			npc(20, NpcKind.SOLARFLARE_ORB_ID, 4, 4, -1, -1, -1, WaveLog.TARGET_NONE),
			// Off the grid: left out.
			npc(21, MINIMUS_ID, 40, 4, -1, -1, -1, WaveLog.TARGET_NONE)), COUNTERS);

		log.onPlayerHit(13, 16);
		log.onPlayerHit(0, 17);
		log.onNpcHit(11, 21, 12);
		log.onNpcHit(11, 9, 12);
		// The player switched to the fang and struck twice with the same animation; the Manticore showed an orb.
		log.onPlayerAnimation(7552);
		log.onPlayerAnimation(7552);
		// A graphic on a tile of the grid is kept, one off it is not.
		log.onTileGraphic(new GridTile(9, 12), 4001);
		log.onTileGraphic(new GridTile(40, 4), 4002);
		// The Manticore's orb at the player; a special aimed at a tile, seen a tick late; and one with nothing on the grid at
		// either end, which is left out. The damage taken counts up, and only it is listed.
		log.onProjectile(new WaveLog.Projectile(5001, 12, null, WaveLog.TARGET_PLAYER, null, 0, 51));
		log.onProjectile(new WaveLog.Projectile(5002, 11, new GridTile(1, 1), WaveLog.TARGET_NONE, new GridTile(9, 12), -12, 48));
		log.onProjectile(new WaveLog.Projectile(5003, WaveLog.TARGET_NONE, new GridTile(40, 4), WaveLog.TARGET_NONE, null, 0, 30));
		log.record(101, new WaveLog.PlayerTick(new GridTile(7, 14), 86, 75, Arrays.asList("ranged", "rigour"), 7552, 11, FANG), Arrays.asList(
			npc(11, NpcKind.SHAMAN_ID, 13, 19, 7579, 20, 30, WaveLog.TARGET_PLAYER),
			new WaveLog.NpcTick(12, NpcKind.MANTICORE_ID, new GridTile(16, 23), -1, 30, 30, WaveLog.TARGET_PLAYER, new int[] {3001}),
			npc(13, FREM_RANGER_ID, 7, 13, 426, -1, -1, 12),
			npc(20, NpcKind.SOLARFLARE_ORB_ID, 5, 4, -1, -1, -1, WaveLog.TARGET_NONE),
			npc(21, MINIMUS_ID, 20, 4, -1, -1, -1, WaveLog.TARGET_NONE)), COUNTERS_HIT);

		// A tick the plugin missed leaves a gap in `t`; a hit on an NPC that has gone is a stray hit.
		log.onNpcHit(11, 5, 12);
		log.record(103, new WaveLog.PlayerTick(null, 86, 74, Collections.emptyList(), -1, WaveLog.TARGET_NONE, FANG), Arrays.asList(
			npc(12, NpcKind.MANTICORE_ID, 16, 22, -1, 30, 30, WaveLog.TARGET_PLAYER)));
		log.finish(WaveLog.End.COMPLETED);

		assertEquals(3, log.size());
		assertFalse(log.isRecording());
		assertEquals(WaveLog.End.COMPLETED, log.getEnd());
		assertEquals(fixture("wave-log.json"), WaveLogWriter.toJson(log));
	}

	@Test
	public void theLogIsKeptAfterTheWaveAndResetByTheNext()
	{
		startWave4(100);
		log.record(100, player(7, 15, 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList());
		log.record(101, player(7, 14, 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList());
		log.finish(WaveLog.End.LEFT);

		// Ticks after the wave are not recorded, and their hitsplats do not wait for the next wave.
		log.onPlayerHit(5, 16);
		log.record(105, player(7, 14, 94, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList());
		assertEquals(2, log.size());
		assertEquals(WaveLog.End.LEFT, log.getEnd());
		assertTrue(log.hasLog());

		log.start(5, 200, Collections.emptyMap(), true, "test", null);
		log.record(200, player(7, 15, 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList());
		assertEquals(Integer.valueOf(5), log.getWave());
		assertEquals(1, log.size());
		assertNull(log.getEnd());
		assertTrue(log.isRecording());
		assertTrue(WaveLogWriter.toJson(log).contains("\"hits\":[]"));
	}

	@Test
	public void theAnimationsStartedSinceTheTickBeforeAreLoggedEachTimeEvenARepeat()
	{
		startWave4(100);
		log.record(100, player(7, 15, 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList());
		log.onNpcAnimation(11, 10859);
		log.onNpcAnimation(12, 10892);
		log.record(101, player(7, 15, 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList());
		log.onNpcAnimation(11, 10859);
		log.record(102, player(7, 15, 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList());
		String json = WaveLogWriter.toJson(log);
		assertTrue(json, json.contains("{\"t\":0,\"player\":[7,15,99,77,[],-1,null],\"hits\":[],\"npcs\":[],\"orbs\":[]}"));
		assertTrue(json, json.contains("\"orbs\":[],\"anims\":[[11,10859],[12,10892]]}"));
		assertTrue(json, json.contains("{\"t\":2,\"player\":[7,15,99,77,[],-1,null],\"hits\":[],\"npcs\":[],\"orbs\":[],\"anims\":[[11,10859]]}"));
	}

	@Test
	public void theCountersAreListedOnTheFirstTickAndWhenTheyChange()
	{
		// The prayer points drain a point a tick, so that no tick repeats the one before (aWaitIsWrittenOnce) and each has a line.
		startWave4(100);
		log.record(100, player(7, 15, 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList(), COUNTERS);
		log.record(101, player(7, 15, 99, 76, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList(), COUNTERS);
		log.record(102, player(7, 15, 99, 75, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList(), COUNTERS_HIT);
		// Counters that could not be read list nothing and leave the last ones standing.
		log.record(103, player(7, 15, 99, 74, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList(), null);
		log.record(104, player(7, 15, 99, 73, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList(), COUNTERS_HIT);
		String[] ticks = WaveLogWriter.toJson(log).split("\n");
		assertTrue(ticks[1], ticks[1].endsWith(",\"counters\":{\"doomStacks\":0,\"currentGlory\":1200,\"waveStartTime\":51000,"
			+ "\"waveDamageTaken\":0,\"lastModifierGlory\":150,\"lastWaveDuration\":120,\"totalDuration\":900}},"));
		assertFalse(ticks[2], ticks[2].contains("counters"));
		assertTrue(ticks[3], ticks[3].endsWith(",\"counters\":{\"waveDamageTaken\":13}},"));
		assertFalse(ticks[4], ticks[4].contains("counters"));
		assertFalse(ticks[5], ticks[5].contains("counters"));

		// A shared log leaves out the wave's start time and the run's total duration, and a tick that changed only those
		// lists no counters.
		String[] shared = WaveLogWriter.toShare(log).split("\n");
		assertTrue(shared[1], shared[1].endsWith(",\"counters\":{\"doomStacks\":0,\"currentGlory\":1200,"
			+ "\"waveDamageTaken\":0,\"lastModifierGlory\":150,\"lastWaveDuration\":120}},"));
		assertTrue(shared[3], shared[3].endsWith(",\"counters\":{\"waveDamageTaken\":13}},"));
		log.record(105, player(7, 15, 99, 72, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList(),
			new int[]{0, 1200, 51000, 13, 150, 120, 901});
		String[] later = WaveLogWriter.toShare(log).split("\n");
		assertFalse(later[6], later[6].contains("counters"));
		assertTrue(WaveLogWriter.toJson(log).split("\n")[6].endsWith(",\"counters\":{\"totalDuration\":901}}"));

		// The next wave lists them all on its first tick again.
		log.start(5, 200, Collections.emptyMap(), true, "test", null);
		log.record(200, player(7, 15, 99, 77, Collections.emptyList(), -1, WaveLog.TARGET_NONE), Collections.emptyList(), COUNTERS_HIT);
		assertTrue(WaveLogWriter.toJson(log).contains("\"counters\":{\"doomStacks\":0,"));
	}

